import sys, subprocess, os

src = sys.argv[1]
dst = sys.argv[2]

def try_pypdf():
    try:
        import pypdf
    except ImportError:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "--quiet", "--user", "pypdf"])
        import pypdf
    r = pypdf.PdfReader(src)
    out = []
    for i, p in enumerate(r.pages):
        t = p.extract_text() or ""
        out.append(f"\n\n===== PAGE {i+1} =====\n{t}")
    return "".join(out), len(r.pages)

def try_fitz():
    import fitz
    d = fitz.open(src)
    out = []
    for i, p in enumerate(d):
        out.append(f"\n\n===== PAGE {i+1} =====\n{p.get_text()}")
    return "".join(out), len(d)

text, n = None, 0
for fn in (try_fitz, try_pypdf):
    try:
        text, n = fn()
        print("extractor:", fn.__name__, "pages:", n)
        break
    except Exception as e:
        print("failed", fn.__name__, repr(e)[:200])

if text is None:
    sys.exit(2)
with open(dst, "w", encoding="utf-8") as f:
    f.write(text)
print("chars:", len(text))

