205	
206	        /// <summary>
207	        /// B2 + B3 + B4 (PLAN.md §6.3). <paramref name="xProbe1"/>/<paramref name="xProbe2"/> là
208	        /// hai vị trí X đã biết, khác nhau đủ xa (vài mm trở lên) và vẫn giữ được bản chuẩn trong
209	        /// khung hình — operator chọn khi jog thử trước lúc bấm nút.
210	        /// </summary>
211	        public async Task<BottomUpCalibResult> CalibrateBottomUpAsync(double xProbe1, double xProbe2, CancellationToken ct)
212	        {
213	            try
214	            {
215	                var sys = _sys();
216	                var vision = _vision();
217	
218	                // B2: công cụ hiệu chuẩn bản chuẩn của VisionMaster tính scale/độ không vuông góc
219	                // từ hàng trăm góc trong một ảnh.
220	                var board = await vision.TriggerCalibBoardAsync(ct).ConfigureAwait(false);
221	                if (!board.Found)
222	                    return new BottomUpCalibResult { Ok = false, Reason = board.Error ?? "không đọc được bản chuẩn — kiểm tra tấm checkerboard trong khung hình" };
223	
224	                // B4: ghép thành ma trận affine. Gốc đặt tại pixel (0,0) — PlacementSolver chỉ dùng
225	                // toạ độ TƯƠNG ĐỐI (p − C_i) nên hằng số gốc không ảnh hưởng kết quả cuối, miễn
226	                // nhất quán trong toàn bộ VisionCalib này.
227	                // BottomUpYSign KHÔNG ghép ở đây — PlacementSolver tự nhân dấu đó riêng (§6.3 cuối).
228	                double skewRad = board.SkewDeg * Math.PI / 180.0;
229	                var calib = new CameraCalib
230	                {
231	                    B11 = board.ScaleU,
232	                    B12 = board.ScaleU * Math.Sin(skewRad),
233	                    B13 = 0,
234	                    B21 = 0,
235	                    B22 = board.ScaleV,
236	                    B23 = 0,
237	                    Method = "checkerboard 1×1 mm (bottom-up)",
238	                    PointCount = board.CornerCount
239	                };
240	
241	                var result = new BottomUpCalibResult
242	                {
243	                    Calib = calib,
244	                    CornerCount = board.CornerCount,
245	                    SkewDeg = board.SkewDeg,
246	                    ScaleFromBoard = board.ScaleU
247	                };
248	
249	                // B3: chạy X tới 2 vị trí đã biết, đối chiếu chéo scale đo bằng trục máy với scale
250	                // đo bằng bản chuẩn — phép thử duy nhất bắt được lỗi cao độ đồ gá.
251	                if (!await _func.MoveAsync(AxisId.X, xProbe1, sys.GetAxis(AxisId.X).MoveSpeed, ct).ConfigureAwait(false))
252	                    return new BottomUpCalibResult { Ok = false, Reason = "không di chuyển được tới điểm đối chiếu 1" };
253	                var board1 = await vision.TriggerCalibBoardAsync(ct).ConfigureAwait(false);
254	                double axisPos1 = _motion[AxisId.X]?.CurrentPos ?? xProbe1;
255	
256	                if (!await _func.MoveAsync(AxisId.X, xProbe2, sys.GetAxis(AxisId.X).MoveSpeed, ct).ConfigureAwait(false))
257	                    return new BottomUpCalibResult { Ok = false, Reason = "không di chuyển được tới điểm đối chiếu 2" };
258	                var board2 = await vision.TriggerCalibBoardAsync(ct).ConfigureAwait(false);
259	                double axisPos2 = _motion[AxisId.X]?.CurrentPos ?? xProbe2;
260	
261	                if (!board1.Found || !board2.Found)
262	                {
263	                    result.Reason = "không thấy bản chuẩn tại điểm đối chiếu — kiểm tra khung hình";
264	                    return result;
265	                }
266	
267	                double axisDeltaMm = Math.Abs(axisPos2 - axisPos1);
268	                double pixelDeltaU = Math.Abs(board2.OriginPixelU - board1.OriginPixelU);
269	                if (axisDeltaMm < 1e-6 || pixelDeltaU < 1e-6)
270	                {
271	                    result.Reason = "hai điểm đối chiếu trùng nhau hoặc góc mốc không dịch chuyển — chọn lại vị trí";
272	                    return result;
273	                }
274	
275	                double scaleFromAxis = axisDeltaMm / pixelDeltaU;
276	                double diffRatio = Math.Abs(scaleFromAxis - board.ScaleU) / board.ScaleU;
277	
278	                result.ScaleFromAxis = scaleFromAxis;
279	                result.ScaleCrossCheckDiffRatio = diffRatio;
280	                result.CrossCheckOk = diffRatio <= sys.BottomUpScaleCrossCheckTolerance;
281	                result.Ok = result.CrossCheckOk;
282	                if (!result.CrossCheckOk)
283	                    result.Reason = string.Format(
284	                        "scale theo trục X ({0:0.00000} mm/px) lệch bản chuẩn ({1:0.00000} mm/px) {2:0.00}% > ngưỡng {3:0.00}% " +
285	                        "— thường là sai cao độ đồ gá bản chuẩn, kiểm tra trước khi đổ cho camera (§6.3)",
286	                        scaleFromAxis, board.ScaleU, diffRatio * 100, sys.BottomUpScaleCrossCheckTolerance * 100);
287	
288	                LogWorker.Instance.RecordLog(
289	                    string.Format("Hiệu chuẩn CAM bottom-up: scale bản chuẩn {0:0.00000}, scale trục X {1:0.00000}, lệch {2:0.00}% — {3}",
290	                        board.ScaleU, scaleFromAxis, diffRatio * 100, result.Ok ? "ĐẠT" : "KHÔNG ĐẠT: " + result.Reason),
291	                    result.Ok ? Utility.Log.LogLevel.Info : Utility.Log.LogLevel.Warning, "Calib");
292	
293	                return result;
294	            }
295	            catch (OperationCanceledException)
296	            {
297	                return new BottomUpCalibResult { Ok = false, Reason = "bị huỷ" };
298	            }
299	            catch (Exception ex)
300	            {
301	                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
302	                return new BottomUpCalibResult { Ok = false, Reason = "lỗi bất thường: " + ex.Message };
303	            }
304	        }
305	
306	        // ───────────────────────── §6.4 Tâm xoay từng tay hút (VisionMaster, hiện dùng) ─────────────────────────
307	        //
308	        // Tâm xoay + Master của CAM bottom-up nay hiệu chuẩn bằng chính module N-point CÓ XOAY +
309	        // Teaching của VisionMaster (Tuấn chốt 2026-09-08), đúng khuôn đã làm cho CAM top-down
310	        // §6.2: 2 lệnh RỜI — xoay-và-chụp từng góc một, KHÔNG tính gì, KHÔNG ghi ModelData.Calib.
311	        // Phép hiệu chuẩn thực hiện thủ công bên trong VMEditControl (VisionMaster) bằng chính các
312	        // điểm đã chụp qua Flow AlignCalibTool{N}; hai lệnh này chỉ lo phần xoay trục + kích hoạt
313	        // Flow, đúng việc duy nhất phần mềm này còn cần làm cho quy trình đó.
314	
315	        /// <summary>Xoay trục A của tay <paramref name="nozzle"/> tới <paramref name="angleDeg"/>
316	        /// rồi kích hoạt Flow AlignCalib của đúng tay đó — dùng cho từng nút trong dãy góc hiệu
317	        /// chuẩn thủ công (gợi ý: <see cref="RotationCenterAngles"/>).</summary>
318	        public async Task<bool> MoveAndTriggerAlignCalibAsync(int nozzle, double angleDeg, CancellationToken ct)
319	        {
320	            string axisName = nozzle == 1 ? AxisId.A1 : AxisId.A2;
321	            var axis = _motion[axisName];
322	            if (axis == null) return false;
323	
324	            if (!await _func.MoveAsync(axisName, angleDeg, axis.Config.MoveSpeed, ct).ConfigureAwait(false))
325	                return false;
326	
327	            var proc = nozzle == 1 ? EVisionProcedure.AlignCalibTool1 : EVisionProcedure.AlignCalibTool2;
328	            var pose = await _vision().TriggerAsync(proc, ct).ConfigureAwait(false);
329	            return pose.Found;
330	        }
331	
332	        /// <summary>Kích hoạt Flow AlignCalib của tay <paramref name="nozzle"/> tại góc hiện tại,
333	        /// không xoay — dùng để test Flow riêng.</summary>
334	        public async Task<bool> TriggerAlignCalibFlowAsync(int nozzle, CancellationToken ct)
335	        {
336	            var proc = nozzle == 1 ? EVisionProcedure.AlignCalibTool1 : EVisionProcedure.AlignCalibTool2;
337	            var pose = await _vision().TriggerAsync(proc, ct).ConfigureAwait(false);
338	            return pose.Found;
339	        }
340	
341	        // ───────────────────────── §6.5 Hand-eye ─────────────────────────
342	
343	        /// <summary>
344	        /// Nửa đầu của phép đo hand-eye (PLAN.md §6.5): soi dấu chuẩn bằng CAM top-down ĐÃ HIỆU
345	        /// CHUẨN, trả về vị trí trục (X, Y2) nơi tâm ảnh sẽ trùng dấu chuẩn đó. Nửa sau — đưa đầu
346	        /// hút chạm đúng dấu chuẩn rồi đọc vị trí trục — là thao tác tay, trang Teaching đọc thẳng
347	        /// <c>CurrentPos</c> giống các nút Teach khác, không cần hàm riêng.
348	        /// </summary>
349	        public async Task<HandEyeMeasurement> MeasureHandEyeCameraPosAsync(CameraCalib topDownCalib, CancellationToken ct)
350	        {
351	            if (topDownCalib == null || !topDownCalib.IsCalibrated)
352	                return new HandEyeMeasurement { Ok = false, Reason = "chưa hiệu chuẩn CAM top-down — làm §6.2 trước" };
353	
354	            try
355	            {
356	                var pose = await CaptureAveragedAsync(EVisionProcedure.LocateTop, _sys().CalibShotsPerPoint, ct).ConfigureAwait(false);
357	                if (!pose.Found)
358	                    return new HandEyeMeasurement { Ok = false, Reason = pose.Error ?? "không thấy dấu chuẩn" };
359	
360	                double tdx, tdy;
361	                topDownCalib.ToMm(pose.PixelX, pose.PixelY, out tdx, out tdy);
362	
363	                return new HandEyeMeasurement
364	                {
365	                    Ok = true,
366	                    CamX = (_motion[AxisId.X]?.CurrentPos ?? 0) + tdx,
367	                    CamY = (_motion[AxisId.Y2]?.CurrentPos ?? 0) + tdy
368	                };
369	            }
370	            catch (OperationCanceledException)
371	            {
372	                return new HandEyeMeasurement { Ok = false, Reason = "bị huỷ" };
373	            }
374	            catch (Exception ex)
375	            {
376	                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
377	                return new HandEyeMeasurement { Ok = false, Reason = "lỗi bất thường: " + ex.Message };
378	            }
379	        }
380	
381	        // ───────────────────────── tiện ích ─────────────────────────
382	
383	        private async Task<VisionPose> CaptureAveragedAsync(EVisionProcedure proc, int shots, CancellationToken ct)
384	        {
385	            var vision = _vision();
386	            double sumX = 0, sumY = 0, sumA = 0;
387	            int ok = 0;
388	
389	            for (int i = 0; i < shots; i++)
390	            {
391	                if (ct.IsCancellationRequested) return VisionPose.NotFound("bị huỷ");
392	
393	                var p = await vision.TriggerAsync(proc, ct).ConfigureAwait(false);
394	                if (!p.Found) return VisionPose.NotFound(p.Error ?? "không tìm thấy đối tượng");
395	
396	                sumX += p.PixelX;
397	                sumY += p.PixelY;
398	                sumA += p.Angle;
399	                ok++;
400	            }
401	
402	            // PLAN §6.1 quy tắc 4: mỗi điểm chụp N ảnh, lấy trung bình vị trí pixel để khử nhiễu đo.
403	            return new VisionPose { Found = true, PixelX = sumX / ok, PixelY = sumY / ok, Angle = sumA / ok, Score = 100 };
404	        }
405	    }
406	}
