using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using ShieldCanAssy.Core.Communication;
using ShieldCanAssy.Core.Data;
using ShieldCanAssy.Core.Data.Model;
using ShieldCanAssy.Core.Infor;
using ShieldCanAssy.Utility.Log;

namespace ShieldCanAssy.Core.Controller
{
    public class TopDownCalibResult
    {
        public bool Ok { get; set; }
        public string Reason { get; set; }
        public AffineFitResult Fit { get; set; }
        public double VerifyErrorMm { get; set; }
        public bool VerifyOk { get; set; }
    }

    public class BottomUpCalibResult
    {
        public bool Ok { get; set; }
        public string Reason { get; set; }
        public CameraCalib Calib { get; set; }
        public int CornerCount { get; set; }
        public double SkewDeg { get; set; }
        public double ScaleFromBoard { get; set; }
        public double ScaleFromAxis { get; set; }
        public double ScaleCrossCheckDiffRatio { get; set; }
        public bool CrossCheckOk { get; set; }
    }

    public class HandEyeMeasurement
    {
        public bool Ok { get; set; }
        public string Reason { get; set; }

        /// <summary>Vị trí trục (X, Y2) nơi tâm ảnh CAM top-down trùng dấu chuẩn.</summary>
        public double CamX { get; set; }
        public double CamY { get; set; }
    }

    /// <summary>
    /// Hiệu chuẩn vision — PLAN.md §6. Bốn wizard độc lập, mỗi cái trả về một kết quả để trang
    /// Teaching cho operator XEM residual rồi mới quyết định lưu, chứ không tự ghi đè
    /// <c>ModelData.Calib</c> — "Không đạt → không cho lưu" (§6.1) là quyết định của người, không
    /// phải của routine.
    ///
    /// <para>Cũng vì vậy lớp này không giữ trạng thái <c>VisionCalib</c> nào cả: mọi hàm nhận
    /// calib cần thiết qua tham số (giống <see cref="PlacementSolver"/>) và trả về kết quả mới,
    /// không đọc/ghi <c>McDataManager.Model</c> trực tiếp.</para>
    /// </summary>
    public class Routine_Calib
    {
        private readonly MotionConnect _motion;
        private readonly McFunction _func;
        private readonly Func<SystemData> _sys;
        private readonly Func<IVisionDevice> _vision;

        public Routine_Calib(MotionConnect motion, McFunction func, Func<SystemData> sys, Func<IVisionDevice> vision)
        {
            _motion = motion;
            _func = func;
            _sys = sys;
            _vision = vision;
        }

        // ───────────────────────── §6.2 CAM top-down: lưới 9 điểm bằng trục máy ─────────────────────────

        /// <summary>
        /// Chạy lưới 3×3 quanh (<paramref name="centerX"/>, <paramref name="centerY"/>) — bước
        /// lấy từ <c>SystemData.TopDownCalibStepXMm/YMm</c> — rồi hồi quy affine pixel → (X, Y2).
        /// Sau đó chạy thêm một điểm kiểm chứng nằm ngoài lưới (PLAN.md §6.1 quy tắc 5).
        ///
        /// <para><paramref name="centerX"/>/<paramref name="centerY"/> là toạ độ trục X/Y2 operator
        /// đã jog tới trước khi bấm nút — trang Teaching đọc từ <c>CurrentPos</c>, giống hệt cách
        /// Teach điểm P00/P0C/PR0 đọc vị trí thật thay vì cho gõ tay (§8.2).</para>
        /// </summary>
        public async Task<TopDownCalibResult> CalibrateTopDownAsync(double centerX, double centerY, CancellationToken ct)
        {
            try
            {
                var sys = _sys();
                double stepX = sys.TopDownCalibStepXMm;
                double stepY = sys.TopDownCalibStepYMm;
                int shots = sys.CalibShotsPerPoint;

                var pts = new List<CalibPoint>();

                // PLAN §6.1 quy tắc 2: cùng một chiều tiếp cận. Quét kiểu "rắn bò" (serpentine)
                // để giảm số lần đảo chiều X xuống còn đúng một lần mỗi hàng, thay vì mọi điểm.
                // Chưa có số đo backlash thật nên chưa làm overshoot-rồi-lùi lại từng điểm — ghi
                // rõ ở đây để không ai tưởng nhầm đây đã là lời giải đầy đủ cho quy tắc 2.
                for (int r = -1; r <= 1; r++)
                {
                    bool reverse = (r == 0);
                    for (int ci = 0; ci <= 2; ci++)
                    {
                        int c = reverse ? (1 - ci) : (ci - 1);
                        var p = await CaptureGridPointAsync(centerX + c * stepX, centerY + r * stepY, shots, ct)
                            .ConfigureAwait(false);
                        if (p == null)
                            return new TopDownCalibResult { Ok = false, Reason = $"điểm lưới (hàng {r}, cột {c}) đo thất bại — dừng hiệu chuẩn" };
                        pts.Add(p.Value);
                    }
                }

                var fit = VisionCalibMath.FitAffine(pts);
                if (!fit.Ok)
                    return new TopDownCalibResult { Ok = false, Reason = fit.Reason, Fit = fit };

                bool accepted = fit.RmsResidual <= sys.CalibRmsThresholdMm && fit.MaxResidual <= sys.CalibMaxResidualThresholdMm;
                var result = new TopDownCalibResult { Ok = accepted, Fit = fit };
                if (!accepted)
                    result.Reason = string.Format(
                        "RMS {0:0.000} mm / max {1:0.000} mm vượt ngưỡng {2:0.000} / {3:0.000} mm — không lưu",
                        fit.RmsResidual, fit.MaxResidual, sys.CalibRmsThresholdMm, sys.CalibMaxResidualThresholdMm);

                // Điểm kiểm chứng thứ 10, cố ý nằm ngoài lưới 3×3 (PLAN §6.1 quy tắc 5): residual
                // của 9 điểm gốc luôn lạc quan hơn thực tế vì chính chúng tham gia fit ra ma trận.
                double vx = centerX + 1.5 * stepX;
                double vy = centerY + 1.5 * stepY;
                var verify = await CaptureGridPointAsync(vx, vy, shots, ct).ConfigureAwait(false);
                if (verify == null)
                {
                    result.Reason = (result.Reason == null ? "" : result.Reason + "; ") + "điểm kiểm chứng đo thất bại";
                }
                else
                {
                    double predX, predY;
                    fit.Calib.ToMm(verify.Value.U, verify.Value.V, out predX, out predY);
                    double ex = predX - verify.Value.X;
                    double ey = predY - verify.Value.Y;
                    result.VerifyErrorMm = Math.Sqrt(ex * ex + ey * ey);
                    result.VerifyOk = result.VerifyErrorMm <= sys.CalibMaxResidualThresholdMm;
                    result.Ok = result.Ok && result.VerifyOk;
                    if (!result.VerifyOk)
                        result.Reason = (result.Reason == null ? "" : result.Reason + "; ") +
                            string.Format("điểm kiểm chứng lệch {0:0.000} mm > ngưỡng {1:0.000} mm", result.VerifyErrorMm, sys.CalibMaxResidualThresholdMm);
                }

                LogWorker.Instance.RecordLog(
                    string.Format("Hiệu chuẩn CAM top-down: RMS {0:0.000} mm, max {1:0.000} mm, verify {2:0.000} mm — {3}",
                        fit.RmsResidual, fit.MaxResidual, result.VerifyErrorMm, result.Ok ? "ĐẠT" : "KHÔNG ĐẠT: " + result.Reason),
                    result.Ok ? Utility.Log.LogLevel.Info : Utility.Log.LogLevel.Warning, "Calib");

                return result;
            }
            catch (OperationCanceledException)
            {
                return new TopDownCalibResult { Ok = false, Reason = "bị huỷ" };
            }
            catch (Exception ex)
            {
                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
                return new TopDownCalibResult { Ok = false, Reason = "lỗi bất thường: " + ex.Message };
            }
        }

        private async Task<CalibPoint?> CaptureGridPointAsync(double x, double y2, int shots, CancellationToken ct)
        {
            if (!await _func.MoveToCellAsync(AxisId.Y2, y2, x, ct).ConfigureAwait(false))
                return null;

            var pose = await CaptureAveragedAsync(EVisionProcedure.LocateTop, shots, ct).ConfigureAwait(false);
            if (!pose.Found) return null;

            // PLAN §6.1 quy tắc 3: ghi ActualPosition đọc từ encoder SAU khi lệnh move đã xác
            // nhận tới đích, không phải giá trị lệnh (x, y2) đưa vào.
            double actualX = _motion[AxisId.X]?.CurrentPos ?? x;
            double actualY = _motion[AxisId.Y2]?.CurrentPos ?? y2;
            return new CalibPoint(pose.PixelX, pose.PixelY, actualX, actualY);
        }

        // ───────────────────────── §6.2b lưới 9 điểm thủ công (trang Vision Edit) ─────────────────────────
        //
        // Khác CalibrateTopDownAsync ở trên (quét 9 điểm tự động, tự fit affine, tự đề xuất lưu):
        // đây là 2 lệnh RỜI — di chuyển-và-chụp từng điểm một, KHÔNG tính affine, KHÔNG ghi
        // ModelData.Calib. Phép hiệu chuẩn thực hiện thủ công bên trong VMEditControl (VisionMaster)
        // bằng chính các điểm đã chụp qua Flow TopDownCalib; hai lệnh này chỉ lo phần di chuyển +
        // kích hoạt Flow, đúng việc duy nhất phần mềm này còn cần làm cho quy trình đó.

        /// <summary>Di chuyển tới (x, y2) rồi kích hoạt Flow TopDownCalib — dùng cho từng nút trong
        /// lưới 9 điểm thủ công. Trả về false nếu di chuyển thất bại hoặc Flow báo không tìm thấy.</summary>
        public async Task<bool> MoveAndTriggerTopDownCalibAsync(double x, double y2, CancellationToken ct)
        {
            if (!await _func.MoveToCellAsync(AxisId.Y2, y2, x, ct).ConfigureAwait(false))
                return false;

            var pose = await _vision().TriggerAsync(EVisionProcedure.TopDownCalib, ct).ConfigureAwait(false);
            return pose.Found;
        }

        /// <summary>Kích hoạt Flow TopDownCalib tại vị trí hiện tại, không di chuyển — dùng để test
        /// Flow riêng hoặc chụp điểm giữa (điểm 5, tâm khung hình, không cần offset).</summary>
        public async Task<bool> TriggerTopDownCalibFlowAsync(CancellationToken ct)
        {
            var pose = await _vision().TriggerAsync(EVisionProcedure.TopDownCalib, ct).ConfigureAwait(false);
            return pose.Found;
        }

        // ───────────────────────── §6.3 CAM bottom-up: checkerboard ─────────────────────────

        /// <summary>
        /// B2 + B3 + B4 (PLAN.md §6.3). <paramref name="xProbe1"/>/<paramref name="xProbe2"/> là
        /// hai vị trí X đã biết, khác nhau đủ xa (vài mm trở lên) và vẫn giữ được bản chuẩn trong
        /// khung hình — operator chọn khi jog thử trước lúc bấm nút.
        /// </summary>
        public async Task<BottomUpCalibResult> CalibrateBottomUpAsync(double xProbe1, double xProbe2, CancellationToken ct)
        {
            try
            {
                var sys = _sys();
                var vision = _vision();

                // B2: công cụ hiệu chuẩn bản chuẩn của VisionMaster tính scale/độ không vuông góc
                // từ hàng trăm góc trong một ảnh.
                var board = await vision.TriggerCalibBoardAsync(ct).ConfigureAwait(false);
                if (!board.Found)
                    return new BottomUpCalibResult { Ok = false, Reason = board.Error ?? "không đọc được bản chuẩn — kiểm tra tấm checkerboard trong khung hình" };

                // B4: ghép thành ma trận affine. Gốc đặt tại pixel (0,0) — PlacementSolver chỉ dùng
                // toạ độ TƯƠNG ĐỐI (p − C_i) nên hằng số gốc không ảnh hưởng kết quả cuối, miễn
                // nhất quán trong toàn bộ VisionCalib này.
                // BottomUpYSign KHÔNG ghép ở đây — PlacementSolver tự nhân dấu đó riêng (§6.3 cuối).
                double skewRad = board.SkewDeg * Math.PI / 180.0;
                var calib = new CameraCalib
                {
                    B11 = board.ScaleU,
                    B12 = board.ScaleU * Math.Sin(skewRad),
                    B13 = 0,
                    B21 = 0,
                    B22 = board.ScaleV,
                    B23 = 0,
                    Method = "checkerboard 1×1 mm (bottom-up)",
                    PointCount = board.CornerCount
                };

                var result = new BottomUpCalibResult
                {
                    Calib = calib,
                    CornerCount = board.CornerCount,
                    SkewDeg = board.SkewDeg,
                    ScaleFromBoard = board.ScaleU
                };

                // B3: chạy X tới 2 vị trí đã biết, đối chiếu chéo scale đo bằng trục máy với scale
                // đo bằng bản chuẩn — phép thử duy nhất bắt được lỗi cao độ đồ gá.
                if (!await _func.MoveAsync(AxisId.X, xProbe1, sys.GetAxis(AxisId.X).MoveSpeed, ct).ConfigureAwait(false))
                    return new BottomUpCalibResult { Ok = false, Reason = "không di chuyển được tới điểm đối chiếu 1" };
                var board1 = await vision.TriggerCalibBoardAsync(ct).ConfigureAwait(false);
                double axisPos1 = _motion[AxisId.X]?.CurrentPos ?? xProbe1;

                if (!await _func.MoveAsync(AxisId.X, xProbe2, sys.GetAxis(AxisId.X).MoveSpeed, ct).ConfigureAwait(false))
                    return new BottomUpCalibResult { Ok = false, Reason = "không di chuyển được tới điểm đối chiếu 2" };
                var board2 = await vision.TriggerCalibBoardAsync(ct).ConfigureAwait(false);
                double axisPos2 = _motion[AxisId.X]?.CurrentPos ?? xProbe2;

                if (!board1.Found || !board2.Found)
                {
                    result.Reason = "không thấy bản chuẩn tại điểm đối chiếu — kiểm tra khung hình";
                    return result;
                }

                double axisDeltaMm = Math.Abs(axisPos2 - axisPos1);
                double pixelDeltaU = Math.Abs(board2.OriginPixelU - board1.OriginPixelU);
                if (axisDeltaMm < 1e-6 || pixelDeltaU < 1e-6)
                {
                    result.Reason = "hai điểm đối chiếu trùng nhau hoặc góc mốc không dịch chuyển — chọn lại vị trí";
                    return result;
                }

                double scaleFromAxis = axisDeltaMm / pixelDeltaU;
                double diffRatio = Math.Abs(scaleFromAxis - board.ScaleU) / board.ScaleU;

                result.ScaleFromAxis = scaleFromAxis;
                result.ScaleCrossCheckDiffRatio = diffRatio;
                result.CrossCheckOk = diffRatio <= sys.BottomUpScaleCrossCheckTolerance;
                result.Ok = result.CrossCheckOk;
                if (!result.CrossCheckOk)
                    result.Reason = string.Format(
                        "scale theo trục X ({0:0.00000} mm/px) lệch bản chuẩn ({1:0.00000} mm/px) {2:0.00}% > ngưỡng {3:0.00}% " +
                        "— thường là sai cao độ đồ gá bản chuẩn, kiểm tra trước khi đổ cho camera (§6.3)",
                        scaleFromAxis, board.ScaleU, diffRatio * 100, sys.BottomUpScaleCrossCheckTolerance * 100);

                LogWorker.Instance.RecordLog(
                    string.Format("Hiệu chuẩn CAM bottom-up: scale bản chuẩn {0:0.00000}, scale trục X {1:0.00000}, lệch {2:0.00}% — {3}",
                        board.ScaleU, scaleFromAxis, diffRatio * 100, result.Ok ? "ĐẠT" : "KHÔNG ĐẠT: " + result.Reason),
                    result.Ok ? Utility.Log.LogLevel.Info : Utility.Log.LogLevel.Warning, "Calib");

                return result;
            }
            catch (OperationCanceledException)
            {
                return new BottomUpCalibResult { Ok = false, Reason = "bị huỷ" };
            }
            catch (Exception ex)
            {
                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
                return new BottomUpCalibResult { Ok = false, Reason = "lỗi bất thường: " + ex.Message };
            }
        }

        // ───────────────────────── §6.4 Tâm xoay từng tay hút (VisionMaster, hiện dùng) ─────────────────────────
        //
        // Tâm xoay + Master của CAM bottom-up nay hiệu chuẩn bằng chính module N-point CÓ XOAY +
        // Teaching của VisionMaster (Tuấn chốt 2026-09-08), đúng khuôn đã làm cho CAM top-down
        // §6.2: 2 lệnh RỜI — xoay-và-chụp từng góc một, KHÔNG tính gì, KHÔNG ghi ModelData.Calib.
        // Phép hiệu chuẩn thực hiện thủ công bên trong VMEditControl (VisionMaster) bằng chính các
        // điểm đã chụp qua Flow AlignCalibTool{N}; hai lệnh này chỉ lo phần xoay trục + kích hoạt
        // Flow, đúng việc duy nhất phần mềm này còn cần làm cho quy trình đó.

        /// <summary>Xoay trục A của tay <paramref name="nozzle"/> tới <paramref name="angleDeg"/>
        /// rồi kích hoạt Flow AlignCalib của đúng tay đó — dùng cho từng nút trong dãy góc hiệu
        /// chuẩn thủ công (gợi ý: <see cref="RotationCenterAngles"/>).</summary>
        public async Task<bool> MoveAndTriggerAlignCalibAsync(int nozzle, double angleDeg, CancellationToken ct)
        {
            string axisName = nozzle == 1 ? AxisId.A1 : AxisId.A2;
            var axis = _motion[axisName];
            if (axis == null) return false;

            if (!await _func.MoveAsync(axisName, angleDeg, axis.Config.MoveSpeed, ct).ConfigureAwait(false))
                return false;

            var proc = nozzle == 1 ? EVisionProcedure.AlignCalibTool1 : EVisionProcedure.AlignCalibTool2;
            var pose = await _vision().TriggerAsync(proc, ct).ConfigureAwait(false);
            return pose.Found;
        }

        /// <summary>Kích hoạt Flow AlignCalib của tay <paramref name="nozzle"/> tại góc hiện tại,
        /// không xoay — dùng để test Flow riêng.</summary>
        public async Task<bool> TriggerAlignCalibFlowAsync(int nozzle, CancellationToken ct)
        {
            var proc = nozzle == 1 ? EVisionProcedure.AlignCalibTool1 : EVisionProcedure.AlignCalibTool2;
            var pose = await _vision().TriggerAsync(proc, ct).ConfigureAwait(false);
            return pose.Found;
        }

        // ───────────────────────── §6.5 Hand-eye ─────────────────────────

        /// <summary>
        /// Nửa đầu của phép đo hand-eye (PLAN.md §6.5): soi dấu chuẩn bằng CAM top-down ĐÃ HIỆU
        /// CHUẨN, trả về vị trí trục (X, Y2) nơi tâm ảnh sẽ trùng dấu chuẩn đó. Nửa sau — đưa đầu
        /// hút chạm đúng dấu chuẩn rồi đọc vị trí trục — là thao tác tay, trang Teaching đọc thẳng
        /// <c>CurrentPos</c> giống các nút Teach khác, không cần hàm riêng.
        /// </summary>
        public async Task<HandEyeMeasurement> MeasureHandEyeCameraPosAsync(CameraCalib topDownCalib, CancellationToken ct)
        {
            if (topDownCalib == null || !topDownCalib.IsCalibrated)
                return new HandEyeMeasurement { Ok = false, Reason = "chưa hiệu chuẩn CAM top-down — làm §6.2 trước" };

            try
            {
                var pose = await CaptureAveragedAsync(EVisionProcedure.LocateTop, _sys().CalibShotsPerPoint, ct).ConfigureAwait(false);
                if (!pose.Found)
                    return new HandEyeMeasurement { Ok = false, Reason = pose.Error ?? "không thấy dấu chuẩn" };

                double tdx, tdy;
                topDownCalib.ToMm(pose.PixelX, pose.PixelY, out tdx, out tdy);

                return new HandEyeMeasurement
                {
                    Ok = true,
                    CamX = (_motion[AxisId.X]?.CurrentPos ?? 0) + tdx,
                    CamY = (_motion[AxisId.Y2]?.CurrentPos ?? 0) + tdy
                };
            }
            catch (OperationCanceledException)
            {
                return new HandEyeMeasurement { Ok = false, Reason = "bị huỷ" };
            }
            catch (Exception ex)
            {
                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
                return new HandEyeMeasurement { Ok = false, Reason = "lỗi bất thường: " + ex.Message };
            }
        }

        // ───────────────────────── tiện ích ─────────────────────────

        private async Task<VisionPose> CaptureAveragedAsync(EVisionProcedure proc, int shots, CancellationToken ct)
        {
            var vision = _vision();
            double sumX = 0, sumY = 0, sumA = 0;
            int ok = 0;

            for (int i = 0; i < shots; i++)
            {
                if (ct.IsCancellationRequested) return VisionPose.NotFound("bị huỷ");

                var p = await vision.TriggerAsync(proc, ct).ConfigureAwait(false);
                if (!p.Found) return VisionPose.NotFound(p.Error ?? "không tìm thấy đối tượng");

                sumX += p.PixelX;
                sumY += p.PixelY;
                sumA += p.Angle;
                ok++;
            }

            // PLAN §6.1 quy tắc 4: mỗi điểm chụp N ảnh, lấy trung bình vị trí pixel để khử nhiễu đo.
            return new VisionPose { Found = true, PixelX = sumX / ok, PixelY = sumY / ok, Angle = sumA / ok, Score = 100 };
        }
    }
}

