18	    /// §6.1): mọi hàm dưới đây chỉ ghi vào Calib khi wizard báo Ok, còn ghi xuống ĐĨA vẫn phải
19	    /// bấm nút Lưu model riêng (trang Teaching) — hai bước tách biệt để operator luôn được xem
20	    /// residual trước khi quyết định.
21	    ///
22	    /// <para>Hiệu chuẩn Align + hand-eye vốn có 2 khối UI riêng cho tay #1/#2 (bản gốc ở Teaching page,
23	    /// đủ rộng để đặt song song) — cột hẹp hơn ở đây chỉ đủ chỗ 1 khối, nên gộp thành 1 bộ control
24	    /// dùng chung, chuyển ngữ cảnh bằng <see cref="SelectedTool"/> ("Tool 1"/"Tool 2" — chính là
25	    /// tay hút #1/#2 đã có, không phải khái niệm mới).</para>
26	    /// </summary>
27	    public class VisionCalibViewModel : ObservableObject
28	    {
29	        private readonly IDialogService _dialog = new DialogService();
30	
31	        public VisionCalibViewModel()
32	        {
33	            // 9 command riêng thay vì 1 command tham số hoá (int) — CommandParameter gõ thẳng số
34	            // trong XAML (vd. CommandParameter="7") tới tay ICommand.Execute dưới dạng string, không
35	            // tự ép kiểu sang int (khác trường hợp CommandParameter="{Binding}" trỏ object thật) —
36	            // RelayCommand<T>.Execute lặng lẽ dùng default(T) khi ép kiểu thất bại, sai điểm mà
37	            // không có lỗi nào báo. Đóng luôn số điểm vào closure là tránh hẳn lớp lỗi đó.
38	            TopDownPoint1Command = new RelayCommand(async () => await RunTopDownGridPointAsync(1));
39	            TopDownPoint2Command = new RelayCommand(async () => await RunTopDownGridPointAsync(2));
40	            TopDownPoint3Command = new RelayCommand(async () => await RunTopDownGridPointAsync(3));
41	            TopDownPoint4Command = new RelayCommand(async () => await RunTopDownGridPointAsync(4));
42	            TopDownPoint5Command = new RelayCommand(async () => await RunTopDownGridPointAsync(5));
43	            TopDownPoint6Command = new RelayCommand(async () => await RunTopDownGridPointAsync(6));
44	            TopDownPoint7Command = new RelayCommand(async () => await RunTopDownGridPointAsync(7));
45	            TopDownPoint8Command = new RelayCommand(async () => await RunTopDownGridPointAsync(8));
46	            TopDownPoint9Command = new RelayCommand(async () => await RunTopDownGridPointAsync(9));
47	            SaveCalibrationCenterCommand = new RelayCommand(SaveCalibrationCenter);
48	            AutoCalibCommand = new RelayCommand(async () => await RunAutoCalibAsync());
49	            TriggerTopDownFlowCommand = new RelayCommand(async () => await TriggerTopDownFlowAsync());
50	            RunBottomUpCalibCommand = new RelayCommand(async () => await RunBottomUpCalibAsync());
51	            // Hiệu chuẩn Align (tâm xoay + Master) — 6 góc cố định, mỗi nút đóng góc vào closure
52	            // giống hệt 9 nút numpad CAM top-down ở trên (cùng lý do: CommandParameter gõ số
53	            // trong XAML tới ICommand.Execute dưới dạng string, RelayCommand<T> ép kiểu lặng lẽ
54	            // ra default(T) khi thất bại — đóng số vào closure tránh hẳn lớp lỗi đó).
55	            RunAlignCalibAngle0Command = new RelayCommand(async () => await RunAlignCalibPointAsync(0));
56	            RunAlignCalibAngle60Command = new RelayCommand(async () => await RunAlignCalibPointAsync(60));
57	            RunAlignCalibAngle120Command = new RelayCommand(async () => await RunAlignCalibPointAsync(120));
58	            RunAlignCalibAngle180Command = new RelayCommand(async () => await RunAlignCalibPointAsync(180));
59	            RunAlignCalibAngle240Command = new RelayCommand(async () => await RunAlignCalibPointAsync(240));
60	            RunAlignCalibAngle300Command = new RelayCommand(async () => await RunAlignCalibPointAsync(300));
61	            TriggerAlignCalibFlowCommand = new RelayCommand(async () => await TriggerAlignCalibFlowAsync());
62	            MeasureHandEyeCommand = new RelayCommand(async () => await MeasureHandEyeCameraAsync(SelectedTool));
63	            CommitHandEyeCommand = new RelayCommand(() => CommitHandEye(SelectedTool));
64	            SetYSignPositiveCommand = new RelayCommand(() => SetBottomUpYSign(1));
65	            SetYSignNegativeCommand = new RelayCommand(() => SetBottomUpYSign(-1));
66	
67	            RefreshCalibText();
68	        }
