using System;
using System.Threading.Tasks;
using System.Windows.Input;
using ShieldCanAssy.Core.Controller;
using ShieldCanAssy.Core.Data;
using ShieldCanAssy.Core.Data.Model;
using ShieldCanAssy.Core.Infor;
using ShieldCanAssy.Wpf.Mvvm;
using ShieldCanAssy.Wpf.Services;

namespace ShieldCanAssy.Wpf.ViewModels
{
    /// <summary>
    /// Hiệu chuẩn vision (§6) — DataContext cột phải trang Vision Edit. Tách từ TeachingViewModel
    /// sang đây để gộp chung với công cụ sửa solution VisionMaster (VisionEditView), một chỗ khi
    /// cần chỉnh cả hai. Wizard hiệu chuẩn dùng chung MỘT VisionCalib của cả model
    /// (McDataManager.Model.Calib) — không phụ thuộc tray nào. "Không đạt → không cho lưu" (PLAN
    /// §6.1): mọi hàm dưới đây chỉ ghi vào Calib khi wizard báo Ok, còn ghi xuống ĐĨA vẫn phải
    /// bấm nút Lưu model riêng (trang Teaching) — hai bước tách biệt để operator luôn được xem
    /// residual trước khi quyết định.
    ///
    /// <para>Hiệu chuẩn Align + hand-eye vốn có 2 khối UI riêng cho tay #1/#2 (bản gốc ở Teaching page,
    /// đủ rộng để đặt song song) — cột hẹp hơn ở đây chỉ đủ chỗ 1 khối, nên gộp thành 1 bộ control
    /// dùng chung, chuyển ngữ cảnh bằng <see cref="SelectedTool"/> ("Tool 1"/"Tool 2" — chính là
    /// tay hút #1/#2 đã có, không phải khái niệm mới).</para>
    /// </summary>
    public class VisionCalibViewModel : ObservableObject
    {
        private readonly IDialogService _dialog = new DialogService();

        public VisionCalibViewModel()
        {
            // 9 command riêng thay vì 1 command tham số hoá (int) — CommandParameter gõ thẳng số
            // trong XAML (vd. CommandParameter="7") tới tay ICommand.Execute dưới dạng string, không
            // tự ép kiểu sang int (khác trường hợp CommandParameter="{Binding}" trỏ object thật) —
            // RelayCommand<T>.Execute lặng lẽ dùng default(T) khi ép kiểu thất bại, sai điểm mà
            // không có lỗi nào báo. Đóng luôn số điểm vào closure là tránh hẳn lớp lỗi đó.
            TopDownPoint1Command = new RelayCommand(async () => await RunTopDownGridPointAsync(1));
            TopDownPoint2Command = new RelayCommand(async () => await RunTopDownGridPointAsync(2));
            TopDownPoint3Command = new RelayCommand(async () => await RunTopDownGridPointAsync(3));
            TopDownPoint4Command = new RelayCommand(async () => await RunTopDownGridPointAsync(4));
            TopDownPoint5Command = new RelayCommand(async () => await RunTopDownGridPointAsync(5));
            TopDownPoint6Command = new RelayCommand(async () => await RunTopDownGridPointAsync(6));
            TopDownPoint7Command = new RelayCommand(async () => await RunTopDownGridPointAsync(7));
            TopDownPoint8Command = new RelayCommand(async () => await RunTopDownGridPointAsync(8));
            TopDownPoint9Command = new RelayCommand(async () => await RunTopDownGridPointAsync(9));
            SaveCalibrationCenterCommand = new RelayCommand(SaveCalibrationCenter);
            AutoCalibCommand = new RelayCommand(async () => await RunAutoCalibAsync());
            TriggerTopDownFlowCommand = new RelayCommand(async () => await TriggerTopDownFlowAsync());
            RunBottomUpCalibCommand = new RelayCommand(async () => await RunBottomUpCalibAsync());
            // Hiệu chuẩn Align (tâm xoay + Master) — 6 góc cố định, mỗi nút đóng góc vào closure
            // giống hệt 9 nút numpad CAM top-down ở trên (cùng lý do: CommandParameter gõ số
            // trong XAML tới ICommand.Execute dưới dạng string, RelayCommand<T> ép kiểu lặng lẽ
            // ra default(T) khi thất bại — đóng số vào closure tránh hẳn lớp lỗi đó).
            RunAlignCalibAngle0Command = new RelayCommand(async () => await RunAlignCalibPointAsync(0));
            RunAlignCalibAngle60Command = new RelayCommand(async () => await RunAlignCalibPointAsync(60));
            RunAlignCalibAngle120Command = new RelayCommand(async () => await RunAlignCalibPointAsync(120));
            RunAlignCalibAngle180Command = new RelayCommand(async () => await RunAlignCalibPointAsync(180));
            RunAlignCalibAngle240Command = new RelayCommand(async () => await RunAlignCalibPointAsync(240));
            RunAlignCalibAngle300Command = new RelayCommand(async () => await RunAlignCalibPointAsync(300));
            TriggerAlignCalibFlowCommand = new RelayCommand(async () => await TriggerAlignCalibFlowAsync());
            MeasureHandEyeCommand = new RelayCommand(async () => await MeasureHandEyeCameraAsync(SelectedTool));
            CommitHandEyeCommand = new RelayCommand(() => CommitHandEye(SelectedTool));
            SetYSignPositiveCommand = new RelayCommand(() => SetBottomUpYSign(1));
            SetYSignNegativeCommand = new RelayCommand(() => SetBottomUpYSign(-1));

            RefreshCalibText();
        }

        private VisionCalib Calib => McDataManager.Model.Calib;

        private bool _busy;
        public bool Busy { get => _busy; private set => SetProperty(ref _busy, value); }

        // ───────────────────────── chọn Tool (tay hút #1/#2) ─────────────────────────

        private int _selectedTool = 1;
        public int SelectedTool
        {
            get => _selectedTool;
            private set
            {
                if (SetProperty(ref _selectedTool, value))
                {
                    OnPropertyChanged(nameof(IsTool1));
                    OnPropertyChanged(nameof(IsTool2));
                    RefreshCalibText();
                }
            }
        }

        public bool IsTool1 { get => SelectedTool == 1; set { if (value) SelectedTool = 1; } }
        public bool IsTool2 { get => SelectedTool == 2; set { if (value) SelectedTool = 2; } }

        // ───────────────────────── CAM top-down / bottom-up (chung, không theo Tool) ─────────────────────────

        public string TopDownStatusText => StatusText(Calib.TopDown, "9 điểm bằng trục máy");
        public string BottomUpStatusText => StatusText(Calib.BottomUp, "checkerboard 1×1 mm");

        /// <summary>Bước lưới 9 điểm CAM top-down, mm — pass-through thẳng vào SystemData (đọc/ghi
        /// cùng đối tượng đang chạy, không có bản sao riêng) để đổi ở đây là dùng ngay cho lần bấm
        /// điểm kế tiếp, không cần sang trang Setting.</summary>
        public double TopDownCalibStepXMm
        {
            get => McDataManager.SysData.TopDownCalibStepXMm;
            set { McDataManager.SysData.TopDownCalibStepXMm = value; OnPropertyChanged(); }
        }

        public double TopDownCalibStepYMm
        {
            get => McDataManager.SysData.TopDownCalibStepYMm;
            set { McDataManager.SysData.TopDownCalibStepYMm = value; OnPropertyChanged(); }
        }

        private double _bottomUpProbeDeltaX = 20.0;
        /// <summary>Khoảng cách chạy X để đối chiếu chéo B3 (PLAN §6.3) — vài mm trở lên, vẫn
        /// phải giữ được bản chuẩn trong khung hình cả hai đầu.</summary>
        public double BottomUpProbeDeltaX { get => _bottomUpProbeDeltaX; set => SetProperty(ref _bottomUpProbeDeltaX, value); }

        public string BottomUpYSignText => Calib.BottomUpYSignVerifiedAt > DateTime.MinValue
            ? $"{(Calib.BottomUpYSign > 0 ? "+1" : "−1")}  (xác minh {Calib.BottomUpYSignVerifiedAt:dd/MM/yyyy})"
            : "CHƯA xác minh bằng phép thử vật lý — §6.3";

        // ───────────────────────── hand-eye (theo Tool đang chọn) ─────────────────────────

        public string HandEyeStatusText => SelectedTool == 1
            ? $"dx={Calib.HandEye1Dx:0.000}, dy={Calib.HandEye1Dy:0.000} mm"
            : $"dx={Calib.HandEye2Dx:0.000}, dy={Calib.HandEye2Dy:0.000} mm";

        private string StatusText(CameraCalib c, string expectMethod)
        {
            if (!c.IsCalibrated) return "Chưa hiệu chuẩn";
            bool expired = c.IsExpired(McDataManager.SysData.CalibValidDays);
            return string.Format("{0}{1} — {2:dd/MM/yyyy HH:mm} — scale {3:0.00000}/{4:0.00000} mm/px, " +
                "góc {5:0.00}°, RMS {6:0.000} mm, max {7:0.000} mm, {8} điểm",
                expired ? "HẾT HẠN — " : "", c.Method ?? expectMethod, c.CalibratedAt,
                c.ScaleX, c.ScaleY, c.RotationDeg, c.RmsResidual, c.MaxResidual, c.PointCount);
        }

        private void RefreshCalibText()
        {
            OnPropertyChanged(nameof(TopDownStatusText));
            OnPropertyChanged(nameof(BottomUpStatusText));
            OnPropertyChanged(nameof(HandEyeStatusText));
            OnPropertyChanged(nameof(BottomUpYSignText));
        }

        // ───────────────────────── lưới 9 điểm thủ công (numpad) ─────────────────────────
        //
        // Thay quét 9 điểm tự động + tự fit affine (Routine_Calib.CalibrateTopDownAsync, vẫn còn
        // trong Core nhưng không còn nút gọi ở đây) bằng 9 nút bấm tay, đánh số kiểu numpad khớp
        // hình người dùng minh hoạ (dưới 1,2,3 — giữa 4,5,6 — trên 7,8,9). Phép hiệu chuẩn (fit
        // affine) làm THỦ CÔNG trong VMEditControl (cột trái trang này) từ chính các điểm đã chụp
        // qua Flow TopDownCalib — phần mềm chỉ còn lo di chuyển + kích hoạt Flow.

        /// <summary>"Calibration Center Point" — toạ độ (X, Y2) ứng với điểm 5 (giữa khung hình),
        /// lưu bằng nút Save sau khi jog máy tới đó qua trang Manual. Pass-through vào SystemData
        /// (persist qua McDataManager.SaveSystemData như mọi cấu hình khác) — KHÁC bản trước đọc
        /// CurrentPos ngay lúc bấm điểm 5: giờ Save và Dùng là 2 bước tách biệt, không phải jog
        /// lại tâm mỗi lần mở app hay muốn chụp lại một điểm lẻ.</summary>
        public double CalibrationCenterX
        {
            get => McDataManager.SysData.TopDownCalibCenterX;
            set { McDataManager.SysData.TopDownCalibCenterX = value; OnPropertyChanged(); }
        }

        public double CalibrationCenterY
        {
            get => McDataManager.SysData.TopDownCalibCenterY;
            set { McDataManager.SysData.TopDownCalibCenterY = value; OnPropertyChanged(); }
        }

        /// <summary>Phân biệt "chưa từng Save" với "đã Save đúng tại (0,0)" — 2 giá trị double mặc
        /// định 0 không tự nói lên được điều đó.</summary>
        public bool CalibrationCenterSet
        {
            get => McDataManager.SysData.TopDownCalibCenterSet;
            set { McDataManager.SysData.TopDownCalibCenterSet = value; OnPropertyChanged(); OnPropertyChanged(nameof(CalibrationCenterStatusText)); }
        }

        public string CalibrationCenterStatusText => CalibrationCenterSet ? "(đã lưu)" : "(chưa lưu)";

        /// <summary>Đọc vị trí trục (X, Y2) HIỆN TẠI (operator đã jog qua trang Manual tới đúng
        /// giữa khung hình) rồi lưu làm Calibration Center Point.</summary>
        private void SaveCalibrationCenter()
        {
            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — toạ độ đọc lúc này không có ý nghĩa."); return; }

            CalibrationCenterX = McControl.Motion[AxisId.X].CurrentPos;
            CalibrationCenterY = McControl.Motion[AxisId.Y2].CurrentPos;
            CalibrationCenterSet = true;
            _dialog.Info(string.Format("Đã lưu Calibration Center Point: ({0:0.000}, {1:0.000}).",
                CalibrationCenterX, CalibrationCenterY));
        }

        /// <summary>Di chuyển tới điểm numpad <paramref name="number"/> (offset từ
        /// <see cref="CalibrationCenterX"/>/<see cref="CalibrationCenterY"/> theo
        /// <see cref="TopDownCalibStepXMm"/>/<see cref="TopDownCalibStepYMm"/>) rồi kích hoạt Flow
        /// TopDownCalib. Numpad: hàng trên (7,8,9) row=+1, hàng dưới (1,2,3) row=-1; cột trái
        /// (1,4,7) col=-1, cột phải (3,6,9) col=+1; điểm 5 = offset (0,0), đúng tâm đã lưu.</summary>
        private async Task<bool> MoveAndTriggerGridPointAsync(int number)
        {
            int rowMul, colMul;
            TopDownGridOffset(number, out rowMul, out colMul);
            double x = CalibrationCenterX + colMul * TopDownCalibStepXMm;
            double y = CalibrationCenterY + rowMul * TopDownCalibStepYMm;
            return await McControl.Calib.MoveAndTriggerTopDownCalibAsync(x, y, McControl.Safety.AbortToken).ConfigureAwait(true);
        }

        /// <summary>Số numpad 1-9 → (hệ số hàng, hệ số cột) quanh tâm, khớp hình minh hoạ người
        /// dùng gửi (1,2,3 hàng dưới; 4,5,6 hàng giữa; 7,8,9 hàng trên).</summary>
        private static void TopDownGridOffset(int number, out int rowMul, out int colMul)
        {
            int idx = number - 1;
            rowMul = idx / 3 - 1;
            colMul = idx % 3 - 1;
        }

        private bool CheckReadyForGrid()
        {
            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước khi hiệu chuẩn."); return false; }
            if (!CalibrationCenterSet) { _dialog.Warn("Chưa lưu Calibration Center Point — jog tới giữa khung hình rồi bấm Save trước."); return false; }
            return true;
        }

        private async Task RunTopDownGridPointAsync(int number)
        {
            if (Busy || !CheckReadyForGrid()) return;

            Busy = true;
            try
            {
                bool ok = await MoveAndTriggerGridPointAsync(number).ConfigureAwait(true);
                if (!ok) _dialog.Warn($"Điểm {number}: di chuyển hoặc Flow TopDownCalib thất bại — kiểm tra lại.");
            }
            finally { Busy = false; }
        }

        /// <summary>Auto Calib — chạy tuần tự cả 9 điểm (1→9) không cần bấm tay từng nút, dừng lại
        /// ngay khi một điểm thất bại thay vì âm thầm bỏ qua rồi báo "xong" sai sự thật.</summary>
        private async Task RunAutoCalibAsync()
        {
            if (Busy || !CheckReadyForGrid()) return;

            Busy = true;
            try
            {
                for (int number = 1; number <= 9; number++)
                {
                    bool ok = await MoveAndTriggerGridPointAsync(number).ConfigureAwait(true);
                    if (!ok)
                    {
                        _dialog.Warn($"Auto Calib dừng tại điểm {number}: di chuyển hoặc Flow TopDownCalib thất bại.");
                        return;
                    }
                }
                _dialog.Info("Auto Calib hoàn tất — đã chụp đủ 9 điểm.");
            }
            finally { Busy = false; }
        }

        /// <summary>Kích hoạt Flow TopDownCalib tại vị trí hiện tại, không di chuyển — test Flow
        /// riêng, không gắn với điểm nào trong lưới 9 điểm.</summary>
        private async Task TriggerTopDownFlowAsync()
        {
            if (Busy) return;

            Busy = true;
            try
            {
                bool ok = await McControl.Calib.TriggerTopDownCalibFlowAsync(McControl.Safety.AbortToken).ConfigureAwait(true);
                _dialog.Info(ok
                    ? "Đã kích hoạt Flow TopDownCalib — báo tìm thấy."
                    : "Đã kích hoạt Flow TopDownCalib — KHÔNG báo tìm thấy, kiểm tra dấu chuẩn/khung hình.");
            }
            finally { Busy = false; }
        }

        private async Task RunBottomUpCalibAsync()
        {
            if (Busy) return;

            Busy = true;
            try
            {
                double x1 = McControl.Motion[AxisId.X].CurrentPos;
                double x2 = x1 + BottomUpProbeDeltaX;
                var result = await McControl.Calib.CalibrateBottomUpAsync(x1, x2, McControl.Safety.AbortToken).ConfigureAwait(true);

                if (result.Calib == null)
                {
                    _dialog.Error("Hiệu chuẩn CAM bottom-up thất bại: " + result.Reason);
                    return;
                }

                string msg = string.Format("scale bản chuẩn {0:0.00000} mm/px, scale trục X {1:0.00000} mm/px, lệch {2:0.00}%.",
                    result.ScaleFromBoard, result.ScaleFromAxis, result.ScaleCrossCheckDiffRatio * 100);

                if (result.Ok)
                {
                    var c = result.Calib;
                    c.IsCalibrated = true;
                    c.CalibratedAt = DateTime.Now;
                    c.CalibratedBy = Environment.UserName;
                    c.PointCount = result.CornerCount;
                    Calib.BottomUp = c;
                    RefreshCalibText();
                    _dialog.Info("Hiệu chuẩn CAM bottom-up ĐẠT, đã ghi vào model — nhớ bấm Lưu model. " + msg);
                }
                else
                {
                    _dialog.Warn("Hiệu chuẩn CAM bottom-up KHÔNG ĐẠT, chưa ghi vào model. " + msg + " " + result.Reason);
                }
            }
            finally { Busy = false; }
        }

        /// <summary>Xoay tay đang chọn (<see cref="SelectedTool"/>) tới <paramref name="angleDeg"/>
        /// rồi trigger Flow AlignCalib của đúng tay đó — App chỉ lo di chuyển + trigger, phép
        /// hiệu chuẩn N-point CÓ XOAY + Teach Master làm thủ công trong VMEditControl (cột trái)
        /// từ các điểm vừa chụp (PLAN.md §6.4, Tuấn chốt 2026-09-08) — giống hệt cách §6.2 CAM
        /// top-down đã làm cho lưới 9 điểm.</summary>
        private async Task RunAlignCalibPointAsync(double angleDeg)
        {
            if (Busy) return;
            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước khi hiệu chuẩn."); return; }

            Busy = true;
            try
            {
                bool ok = await McControl.Calib
                    .MoveAndTriggerAlignCalibAsync(SelectedTool, angleDeg, McControl.Safety.AbortToken)
                    .ConfigureAwait(true);
                if (!ok) _dialog.Warn($"Góc {angleDeg}°: xoay hoặc Flow AlignCalib Tool{SelectedTool} thất bại — kiểm tra lại.");
            }
            finally { Busy = false; }
        }

        /// <summary>Trigger Flow AlignCalib của tay đang chọn tại góc hiện tại, không xoay — test
        /// Flow riêng, giống "Trigger Flow TopDownCalib".</summary>
        private async Task TriggerAlignCalibFlowAsync()
        {
            if (Busy) return;

            Busy = true;
            try
            {
                bool ok = await McControl.Calib.TriggerAlignCalibFlowAsync(SelectedTool, McControl.Safety.AbortToken).ConfigureAwait(true);
                _dialog.Info(ok
                    ? $"Đã kích hoạt Flow AlignCalib Tool{SelectedTool} — báo tìm thấy."
                    : $"Đã kích hoạt Flow AlignCalib Tool{SelectedTool} — KHÔNG báo tìm thấy, kiểm tra sản phẩm/khung hình.");
            }
            finally { Busy = false; }
        }

        private double _handEyeCamX, _handEyeCamY;
        private int _handEyeMeasuredNozzle;

        private async Task MeasureHandEyeCameraAsync(int nozzle)
        {
            if (Busy) return;
            if (!Calib.TopDown.IsCalibrated) { _dialog.Warn("Chưa hiệu chuẩn CAM top-down — làm §6.2 trước."); return; }

            Busy = true;
            try
            {
                var result = await McControl.Calib
                    .MeasureHandEyeCameraPosAsync(Calib.TopDown, McControl.Safety.AbortToken)
                    .ConfigureAwait(true);

                if (!result.Ok)
                {
                    _dialog.Error("Không thấy dấu chuẩn: " + result.Reason);
                    return;
                }

                _handEyeCamX = result.CamX;
                _handEyeCamY = result.CamY;
                _handEyeMeasuredNozzle = nozzle;

                _dialog.Info(string.Format(
                    "Đã đo vị trí camera: ({0:0.000}, {1:0.000}). Giờ sang trang Manual, jog đầu hút #{2} " +
                    "chạm ĐÚNG dấu chuẩn đó, rồi quay lại đây bấm \"Ghi offset\".",
                    result.CamX, result.CamY, nozzle));
            }
            finally { Busy = false; }
        }

        private void CommitHandEye(int nozzle)
        {
            if (_handEyeMeasuredNozzle != nozzle)
            {
                _dialog.Warn($"Chưa đo vị trí camera cho tay #{nozzle} — bấm \"Đo vị trí camera\" trước.");
                return;
            }
            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc."); return; }

            double nozzleX = McControl.Motion[AxisId.X].CurrentPos;
            double nozzleY = McControl.Motion[AxisId.Y2].CurrentPos;
            double dx = nozzleX - _handEyeCamX;
            double dy = nozzleY - _handEyeCamY;

            if (nozzle == 1) { Calib.HandEye1Dx = dx; Calib.HandEye1Dy = dy; }
            else { Calib.HandEye2Dx = dx; Calib.HandEye2Dy = dy; }

            _handEyeMeasuredNozzle = 0;
            RefreshCalibText();
            _dialog.Info($"Đã ghi hand-eye tay #{nozzle}: dx={dx:0.000}, dy={dy:0.000} mm — nhớ bấm Lưu model.");
        }

        private void SetBottomUpYSign(int sign)
        {
            Calib.BottomUpYSign = sign;
            Calib.BottomUpYSignVerifiedAt = DateTime.Now;
            RefreshCalibText();
            _dialog.Info("Đã ghi dấu trục Y = " + (sign > 0 ? "+1" : "−1") +
                ", ngày xác minh " + DateTime.Now.ToString("dd/MM/yyyy") + " — nhớ bấm Lưu model.");
        }

        // ───────────────────────── commands ─────────────────────────

        public ICommand TopDownPoint1Command { get; }
        public ICommand TopDownPoint2Command { get; }
        public ICommand TopDownPoint3Command { get; }
        public ICommand TopDownPoint4Command { get; }
        public ICommand TopDownPoint5Command { get; }
        public ICommand TopDownPoint6Command { get; }
        public ICommand TopDownPoint7Command { get; }
        public ICommand TopDownPoint8Command { get; }
        public ICommand TopDownPoint9Command { get; }
        public ICommand SaveCalibrationCenterCommand { get; }
        public ICommand AutoCalibCommand { get; }
        public ICommand TriggerTopDownFlowCommand { get; }

        public ICommand RunBottomUpCalibCommand { get; }
        public ICommand RunAlignCalibAngle0Command { get; }
        public ICommand RunAlignCalibAngle60Command { get; }
        public ICommand RunAlignCalibAngle120Command { get; }
        public ICommand RunAlignCalibAngle180Command { get; }
        public ICommand RunAlignCalibAngle240Command { get; }
        public ICommand RunAlignCalibAngle300Command { get; }
        public ICommand TriggerAlignCalibFlowCommand { get; }
        public ICommand MeasureHandEyeCommand { get; }
        public ICommand CommitHandEyeCommand { get; }
        public ICommand SetYSignPositiveCommand { get; }
        public ICommand SetYSignNegativeCommand { get; }
    }
}

