using System;
using ShieldCanAssy.Core.Communication;
using ShieldCanAssy.Core.Data.Model;

namespace ShieldCanAssy.Core.Controller
{
    /// <summary>Kết quả tính điểm đặt cho một sản phẩm.</summary>
    public class PlaceSolution
    {
        public bool Ok { get; set; }
        public string Reason { get; set; }

        /// <summary>Góc phải xoay thêm cho trục A của tay hút này, độ.</summary>
        public double DeltaThetaDeg { get; set; }

        /// <summary>Toạ độ lệnh cho trục X và trục Y của tray lắp ráp (Y2).</summary>
        public double CommandX { get; set; }
        public double CommandY { get; set; }

        /// <summary>Độ lệch tâm sản phẩm so với trục xoay SAU KHI xoay — phần bù bằng X/Y2.</summary>
        public double ErrX { get; set; }
        public double ErrY { get; set; }
        public double ErrDistance { get { return Math.Sqrt(ErrX * ErrX + ErrY * ErrY); } }

        public static PlaceSolution Fail(string why)
        {
            return new PlaceSolution { Ok = false, Reason = why };
        }
    }

    /// <summary>
    /// Toán tính điểm đặt — PLAN.md §6.6. Tách thành hàm thuần để kiểm chứng được bằng
    /// <c>--selftest</c> mà không cần camera hay trục nào: đây là phần dễ sai nhất của cả máy
    /// và sai của nó biểu hiện thành đặt lệch chứ không phải thành thông báo lỗi.
    ///
    /// <para><b>Quy ước toạ độ.</b> Mọi giá trị hình học đều quy về <b>toạ độ lệnh của trục</b>,
    /// không qua hệ trung gian nào:</para>
    /// <list type="bullet">
    /// <item><c>bottom.PixelX/PixelY/Angle</c> (procedure <c>AlignBottomTool1</c>/
    /// <c>AlignBottomTool2</c>) đã là ĐỘ LỆCH mm/độ so với tâm xoay và Master của ĐÚNG tay hút
    /// này — VisionMaster tự hiệu chuẩn N-point CÓ XOAY + Teaching bên trong Flow (§6.4, Tuấn
    /// chốt 2026-09-08), KHÔNG còn quy đổi pixel→mm hay trừ tâm xoay/Master ở đây nữa (khác bản
    /// trước). Tên field vẫn là "Pixel..." vì dùng chung <see cref="VisionPose"/> với các
    /// procedure khác còn trả pixel thô — chỉ riêng 2 procedure này đổi ý nghĩa.</item>
    /// <item><c>TopDown.ToMm</c> trả về lượng phải dịch trục X và Y2 để đưa tâm ảnh CAM
    /// top-down tới đúng chi tiết vừa nhìn thấy. Dấu nằm sẵn trong ma trận vì camera này
    /// được hồi quy thẳng pixel → toạ độ lệnh trục (§6.2).</item>
    /// <item><c>HandEye_i</c> = hiệu toạ độ trục giữa "đầu hút i chạm dấu chuẩn" và "CAM
    /// top-down nhìn thấy dấu chuẩn đó" (§6.5). Đo riêng từng tay nên nó đã chứa sẵn khoảng
    /// cách pitch giữa hai đầu hút — <b>không</b> được cộng pitch thêm lần nữa ở đây.</item>
    /// </list>
    /// </summary>
    public static class PlacementSolver
    {
        /// <summary>
        /// Tính lệnh xoay và lệnh X/Y2 để đặt sản phẩm đang giữ trên tay hút <paramref name="nozzle"/>
        /// vào đúng tư thế của chi tiết đích.
        /// </summary>
        /// <param name="bottom">Tư thế sản phẩm do CAM bottom-up đo (bước S20/S21).</param>
        /// <param name="top">Tư thế chi tiết đích do CAM top-down đo (bước S30/S32).</param>
        /// <param name="captureX">Toạ độ trục X lúc chụp ảnh top-down.</param>
        /// <param name="captureY">Toạ độ trục Y2 lúc chụp ảnh top-down.</param>
        public static PlaceSolution Solve(VisionCalib calib, int nozzle,
                                          VisionPose bottom, VisionPose top,
                                          double captureX, double captureY,
                                          double maxAngleDeg, double maxDistance)
        {
            if (calib == null) return PlaceSolution.Fail("chưa có dữ liệu hiệu chuẩn");
            if (bottom == null || !bottom.Found) return PlaceSolution.Fail("CAM bottom-up không tìm thấy sản phẩm");
            if (top == null || !top.Found) return PlaceSolution.Fail("CAM top-down không tìm thấy chi tiết đích");

            // ── Sản phẩm đang giữ: (px, py, bottomAngle) đã là ĐỘ LỆCH mm/độ so với tâm xoay và
            // Master của ĐÚNG tay hút này, tính SẴN bên trong VisionMaster (Flow AlignBottomTool1/
            // AlignBottomTool2 — hiệu chuẩn N-point CÓ XOAY + Teaching, PLAN.md §6.4, Tuấn chốt
            // 2026-09-08). Không còn CameraCalib.BottomUp.ToMm/BottomUpYSign/RotationCenter/Master
            // ở đây nữa — bản trước tự làm cả chuỗi đó bằng tay, giờ VisionMaster đã làm xong.
            double px = bottom.PixelX;
            double py = bottom.PixelY;
            double bottomAngle = bottom.Angle;

            // ── Chi tiết đích: lượng dịch trục để tâm ảnh top-down trùng chi tiết ──
            double tdx, tdy;
            calib.TopDown.ToMm(top.PixelX, top.PixelY, out tdx, out tdy);

            double handEyeDx = nozzle == 1 ? calib.HandEye1Dx : calib.HandEye2Dx;
            double handEyeDy = nozzle == 1 ? calib.HandEye1Dy : calib.HandEye2Dy;

            double targetX = captureX + tdx + handEyeDx;
            double targetY = captureY + tdy + handEyeDy;

            // ── Xoay ──
            double delta = NormalizeDeg(top.Angle - bottomAngle);

            // Sản phẩm không nằm đúng trục xoay, nên xoay Δθ làm TÂM SẢN PHẨM dịch đi một
            // lượng phụ thuộc độ lệch tâm. Bỏ qua bước này thì sai số đặt tỉ lệ với độ lệch
            // tâm và không bù được bằng một offset cố định — lượng dịch đổi theo từng Δθ (§6.4).
            double rad = delta * Math.PI / 180.0;
            double cos = Math.Cos(rad), sin = Math.Sin(rad);
            double dx = px, dy = py;

            double errX = dx * cos - dy * sin;      // p' = R(Δθ)·p — p đã là độ lệch so với tâm xoay
            double errY = dx * sin + dy * cos;

            var sol = new PlaceSolution
            {
                Ok = true,
                DeltaThetaDeg = delta,
                ErrX = errX,
                ErrY = errY,
                CommandX = targetX - errX,
                CommandY = targetY - errY
            };

            // Vượt ngưỡng nghĩa là vision đo nhầm vật, không phải sản phẩm lệch nhiều. Coi là
            // Align fail chứ không lao trục đi bù (§6.6).
            if (Math.Abs(delta) > maxAngleDeg)
            {
                sol.Ok = false;
                sol.Reason = string.Format("góc bù {0:0.0}° vượt ngưỡng {1:0.0}°", delta, maxAngleDeg);
            }
            else if (sol.ErrDistance > maxDistance)
            {
                sol.Ok = false;
                sol.Reason = string.Format("lượng bù {0:0.00} mm vượt ngưỡng {1:0.00} mm",
                    sol.ErrDistance, maxDistance);
            }

            return sol;
        }

        /// <summary>Đưa góc về khoảng (−180, 180] — xoay 350° và xoay −10° là một, chọn cái ngắn.</summary>
        public static double NormalizeDeg(double deg)
        {
            while (deg > 180.0) deg -= 360.0;
            while (deg <= -180.0) deg += 360.0;
            return deg;
        }
    }
}

