25	    /// dùng trong toàn bộ mẫu C#/WPF của hãng.</para>
26	    ///
27	    /// <para><b>Chưa chạy thử với solution thật.</b> API tồn tại và biên dịch được — SDK đã cài
28	    /// sẵn trên máy dev, tham chiếu thẳng DLL thật (xem ShieldCanAssy.Core.csproj) — nhưng chưa
29	    /// đối chiếu với solution VisionMaster thật vì solution đó chưa được dựng.</para>
