31	    /// <para><b>Tên Flow và tên biến output KHÔNG nằm trong lớp này.</b> Lớp này chỉ biết chạy
32	    /// một Flow theo tên truyền vào và đọc các output theo tên truyền vào —
33	    /// <see cref="ShieldCanAssy.Core.Data.SystemData.VisionOutputs"/> (sửa được ở trang Setting)
34	    /// mới là nơi giữ tên thật, để đổi tên Flow/output trong solution không cần build lại app —
35	    /// PLAN.md §6.8, giống màn hình nhập tên Output ở app HousingCorrosion.</para>
36	    /// </summary>
37	    public class VisionMasterDevice
38	    {
39	        public bool IsSolutionLoaded { get; private set; }
40	
41	        /// <summary>Nạp solution — <see cref="VmSolution"/> là singleton toàn tiến trình nên chỉ
42	        /// một solution được nạp tại một thời điểm (mẫu <c>SolutionControlCS_WPF</c>).</summary>
43	        public void LoadSolution(string path, string password)
44	        {
45	            VmSolution.Load(path, password ?? "");
46	
47	            // Sau khi nạp xong, tắt callback kết quả của mọi module để đỡ tốn tài nguyên — ta chỉ
48	            // cần Run() rồi đọc output của Flow bằng GetFloatOutputResult, không cần callback
49	            // (mẫu GetResultControl\Form1.cs làm y hệt ngay sau LoadSolution).
50	            VmSolution.Instance.DisableModulesCallback();
51	            IsSolutionLoaded = true;
52	        }
53	
54	        /// <summary>
55	        /// Chạy một Flow (đồng bộ, CHẶN luồng gọi — lớp trên phải tự bọc Task.Run + timeout) rồi
56	        /// đọc các output float đã đặt tên theo đúng thứ tự tham số. Ném <see cref="VmException"/>
57	        /// nếu Flow không tồn tại, chạy lỗi, hoặc thiếu output đã khai — lớp trên (VisionConnect)
58	        /// chịu trách nhiệm bắt và quy đổi thành alarm/kết quả "không tìm thấy".
59	        /// </summary>
60	        public float[] RunAndGetFloats(string flowName, params string[] outputNames)
61	        {
62	            var pro = VmSolution.Instance[flowName] as VmProcedure;
63	            if (pro == null)
64	                throw new VmException(-1, "không tìm thấy Flow \"" + flowName + "\" trong solution — kiểm tra tên trong VisionMaster IDE");
65	
66	            pro.Run();
67	
68	            // GetFloatOutputResult(string) của VmProcedure đã DEPRECATED trong bản SDK cài trên
69	            // máy — dùng thay thế theo đúng khuyến cáo của trình biên dịch: ModuResult.GetOutputFloat.
70	            var moduResult = pro.ModuResult;
71	            var results = new float[outputNames.Length];
72	            for (int i = 0; i < outputNames.Length; i++)
73	            {
74	                var r = moduResult.GetOutputFloat(outputNames[i]);
75	                if (r.nValueNum < 1 || r.pFloatVal == null || r.pFloatVal.Length < 1)
76	                    throw new VmException(-1, "Flow \"" + flowName + "\" thiếu output \"" + outputNames[i] + "\" — kiểm tra biến output trong solution");
77	                results[i] = r.pFloatVal[0];
78	            }
79	            return results;
80	        }
81	
82	        /// <summary>
83	        /// Như <see cref="RunAndGetFloats"/> nhưng CHỈ chạy Flow MỘT LẦN rồi đọc cả output float
84	        /// lẫn ảnh từ đúng lần chạy đó — chạy hai lần (một để lấy số, một để lấy ảnh) sẽ kích
85	        /// camera thật chụp hai lần cho một lần trigger logic, tốn thời gian và có thể đọc phải
86	        /// hai khung hình khác nhau nếu vật vừa dịch giữa hai lần chụp.
87	        ///
88	        /// <para><c>EnableResultCallback()</c> theo đúng mẫu SDK
89	        /// <c>GetResultControl\Form1.cs</c> — không gọi thì <c>GetOutputImageV2</c> không có dữ
90	        /// liệu để trả, dù output float vẫn đọc được bình thường.</para>
91	        ///
92	        /// <para>Ảnh không bắt buộc: <paramref name="imageOutputName"/> để trống/null thì bỏ qua
93	        /// hẳn bước lấy ảnh; solution chưa khai output ảnh (hoặc lấy ảnh lỗi) thì
94	        /// <see cref="VisionRunResult.Image"/> là null nhưng KHÔNG ném lỗi — đo tư thế để đặt
95	        /// hàng không phụ thuộc vào việc có lấy được ảnh hiển thị hay không.</para>
96	        /// </summary>
97	        public VisionRunResult RunAndGetFloatsWithImage(string flowName, string imageOutputName, params string[] outputNames)
98	        {
99	            var pro = VmSolution.Instance[flowName] as VmProcedure;
100	            if (pro == null)
101	                throw new VmException(-1, "không tìm thấy Flow \"" + flowName + "\" trong solution — kiểm tra tên trong VisionMaster IDE");
102	
103	            bool wantImage = !string.IsNullOrEmpty(imageOutputName);
104	            if (wantImage) pro.EnableResultCallback();
105	
106	            pro.Run();
107	
108	            var moduResult = pro.ModuResult;
109	            var results = new float[outputNames.Length];
110	            for (int i = 0; i < outputNames.Length; i++)
111	            {
112	                var r = moduResult.GetOutputFloat(outputNames[i]);
113	                if (r.nValueNum < 1 || r.pFloatVal == null || r.pFloatVal.Length < 1)
114	                    throw new VmException(-1, "Flow \"" + flowName + "\" thiếu output \"" + outputNames[i] + "\" — kiểm tra biến output trong solution");
115	                results[i] = r.pFloatVal[0];
116	            }
117	
118	            Bitmap image = null;
119	            if (wantImage)
120	            {
121	                try
122	                {
123	                    var imgData = moduResult.GetOutputImageV2(imageOutputName);
124	                    if (imgData != null) image = imgData.ToBitmap();
125	                }
126	                catch
127	                {
128	                    // Ảnh chỉ để hiển thị, không phải số dùng để tính lượng bù — im lặng bỏ qua.
129	                }
130	            }
131	
132	            return new VisionRunResult { Floats = results, Image = image };
133	        }
134	
135	        public void CloseSolution()
136	        {
137	            try { VmSolution.Instance?.CloseSolution(); } catch { }
138	            IsSolutionLoaded = false;
139	        }
140	
