372	        private async Task<bool> S2x_Align(int nozzle, EAutoState next, CancellationToken ct)
373	        {
374	            var nz = Nozzle(nozzle);
375	            if (!nz.HasProduct) { Run.AutoState = next; return true; }
376	            if (_bottomPose[nozzle] != null) { Run.AutoState = next; return true; }
377	
378	            double alignX = nozzle == 1 ? Model.AlignPosX_Nozzle1 : Model.AlignPosX_Nozzle2;
379	            if (!await _func.MoveAsync(AxisId.X, alignX, MoveSpeed(AxisId.X), ct).ConfigureAwait(false))
380	                return Halt("không tới được vị trí soi tay #" + nozzle);
381	
382	            // Flow RIÊNG từng tay (PLAN.md §6.4, Tuấn chốt 2026-09-08) — đã tự hiệu chuẩn tâm xoay
383	            // + Teach Master bên trong VisionMaster. EVisionProcedure.AlignBottom (Flow chung, cũ)
384	            // đã bỏ hẳn (2026-09-10) cùng 2 wizard orphan từng dùng nó trong Routine_Calib.
385	            var alignProc = nozzle == 1 ? EVisionProcedure.AlignBottomTool1 : EVisionProcedure.AlignBottomTool2;
386	            var pose = await TriggerAsync(alignProc, ct).ConfigureAwait(false);
387	
388	            if (pose == null || !pose.Found)
389	            {
390	                // Align fail: trả sản phẩm về ĐÚNG ô cũ rồi đánh dấu ô đó NG. Thả bừa ở đâu đó
391	                // là mất dấu sản phẩm và lần về gốc sau sẽ đâm vào nó (§5.4).
392	                AlarmManager.Raise(AlarmCode.VisionNotFound, "Vision",
393	                    "AlignBottom tay #" + nozzle + (pose == null ? "" : ": " + pose.Error));
394	                if (!await ReturnToSourceAsync(nozzle, ct).ConfigureAwait(false)) return false;
395	                AlarmManager.ClearCondition(AlarmCode.VisionNotFound);
396	                CountNg("align fail tay #" + nozzle);
397	                return CheckConsecutiveNg();
398	            }
399	
400	            _bottomPose[nozzle] = pose;
401	            nz.MeasuredAngle = pose.Angle;
402	            nz.Aligned = true;
403	            Run.AutoState = next;
404	            return true;
405	        }
