// ───────────────────────── S20 / S21 — soi tư thế ─────────────────────────

/// <summary>
/// Đưa tay hút vào khung hình CAM bottom-up và đo tư thế sản phẩm.
///
/// <para><b>Không xoay ở bước này</b>, khác với bản phác thảo đầu tiên của §5.2. Góc
/// đích θ_t chỉ biết được sau khi CAM top-down soi ô đích ở S30, nên xoay ngay tại đây
/// sẽ phải xoay lần thứ hai — vừa tốn thời gian vừa thêm một nguồn sai số. Toàn bộ lượng
/// xoay dồn vào lúc di chuyển tới ô đặt, khi đó trục A chạy song song với X/Y2 nên
/// không tốn thêm giây nào của chu kỳ.</para>
/// </summary>
private async Task<bool> S2x_Align(int nozzle, EAutoState next, CancellationToken ct)
{
    var nz = Nozzle(nozzle);
    if (!nz.HasProduct) { Run.AutoState = next; return true; }
    if (_bottomPose[nozzle] != null) { Run.AutoState = next; return true; }

    double alignX = nozzle == 1 ? Model.AlignPosX_Nozzle1 : Model.AlignPosX_Nozzle2;
    if (!await _func.MoveAsync(AxisId.X, alignX, MoveSpeed(AxisId.X), ct).ConfigureAwait(false))
        return Halt("không tới được vị trí soi tay #" + nozzle);

    // Flow RIÊNG từng tay (PLAN.md §6.4, Tuấn chốt 2026-09-08) — đã tự hiệu chuẩn tâm xoay
    // + Teach Master bên trong VisionMaster. EVisionProcedure.AlignBottom (Flow chung, cũ)
    // đã bỏ hẳn (2026-09-10) cùng 2 wizard orphan từng dùng nó trong Routine_Calib.
    var alignProc = nozzle == 1 ? EVisionProcedure.AlignBottomTool1 : EVisionProcedure.AlignBottomTool2;
    var pose = await TriggerAsync(alignProc, ct).ConfigureAwait(false);

    if (pose == null || !pose.Found)
    {
        // Align fail: trả sản phẩm về ĐÚNG ô cũ rồi đánh dấu ô đó NG. Thả bừa ở đâu đó
        // là mất dấu sản phẩm và lần về gốc sau sẽ đâm vào nó (§5.4).
        AlarmManager.Raise(AlarmCode.VisionNotFound, "Vision",
            "AlignBottom tay #" + nozzle + (pose == null ? "" : ": " + pose.Error));
        if (!await ReturnToSourceAsync(nozzle, ct).ConfigureAwait(false)) return false;
        AlarmManager.ClearCondition(AlarmCode.VisionNotFound);
        CountNg("align fail tay #" + nozzle);
        return CheckConsecutiveNg();
    }

    _bottomPose[nozzle] = pose;
    nz.MeasuredAngle = pose.Angle;
    nz.Aligned = true;
    Run.AutoState = next;
    return true;
}

// ───────────────────────── S30–S33 — soi ô đích và đặt ─────────────────────────

private async Task<bool> S3x_LocateAndPlace(int nozzle, EAutoState next, CancellationToken ct)
{
    var nz = Nozzle(nozzle);
    if (!nz.HasProduct) { Run.AutoState = next; return true; }

    // Chạy lại sau khi tắt app: trạng thái bước nằm trên đĩa nhưng tư thế đo được thì
    // không — nó chỉ có nghĩa cho đúng lần chụp đó. Đo lại thay vì dùng số cũ hoặc coi
    // như hỏng hàng.
    if (_bottomPose[nozzle] == null)
    {
        // S20_Align1 soi tay #2 trước, S21_Align2 soi tay #1 (Tuấn xác nhận 2026-09-05) —
        // ánh xạ ngược lại với thứ tự nozzle số vì tên BƯỚC không đổi theo.
        Run.AutoState = nozzle == 1 ? EAutoState.S21_Align2 : EAutoState.S20_Align1;
        LogWorker.Instance.RecordLog(
            "Chưa có tư thế đo của tay #" + nozzle + " — soi lại trước khi đặt",
            Utility.Log.LogLevel.Info, "Auto");
        return true;
    }

    var tray = Run.AssyTray;
    int index = NextFreeCell(tray);
    if (index < 0)
    {
        // Hết ô lắp ráp mà tay vẫn còn hàng: giữ nguyên sản phẩm, đi đổi tray. Trạng
        // thái tay hút đã ghi xuống đĩa nên đổi xong quay lại đặt tiếp được.
        Run.AutoState = EAutoState.S50_TrayCheck;
        return true;
    }

    tray.CurrentIndex = index;
    int row, col;
    tray.RowCol(index, out row, out col);
    tray.Set(index, ECellState.Processing);

    VisionPose top;
    double captureX, captureY;

    AssyCellScan scan;
    if (_assyScan.TryGetValue(index, out scan))
    {
        // Đường thường: đã có sẵn từ S05_ScanAssy — không di chuyển CAM, không trigger
        // gì nữa, đúng phần rút ngắn chu kỳ mà thay đổi này nhắm tới. Dùng rồi thì bỏ
        // khỏi cache — ô này coi như đã tiêu thụ, tránh dùng nhầm nếu ô bị gán lại.
        top = scan.Top;
        captureX = scan.CaptureX;
        captureY = scan.CaptureY;
        _assyScan.Remove(index);
    }
    else
    {
        // Dự phòng: quét trước chưa kịp phủ ô này (vd. tray bị đổi hoặc cache bị dọn
        // giữa chừng) — đo trực tiếp như cách làm cũ, để việc đặt hàng KHÔNG BAO GIỜ phụ
        // thuộc bắt buộc vào việc đã quét trước hay chưa.
        var cell = Model.AssyTray.CellPos(AxisId.Z1, row, col);
        var cell00 = Model.AssyTray.CellPos(AxisId.Z1, 0, 0);
        double camX = Model.AssyTray.CamTopDownAnchorX + (cell.X - cell00.X);
        double camY = Model.AssyTray.CamTopDownAnchorY + (cell.Y - cell00.Y);

        if (!await _func.MoveToCellAsync(Model.AssyTray.AxisRow, camY, camX, ct).ConfigureAwait(false))
            return Halt("không tới được vị trí soi ô đích (" + row + "," + col + ")");

        captureX = _motion[AxisId.X].CurrentPos;
        captureY = _motion[Model.AssyTray.AxisRow].CurrentPos;
        top = await TriggerAsync(EVisionProcedure.LocateTop, ct).ConfigureAwait(false);
    }

    if (top == null || !top.Found)
    {
        // Không thấy chi tiết đích: bỏ qua ô đó, GIỮ sản phẩm sang ô kế tiếp. Sản phẩm
        // trên tay còn tốt, không có lý do gì loại nó vì ô đích trống (§5.4).
        AlarmManager.Raise(AlarmCode.VisionNotFound, "Vision",
            "LocateTop ô (" + row + "," + col + ")" + (top == null ? "" : ": " + top.Error));
        tray.Set(index, ECellState.Skipped);
        AlarmManager.ClearCondition(AlarmCode.VisionNotFound);
        return true;      // ở nguyên bước này, vòng sau lấy ô kế
    }

    var sys = _sys();
    var sol = PlacementSolver.Solve(Model.Calib, nozzle, _bottomPose[nozzle], top,
        captureX, captureY, sys.MaxCompensationAngleDeg, sys.MaxCompensationDistance);

    if (!sol.Ok)
    {
        AlarmManager.Raise(AlarmCode.CompensationOutOfRange, "Auto",
            "tay #" + nozzle + ": " + sol.Reason);
        tray.Set(index, ECellState.Empty);
        if (!await ReturnToSourceAsync(nozzle, ct).ConfigureAwait(false)) return false;
        AlarmManager.ClearCondition(AlarmCode.CompensationOutOfRange);
        CountNg("lượng bù vượt ngưỡng tay #" + nozzle);
        return CheckConsecutiveNg();
    }

    _status.LastDeltaTheta = sol.DeltaThetaDeg;
    _status.LastPlaceError = sol.ErrDistance;

    if (!await PlaceAsync(nozzle, sol, ct).ConfigureAwait(false)) return false;

    tray.Set(index, ECellState.Ok);
    Run.CountOk++;
    Run.CountTotal++;
    Run.ConsecutiveNg = 0;

    int src = nz.SourceCellIndex;
    if (src >= 0) Run.InputTray.Set(src, ECellState.Ok);

    nz.HasProduct = false;
    nz.SourceCellIndex = -1;
    nz.Aligned = false;
    _bottomPose[nozzle] = null;

    Save();
    Run.AutoState = next;
    return true;
}

/// <summary>Xoay, di chuyển tới điểm đã bù, hạ, nhả, nâng.</summary>
private async Task<bool> PlaceAsync(int nozzle, PlaceSolution sol, CancellationToken ct)
{
    string aName = nozzle == 1 ? AxisId.A1 : AxisId.A2;
    string zName = nozzle == 1 ? AxisId.Z1 : AxisId.Z2;
    string yName = Model.AssyTray.AxisRow;

    // Trục A chạy song song với X/Y2 — xoay không tốn thêm thời gian chu kỳ.
    double aTarget = _motion[aName].CurrentPos + sol.DeltaThetaDeg;

    var moves = new Task<bool>[]
    {
        _func.MoveAsync(aName, aTarget, MoveSpeed(aName), ct),
        _func.MoveAsync(AxisId.X, sol.CommandX, MoveSpeed(AxisId.X), ct),
        _func.MoveAsync(yName, sol.CommandY, MoveSpeed(yName), ct)
    };

    var results = await Task.WhenAll(moves).ConfigureAwait(false);
    foreach (bool r in results)
        if (!r) return Halt("không tới được điểm đặt của tay #" + nozzle);

    if (!await _func.MoveAsync(zName, Model.AssyTray.ZPickFor(zName), ZSpeed(zName), ct).ConfigureAwait(false))
        return Halt(zName + " không hạ được xuống cao độ đặt");

    _func.SetVacuum(nozzle, false);
    _func.SetBlow(nozzle, true);

    bool released = await WaitVacuumAsync(nozzle, false, ct).ConfigureAwait(false);
    await Task.Delay(_sys().BlowTimeMs, ct).ConfigureAwait(false);
    _func.SetBlow(nozzle, false);

    if (!await _func.MoveAsync(zName, SafeZ(), ZSpeed(zName), ct).ConfigureAwait(false))
        return Halt(zName + " không nâng lên được sau khi đặt");

