89	            }
90	        }
91	
92	        public bool IsTool1 { get => SelectedTool == 1; set { if (value) SelectedTool = 1; } }
93	        public bool IsTool2 { get => SelectedTool == 2; set { if (value) SelectedTool = 2; } }
94	
95	        // ───────────────────────── CAM top-down / bottom-up (chung, không theo Tool) ─────────────────────────
96	
97	        public string TopDownStatusText => StatusText(Calib.TopDown, "9 điểm bằng trục máy");
98	        public string BottomUpStatusText => StatusText(Calib.BottomUp, "checkerboard 1×1 mm");
99	
100	        /// <summary>Bước lưới 9 điểm CAM top-down, mm — pass-through thẳng vào SystemData (đọc/ghi
101	        /// cùng đối tượng đang chạy, không có bản sao riêng) để đổi ở đây là dùng ngay cho lần bấm
102	        /// điểm kế tiếp, không cần sang trang Setting.</summary>
103	        public double TopDownCalibStepXMm
104	        {
105	            get => McDataManager.SysData.TopDownCalibStepXMm;
106	            set { McDataManager.SysData.TopDownCalibStepXMm = value; OnPropertyChanged(); }
107	        }
