110	        {
111	            get => McDataManager.SysData.TopDownCalibStepYMm;
112	            set { McDataManager.SysData.TopDownCalibStepYMm = value; OnPropertyChanged(); }
113	        }
114	
115	        private double _bottomUpProbeDeltaX = 20.0;
116	        /// <summary>Khoảng cách chạy X để đối chiếu chéo B3 (PLAN §6.3) — vài mm trở lên, vẫn
117	        /// phải giữ được bản chuẩn trong khung hình cả hai đầu.</summary>
118	        public double BottomUpProbeDeltaX { get => _bottomUpProbeDeltaX; set => SetProperty(ref _bottomUpProbeDeltaX, value); }
119	
