121	            ? $"{(Calib.BottomUpYSign > 0 ? "+1" : "−1")}  (xác minh {Calib.BottomUpYSignVerifiedAt:dd/MM/yyyy})"
122	            : "CHƯA xác minh bằng phép thử vật lý — §6.3";
