125	
126	        public string HandEyeStatusText => SelectedTool == 1
127	            ? $"dx={Calib.HandEye1Dx:0.000}, dy={Calib.HandEye1Dy:0.000} mm"
128	            : $"dx={Calib.HandEye2Dx:0.000}, dy={Calib.HandEye2Dy:0.000} mm";
