130	        private string StatusText(CameraCalib c, string expectMethod)
131	        {
132	            if (!c.IsCalibrated) return "Chưa hiệu chuẩn";
133	            bool expired = c.IsExpired(McDataManager.SysData.CalibValidDays);
134	            return string.Format("{0}{1} — {2:dd/MM/yyyy HH:mm} — scale {3:0.00000}/{4:0.00000} mm/px, " +
135	                "góc {5:0.00}°, RMS {6:0.000} mm, max {7:0.000} mm, {8} điểm",
136	                expired ? "HẾT HẠN — " : "", c.Method ?? expectMethod, c.CalibratedAt,
