138	        }
139	
140	        private void RefreshCalibText()
141	        {
142	            OnPropertyChanged(nameof(TopDownStatusText));
143	            OnPropertyChanged(nameof(BottomUpStatusText));
144	            OnPropertyChanged(nameof(HandEyeStatusText));
145	            OnPropertyChanged(nameof(BottomUpYSignText));
146	        }
147	
148	        // ───────────────────────── lưới 9 điểm thủ công (numpad) ─────────────────────────
149	        //
150	        // Thay quét 9 điểm tự động + tự fit affine (Routine_Calib.CalibrateTopDownAsync, vẫn còn
151	        // trong Core nhưng không còn nút gọi ở đây) bằng 9 nút bấm tay, đánh số kiểu numpad khớp
152	        // hình người dùng minh hoạ (dưới 1,2,3 — giữa 4,5,6 — trên 7,8,9). Phép hiệu chuẩn (fit
153	        // affine) làm THỦ CÔNG trong VMEditControl (cột trái trang này) từ chính các điểm đã chụp
154	        // qua Flow TopDownCalib — phần mềm chỉ còn lo di chuyển + kích hoạt Flow.
155	
156	        /// <summary>"Calibration Center Point" — toạ độ (X, Y2) ứng với điểm 5 (giữa khung hình),
157	        /// lưu bằng nút Save sau khi jog máy tới đó qua trang Manual. Pass-through vào SystemData
158	        /// (persist qua McDataManager.SaveSystemData như mọi cấu hình khác) — KHÁC bản trước đọc
159	        /// CurrentPos ngay lúc bấm điểm 5: giờ Save và Dùng là 2 bước tách biệt, không phải jog
160	        /// lại tâm mỗi lần mở app hay muốn chụp lại một điểm lẻ.</summary>
161	        public double CalibrationCenterX
162	        {
163	            get => McDataManager.SysData.TopDownCalibCenterX;
164	            set { McDataManager.SysData.TopDownCalibCenterX = value; OnPropertyChanged(); }
165	        }
166	
167	        public double CalibrationCenterY
168	        {
169	            get => McDataManager.SysData.TopDownCalibCenterY;
170	            set { McDataManager.SysData.TopDownCalibCenterY = value; OnPropertyChanged(); }
171	        }
172	
173	        /// <summary>Phân biệt "chưa từng Save" với "đã Save đúng tại (0,0)" — 2 giá trị double mặc
174	        /// định 0 không tự nói lên được điều đó.</summary>
175	        public bool CalibrationCenterSet
176	        {
177	            get => McDataManager.SysData.TopDownCalibCenterSet;
178	            set { McDataManager.SysData.TopDownCalibCenterSet = value; OnPropertyChanged(); OnPropertyChanged(nameof(CalibrationCenterStatusText)); }
179	        }
180	
181	        public string CalibrationCenterStatusText => CalibrationCenterSet ? "(đã lưu)" : "(chưa lưu)";
182	
183	        /// <summary>Đọc vị trí trục (X, Y2) HIỆN TẠI (operator đã jog qua trang Manual tới đúng
184	        /// giữa khung hình) rồi lưu làm Calibration Center Point.</summary>
185	        private void SaveCalibrationCenter()
186	        {
187	            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — toạ độ đọc lúc này không có ý nghĩa."); return; }
188	
189	            CalibrationCenterX = McControl.Motion[AxisId.X].CurrentPos;
190	            CalibrationCenterY = McControl.Motion[AxisId.Y2].CurrentPos;
191	            CalibrationCenterSet = true;
192	            _dialog.Info(string.Format("Đã lưu Calibration Center Point: ({0:0.000}, {1:0.000}).",
193	                CalibrationCenterX, CalibrationCenterY));
194	        }
195	
196	        /// <summary>Di chuyển tới điểm numpad <paramref name="number"/> (offset từ
197	        /// <see cref="CalibrationCenterX"/>/<see cref="CalibrationCenterY"/> theo
198	        /// <see cref="TopDownCalibStepXMm"/>/<see cref="TopDownCalibStepYMm"/>) rồi kích hoạt Flow
199	        /// TopDownCalib. Numpad: hàng trên (7,8,9) row=+1, hàng dưới (1,2,3) row=-1; cột trái
200	        /// (1,4,7) col=-1, cột phải (3,6,9) col=+1; điểm 5 = offset (0,0), đúng tâm đã lưu.</summary>
201	        private async Task<bool> MoveAndTriggerGridPointAsync(int number)
202	        {
203	            int rowMul, colMul;
204	            TopDownGridOffset(number, out rowMul, out colMul);
205	            double x = CalibrationCenterX + colMul * TopDownCalibStepXMm;
206	            double y = CalibrationCenterY + rowMul * TopDownCalibStepYMm;
207	            return await McControl.Calib.MoveAndTriggerTopDownCalibAsync(x, y, McControl.Safety.AbortToken).ConfigureAwait(true);
208	        }
209	
210	        /// <summary>Số numpad 1-9 → (hệ số hàng, hệ số cột) quanh tâm, khớp hình minh hoạ người
211	        /// dùng gửi (1,2,3 hàng dưới; 4,5,6 hàng giữa; 7,8,9 hàng trên).</summary>
212	        private static void TopDownGridOffset(int number, out int rowMul, out int colMul)
213	        {
214	            int idx = number - 1;
215	            rowMul = idx / 3 - 1;
216	            colMul = idx % 3 - 1;
217	        }
218	
219	        private bool CheckReadyForGrid()
220	        {
221	            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước khi hiệu chuẩn."); return false; }
222	            if (!CalibrationCenterSet) { _dialog.Warn("Chưa lưu Calibration Center Point — jog tới giữa khung hình rồi bấm Save trước."); return false; }
223	            return true;
224	        }
225	
226	        private async Task RunTopDownGridPointAsync(int number)
227	        {
228	            if (Busy || !CheckReadyForGrid()) return;
229	
230	            Busy = true;
231	            try
232	            {
233	                bool ok = await MoveAndTriggerGridPointAsync(number).ConfigureAwait(true);
234	                if (!ok) _dialog.Warn($"Điểm {number}: di chuyển hoặc Flow TopDownCalib thất bại — kiểm tra lại.");
235	            }
236	            finally { Busy = false; }
237	        }
238	
239	        /// <summary>Auto Calib — chạy tuần tự cả 9 điểm (1→9) không cần bấm tay từng nút, dừng lại
240	        /// ngay khi một điểm thất bại thay vì âm thầm bỏ qua rồi báo "xong" sai sự thật.</summary>
241	        private async Task RunAutoCalibAsync()
242	        {
243	            if (Busy || !CheckReadyForGrid()) return;
244	
245	            Busy = true;
246	            try
247	            {
248	                for (int number = 1; number <= 9; number++)
249	                {
250	                    bool ok = await MoveAndTriggerGridPointAsync(number).ConfigureAwait(true);
251	                    if (!ok)
252	                    {
253	                        _dialog.Warn($"Auto Calib dừng tại điểm {number}: di chuyển hoặc Flow TopDownCalib thất bại.");
254	                        return;
255	                    }
256	                }
257	                _dialog.Info("Auto Calib hoàn tất — đã chụp đủ 9 điểm.");
258	            }
259	            finally { Busy = false; }
260	        }
261	
262	        /// <summary>Kích hoạt Flow TopDownCalib tại vị trí hiện tại, không di chuyển — test Flow
263	        /// riêng, không gắn với điểm nào trong lưới 9 điểm.</summary>
264	        private async Task TriggerTopDownFlowAsync()
265	        {
266	            if (Busy) return;
267	
268	            Busy = true;
269	            try
270	            {
271	                bool ok = await McControl.Calib.TriggerTopDownCalibFlowAsync(McControl.Safety.AbortToken).ConfigureAwait(true);
272	                _dialog.Info(ok
273	                    ? "Đã kích hoạt Flow TopDownCalib — báo tìm thấy."
274	                    : "Đã kích hoạt Flow TopDownCalib — KHÔNG báo tìm thấy, kiểm tra dấu chuẩn/khung hình.");
275	            }
276	            finally { Busy = false; }
277	        }
278	
279	        private async Task RunBottomUpCalibAsync()
280	        {
281	            if (Busy) return;
282	
283	            Busy = true;
284	            try
285	            {
286	                double x1 = McControl.Motion[AxisId.X].CurrentPos;
287	                double x2 = x1 + BottomUpProbeDeltaX;
288	                var result = await McControl.Calib.CalibrateBottomUpAsync(x1, x2, McControl.Safety.AbortToken).ConfigureAwait(true);
289	
290	                if (result.Calib == null)
291	                {
292	                    _dialog.Error("Hiệu chuẩn CAM bottom-up thất bại: " + result.Reason);
293	                    return;
294	                }
295	
296	                string msg = string.Format("scale bản chuẩn {0:0.00000} mm/px, scale trục X {1:0.00000} mm/px, lệch {2:0.00}%.",
297	                    result.ScaleFromBoard, result.ScaleFromAxis, result.ScaleCrossCheckDiffRatio * 100);
298	
299	                if (result.Ok)
300	                {
301	                    var c = result.Calib;
302	                    c.IsCalibrated = true;
303	                    c.CalibratedAt = DateTime.Now;
304	                    c.CalibratedBy = Environment.UserName;
305	                    c.PointCount = result.CornerCount;
306	                    Calib.BottomUp = c;
307	                    RefreshCalibText();
308	                    _dialog.Info("Hiệu chuẩn CAM bottom-up ĐẠT, đã ghi vào model — nhớ bấm Lưu model. " + msg);
309	                }
310	                else
311	                {
312	                    _dialog.Warn("Hiệu chuẩn CAM bottom-up KHÔNG ĐẠT, chưa ghi vào model. " + msg + " " + result.Reason);
313	                }
314	            }
315	            finally { Busy = false; }
316	        }
317	
318	        /// <summary>Xoay tay đang chọn (<see cref="SelectedTool"/>) tới <paramref name="angleDeg"/>
319	        /// rồi trigger Flow AlignCalib của đúng tay đó — App chỉ lo di chuyển + trigger, phép
320	        /// hiệu chuẩn N-point CÓ XOAY + Teach Master làm thủ công trong VMEditControl (cột trái)
321	        /// từ các điểm vừa chụp (PLAN.md §6.4, Tuấn chốt 2026-09-08) — giống hệt cách §6.2 CAM
322	        /// top-down đã làm cho lưới 9 điểm.</summary>
323	        private async Task RunAlignCalibPointAsync(double angleDeg)
324	        {
325	            if (Busy) return;
326	            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước khi hiệu chuẩn."); return; }
327	
328	            Busy = true;
329	            try
330	            {
331	                bool ok = await McControl.Calib
332	                    .MoveAndTriggerAlignCalibAsync(SelectedTool, angleDeg, McControl.Safety.AbortToken)
333	                    .ConfigureAwait(true);
334	                if (!ok) _dialog.Warn($"Góc {angleDeg}°: xoay hoặc Flow AlignCalib Tool{SelectedTool} thất bại — kiểm tra lại.");
335	            }
336	            finally { Busy = false; }
337	        }
338	
339	        /// <summary>Trigger Flow AlignCalib của tay đang chọn tại góc hiện tại, không xoay — test
340	        /// Flow riêng, giống "Trigger Flow TopDownCalib".</summary>
341	        private async Task TriggerAlignCalibFlowAsync()
342	        {
343	            if (Busy) return;
344	
345	            Busy = true;
346	            try
347	            {
348	                bool ok = await McControl.Calib.TriggerAlignCalibFlowAsync(SelectedTool, McControl.Safety.AbortToken).ConfigureAwait(true);
349	                _dialog.Info(ok
350	                    ? $"Đã kích hoạt Flow AlignCalib Tool{SelectedTool} — báo tìm thấy."
351	                    : $"Đã kích hoạt Flow AlignCalib Tool{SelectedTool} — KHÔNG báo tìm thấy, kiểm tra sản phẩm/khung hình.");
352	            }
353	            finally { Busy = false; }
354	        }
355	
356	        private double _handEyeCamX, _handEyeCamY;
357	        private int _handEyeMeasuredNozzle;
358	
359	        private async Task MeasureHandEyeCameraAsync(int nozzle)
360	        {
361	            if (Busy) return;
362	            if (!Calib.TopDown.IsCalibrated) { _dialog.Warn("Chưa hiệu chuẩn CAM top-down — làm §6.2 trước."); return; }
363	
364	            Busy = true;
365	            try
366	            {
367	                var result = await McControl.Calib
368	                    .MeasureHandEyeCameraPosAsync(Calib.TopDown, McControl.Safety.AbortToken)
369	                    .ConfigureAwait(true);
370	
371	                if (!result.Ok)
372	                {
373	                    _dialog.Error("Không thấy dấu chuẩn: " + result.Reason);
374	                    return;
375	                }
376	
377	                _handEyeCamX = result.CamX;
378	                _handEyeCamY = result.CamY;
379	                _handEyeMeasuredNozzle = nozzle;
380	
381	                _dialog.Info(string.Format(
382	                    "Đã đo vị trí camera: ({0:0.000}, {1:0.000}). Giờ sang trang Manual, jog đầu hút #{2} " +
383	                    "chạm ĐÚNG dấu chuẩn đó, rồi quay lại đây bấm \"Ghi offset\".",
384	                    result.CamX, result.CamY, nozzle));
385	            }
386	            finally { Busy = false; }
387	        }
388	
389	        private void CommitHandEye(int nozzle)
390	        {
391	            if (_handEyeMeasuredNozzle != nozzle)
392	            {
393	                _dialog.Warn($"Chưa đo vị trí camera cho tay #{nozzle} — bấm \"Đo vị trí camera\" trước.");
394	                return;
395	            }
396	            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc."); return; }
397	
398	            double nozzleX = McControl.Motion[AxisId.X].CurrentPos;
399	            double nozzleY = McControl.Motion[AxisId.Y2].CurrentPos;
400	            double dx = nozzleX - _handEyeCamX;
401	            double dy = nozzleY - _handEyeCamY;
402	
403	            if (nozzle == 1) { Calib.HandEye1Dx = dx; Calib.HandEye1Dy = dy; }
404	            else { Calib.HandEye2Dx = dx; Calib.HandEye2Dy = dy; }
405	
406	            _handEyeMeasuredNozzle = 0;
407	            RefreshCalibText();
408	            _dialog.Info($"Đã ghi hand-eye tay #{nozzle}: dx={dx:0.000}, dy={dy:0.000} mm — nhớ bấm Lưu model.");
409	        }
410	
411	        private void SetBottomUpYSign(int sign)
412	        {
413	            Calib.BottomUpYSign = sign;
414	            Calib.BottomUpYSignVerifiedAt = DateTime.Now;
415	            RefreshCalibText();
416	            _dialog.Info("Đã ghi dấu trục Y = " + (sign > 0 ? "+1" : "−1") +
417	                ", ngày xác minh " + DateTime.Now.ToString("dd/MM/yyyy") + " — nhớ bấm Lưu model.");
418	        }
419	
420	        // ───────────────────────── commands ─────────────────────────
421	
422	        public ICommand TopDownPoint1Command { get; }
423	        public ICommand TopDownPoint2Command { get; }
424	        public ICommand TopDownPoint3Command { get; }
425	        public ICommand TopDownPoint4Command { get; }
426	        public ICommand TopDownPoint5Command { get; }
427	        public ICommand TopDownPoint6Command { get; }
428	        public ICommand TopDownPoint7Command { get; }
429	        public ICommand TopDownPoint8Command { get; }
430	        public ICommand TopDownPoint9Command { get; }
431	        public ICommand SaveCalibrationCenterCommand { get; }
432	        public ICommand AutoCalibCommand { get; }
433	        public ICommand TriggerTopDownFlowCommand { get; }
434	
435	        public ICommand RunBottomUpCalibCommand { get; }
436	        public ICommand RunAlignCalibAngle0Command { get; }
437	        public ICommand RunAlignCalibAngle60Command { get; }
438	        public ICommand RunAlignCalibAngle120Command { get; }
439	        public ICommand RunAlignCalibAngle180Command { get; }
440	        public ICommand RunAlignCalibAngle240Command { get; }
441	        public ICommand RunAlignCalibAngle300Command { get; }
442	        public ICommand TriggerAlignCalibFlowCommand { get; }
443	        public ICommand MeasureHandEyeCommand { get; }
444	        public ICommand CommitHandEyeCommand { get; }
445	        public ICommand SetYSignPositiveCommand { get; }
446	        public ICommand SetYSignNegativeCommand { get; }
447	    }
