1	using System;
2	using ShieldCanAssy.Core.Communication;
3	using ShieldCanAssy.Core.Data.Model;
4	
5	namespace ShieldCanAssy.Core.Controller
6	{
7	    /// <summary>Kết quả tính điểm đặt cho một sản phẩm.</summary>
8	    public class PlaceSolution
9	    {
10	        public bool Ok { get; set; }
11	        public string Reason { get; set; }
12	
13	        /// <summary>Góc phải xoay thêm cho trục A của tay hút này, độ.</summary>
14	        public double DeltaThetaDeg { get; set; }
15	
16	        /// <summary>Toạ độ lệnh cho trục X và trục Y của tray lắp ráp (Y2).</summary>
17	        public double CommandX { get; set; }
18	        public double CommandY { get; set; }
19	
20	        /// <summary>Độ lệch tâm sản phẩm so với trục xoay SAU KHI xoay — phần bù bằng X/Y2.</summary>
21	        public double ErrX { get; set; }
22	        public double ErrY { get; set; }
23	        public double ErrDistance { get { return Math.Sqrt(ErrX * ErrX + ErrY * ErrY); } }
24	
25	        public static PlaceSolution Fail(string why)
26	        {
27	            return new PlaceSolution { Ok = false, Reason = why };
28	        }
29	    }
30	
31	    /// <summary>
32	    /// Toán tính điểm đặt — PLAN.md §6.6. Tách thành hàm thuần để kiểm chứng được bằng
33	    /// <c>--selftest</c> mà không cần camera hay trục nào: đây là phần dễ sai nhất của cả máy
34	    /// và sai của nó biểu hiện thành đặt lệch chứ không phải thành thông báo lỗi.
35	    ///
36	    /// <para><b>Quy ước toạ độ.</b> Mọi giá trị hình học đều quy về <b>toạ độ lệnh của trục</b>,
37	    /// không qua hệ trung gian nào:</para>
38	    /// <list type="bullet">
39	    /// <item><c>bottom.PixelX/PixelY/Angle</c> (procedure <c>AlignBottomTool1</c>/
40	    /// <c>AlignBottomTool2</c>) đã là ĐỘ LỆCH mm/độ so với tâm xoay và Master của ĐÚNG tay hút
41	    /// này — VisionMaster tự hiệu chuẩn N-point CÓ XOAY + Teaching bên trong Flow (§6.4, Tuấn
42	    /// chốt 2026-09-08), KHÔNG còn quy đổi pixel→mm hay trừ tâm xoay/Master ở đây nữa (khác bản
43	    /// trước). Tên field vẫn là "Pixel..." vì dùng chung <see cref="VisionPose"/> với các
44	    /// procedure khác còn trả pixel thô — chỉ riêng 2 procedure này đổi ý nghĩa.</item>
45	    /// <item><c>TopDown.ToMm</c> trả về lượng phải dịch trục X và Y2 để đưa tâm ảnh CAM
46	    /// top-down tới đúng chi tiết vừa nhìn thấy. Dấu nằm sẵn trong ma trận vì camera này
47	    /// được hồi quy thẳng pixel → toạ độ lệnh trục (§6.2).</item>
48	    /// <item><c>HandEye_i</c> = hiệu toạ độ trục giữa "đầu hút i chạm dấu chuẩn" và "CAM
49	    /// top-down nhìn thấy dấu chuẩn đó" (§6.5). Đo riêng từng tay nên nó đã chứa sẵn khoảng
50	    /// cách pitch giữa hai đầu hút — <b>không</b> được cộng pitch thêm lần nữa ở đây.</item>
51	    /// </list>
52	    /// </summary>
53	    public static class PlacementSolver
54	    {
55	        /// <summary>
56	        /// Tính lệnh xoay và lệnh X/Y2 để đặt sản phẩm đang giữ trên tay hút <paramref name="nozzle"/>
57	        /// vào đúng tư thế của chi tiết đích.
58	        /// </summary>
59	        /// <param name="bottom">Tư thế sản phẩm do CAM bottom-up đo (bước S20/S21).</param>
60	        /// <param name="top">Tư thế chi tiết đích do CAM top-down đo (bước S30/S32).</param>
61	        /// <param name="captureX">Toạ độ trục X lúc chụp ảnh top-down.</param>
62	        /// <param name="captureY">Toạ độ trục Y2 lúc chụp ảnh top-down.</param>
63	        public static PlaceSolution Solve(VisionCalib calib, int nozzle,
64	                                          VisionPose bottom, VisionPose top,
65	                                          double captureX, double captureY,
66	                                          double maxAngleDeg, double maxDistance)
67	        {
68	            if (calib == null) return PlaceSolution.Fail("chưa có dữ liệu hiệu chuẩn");
69	            if (bottom == null || !bottom.Found) return PlaceSolution.Fail("CAM bottom-up không tìm thấy sản phẩm");
70	            if (top == null || !top.Found) return PlaceSolution.Fail("CAM top-down không tìm thấy chi tiết đích");
71	
72	            // ── Sản phẩm đang giữ: (px, py, bottomAngle) đã là ĐỘ LỆCH mm/độ so với tâm xoay và
73	            // Master của ĐÚNG tay hút này, tính SẴN bên trong VisionMaster (Flow AlignBottomTool1/
74	            // AlignBottomTool2 — hiệu chuẩn N-point CÓ XOAY + Teaching, PLAN.md §6.4, Tuấn chốt
75	            // 2026-09-08). Không còn CameraCalib.BottomUp.ToMm/BottomUpYSign/RotationCenter/Master
76	            // ở đây nữa — bản trước tự làm cả chuỗi đó bằng tay, giờ VisionMaster đã làm xong.
77	            double px = bottom.PixelX;
78	            double py = bottom.PixelY;
79	            double bottomAngle = bottom.Angle;
80	
81	            // ── Chi tiết đích: lượng dịch trục để tâm ảnh top-down trùng chi tiết ──
82	            double tdx, tdy;
83	            calib.TopDown.ToMm(top.PixelX, top.PixelY, out tdx, out tdy);
84	
85	            double handEyeDx = nozzle == 1 ? calib.HandEye1Dx : calib.HandEye2Dx;
86	            double handEyeDy = nozzle == 1 ? calib.HandEye1Dy : calib.HandEye2Dy;
87	
88	            double targetX = captureX + tdx + handEyeDx;
89	            double targetY = captureY + tdy + handEyeDy;
90	
91	            // ── Xoay ──
92	            double delta = NormalizeDeg(top.Angle - bottomAngle);
93	
94	            // Sản phẩm không nằm đúng trục xoay, nên xoay Δθ làm TÂM SẢN PHẨM dịch đi một
95	            // lượng phụ thuộc độ lệch tâm. Bỏ qua bước này thì sai số đặt tỉ lệ với độ lệch
96	            // tâm và không bù được bằng một offset cố định — lượng dịch đổi theo từng Δθ (§6.4).
97	            double rad = delta * Math.PI / 180.0;
98	            double cos = Math.Cos(rad), sin = Math.Sin(rad);
99	            double dx = px, dy = py;
100	
101	            double errX = dx * cos - dy * sin;      // p' = R(Δθ)·p — p đã là độ lệch so với tâm xoay
102	            double errY = dx * sin + dy * cos;
103	
104	            var sol = new PlaceSolution
105	            {
106	                Ok = true,
107	                DeltaThetaDeg = delta,
108	                ErrX = errX,
109	                ErrY = errY,
110	                CommandX = targetX - errX,
111	                CommandY = targetY - errY
112	            };
113	
114	            // Vượt ngưỡng nghĩa là vision đo nhầm vật, không phải sản phẩm lệch nhiều. Coi là
115	            // Align fail chứ không lao trục đi bù (§6.6).
116	            if (Math.Abs(delta) > maxAngleDeg)
117	            {
118	                sol.Ok = false;
119	                sol.Reason = string.Format("góc bù {0:0.0}° vượt ngưỡng {1:0.0}°", delta, maxAngleDeg);
120	            }
121	            else if (sol.ErrDistance > maxDistance)
122	            {
123	                sol.Ok = false;
124	                sol.Reason = string.Format("lượng bù {0:0.00} mm vượt ngưỡng {1:0.00} mm",
125	                    sol.ErrDistance, maxDistance);
126	            }
127	
128	            return sol;
129	        }
130	
131	        /// <summary>Đưa góc về khoảng (−180, 180] — xoay 350° và xoay −10° là một, chọn cái ngắn.</summary>
132	        public static double NormalizeDeg(double deg)
133	        {
134	            while (deg > 180.0) deg -= 360.0;
135	            while (deg <= -180.0) deg += 360.0;
136	            return deg;
137	        }
