{
    /// <summary>
    /// Ma trận affine pixel → mm hệ máy của một camera, cùng số liệu chất lượng của lần
    /// hiệu chuẩn sinh ra nó (PLAN.md §6.1).
    /// </summary>
    public class CameraCalib
    {
        /// <summary>X = B11·u + B12·v + B13</summary>
        public double B11 { get; set; } = 1;
        public double B12 { get; set; }
        public double B13 { get; set; }

        /// <summary>Y = B21·u + B22·v + B23</summary>
        public double B21 { get; set; }
        public double B22 { get; set; } = 1;
        public double B23 { get; set; }

        public bool IsCalibrated { get; set; }
        public DateTime CalibratedAt { get; set; }
        public string CalibratedBy { get; set; }
        public double RmsResidual { get; set; }
        public double MaxResidual { get; set; }
        public int PointCount { get; set; }

        /// <summary>Ghi chú cách hiệu chuẩn: "9 điểm bằng trục máy" hay "checkerboard 1 mm".</summary>
        public string Method { get; set; }

        public void ToMm(double pixelX, double pixelY, out double mmX, out double mmY)
        {
            mmX = B11 * pixelX + B12 * pixelY + B13;
            mmY = B21 * pixelX + B22 * pixelY + B23;
        }

        public double ScaleX => Math.Sqrt(B11 * B11 + B21 * B21);
        public double ScaleY => Math.Sqrt(B12 * B12 + B22 * B22);
        public double RotationDeg => Math.Atan2(B21, B11) * 180.0 / Math.PI;
        public int Handedness => Math.Sign(B11 * B22 - B12 * B21);

        public bool IsExpired(int validDays)
            => IsCalibrated && (DateTime.Now - CalibratedAt).TotalDays > validDays;

        /// <summary>
        /// Ma trận đơn giản hoá cho chế độ mô phỏng: chỉ có tỉ lệ mm/pixel, không xoay, không
        /// nghiêng, gốc đặt tại tâm ảnh. Đủ để chạy và kiểm chứng toàn bộ chuỗi Auto trước khi
        /// có camera thật; <see cref="Method"/> ghi rõ là số giả để không ai nhầm với hiệu chuẩn.
        /// </summary>
        public static CameraCalib CreateSimulation(double mmPerPixel, double centerX, double centerY)
        {
            return new CameraCalib
            {
                B11 = mmPerPixel, B12 = 0, B13 = -mmPerPixel * centerX,
                B21 = 0, B22 = mmPerPixel, B23 = -mmPerPixel * centerY,
                IsCalibrated = true,
                CalibratedAt = DateTime.Now,
                CalibratedBy = "(mô phỏng)",
                Method = "SỐ GIẢ — chế độ mô phỏng, chưa hiệu chuẩn thật",
                PointCount = 0
            };
        }
    }

    /// <summary>
    /// Toàn bộ dữ liệu hiệu chuẩn vision của một model.
    ///
    /// <para>Tâm xoay + Master của từng tay hút (cũ: <c>RotationCenter</c>/<c>MasterPose</c>,
    /// PLAN.md §6.4) đã BỎ khỏi đây — hiệu chuẩn N-point CÓ XOAY + Teaching nay làm trực tiếp
    /// trong VisionMaster (Flow AlignBottomTool1/AlignBottomTool2 tự trả về độ lệch đã bù sẵn,
    /// xem <see cref="ShieldCanAssy.Core.Controller.PlacementSolver"/>), App không còn giữ hằng
    /// số nào cho việc này (Tuấn chốt 2026-09-08).</para>
    /// </summary>
    public class VisionCalib
    {
        public CameraCalib BottomUp { get; set; } = new CameraCalib();
        public CameraCalib TopDown { get; set; } = new CameraCalib();

        /// <summary>Hand-eye: offset từ tâm quang CAM top-down tới tâm mỗi đầu hút (§6.5).</summary>
        public double HandEye1Dx { get; set; }
        public double HandEye1Dy { get; set; }
        public double HandEye2Dx { get; set; }
        public double HandEye2Dy { get; set; }

        /// <summary>
        /// Dấu của trục Y trong ảnh bottom-up so với chiều dương của Y2. CAM bottom-up không có
        /// chuyển động Y để suy ra dấu này, nên nó phải được xác minh bằng một phép thử vật lý
        /// và ghi lại kèm ngày (PLAN.md §6.3) — không suy đoán.
        /// </summary>
        public int BottomUpYSign { get; set; } = 1;
        public DateTime BottomUpYSignVerifiedAt { get; set; }

        /// <summary>Chỉ còn đòi 2 camera (checkerboard §6.3 + 9 điểm §6.2) — tâm xoay/Master của
        /// AlignBottom nay hiệu chuẩn trong VisionMaster, App không còn tự kiểm được nên không
        /// còn nằm trong điều kiện này (PLAN.md §6.4, Tuấn chốt 2026-09-08).</summary>
        public bool IsUsable
        {
            get
            {
                return BottomUp != null && BottomUp.IsCalibrated &&
                       TopDown != null && TopDown.IsCalibrated;
            }
        }
    }

    /// <summary>Dữ liệu một model sản phẩm — lưu ở Model\&lt;tên&gt;.json.</summary>
    public class ModelData
    {
        public string Name { get; set; } = "DEFAULT";
        public string Description { get; set; }
        public DateTime ModifiedAt { get; set; } = DateTime.Now;

        public TrayLayout InputTray { get; set; } = TrayLayout.CreateInputDefault();
        public TrayLayout AssyTray { get; set; } = TrayLayout.CreateAssyDefault();

        public VisionCalib Calib { get; set; } = new VisionCalib();

        /// <summary>Vị trí X để đưa từng tay hút vào giữa khung hình CAM bottom-up.</summary>
        public double AlignPosX_Nozzle1 { get; set; }
        public double AlignPosX_Nozzle2 { get; set; }

        /// <summary>
        /// Nạp bộ số giả để chạy được chuỗi Auto ở chế độ mô phỏng: lưới tray đã teach, hiệu
        /// chuẩn 2 camera, tâm xoay, hand-eye. Chỉ gọi khi <c>SimulationMode</c>, và có ghi log.
        /// Toàn bộ số ở đây là bịa — mục đích là kiểm chứng LOGIC chu trình trước khi có máy.
        /// </summary>
        public static ModelData CreateSimulation()
        {
            var m = new ModelData
            {
                Name = "SIM",
                Description = "Model giả lập — số liệu bịa, chỉ dùng để chạy thử chu trình"
            };

            // Mỗi Tool có lưới riêng (TrayGeometry) — Z2 cố ý lệch Z1 một lượng KHÔNG PHẢI một
            // shift X thuần tuý (−30 X, +0.4 Y) để mô phỏng vừa pitch cơ khí vừa sai lệch nhỏ
            // ngoài trục X, bắt được bài test nào lỡ giả định "Tool2 = Tool1 trừ hằng số X" thay
            // vì đọc đúng lưới riêng của Tool2 (Tuấn xác nhận 2026-09-05).
            const double pitchX = 30.0, skewY = 0.4;

            m.InputTray.Rows = 4; m.InputTray.Cols = 5;
            m.InputTray.GeoZ1.P00 = new TeachPoint(150, 50);
            m.InputTray.GeoZ1.P0C = new TeachPoint(230, 50);      // 4 bước × 20 mm
            m.InputTray.GeoZ1.PR0 = new TeachPoint(150, 125);     // 3 bước × 25 mm
            m.InputTray.GeoZ2.P00 = new TeachPoint(150 - pitchX, 50 + skewY);
            m.InputTray.GeoZ2.P0C = new TeachPoint(230 - pitchX, 50 + skewY);
            m.InputTray.GeoZ2.PR0 = new TeachPoint(150 - pitchX, 125 + skewY);
            // Z dương là chiều ĐI XUỐNG, "an toàn" (Z_SAFE mặc định 50) là vị trí NHỎ (Tuấn xác
            // nhận 2026-09-04) — Z_Pick phải LỚN HƠN Z_SAFE để mô phỏng đúng "đã hạ xuống, chưa
            // an toàn", nếu không chốt chặn Z_SAFE không được bài test nào chạy qua thật sự. Z1/Z2
            // cố ý lệch nhau 1 mm — số giả, chỉ để bài test không vô tình phụ thuộc vào việc hai
            // tay hút luôn cùng cao độ (Tuấn xác nhận 2026-09-05: hai tay không nhất thiết bằng nhau).
            m.InputTray.Z_PickZ1 = 90;
            m.InputTray.Z_PickZ2 = 91;

            m.AssyTray.Rows = 5; m.AssyTray.Cols = 6;
            m.AssyTray.GeoZ1.P00 = new TeachPoint(350, 60);
            m.AssyTray.GeoZ1.P0C = new TeachPoint(460, 60);       // 5 bước × 22 mm
            m.AssyTray.GeoZ1.PR0 = new TeachPoint(350, 164);      // 4 bước × 26 mm
            m.AssyTray.GeoZ2.P00 = new TeachPoint(350 - pitchX, 60 + skewY);
            m.AssyTray.GeoZ2.P0C = new TeachPoint(460 - pitchX, 60 + skewY);
            m.AssyTray.GeoZ2.PR0 = new TeachPoint(350 - pitchX, 164 + skewY);
            m.AssyTray.Z_PickZ1 = 95;
            m.AssyTray.Z_PickZ2 = 96;

            // CAM bottom-up cố định ở X = 300 (toạ độ của đầu hút khi nằm giữa khung hình), teach
            // riêng từng Tool nên không suy ra từ pitch nữa.
            m.AlignPosX_Nozzle1 = 300;
            m.AlignPosX_Nozzle2 = 300 - pitchX;

            // FOV 30 mm trải trên 1280 pixel — khớp ảnh giả của FakeVision (tâm 640×480).
            const double mmPerPixel = 30.0 / 1280.0;
            m.Calib.BottomUp = CameraCalib.CreateSimulation(mmPerPixel, 640, 480);
            m.Calib.TopDown = CameraCalib.CreateSimulation(mmPerPixel, 640, 480);

            m.Calib.HandEye1Dx = -40; m.Calib.HandEye1Dy = 5;
            m.Calib.HandEye2Dx = -10; m.Calib.HandEye2Dy = 5;
            m.Calib.BottomUpYSign = 1;
            m.Calib.BottomUpYSignVerifiedAt = DateTime.Now;

            // Mốc CAM top-down = vị trí camera khi soi Ô (1,1) của Assy Tray — giữ tương đương
            // công thức cũ (cellPos(0,0) trừ Hand-Eye tay #1) để hành vi mô phỏng không đổi.
            m.AssyTray.CamTopDownAnchorX = m.AssyTray.GeoZ1.P00.X - m.Calib.HandEye1Dx;
            m.AssyTray.CamTopDownAnchorY = m.AssyTray.GeoZ1.P00.Y - m.Calib.HandEye1Dy;
            m.AssyTray.CamTopDownAnchorTaught = true;

            return m;
        }
    }
}

