12	namespace ShieldCanAssy.Core.Communication
13	{
14	    /// <summary>
15	    /// CAM bottom-up + CAM top-down thật, qua HIKROBOT VisionMaster 4.4.0 — bọc
16	    /// <see cref="VisionMasterDevice"/>. PLAN.md §2.1, §6.
17	    ///
18	    /// <para><b>Chưa kiểm chứng với solution thật.</b> Viết trước để khi có file .sol thật chỉ
19	    /// còn sửa tên Flow/biến output ở trang Setting, không phải vừa gõ code vừa đứng cạnh máy —
20	    /// giống <see cref="PanasonicAxis"/>. Tên Flow/output đọc từ
21	    /// <see cref="SystemData.VisionOutputs"/> (cấu hình được, không hardcode) — đó cũng là hợp
22	    /// đồng Tuấn cần khớp khi dựng solution trong VisionMaster IDE (PLAN.md §6.8).</para>
23	    /// </summary>
24	    public class VisionConnect : Bindable, IVisionDevice
25	    {
26	        private readonly SystemData _sys;
27	        private readonly VisionMasterDevice _device = new VisionMasterDevice();
28	        private readonly object _cmdLock = new object();
29	
30	        public VisionConnect(SystemData sys)
31	        {
32	            _sys = sys;
33	        }
34	
35	        private bool _connected;
36	        public bool IsConnected { get { return _connected; } private set { SetProperty(ref _connected, value); } }
37	
38	        public bool IsSolutionLoaded { get { return _device.IsSolutionLoaded; } }
39	
40	        private Bitmap _lastTopDownImage;
41	        public Bitmap LastTopDownImage { get { return _lastTopDownImage; } private set { SetProperty(ref _lastTopDownImage, value); } }
42	
43	        private Bitmap _lastBottomUpImage;
44	        public Bitmap LastBottomUpImage { get { return _lastBottomUpImage; } private set { SetProperty(ref _lastBottomUpImage, value); } }
45	
46	        /// <summary>
47	        /// PlatformSDK không có bước "connect" tách rời khỏi nạp solution — kết nối camera thật
48	        /// diễn ra bên trong <c>LoadSolution</c>. Cờ này chỉ đánh dấu "sẵn sàng gọi nạp solution",
49	        /// đúng thứ tự <c>McControl.Init()</c> đang gọi: <c>Connect()</c> rồi <c>LoadSolutionAsync()</c>.
50	        /// </summary>
51	        public bool Connect()
52	        {
53	            IsConnected = true;
54	            return true;
55	        }
56	
57	        public void Disconnect()
58	        {
59	            try { _device.Shutdown(); } catch { }
60	            IsConnected = false;
61	        }
62	
63	        public async Task<bool> LoadSolutionAsync(string solutionPath)
64	        {
65	            try
66	            {
67	                await Task.Run(() =>
68	                {
69	                    lock (_cmdLock) { _device.LoadSolution(solutionPath, ""); }
70	                }).ConfigureAwait(false);
71	                return true;
72	            }
73	            catch (Exception ex)
74	            {
75	                LogWorker.Instance.RecordLog("Vision: nạp solution lỗi — " + ex.Message,
76	                    Utility.Log.LogLevel.Error, "Vision");
77	                return false;
78	            }
79	        }
80	
81	        public async Task<VisionPose> TriggerAsync(EVisionProcedure procedure, CancellationToken ct)
82	        {
83	            if (!IsConnected) return VisionPose.NotFound("chưa kết nối");
84	            if (!IsSolutionLoaded) return VisionPose.NotFound("chưa nạp solution");
85	
86	            var names = _sys.VisionOutputs;
87	            string flow;
88	            switch (procedure)
89	            {
90	                case EVisionProcedure.TopDownCalib: flow = names.FlowTopDownCalib; break;
91	                case EVisionProcedure.AlignBottomTool1: flow = names.FlowAlignBottomTool1; break;
92	                case EVisionProcedure.AlignBottomTool2: flow = names.FlowAlignBottomTool2; break;
93	                case EVisionProcedure.AlignCalibTool1: flow = names.FlowAlignCalibTool1; break;
94	                case EVisionProcedure.AlignCalibTool2: flow = names.FlowAlignCalibTool2; break;
95	                default: flow = names.FlowLocateTop; break;
96	            }
97	
98	            try
99	            {
100	                var result = await RunWithTimeoutAsync(() => _device.RunAndGetFloatsWithImage(flow, names.OutImage,
101	                    names.OutFound, names.OutPoseX, names.OutPoseY, names.OutAngle, names.OutScore),
102	                    ct).ConfigureAwait(false);
103	
104	                if (result == null)
105	                {
106	                    AlarmManager.Raise(AlarmCode.VisionTriggerTimeout, "Vision", flow);
107	                    return VisionPose.NotFound("quá thời gian chờ");
108	                }
109	
110	                // Sửa lỗi tồn tại từ trước (2026-09-10, phát hiện lúc bỏ Flow AlignBottom chung):
111	                // điều kiện cũ so procedure == AlignBottom (Flow chung, đã orphan) — nhưng Auto
112	                // thật CHỈ trigger AlignBottomTool1/Tool2 (không bao giờ AlignBottom nữa), nên ảnh
113	                // CAM bottom-up trước đây KHÔNG BAO GIỜ được gán vào LastBottomUpImage, luôn rơi
114	                // nhầm vào nhánh LastTopDownImage bên dưới. AlignBottomTool1/2 VÀ AlignCalibTool1/2
115	                // đều là CAM bottom-up (khác CAM top-down của LocateTop/TopDownCalib).
116	                bool isBottomUp = procedure == EVisionProcedure.AlignBottomTool1
117	                    || procedure == EVisionProcedure.AlignBottomTool2
118	                    || procedure == EVisionProcedure.AlignCalibTool1
119	                    || procedure == EVisionProcedure.AlignCalibTool2;
120	                if (isBottomUp) LastBottomUpImage = result.Image;
121	                else LastTopDownImage = result.Image;
122	
123	                float[] r = result.Floats;
124	                bool found = r[0] > 0.5f;
125	                if (!found) return VisionPose.NotFound("solution báo không tìm thấy");
126	
127	                return new VisionPose { Found = true, PixelX = r[1], PixelY = r[2], Angle = r[3], Score = r[4] };
128	            }
129	            catch (VmException ex)
130	            {
131	                LogWorker.Instance.RecordLog("Vision: " + flow + " lỗi — " + ex.errorMessage,
132	                    Utility.Log.LogLevel.Error, "Vision");
133	                return VisionPose.NotFound(ex.errorMessage);
134	            }
135	            catch (Exception ex)
136	            {
137	                LogWorker.Instance.RecordLog("Vision: " + flow + " lỗi — " + ex.Message,
138	                    Utility.Log.LogLevel.Error, "Vision");
139	                return VisionPose.NotFound(ex.Message);
140	            }
141	        }
142	
143	        public async Task<CalibBoardResult> TriggerCalibBoardAsync(CancellationToken ct)
144	        {
145	            if (!IsConnected) return CalibBoardResult.NotFound("chưa kết nối");
146	            if (!IsSolutionLoaded) return CalibBoardResult.NotFound("chưa nạp solution");
147	
148	            var names = _sys.VisionOutputs;
149	
150	            try
151	            {
152	                float[] r = await RunWithTimeoutAsync(() => _device.RunAndGetFloats(names.FlowCalibBottomUp,
153	                    names.OutFound, names.OutScaleU, names.OutScaleV,
154	                    names.OutSkewDeg, names.OutCornerCount, names.OutOriginPixelU, names.OutOriginPixelV),
155	                    ct).ConfigureAwait(false);
156	
157	                if (r == null)
158	                {
159	                    AlarmManager.Raise(AlarmCode.VisionTriggerTimeout, "Vision", names.FlowCalibBottomUp);
160	                    return CalibBoardResult.NotFound("quá thời gian chờ");
161	                }
162	
163	                bool found = r[0] > 0.5f;
164	                if (!found) return CalibBoardResult.NotFound("không thấy đủ góc trên bản chuẩn");
165	
166	                return new CalibBoardResult
167	                {
168	                    Found = true,
169	                    ScaleU = r[1],
170	                    ScaleV = r[2],
171	                    SkewDeg = r[3],
172	                    CornerCount = (int)r[4],
173	                    OriginPixelU = r[5],
174	                    OriginPixelV = r[6]
175	                };
176	            }
177	            catch (VmException ex)
178	            {
179	                LogWorker.Instance.RecordLog("Vision: " + names.FlowCalibBottomUp + " lỗi — " + ex.errorMessage,
180	                    Utility.Log.LogLevel.Error, "Vision");
181	                return CalibBoardResult.NotFound(ex.errorMessage);
182	            }
183	            catch (Exception ex)
184	            {
185	                LogWorker.Instance.RecordLog("Vision: " + names.FlowCalibBottomUp + " lỗi — " + ex.Message,
186	                    Utility.Log.LogLevel.Error, "Vision");
187	                return CalibBoardResult.NotFound(ex.Message);
188	            }
189	        }
190	
191	        /// <summary>
192	        /// <c>VmProcedure.Run()</c> là lệnh CHẶN, không nhận token huỷ — bọc trong
193	        /// <c>Task.Run</c> rồi canh thời gian bằng <c>Task.WhenAny</c>. Hết giờ thì trả về
194	        /// <c>null</c> cho lớp gọi báo alarm 4003, nhưng luồng chạy <c>Run()</c> bên dưới KHÔNG bị
195	        /// huỷ thật — SDK không cho — nó tự trôi tới khi solution phản hồi. Cùng một giới hạn với
196	        /// timeout đọc trạng thái driver Panasonic.
197	        /// </summary>
198	        private async Task<T> RunWithTimeoutAsync<T>(Func<T> body, CancellationToken ct) where T : class
199	        {
200	            var runTask = Task.Run(() => { lock (_cmdLock) { return body(); } }, ct);
201	            var timeoutTask = Task.Delay(_sys.VisionTriggerTimeoutMs, ct);
202	            var done = await Task.WhenAny(runTask, timeoutTask).ConfigureAwait(false);
203	            return done == runTask ? await runTask.ConfigureAwait(false) : null;
204	        }
205	    }
206	}
