283	                        : Lib.Fastech.FastechBoardId.AxisA2;
284	                    cfg.AxisIndex = 0; cfg.Unit = "deg";
285	                    cfg.SoftLimitNeg = -360; cfg.SoftLimitPos = 360;
286	                    cfg.JogSpeedSlow = 45; cfg.JogSpeedFast = 90; cfg.MoveSpeed = 180;
287	                    cfg.PulsePerUnit = 10000.0 / 360.0; cfg.UnitPerRev = 360;   // ĐÃ CHỐT: 10000 xung/360°
288	                    cfg.HomeDir = +1; cfg.StandbyPos = 0;
