290	        private async Task<bool> S1x_Pick(int nozzle, EAutoState next, CancellationToken ct)
291	        {
292	            var nz = Nozzle(nozzle);
293	
294	            // Đã có sản phẩm sẵn trên tay (chạy tiếp sau khi dừng) thì bỏ qua bước hút.
295	            if (nz.HasProduct) { Run.AutoState = next; return true; }
296	
297	            var tray = Run.InputTray;
298	            int index = NextLoadedCell(tray);
299	            if (index < 0)
300	            {
301	                // Hết tray đầu vào. Nếu tay #1 cũng chưa có gì thì phải đổi tray trước khi
302	                // làm gì tiếp; nếu tay #1 đã có hàng thì chạy nốt sản phẩm đó rồi mới đổi.
303	                if (nozzle == 2 && Nozzle(1).HasProduct) { Run.AutoState = EAutoState.S20_Align1; return true; }
304	                Run.AutoState = EAutoState.S50_TrayCheck;
305	                return true;
306	            }
307	
