/// <summary>Điều kiện cho phép chạy — PLAN.md §5.1, xét lại ở đầu mỗi vòng.</summary>
private bool CanRun(out string why)
{
    why = null;

    if (!_status.OrgOk) { why = "chưa về gốc"; return false; }
    if (_status.Mode != EMcMode.Auto) { why = "chìa không ở vị trí AUTO"; return false; }
    if (AlarmManager.HasError) { why = "còn alarm chưa xoá"; return false; }

    var model = Model;
    if (model == null) { why = "chưa nạp model"; return false; }
    if (!model.InputTray.IsTaught) { why = "tray đầu vào chưa teach"; return false; }
    if (!model.AssyTray.IsTaught) { why = "tray lắp ráp chưa teach"; return false; }
    // IsUsable chỉ còn đòi 2 camera (BottomUp checkerboard §6.3 + TopDown §6.2) — tâm
    // xoay/Master của AlignBottom nay hiệu chuẩn trong VisionMaster, App không còn tự
    // kiểm được nên không còn nằm trong điều kiện này (PLAN.md §6.4, Tuấn chốt 2026-09-08).
    if (!model.Calib.IsUsable) { why = "chưa hiệu chuẩn đủ 2 camera"; return false; }

    int validDays = _sys().CalibValidDays;
    if (model.Calib.BottomUp.IsExpired(validDays) || model.Calib.TopDown.IsExpired(validDays))
        AlarmManager.Raise(AlarmCode.VisionCalibExpired, "Vision",
            "quá " + validDays + " ngày kể từ lần hiệu chuẩn gần nhất");

    // Kiểm tra ở đây để "chưa nạp solution" hiện ra đúng như nó là, chứ không biến thành
    // một chuỗi NG vision mà người vận hành sẽ đi tìm nguyên nhân ở camera và đèn.
    var vision = _vision();
    if (vision == null || !vision.IsConnected) { why = "chưa kết nối vision"; return false; }
    if (!vision.IsSolutionLoaded) { why = "chưa nạp solution vision"; return false; }

    if (!_func.HasTrayIn()) { why = "không có tray đầu vào"; return false; }
    if (!_func.HasTrayAssy()) { why = "không có tray lắp ráp"; return false; }

    return true;
}

// ───────────────────────── S10 / S11 — hút ─────────────────────────

private async Task<bool> S1x_Pick(int nozzle, EAutoState next, CancellationToken ct)
{
    var nz = Nozzle(nozzle);

    // Đã có sản phẩm sẵn trên tay (chạy tiếp sau khi dừng) thì bỏ qua bước hút.
    if (nz.HasProduct) { Run.AutoState = next; return true; }

    var tray = Run.InputTray;
    int index = NextLoadedCell(tray);
    if (index < 0)
    {
        // Hết tray đầu vào. Nếu tay #1 cũng chưa có gì thì phải đổi tray trước khi
        // làm gì tiếp; nếu tay #1 đã có hàng thì chạy nốt sản phẩm đó rồi mới đổi.
        if (nozzle == 2 && Nozzle(1).HasProduct) { Run.AutoState = EAutoState.S20_Align1; return true; }
        Run.AutoState = EAutoState.S50_TrayCheck;
        return true;
    }

    tray.CurrentIndex = index;
    int row, col;
    tray.RowCol(index, out row, out col);

    string zName = nozzle == 1 ? AxisId.Z1 : AxisId.Z2;
    var cell = Model.InputTray.CellPos(zName, row, col);

    tray.Set(index, ECellState.Processing);

    int retries = _sys().PickRetryCount;
    for (int attempt = 0; attempt <= retries; attempt++)
    {
        if (!await _func.MoveToCellAsync(Model.InputTray.AxisRow, cell.Y, cell.X, ct).ConfigureAwait(false))
            return Halt("không tới được ô hút (" + row + "," + col + ")");

        // Hút hụt thì hạ thêm một ít: nguyên nhân phổ biến nhất là sản phẩm nằm thấp
        // hơn dự kiến trong hốc tray, không phải hỏng chân không (§5.4). Z dương là
        // chiều ĐI XUỐNG (Tuấn xác nhận 2026-09-04) nên "hạ thêm" là CỘNG thêm, không
        // phải trừ.
        double zPick = Model.InputTray.ZPickFor(zName) + attempt * _sys().PickRetryDeltaZ;

        if (!await _func.MoveAsync(zName, zPick, ZSpeed(zName), ct).ConfigureAwait(false))
            return Halt(zName + " không hạ được xuống cao độ hút");

        _func.SetVacuum(nozzle, true);
        bool gripped = await WaitVacuumAsync(nozzle, true, ct).ConfigureAwait(false);

        if (!await _func.MoveAsync(zName, SafeZ(), ZSpeed(zName), ct).ConfigureAwait(false))
            return Halt(zName + " không nâng lên được");

        if (gripped)
        {
            nz.HasProduct = true;
            nz.SourceCellIndex = index;
            nz.Aligned = false;
            Run.AutoState = next;
            return true;
        }

        _func.SetVacuum(nozzle, false);
        AlarmManager.Raise(AlarmCode.PickFailed, "Auto",
            string.Format("tay #{0}, ô ({1},{2}), lần thử {3}/{4}",
                nozzle, row, col, attempt + 1, retries + 1));
    }

    // Hết số lần thử: đánh dấu ô hỏng và đi tiếp, KHÔNG dừng máy. Một ô lỗi không phải
    // lý do để cả tray đứng lại (§5.4).
    AlarmManager.ClearCondition(AlarmCode.PickFailed);
    tray.Set(index, ECellState.Ng);
    CountNg("hút hụt ô (" + row + "," + col + ")");
    return CheckConsecutiveNg();
}

