    if (index < 0)
    {
        // Hết ô lắp ráp mà tay vẫn còn hàng: giữ nguyên sản phẩm, đi đổi tray. Trạng
        // thái tay hút đã ghi xuống đĩa nên đổi xong quay lại đặt tiếp được.
        Run.AutoState = EAutoState.S50_TrayCheck;
        return true;
    }

    tray.CurrentIndex = index;
    int row, col;
    tray.RowCol(index, out row, out col);
    tray.Set(index, ECellState.Processing);

    VisionPose top;
    double captureX, captureY;

    AssyCellScan scan;
    if (_assyScan.TryGetValue(index, out scan))
    {
        // Đường thường: đã có sẵn từ S05_ScanAssy — không di chuyển CAM, không trigger
        // gì nữa, đúng phần rút ngắn chu kỳ mà thay đổi này nhắm tới. Dùng rồi thì bỏ
        // khỏi cache — ô này coi như đã tiêu thụ, tránh dùng nhầm nếu ô bị gán lại.
        top = scan.Top;
        captureX = scan.CaptureX;
        captureY = scan.CaptureY;
        _assyScan.Remove(index);
    }
    else
    {
        // Dự phòng: quét trước chưa kịp phủ ô này (vd. tray bị đổi hoặc cache bị dọn
        // giữa chừng) — đo trực tiếp như cách làm cũ, để việc đặt hàng KHÔNG BAO GIỜ phụ
        // thuộc bắt buộc vào việc đã quét trước hay chưa.
        var cell = Model.AssyTray.CellPos(AxisId.Z1, row, col);
        var cell00 = Model.AssyTray.CellPos(AxisId.Z1, 0, 0);
        double camX = Model.AssyTray.CamTopDownAnchorX + (cell.X - cell00.X);
        double camY = Model.AssyTray.CamTopDownAnchorY + (cell.Y - cell00.Y);

        if (!await _func.MoveToCellAsync(Model.AssyTray.AxisRow, camY, camX, ct).ConfigureAwait(false))
            return Halt("không tới được vị trí soi ô đích (" + row + "," + col + ")");

        captureX = _motion[AxisId.X].CurrentPos;
        captureY = _motion[Model.AssyTray.AxisRow].CurrentPos;
        top = await TriggerAsync(EVisionProcedure.LocateTop, ct).ConfigureAwait(false);
    }

    if (top == null || !top.Found)
    {
        // Không thấy chi tiết đích: bỏ qua ô đó, GIỮ sản phẩm sang ô kế tiếp. Sản phẩm
        // trên tay còn tốt, không có lý do gì loại nó vì ô đích trống (§5.4).
        AlarmManager.Raise(AlarmCode.VisionNotFound, "Vision",
            "LocateTop ô (" + row + "," + col + ")" + (top == null ? "" : ": " + top.Error));
        tray.Set(index, ECellState.Skipped);
        AlarmManager.ClearCondition(AlarmCode.VisionNotFound);
        return true;      // ở nguyên bước này, vòng sau lấy ô kế
    }

    var sys = _sys();
    var sol = PlacementSolver.Solve(Model.Calib, nozzle, _bottomPose[nozzle], top,
        captureX, captureY, sys.MaxCompensationAngleDeg, sys.MaxCompensationDistance);

    if (!sol.Ok)
    {
        AlarmManager.Raise(AlarmCode.CompensationOutOfRange, "Auto",
            "tay #" + nozzle + ": " + sol.Reason);
        tray.Set(index, ECellState.Empty);
        if (!await ReturnToSourceAsync(nozzle, ct).ConfigureAwait(false)) return false;
        AlarmManager.ClearCondition(AlarmCode.CompensationOutOfRange);
        CountNg("lượng bù vượt ngưỡng tay #" + nozzle);
        return CheckConsecutiveNg();
    }

    _status.LastDeltaTheta = sol.DeltaThetaDeg;
    _status.LastPlaceError = sol.ErrDistance;

    if (!await PlaceAsync(nozzle, sol, ct).ConfigureAwait(false)) return false;

    tray.Set(index, ECellState.Ok);
    Run.CountOk++;
    Run.CountTotal++;
    Run.ConsecutiveNg = 0;

    int src = nz.SourceCellIndex;
    if (src >= 0) Run.InputTray.Set(src, ECellState.Ok);

    nz.HasProduct = false;
    nz.SourceCellIndex = -1;
    nz.Aligned = false;
    _bottomPose[nozzle] = null;

    Save();
    Run.AutoState = next;
    return true;
}

/// <summary>Xoay, di chuyển tới điểm đã bù, hạ, nhả, nâng.</summary>
private async Task<bool> PlaceAsync(int nozzle, PlaceSolution sol, CancellationToken ct)
