using System.ComponentModel;
using System.Threading;
using System.Threading.Tasks;

namespace ShieldCanAssy.Core.Communication
{
    /// <summary>Kết quả một lần chụp: tư thế đối tượng trong ảnh.</summary>
    public class VisionPose
    {
        public bool Found { get; set; }

        /// <summary>Toạ độ pixel trong ảnh — quy đổi sang mm bằng ma trận hiệu chuẩn.</summary>
        public double PixelX { get; set; }
        public double PixelY { get; set; }

        /// <summary>Góc đo được, độ.</summary>
        public double Angle { get; set; }

        /// <summary>Điểm khớp mẫu 0..100.</summary>
        public double Score { get; set; }

        public string Error { get; set; }

        public static VisionPose NotFound(string why = null)
            => new VisionPose { Found = false, Error = why };
    }

    /// <summary>Các procedure của solution VisionMaster — PLAN.md §1.2.</summary>
    public enum EVisionProcedure
    {
        /// <summary>CAM top-down: đo tư thế chi tiết có sẵn trong ô tray lắp ráp.</summary>
        LocateTop,
        /// <summary>CAM top-down: Flow riêng cho wizard hiệu chuẩn lưới 9 điểm (trang Vision Edit)
        /// — khác <see cref="LocateTop"/> (dùng lúc chạy Auto sản xuất), vì bản hiệu chuẩn
        /// thường soi một dấu chuẩn cố định thay vì chi tiết thật.</summary>
        TopDownCalib,
        /// <summary>CAM bottom-up, tay hút #1 — Flow RIÊNG cho Tool1 (PLAN.md §6.4, Tuấn chốt
        /// 2026-09-08). Đã tự hiệu chuẩn N-point CÓ XOAY + Teaching bên trong VisionMaster nên
        /// Found/PoseX/PoseY/PoseAngle trả về là ĐỘ LỆCH mm/độ ĐÃ BÙ SẴN (tâm xoay + Master của
        /// riêng Tool1) — không còn là pixel thô, khác hẳn <see cref="LocateTop"/>/<see cref="TopDownCalib"/>.
        /// Xem <see cref="PlacementSolver"/>.</summary>
        AlignBottomTool1,
        /// <summary>CAM bottom-up, tay hút #2 — như <see cref="AlignBottomTool1"/> nhưng hiệu
        /// chuẩn/Teach riêng cho Tool2 (tâm xoay vật lý khác Tool1).</summary>
        AlignBottomTool2,
        /// <summary>CAM bottom-up, Flow RIÊNG chỉ dùng lúc hiệu chuẩn tâm xoay Tool1 — khác
        /// <see cref="AlignBottomTool1"/> (dùng lúc chạy Auto), đúng khuôn <see cref="TopDownCalib"/>
        /// vs <see cref="LocateTop"/>. Trigger tại mỗi góc trong chuỗi xoay hiệu chuẩn; phép fit
        /// N-point-có-xoay + Teach làm thủ công trong VMEditControl từ các điểm chụp qua Flow này.</summary>
        AlignCalibTool1,
        /// <summary>Như <see cref="AlignCalibTool1"/>, cho Tool2.</summary>
        AlignCalibTool2
    }

    /// <summary>
    /// Kết quả một lần chạy công cụ hiệu chuẩn bản chuẩn (checkerboard) của VisionMaster trên
    /// CAM bottom-up — PLAN.md §6.3 bước B2. Khác <see cref="VisionPose"/>: đây là số liệu
    /// HIỆU CHUẨN (scale, độ không vuông góc) do chính công cụ đó tính từ vài trăm góc bắt được
    /// trong khung hình, không phải toạ độ pixel của một vật.
    /// </summary>
    public class CalibBoardResult
    {
        public bool Found { get; set; }
        public string Error { get; set; }

        /// <summary>mm/pixel dọc trục ảnh u (ngang).</summary>
        public double ScaleU { get; set; }
        /// <summary>mm/pixel dọc trục ảnh v (dọc).</summary>
        public double ScaleV { get; set; }
        /// <summary>Độ không vuông góc giữa hai trục ảnh, độ — 0 = vuông góc hoàn hảo.</summary>
        public double SkewDeg { get; set; }
        /// <summary>Số góc bắt được trong khung hình — càng nhiều càng đáng tin (§6.3: kỳ vọng 841).</summary>
        public int CornerCount { get; set; }

        /// <summary>Pixel của góc mốc (0,0) trên bản chuẩn — dùng để đối chiếu chéo B3: chạy X
        /// tới vài vị trí đã biết, xem góc mốc dịch bao nhiêu pixel so với đúng bấy nhiêu mm.</summary>
        public double OriginPixelU { get; set; }
        public double OriginPixelV { get; set; }

        public static CalibBoardResult NotFound(string why = null)
            => new CalibBoardResult { Found = false, Error = why };
    }

    public interface IVisionDevice : INotifyPropertyChanged
    {
        bool IsConnected { get; }
        bool IsSolutionLoaded { get; }

        bool Connect();
        void Disconnect();

        Task<bool> LoadSolutionAsync(string solutionPath);

        /// <summary>Kích chụp và chờ kết quả. Timeout sinh alarm 4003 ở lớp gọi.</summary>
        Task<VisionPose> TriggerAsync(EVisionProcedure procedure, CancellationToken ct);

        /// <summary>Kích chạy công cụ hiệu chuẩn bản chuẩn — chỉ dùng trong wizard hiệu chuẩn
        /// CAM bottom-up (PLAN.md §6.3), không dùng trong chu trình Auto.</summary>
        Task<CalibBoardResult> TriggerCalibBoardAsync(CancellationToken ct);

        /// <summary>Ảnh chụp được của lần TriggerAsync(LocateTop) gần nhất — trang Main hiển thị
        /// để operator nhìn được CAM đang thấy gì, không bắt buộc phải có (null nếu solution
        /// chưa khai output ảnh, hoặc đang chạy mô phỏng).</summary>
        System.Drawing.Bitmap LastTopDownImage { get; }

        /// <summary>Ảnh chụp được của lần TriggerAsync(AlignBottom) gần nhất — cùng ý nghĩa với
        /// <see cref="LastTopDownImage"/>, khác camera.</summary>
        System.Drawing.Bitmap LastBottomUpImage { get; }
    }
}

