1	using System;
2	using System.Collections.Generic;
3	using ShieldCanAssy.Core.Data.Model;
4	
5	namespace ShieldCanAssy.Core.Controller
6	{
7	    /// <summary>Một cặp tương ứng pixel ↔ toạ độ thực dùng để hồi quy ma trận affine (PLAN.md §6.1).</summary>
8	    public struct CalibPoint
9	    {
