21	
22	        /// <summary>Sai số dư từng điểm, cùng thứ tự với danh sách điểm đưa vào — PLAN.md §6.1:
23	        /// một điểm lệch hẳn so với các điểm còn lại nghĩa là điểm đó đo sai.</summary>
24	        public double[] PointResiduals { get; set; }
25	
26	        public static AffineFitResult Fail(string reason) => new AffineFitResult { Ok = false, Reason = reason };
27	    }
28	
29	    public class CircleFitResult
30	    {
31	        public bool Ok { get; set; }
32	        public string Reason { get; set; }
33	        public double Cx { get; set; }
34	        public double Cy { get; set; }
35	        public double Radius { get; set; }
36	
37	        /// <summary>RMS của (khoảng cách tới tâm − bán kính) qua các điểm đo — PLAN.md §6.4.</summary>
38	        public double FitResidual { get; set; }
39	
40	        public static CircleFitResult Fail(string reason) => new CircleFitResult { Ok = false, Reason = reason };
41	    }
42	
43	    /// <summary>
44	    /// Toán bình phương tối thiểu dùng chung cho hiệu chuẩn vision — PLAN.md §6.1, §6.3, §6.4.
45	    /// Tách thành hàm thuần, không đụng trục hay camera nào, để kiểm chứng bằng dữ liệu tổng hợp
46	    /// đã biết trước đáp số đúng (--selftest) trước khi tin vào số liệu đo thật.
47	    /// </summary>
48	    public static class VisionCalibMath
49	    {
50	        /// <summary>
51	        /// Hồi quy affine pixel → toạ độ thực: X = B11·u + B12·v + B13, Y = B21·u + B22·v + B23.
52	        ///
53	        /// <para>Hệ 18×6 (9 điểm) của PLAN.md §6.1 phân rã thành HAI hệ 3 ẩn độc lập, vì hàng
54	        /// ứng với X chỉ đụng (B11,B12,B13) và hàng ứng với Y chỉ đụng (B21,B22,B23) — ma trận
55	        /// AᵀA gốc là khối chéo. Giải hai hệ 3×3 riêng cho đáp số giống hệt giải thẳng hệ 6×6
56	        /// mà không cần nghịch đảo ma trận lớn.</para>
57	        /// </summary>
58	        public static AffineFitResult FitAffine(IList<CalibPoint> points)
59	        {
60	            if (points == null || points.Count < 3)
61	                return AffineFitResult.Fail("cần tối thiểu 3 điểm tương ứng");
62	
63	            var px = new Pt3[points.Count];
64	            var py = new Pt3[points.Count];
65	            for (int i = 0; i < points.Count; i++)
66	            {
67	                px[i] = new Pt3(points[i].U, points[i].V, points[i].X);
68	                py[i] = new Pt3(points[i].U, points[i].V, points[i].Y);
69	            }
70	
71	            double[] bx = FitPlane(px);
72	            double[] by = FitPlane(py);
73	            if (bx == null || by == null)
74	                return AffineFitResult.Fail("ma trận suy biến — các điểm gần như thẳng hàng, không phủ đủ diện tích");
75	
76	            var calib = new CameraCalib
77	            {
78	                B11 = bx[0], B12 = bx[1], B13 = bx[2],
79	                B21 = by[0], B22 = by[1], B23 = by[2]
80	            };
81	
82	            var residuals = new double[points.Count];
83	            double sumSq = 0, max = 0;
84	            for (int i = 0; i < points.Count; i++)
85	            {
86	                var p = points[i];
87	                double ex = calib.B11 * p.U + calib.B12 * p.V + calib.B13 - p.X;
88	                double ey = calib.B21 * p.U + calib.B22 * p.V + calib.B23 - p.Y;
89	                double r = Math.Sqrt(ex * ex + ey * ey);
90	                residuals[i] = r;
91	                sumSq += r * r;
92	                if (r > max) max = r;
93	            }
94	
95	            return new AffineFitResult
96	            {
97	                Ok = true,
98	                Calib = calib,
99	                RmsResidual = Math.Sqrt(sumSq / points.Count),
100	                MaxResidual = max,
101	                PointResiduals = residuals
102	            };
103	        }
104	
105	        /// <summary>
106	        /// Fit vòng tròn qua các điểm đo bằng phương pháp Kåsa: đưa phương trình vòng tròn
107	        /// (x−cx)²+(y−cy)²=r² về dạng tuyến tính 2·cx·x + 2·cy·y + (r²−cx²−cy²) = x²+y², rồi
108	        /// bình phương tối thiểu 3 ẩn — PLAN.md §6.4 (tâm xoay tay hút, chạy 6 góc).
109	        /// </summary>
110	        public static CircleFitResult FitCircle(IList<double> xs, IList<double> ys)
111	        {
112	            if (xs == null || ys == null || xs.Count != ys.Count || xs.Count < 3)
113	                return CircleFitResult.Fail("cần tối thiểu 3 điểm cùng số lượng x/y");
114	
115	            var pts = new Pt3[xs.Count];
116	            for (int i = 0; i < xs.Count; i++)
117	            {
118	                double x = xs[i], y = ys[i];
119	                pts[i] = new Pt3(x, y, x * x + y * y);
120	            }
121	
122	            double[] sol = FitPlane(pts);
123	            if (sol == null)
124	                return CircleFitResult.Fail("ma trận suy biến — các điểm gần như thẳng hàng");
125	
126	            double cx = sol[0] / 2.0;
127	            double cy = sol[1] / 2.0;
128	            double r2 = sol[2] + cx * cx + cy * cy;
129	            if (r2 < 0)
130	                return CircleFitResult.Fail("dữ liệu không khớp một vòng tròn (bán kính ảo)");
131	            double radius = Math.Sqrt(r2);
132	
133	            double sumSq = 0;
134	            for (int i = 0; i < xs.Count; i++)
135	            {
136	                double d = Math.Sqrt((xs[i] - cx) * (xs[i] - cx) + (ys[i] - cy) * (ys[i] - cy)) - radius;
137	                sumSq += d * d;
138	            }
139	
140	            return new CircleFitResult
141	            {
142	                Ok = true,
143	                Cx = cx,
144	                Cy = cy,
145	                Radius = radius,
146	                FitResidual = Math.Sqrt(sumSq / xs.Count)
147	            };
148	        }
149	
150	        // ───────────────────────── nội bộ ─────────────────────────
151	
152	        private struct Pt3
153	        {
154	            public double U, V, T;
155	            public Pt3(double u, double v, double t) { U = u; V = v; T = t; }
156	        }
157	
158	        /// <summary>Bình phương tối thiểu T ≈ a·U + b·V + c qua phương trình chuẩn 3 ẩn.</summary>
159	        private static double[] FitPlane(IList<Pt3> pts)
160	        {
161	            double suu = 0, suv = 0, su = 0, svv = 0, sv = 0;
162	            double sut = 0, svt = 0, st = 0;
163	            int n = pts.Count;
164	
165	            foreach (var p in pts)
166	            {
167	                suu += p.U * p.U; suv += p.U * p.V; su += p.U;
168	                svv += p.V * p.V; sv += p.V;
169	                sut += p.U * p.T; svt += p.V * p.T; st += p.T;
170	            }
171	
172	            return Solve3(suu, suv, su,
173	                          suv, svv, sv,
174	                          su, sv, n,
175	                          sut, svt, st);
176	        }
177	
178	        private static double[] Solve3(double a11, double a12, double a13,
179	                                        double a21, double a22, double a23,
180	                                        double a31, double a32, double a33,
181	                                        double b1, double b2, double b3)
182	        {
183	            double det = Det3(a11, a12, a13, a21, a22, a23, a31, a32, a33);
184	            if (Math.Abs(det) < 1e-9) return null;
185	
186	            double x1 = Det3(b1, a12, a13, b2, a22, a23, b3, a32, a33) / det;
187	            double x2 = Det3(a11, b1, a13, a21, b2, a23, a31, b3, a33) / det;
188	            double x3 = Det3(a11, a12, b1, a21, a22, b2, a31, a32, b3) / det;
189	            return new[] { x1, x2, x3 };
190	        }
191	
192	        private static double Det3(double a11, double a12, double a13,
193	                                    double a21, double a22, double a23,
194	                                    double a31, double a32, double a33)
195	        {
196	            return a11 * (a22 * a33 - a23 * a32)
197	                 - a12 * (a21 * a33 - a23 * a31)
198	                 + a13 * (a21 * a32 - a22 * a31);
199	        }
200	    }
201	}
