using System;
using System.Collections.Generic;
using ShieldCanAssy.Core.Data.Model;

namespace ShieldCanAssy.Core.Controller
{
    /// <summary>Một cặp tương ứng pixel ↔ toạ độ thực dùng để hồi quy ma trận affine (PLAN.md §6.1).</summary>
    public struct CalibPoint
    {
        public double U, V, X, Y;
        public CalibPoint(double u, double v, double x, double y) { U = u; V = v; X = x; Y = y; }
    }

    public class AffineFitResult
    {
        public bool Ok { get; set; }
        public string Reason { get; set; }
        public CameraCalib Calib { get; set; }
        public double RmsResidual { get; set; }
        public double MaxResidual { get; set; }

        /// <summary>Sai số dư từng điểm, cùng thứ tự với danh sách điểm đưa vào — PLAN.md §6.1:
        /// một điểm lệch hẳn so với các điểm còn lại nghĩa là điểm đó đo sai.</summary>
        public double[] PointResiduals { get; set; }

        public static AffineFitResult Fail(string reason) => new AffineFitResult { Ok = false, Reason = reason };
    }

    public class CircleFitResult
    {
        public bool Ok { get; set; }
        public string Reason { get; set; }
        public double Cx { get; set; }
        public double Cy { get; set; }
        public double Radius { get; set; }

        /// <summary>RMS của (khoảng cách tới tâm − bán kính) qua các điểm đo — PLAN.md §6.4.</summary>
        public double FitResidual { get; set; }

        public static CircleFitResult Fail(string reason) => new CircleFitResult { Ok = false, Reason = reason };
    }

    /// <summary>
    /// Toán bình phương tối thiểu dùng chung cho hiệu chuẩn vision — PLAN.md §6.1, §6.3, §6.4.
    /// Tách thành hàm thuần, không đụng trục hay camera nào, để kiểm chứng bằng dữ liệu tổng hợp
    /// đã biết trước đáp số đúng (--selftest) trước khi tin vào số liệu đo thật.
    /// </summary>
    public static class VisionCalibMath
    {
        /// <summary>
        /// Hồi quy affine pixel → toạ độ thực: X = B11·u + B12·v + B13, Y = B21·u + B22·v + B23.
        ///
        /// <para>Hệ 18×6 (9 điểm) của PLAN.md §6.1 phân rã thành HAI hệ 3 ẩn độc lập, vì hàng
        /// ứng với X chỉ đụng (B11,B12,B13) và hàng ứng với Y chỉ đụng (B21,B22,B23) — ma trận
        /// AᵀA gốc là khối chéo. Giải hai hệ 3×3 riêng cho đáp số giống hệt giải thẳng hệ 6×6
        /// mà không cần nghịch đảo ma trận lớn.</para>
        /// </summary>
        public static AffineFitResult FitAffine(IList<CalibPoint> points)
        {
            if (points == null || points.Count < 3)
                return AffineFitResult.Fail("cần tối thiểu 3 điểm tương ứng");

            var px = new Pt3[points.Count];
            var py = new Pt3[points.Count];
            for (int i = 0; i < points.Count; i++)
            {
                px[i] = new Pt3(points[i].U, points[i].V, points[i].X);
                py[i] = new Pt3(points[i].U, points[i].V, points[i].Y);
            }

            double[] bx = FitPlane(px);
            double[] by = FitPlane(py);
            if (bx == null || by == null)
                return AffineFitResult.Fail("ma trận suy biến — các điểm gần như thẳng hàng, không phủ đủ diện tích");

            var calib = new CameraCalib
            {
                B11 = bx[0], B12 = bx[1], B13 = bx[2],
                B21 = by[0], B22 = by[1], B23 = by[2]
            };

            var residuals = new double[points.Count];
            double sumSq = 0, max = 0;
            for (int i = 0; i < points.Count; i++)
            {
                var p = points[i];
                double ex = calib.B11 * p.U + calib.B12 * p.V + calib.B13 - p.X;
                double ey = calib.B21 * p.U + calib.B22 * p.V + calib.B23 - p.Y;
                double r = Math.Sqrt(ex * ex + ey * ey);
                residuals[i] = r;
                sumSq += r * r;
                if (r > max) max = r;
            }

            return new AffineFitResult
            {
                Ok = true,
                Calib = calib,
                RmsResidual = Math.Sqrt(sumSq / points.Count),
                MaxResidual = max,
                PointResiduals = residuals
            };
        }

        /// <summary>
        /// Fit vòng tròn qua các điểm đo bằng phương pháp Kåsa: đưa phương trình vòng tròn
        /// (x−cx)²+(y−cy)²=r² về dạng tuyến tính 2·cx·x + 2·cy·y + (r²−cx²−cy²) = x²+y², rồi
        /// bình phương tối thiểu 3 ẩn — PLAN.md §6.4 (tâm xoay tay hút, chạy 6 góc).
        /// </summary>
        public static CircleFitResult FitCircle(IList<double> xs, IList<double> ys)
        {
            if (xs == null || ys == null || xs.Count != ys.Count || xs.Count < 3)
                return CircleFitResult.Fail("cần tối thiểu 3 điểm cùng số lượng x/y");

            var pts = new Pt3[xs.Count];
            for (int i = 0; i < xs.Count; i++)
            {
                double x = xs[i], y = ys[i];
                pts[i] = new Pt3(x, y, x * x + y * y);
            }

            double[] sol = FitPlane(pts);
            if (sol == null)
                return CircleFitResult.Fail("ma trận suy biến — các điểm gần như thẳng hàng");

            double cx = sol[0] / 2.0;
            double cy = sol[1] / 2.0;
            double r2 = sol[2] + cx * cx + cy * cy;
            if (r2 < 0)
                return CircleFitResult.Fail("dữ liệu không khớp một vòng tròn (bán kính ảo)");
            double radius = Math.Sqrt(r2);

            double sumSq = 0;
            for (int i = 0; i < xs.Count; i++)
            {
                double d = Math.Sqrt((xs[i] - cx) * (xs[i] - cx) + (ys[i] - cy) * (ys[i] - cy)) - radius;
                sumSq += d * d;
            }

            return new CircleFitResult
            {
                Ok = true,
                Cx = cx,
                Cy = cy,
                Radius = radius,
                FitResidual = Math.Sqrt(sumSq / xs.Count)
            };
        }

        // ───────────────────────── nội bộ ─────────────────────────

        private struct Pt3
        {
            public double U, V, T;
            public Pt3(double u, double v, double t) { U = u; V = v; T = t; }
        }

        /// <summary>Bình phương tối thiểu T ≈ a·U + b·V + c qua phương trình chuẩn 3 ẩn.</summary>
        private static double[] FitPlane(IList<Pt3> pts)
        {
            double suu = 0, suv = 0, su = 0, svv = 0, sv = 0;
            double sut = 0, svt = 0, st = 0;
            int n = pts.Count;

            foreach (var p in pts)
            {
                suu += p.U * p.U; suv += p.U * p.V; su += p.U;
                svv += p.V * p.V; sv += p.V;
                sut += p.U * p.T; svt += p.V * p.T; st += p.T;
            }

            return Solve3(suu, suv, su,
                          suv, svv, sv,
                          su, sv, n,
                          sut, svt, st);
        }

        private static double[] Solve3(double a11, double a12, double a13,
                                        double a21, double a22, double a23,
                                        double a31, double a32, double a33,
                                        double b1, double b2, double b3)
        {
            double det = Det3(a11, a12, a13, a21, a22, a23, a31, a32, a33);
            if (Math.Abs(det) < 1e-9) return null;

            double x1 = Det3(b1, a12, a13, b2, a22, a23, b3, a32, a33) / det;
            double x2 = Det3(a11, b1, a13, a21, b2, a23, a31, b3, a33) / det;
            double x3 = Det3(a11, a12, b1, a21, a22, b2, a31, a32, b3) / det;
            return new[] { x1, x2, x3 };
        }

        private static double Det3(double a11, double a12, double a13,
                                    double a21, double a22, double a23,
                                    double a31, double a32, double a33)
        {
            return a11 * (a22 * a33 - a23 * a32)
                 - a12 * (a21 * a33 - a23 * a31)
                 + a13 * (a21 * a32 - a22 * a31);
        }
    }
}

