/// sang thẳng S10 — sau lần quét đầu của một tray, các vòng S00 sau chỉ tốn một lượt kiểm
/// tra rỗng rồi đi tiếp ngay, không quét lại (§5.2b).
/// </summary>
private async Task<bool> S05_ScanAssy(CancellationToken ct)
{
    var tray = Run.AssyTray;
    int index = NextUnscannedCell(tray);
    if (index < 0)
    {
        Run.AutoState = EAutoState.S10_Pick1;
        return true;
    }

    int row, col;
    tray.RowCol(index, out row, out col);

    // Mốc tay #1 cố định cho mọi ô — xem ghi chú ở _assyScan. Vị trí camera lấy từ mốc đã
    // teach trực tiếp (CamTopDownAnchorX/Y, xem TrayLayout) cộng độ lệch lưới tính theo
    // lưới của Tool1 so với ô (1,1) — không còn qua Hand-Eye Dx/Dy nữa (Tuấn xác nhận
    // 2026-09-05, xem ghi chú ở CamTopDownAnchorX).
    var cell = Model.AssyTray.CellPos(AxisId.Z1, row, col);
    var cell00 = Model.AssyTray.CellPos(AxisId.Z1, 0, 0);
    double camX = Model.AssyTray.CamTopDownAnchorX + (cell.X - cell00.X);
    double camY = Model.AssyTray.CamTopDownAnchorY + (cell.Y - cell00.Y);

    if (!await _func.MoveToCellAsync(Model.AssyTray.AxisRow, camY, camX, ct).ConfigureAwait(false))
        return Halt("không tới được vị trí soi ô đích lúc quét trước (" + row + "," + col + ")");

    double captureX = _motion[AxisId.X].CurrentPos;
    double captureY = _motion[Model.AssyTray.AxisRow].CurrentPos;

    var top = await TriggerAsync(EVisionProcedure.LocateTop, ct).ConfigureAwait(false);
    if (top == null || !top.Found)
    {
        // Không thấy chi tiết đích ngay từ vòng quét: bỏ ô này luôn, không chờ tới lúc
        // đặt mới phát hiện — cùng cách xử lý với nhánh not-found cũ ở S3x.
        AlarmManager.Raise(AlarmCode.VisionNotFound, "Vision",
            "LocateTop (quét trước) ô (" + row + "," + col + ")" + (top == null ? "" : ": " + top.Error));
        tray.Set(index, ECellState.Skipped);
        AlarmManager.ClearCondition(AlarmCode.VisionNotFound);
        Save();
        return true;      // ở nguyên S05, vòng sau lấy ô kế
    }

    _assyScan[index] = new AssyCellScan { Top = top, CaptureX = captureX, CaptureY = captureY };
    Save();
    return true;          // ở nguyên S05 cho tới khi NextUnscannedCell hết ô
}

