/// Flow thuần tính toán (<c>PlaceAlign</c>, PLAN.md §6.6): App đưa tư thế đích + tư thế
/// sản phẩm vào, VisionMaster trả lượng bù đã tính.
///
/// <para><c>ModuParams.SetInputFloat</c> (kế thừa từ <c>CModuleParamBase</c>) đặt giá trị
/// "chỉ có hiệu lực cho lần chạy này" — đúng thứ cần cho một Flow gọi lại nhiều lần với số
/// khác nhau, không để lại trạng thái trong solution. Tên input phải khớp tab "Input
/// Params" của Flow trong VisionMaster IDE (phân biệt hoa/thường), cấu hình được ở trang
/// Setting như mọi tên khác.</para>
/// </summary>
public float[] RunWithInputsAndGetFloats(string flowName, IDictionary<string, float> inputs,
                                         params string[] outputNames)
{
    var pro = GetProcedure(flowName);

    if (inputs != null)
    {
        foreach (var kv in inputs)
        {
            if (string.IsNullOrEmpty(kv.Key)) continue;
            pro.ModuParams.SetInputFloat(kv.Key, new[] { kv.Value });
        }
    }

    pro.Run();
    return ReadFloats(pro, flowName, outputNames);
}

