using System.Collections.Generic;
using System.Drawing;
using VM.Core;
using VM.PlatformSDKCS;

namespace ShieldCanAssy.Lib.VisionMaster
{
    /// <summary>Kết quả một lần Run(): số output float theo đúng thứ tự yêu cầu, kèm ảnh nếu có
    /// khai tên output ảnh.</summary>
    public class VisionRunResult
    {
        public float[] Floats;
        public Bitmap Image;
    }

    /// <summary>
    /// Bọc mỏng HIKROBOT VisionMaster 4.4.0 PlatformSDK (<c>VM.Core</c> / <c>VM.PlatformSDKCS</c>)
    /// — PLAN.md §2.1, §6.
    ///
    /// <para><b>Cách gọi lấy nguyên từ mẫu chính hãng cài kèm SDK</b> tại
    /// <c>C:\Program Files\VisionMaster4.4.0\Development\V4.x\Samples\C#\PlatformSDKSampleCS\</c>
    /// — cụ thể <c>GetResultControl\Form1.cs</c> (nạp solution, chạy Flow, đọc output) và
    /// <c>SolutionControlCS_WPF\MainWindow.xaml.cs</c> (nạp/đóng solution từ WPF). KHÔNG suy đoán
    /// từ <c>VM.PlatformSDKCS.ServerSDKAPI</c> — lớp P/Invoke thô của SDK không có ví dụ dùng đúng
    /// kèm theo, còn <c>VM.Core.VmSolution</c>/<c>VmProcedure</c> ở đây là lớp bọc OOP chính hãng
    /// dùng trong toàn bộ mẫu C#/WPF của hãng.</para>
    ///
    /// <para><b>Chưa chạy thử với solution thật.</b> API tồn tại và biên dịch được — SDK đã cài
    /// sẵn trên máy dev, tham chiếu thẳng DLL thật (xem ShieldCanAssy.Core.csproj) — nhưng chưa
    /// đối chiếu với solution VisionMaster thật vì solution đó chưa được dựng.</para>
    ///
    /// <para><b>Tên Flow và tên biến output KHÔNG nằm trong lớp này.</b> Lớp này chỉ biết chạy
    /// một Flow theo tên truyền vào và đọc các output theo tên truyền vào —
    /// <see cref="ShieldCanAssy.Core.Data.SystemData.VisionOutputs"/> (sửa được ở trang Setting)
    /// mới là nơi giữ tên thật, để đổi tên Flow/output trong solution không cần build lại app —
    /// PLAN.md §6.8, giống màn hình nhập tên Output ở app HousingCorrosion.</para>
    /// </summary>
    public class VisionMasterDevice
    {
        public bool IsSolutionLoaded { get; private set; }

        /// <summary>Nạp solution — <see cref="VmSolution"/> là singleton toàn tiến trình nên chỉ
        /// một solution được nạp tại một thời điểm (mẫu <c>SolutionControlCS_WPF</c>).</summary>
        public void LoadSolution(string path, string password)
        {
            VmSolution.Load(path, password ?? "");

            // Sau khi nạp xong, tắt callback kết quả của mọi module để đỡ tốn tài nguyên — ta chỉ
            // cần Run() rồi đọc output của Flow bằng GetFloatOutputResult, không cần callback
            // (mẫu GetResultControl\Form1.cs làm y hệt ngay sau LoadSolution).
            VmSolution.Instance.DisableModulesCallback();
            IsSolutionLoaded = true;
        }

        /// <summary>
        /// Chạy một Flow (đồng bộ, CHẶN luồng gọi — lớp trên phải tự bọc Task.Run + timeout) rồi
        /// đọc các output float đã đặt tên theo đúng thứ tự tham số. Ném <see cref="VmException"/>
        /// nếu Flow không tồn tại, chạy lỗi, hoặc thiếu output đã khai — lớp trên (VisionConnect)
        /// chịu trách nhiệm bắt và quy đổi thành alarm/kết quả "không tìm thấy".
        /// </summary>
        public float[] RunAndGetFloats(string flowName, params string[] outputNames)
        {
            var pro = GetProcedure(flowName);
            pro.Run();
            return ReadFloats(pro, flowName, outputNames);
        }

        /// <summary>
        /// Như <see cref="RunAndGetFloats"/> nhưng GÁN input của Flow trước khi chạy — dùng cho
        /// Flow thuần tính toán (<c>PlaceAlign</c>, PLAN.md §6.6): App đưa tư thế đích + tư thế
        /// sản phẩm vào, VisionMaster trả lượng bù đã tính.
        ///
        /// <para><c>ModuParams.SetInputFloat</c> (kế thừa từ <c>CModuleParamBase</c>) đặt giá trị
        /// "chỉ có hiệu lực cho lần chạy này" — đúng thứ cần cho một Flow gọi lại nhiều lần với số
        /// khác nhau, không để lại trạng thái trong solution. Tên input phải khớp tab "Input
        /// Params" của Flow trong VisionMaster IDE (phân biệt hoa/thường), cấu hình được ở trang
        /// Setting như mọi tên khác.</para>
        /// </summary>
        public float[] RunWithInputsAndGetFloats(string flowName, IDictionary<string, float> inputs,
                                                 params string[] outputNames)
        {
            var pro = GetProcedure(flowName);

            if (inputs != null)
            {
                foreach (var kv in inputs)
                {
                    if (string.IsNullOrEmpty(kv.Key)) continue;
                    pro.ModuParams.SetInputFloat(kv.Key, new[] { kv.Value });
                }
            }

            pro.Run();
            return ReadFloats(pro, flowName, outputNames);
        }

        private static VmProcedure GetProcedure(string flowName)
        {
            var pro = VmSolution.Instance[flowName] as VmProcedure;
            if (pro == null)
                throw new VmException(-1, "không tìm thấy Flow \"" + flowName + "\" trong solution — kiểm tra tên trong VisionMaster IDE");
            return pro;
        }

        /// <summary>
        /// Đọc các output float đã đặt tên theo đúng thứ tự yêu cầu.
        ///
        /// <para>GetFloatOutputResult(string) của VmProcedure đã DEPRECATED trong bản SDK cài trên
        /// máy — dùng thay thế theo đúng khuyến cáo của trình biên dịch: ModuResult.GetOutputFloat.
        /// Chỉ lấy phần tử [0] của mỗi output, nên module định vị trong solution phải đặt "Max
        /// Number to Find = 1"; nhiều kết quả thì App lặng lẽ dùng cái đầu tiên.</para>
        /// </summary>
        private static float[] ReadFloats(VmProcedure pro, string flowName, string[] outputNames)
        {
            var moduResult = pro.ModuResult;
            var results = new float[outputNames.Length];
            for (int i = 0; i < outputNames.Length; i++)
            {
                var r = moduResult.GetOutputFloat(outputNames[i]);
                if (r.nValueNum < 1 || r.pFloatVal == null || r.pFloatVal.Length < 1)
                    throw new VmException(-1, "Flow \"" + flowName + "\" thiếu output \"" + outputNames[i] + "\" — kiểm tra biến output trong solution");
                results[i] = r.pFloatVal[0];
            }
            return results;
        }

        /// <summary>
        /// Như <see cref="RunAndGetFloats"/> nhưng CHỈ chạy Flow MỘT LẦN rồi đọc cả output float
        /// lẫn ảnh từ đúng lần chạy đó — chạy hai lần (một để lấy số, một để lấy ảnh) sẽ kích
        /// camera thật chụp hai lần cho một lần trigger logic, tốn thời gian và có thể đọc phải
        /// hai khung hình khác nhau nếu vật vừa dịch giữa hai lần chụp.
        ///
        /// <para><c>EnableResultCallback()</c> theo đúng mẫu SDK
        /// <c>GetResultControl\Form1.cs</c> — không gọi thì <c>GetOutputImageV2</c> không có dữ
        /// liệu để trả, dù output float vẫn đọc được bình thường.</para>
        ///
        /// <para>Ảnh không bắt buộc: <paramref name="imageOutputName"/> để trống/null thì bỏ qua
        /// hẳn bước lấy ảnh; solution chưa khai output ảnh (hoặc lấy ảnh lỗi) thì
        /// <see cref="VisionRunResult.Image"/> là null nhưng KHÔNG ném lỗi — đo tư thế để đặt
        /// hàng không phụ thuộc vào việc có lấy được ảnh hiển thị hay không.</para>
        /// </summary>
        public VisionRunResult RunAndGetFloatsWithImage(string flowName, string imageOutputName, params string[] outputNames)
        {
            var pro = VmSolution.Instance[flowName] as VmProcedure;
            if (pro == null)
                throw new VmException(-1, "không tìm thấy Flow \"" + flowName + "\" trong solution — kiểm tra tên trong VisionMaster IDE");

            bool wantImage = !string.IsNullOrEmpty(imageOutputName);
            if (wantImage) pro.EnableResultCallback();

            pro.Run();

            var moduResult = pro.ModuResult;
            var results = new float[outputNames.Length];
            for (int i = 0; i < outputNames.Length; i++)
            {
                var r = moduResult.GetOutputFloat(outputNames[i]);
                if (r.nValueNum < 1 || r.pFloatVal == null || r.pFloatVal.Length < 1)
                    throw new VmException(-1, "Flow \"" + flowName + "\" thiếu output \"" + outputNames[i] + "\" — kiểm tra biến output trong solution");
                results[i] = r.pFloatVal[0];
            }

            Bitmap image = null;
            if (wantImage)
            {
                try
                {
                    var imgData = moduResult.GetOutputImageV2(imageOutputName);
                    if (imgData != null) image = imgData.ToBitmap();
                }
                catch
                {
                    // Ảnh chỉ để hiển thị, không phải số dùng để tính lượng bù — im lặng bỏ qua.
                }
            }

            return new VisionRunResult { Floats = results, Image = image };
        }

        public void CloseSolution()
        {
            try { VmSolution.Instance?.CloseSolution(); } catch { }
            IsSolutionLoaded = false;
        }

        public void Shutdown()
        {
            try { VmSolution.Instance?.Dispose(); } catch { }
            IsSolutionLoaded = false;
        }
    }
}

using System;
using System.Drawing;
using System.Threading;
using System.Threading.Tasks;
using ShieldCanAssy.Core.Data;
using ShieldCanAssy.Core.Infor;
using ShieldCanAssy.Lib.VisionMaster;
using ShieldCanAssy.Utility;
using ShieldCanAssy.Utility.Log;
using VM.PlatformSDKCS;

namespace ShieldCanAssy.Core.Communication
{
    /// <summary>
    /// CAM bottom-up + CAM top-down thật, qua HIKROBOT VisionMaster 4.4.0 — bọc
    /// <see cref="VisionMasterDevice"/>. PLAN.md §2.1, §6.
    ///
    /// <para><b>Chưa kiểm chứng với solution thật.</b> Viết trước để khi có file .sol thật chỉ
    /// còn sửa tên Flow/biến output ở trang Setting, không phải vừa gõ code vừa đứng cạnh máy —
    /// giống <see cref="PanasonicAxis"/>. Tên Flow/output đọc từ
    /// <see cref="SystemData.VisionOutputs"/> (cấu hình được, không hardcode) — đó cũng là hợp
    /// đồng Tuấn cần khớp khi dựng solution trong VisionMaster IDE (PLAN.md §6.8).</para>
    /// </summary>
    public class VisionConnect : Bindable, IVisionDevice
    {
        private readonly SystemData _sys;
        private readonly VisionMasterDevice _device = new VisionMasterDevice();
        private readonly object _cmdLock = new object();

        public VisionConnect(SystemData sys)
        {
            _sys = sys;
        }

        private bool _connected;
        public bool IsConnected { get { return _connected; } private set { SetProperty(ref _connected, value); } }

        public bool IsSolutionLoaded { get { return _device.IsSolutionLoaded; } }

        private Bitmap _lastTopDownImage;
        public Bitmap LastTopDownImage { get { return _lastTopDownImage; } private set { SetProperty(ref _lastTopDownImage, value); } }

        private Bitmap _lastBottomUpImage;
        public Bitmap LastBottomUpImage { get { return _lastBottomUpImage; } private set { SetProperty(ref _lastBottomUpImage, value); } }

        /// <summary>
        /// PlatformSDK không có bước "connect" tách rời khỏi nạp solution — kết nối camera thật
        /// diễn ra bên trong <c>LoadSolution</c>. Cờ này chỉ đánh dấu "sẵn sàng gọi nạp solution",
        /// đúng thứ tự <c>McControl.Init()</c> đang gọi: <c>Connect()</c> rồi <c>LoadSolutionAsync()</c>.
        /// </summary>
        public bool Connect()
        {
            IsConnected = true;
            return true;
        }

        public void Disconnect()
        {
            try { _device.Shutdown(); } catch { }
            IsConnected = false;
        }

        public async Task<bool> LoadSolutionAsync(string solutionPath)
        {
            try
            {
                await Task.Run(() =>
                {
                    lock (_cmdLock) { _device.LoadSolution(solutionPath, ""); }
                }).ConfigureAwait(false);
                return true;
            }
            catch (Exception ex)
            {
                LogWorker.Instance.RecordLog("Vision: nạp solution lỗi — " + ex.Message,
                    Utility.Log.LogLevel.Error, "Vision");
                return false;
            }
        }

        public async Task<VisionPose> TriggerAsync(EVisionProcedure procedure, CancellationToken ct)
        {
            if (!IsConnected) return VisionPose.NotFound("chưa kết nối");
            if (!IsSolutionLoaded) return VisionPose.NotFound("chưa nạp solution");

            var names = _sys.VisionOutputs;
            string flow;
            switch (procedure)
            {
                case EVisionProcedure.TopDownCalib: flow = names.FlowTopDownCalib; break;
                case EVisionProcedure.AlignBottomTool1: flow = names.FlowAlignBottomTool1; break;
                case EVisionProcedure.AlignBottomTool2: flow = names.FlowAlignBottomTool2; break;
                case EVisionProcedure.AlignCalibTool1: flow = names.FlowAlignCalibTool1; break;
                case EVisionProcedure.AlignCalibTool2: flow = names.FlowAlignCalibTool2; break;
                default: flow = names.FlowLocateTop; break;
            }

            try
            {
                var result = await RunWithTimeoutAsync(() => _device.RunAndGetFloatsWithImage(flow, names.OutImage,
