/// <summary>
/// Flow tính toán <c>PlaceAlign</c> (§6.6): gán 6 input float rồi đọc 4 output. Không có
/// camera trong Flow này nên không đụng ảnh, không gán Last*Image.
/// </summary>
public async Task<PlaceAlignResult> TriggerPlaceAlignAsync(PlaceAlignInput input, CancellationToken ct)
{
    if (input == null) return PlaceAlignResult.NotOk("thiếu dữ liệu đầu vào");
    if (!IsConnected) return PlaceAlignResult.NotOk("chưa kết nối");
    if (!IsSolutionLoaded) return PlaceAlignResult.NotOk("chưa nạp solution");

    var names = _sys.VisionOutputs;

    var inputs = new Dictionary<string, float>
    {
        { names.InTargetX, (float)input.TargetX },
        { names.InTargetY, (float)input.TargetY },
        { names.InTargetAngle, (float)input.TargetAngle },
        { names.InObjectX, (float)input.ObjectX },
        { names.InObjectY, (float)input.ObjectY },
        { names.InObjectAngle, (float)input.ObjectAngle }
    };

    try
    {
        float[] r = await RunWithTimeoutAsync(() => _device.RunWithInputsAndGetFloats(
            names.FlowPlaceAlign, inputs,
            names.OutFound, names.OutDeltaX, names.OutDeltaY, names.OutDeltaTheta),
            ct).ConfigureAwait(false);

        if (r == null)
        {
            AlarmManager.Raise(AlarmCode.VisionTriggerTimeout, "Vision", names.FlowPlaceAlign);
            return PlaceAlignResult.NotOk("quá thời gian chờ");
        }

        if (r[0] <= 0.5f)
            return PlaceAlignResult.NotOk("module Single Point Alignment báo NG — kiểm tra đầu vào và file hiệu chuẩn");

        return new PlaceAlignResult
        {
            Ok = true,
            DeltaX = r[1],
            DeltaY = r[2],
            DeltaThetaDeg = r[3]
        };
    }
    catch (VmException ex)
    {
        LogWorker.Instance.RecordLog("Vision: " + names.FlowPlaceAlign + " lỗi — " + ex.errorMessage,
            Utility.Log.LogLevel.Error, "Vision");
        return PlaceAlignResult.NotOk(ex.errorMessage);
    }
    catch (Exception ex)
    {
        LogWorker.Instance.RecordLog("Vision: " + names.FlowPlaceAlign + " lỗi — " + ex.Message,
            Utility.Log.LogLevel.Error, "Vision");
        return PlaceAlignResult.NotOk(ex.Message);
    }
}

