using System;
using System.Drawing;
using System.Threading;
using System.Threading.Tasks;
using ShieldCanAssy.Core.Data;
using ShieldCanAssy.Core.Infor;
using ShieldCanAssy.Lib.VisionMaster;
using ShieldCanAssy.Utility;
using ShieldCanAssy.Utility.Log;
using VM.PlatformSDKCS;

namespace ShieldCanAssy.Core.Communication
{
    /// <summary>
    /// CAM bottom-up + CAM top-down thật, qua HIKROBOT VisionMaster 4.4.0 — bọc
    /// <see cref="VisionMasterDevice"/>. PLAN.md §2.1, §6.
    ///
    /// <para><b>Chưa kiểm chứng với solution thật.</b> Viết trước để khi có file .sol thật chỉ
    /// còn sửa tên Flow/biến output ở trang Setting, không phải vừa gõ code vừa đứng cạnh máy —
    /// giống <see cref="PanasonicAxis"/>. Tên Flow/output đọc từ
    /// <see cref="SystemData.VisionOutputs"/> (cấu hình được, không hardcode) — đó cũng là hợp
    /// đồng Tuấn cần khớp khi dựng solution trong VisionMaster IDE (PLAN.md §6.8).</para>
    /// </summary>
    public class VisionConnect : Bindable, IVisionDevice
    {
        private readonly SystemData _sys;
        private readonly VisionMasterDevice _device = new VisionMasterDevice();
        private readonly object _cmdLock = new object();

        public VisionConnect(SystemData sys)
        {
            _sys = sys;
        }

        private bool _connected;
        public bool IsConnected { get { return _connected; } private set { SetProperty(ref _connected, value); } }

        public bool IsSolutionLoaded { get { return _device.IsSolutionLoaded; } }

        private Bitmap _lastTopDownImage;
        public Bitmap LastTopDownImage { get { return _lastTopDownImage; } private set { SetProperty(ref _lastTopDownImage, value); } }

        private Bitmap _lastBottomUpImage;
        public Bitmap LastBottomUpImage { get { return _lastBottomUpImage; } private set { SetProperty(ref _lastBottomUpImage, value); } }

        /// <summary>
        /// PlatformSDK không có bước "connect" tách rời khỏi nạp solution — kết nối camera thật
        /// diễn ra bên trong <c>LoadSolution</c>. Cờ này chỉ đánh dấu "sẵn sàng gọi nạp solution",
        /// đúng thứ tự <c>McControl.Init()</c> đang gọi: <c>Connect()</c> rồi <c>LoadSolutionAsync()</c>.
        /// </summary>
        public bool Connect()
        {
            IsConnected = true;
            return true;
        }

        public void Disconnect()
        {
            try { _device.Shutdown(); } catch { }
            IsConnected = false;
        }

        public async Task<bool> LoadSolutionAsync(string solutionPath)
        {
            try
            {
                await Task.Run(() =>
                {
                    lock (_cmdLock) { _device.LoadSolution(solutionPath, ""); }
                }).ConfigureAwait(false);
                return true;
            }
            catch (Exception ex)
            {
                LogWorker.Instance.RecordLog("Vision: nạp solution lỗi — " + ex.Message,
                    Utility.Log.LogLevel.Error, "Vision");
                return false;
            }
        }

        public async Task<VisionPose> TriggerAsync(EVisionProcedure procedure, CancellationToken ct)
        {
            if (!IsConnected) return VisionPose.NotFound("chưa kết nối");
            if (!IsSolutionLoaded) return VisionPose.NotFound("chưa nạp solution");

            var names = _sys.VisionOutputs;
            string flow;
            switch (procedure)
            {
                case EVisionProcedure.TopDownCalib: flow = names.FlowTopDownCalib; break;
                case EVisionProcedure.LocateMark: flow = names.FlowLocateMark; break;
                case EVisionProcedure.AlignBottomTool1: flow = names.FlowAlignBottomTool1; break;
                case EVisionProcedure.AlignBottomTool2: flow = names.FlowAlignBottomTool2; break;
                case EVisionProcedure.AlignCalibTool1: flow = names.FlowAlignCalibTool1; break;
                case EVisionProcedure.AlignCalibTool2: flow = names.FlowAlignCalibTool2; break;
                default: flow = names.FlowLocateTop; break;
            }

            try
            {
                var result = await RunWithTimeoutAsync(() => _device.RunAndGetFloatsWithImage(flow, names.OutImage,
                    names.OutFound, names.OutPoseX, names.OutPoseY, names.OutAngle, names.OutScore),
                    ct).ConfigureAwait(false);

                if (result == null)
                {
                    AlarmManager.Raise(AlarmCode.VisionTriggerTimeout, "Vision", flow);
                    return VisionPose.NotFound("quá thời gian chờ");
                }

                // Sửa lỗi tồn tại từ trước (2026-09-10, phát hiện lúc bỏ Flow AlignBottom chung):
                // điều kiện cũ so procedure == AlignBottom (Flow chung, đã orphan) — nhưng Auto
                // thật CHỈ trigger AlignBottomTool1/Tool2 (không bao giờ AlignBottom nữa), nên ảnh
                // CAM bottom-up trước đây KHÔNG BAO GIỜ được gán vào LastBottomUpImage, luôn rơi
                // nhầm vào nhánh LastTopDownImage bên dưới. AlignBottomTool1/2 VÀ AlignCalibTool1/2
                // đều là CAM bottom-up (khác CAM top-down của LocateTop/TopDownCalib).
                bool isBottomUp = procedure == EVisionProcedure.AlignBottomTool1
                    || procedure == EVisionProcedure.AlignBottomTool2
                    || procedure == EVisionProcedure.AlignCalibTool1
                    || procedure == EVisionProcedure.AlignCalibTool2;
                if (isBottomUp) LastBottomUpImage = result.Image;
                else LastTopDownImage = result.Image;

                float[] r = result.Floats;
                bool found = r[0] > 0.5f;
                if (!found) return VisionPose.NotFound("solution báo không tìm thấy");

                return new VisionPose { Found = true, X = r[1], Y = r[2], Angle = r[3], Score = r[4] };
            }
            catch (VmException ex)
            {
                LogWorker.Instance.RecordLog("Vision: " + flow + " lỗi — " + ex.errorMessage,
                    Utility.Log.LogLevel.Error, "Vision");
                return VisionPose.NotFound(ex.errorMessage);
            }
            catch (Exception ex)
            {
                LogWorker.Instance.RecordLog("Vision: " + flow + " lỗi — " + ex.Message,
                    Utility.Log.LogLevel.Error, "Vision");
                return VisionPose.NotFound(ex.Message);
            }
        }

        public async Task<CalibBoardResult> TriggerCalibBoardAsync(CancellationToken ct)
        {
            if (!IsConnected) return CalibBoardResult.NotFound("chưa kết nối");
            if (!IsSolutionLoaded) return CalibBoardResult.NotFound("chưa nạp solution");

            var names = _sys.VisionOutputs;

            try
            {
                float[] r = await RunWithTimeoutAsync(() => _device.RunAndGetFloats(names.FlowCalibBottomUp,
                    names.OutFound, names.OutScaleU, names.OutScaleV,
                    names.OutSkewDeg, names.OutCornerCount, names.OutOriginPixelU, names.OutOriginPixelV),
                    ct).ConfigureAwait(false);

                if (r == null)
                {
                    AlarmManager.Raise(AlarmCode.VisionTriggerTimeout, "Vision", names.FlowCalibBottomUp);
                    return CalibBoardResult.NotFound("quá thời gian chờ");
                }

                bool found = r[0] > 0.5f;
                if (!found) return CalibBoardResult.NotFound("không thấy đủ góc trên bản chuẩn");

                return new CalibBoardResult
                {
                    Found = true,
                    ScaleU = r[1],
                    ScaleV = r[2],
                    SkewDeg = r[3],
                    CornerCount = (int)r[4],
                    OriginPixelU = r[5],
                    OriginPixelV = r[6]
                };
            }
            catch (VmException ex)
            {
                LogWorker.Instance.RecordLog("Vision: " + names.FlowCalibBottomUp + " lỗi — " + ex.errorMessage,
                    Utility.Log.LogLevel.Error, "Vision");
                return CalibBoardResult.NotFound(ex.errorMessage);
            }
            catch (Exception ex)
            {
                LogWorker.Instance.RecordLog("Vision: " + names.FlowCalibBottomUp + " lỗi — " + ex.Message,
                    Utility.Log.LogLevel.Error, "Vision");
                return CalibBoardResult.NotFound(ex.Message);
            }
        }

        /// <summary>
        /// <c>VmProcedure.Run()</c> là lệnh CHẶN, không nhận token huỷ — bọc trong
        /// <c>Task.Run</c> rồi canh thời gian bằng <c>Task.WhenAny</c>. Hết giờ thì trả về
        /// <c>null</c> cho lớp gọi báo alarm 4003, nhưng luồng chạy <c>Run()</c> bên dưới KHÔNG bị
        /// huỷ thật — SDK không cho — nó tự trôi tới khi solution phản hồi. Cùng một giới hạn với
        /// timeout đọc trạng thái driver Panasonic.
        /// </summary>
        private async Task<T> RunWithTimeoutAsync<T>(Func<T> body, CancellationToken ct) where T : class
        {
            var runTask = Task.Run(() => { lock (_cmdLock) { return body(); } }, ct);
            var timeoutTask = Task.Delay(_sys.VisionTriggerTimeoutMs, ct);
            var done = await Task.WhenAny(runTask, timeoutTask).ConfigureAwait(false);
            return done == runTask ? await runTask.ConfigureAwait(false) : null;
        }
    }
}

