using System;
using System.Threading;
using System.Threading.Tasks;
using ShieldCanAssy.Utility;

namespace ShieldCanAssy.Core.Communication.Sim
{
    /// <summary>
    /// Vision mô phỏng. Trả về tư thế quanh tâm ảnh với nhiễu ngẫu nhiên, kèm xác suất
    /// không tìm thấy / điểm số thấp để chạy được nhánh NG của chuỗi Auto (PLAN.md §5.4).
    /// </summary>
    public class FakeVision : Bindable, IVisionDevice
    {
        private readonly Random _rng = new Random(20260731);

        private bool _connected;
        public bool IsConnected { get => _connected; private set => SetProperty(ref _connected, value); }

        private bool _loaded;
        public bool IsSolutionLoaded { get => _loaded; private set => SetProperty(ref _loaded, value); }

        /// <summary>Thời gian chụp + xử lý giả lập, ms.</summary>
        public int ProcessTimeMs { get; set; } = 120;

        /// <summary>Xác suất tìm thấy đối tượng.</summary>
        public double FoundRate { get; set; } = 1.0;

        /// <summary>Độ lệch tối đa mô phỏng quanh tâm, pixel.</summary>
        public double NoisePixel { get; set; } = 12.0;

        /// <summary>Độ lệch góc tối đa mô phỏng, độ.</summary>
        public double NoiseAngle { get; set; } = 4.0;

        /// <summary>Độ lệch tối đa mô phỏng cho AlignBottomTool1/2 và AlignCalibTool1/2, mm —
        /// khác <see cref="NoisePixel"/>: hai procedure này đã tự hiệu chuẩn tâm xoay + Teach
        /// Master bên trong VisionMaster (PLAN.md §6.4), nên PixelX/PixelY trả về là ĐỘ LỆCH mm
        /// đã bù sẵn, dao động quanh 0 chứ không phải quanh tâm ảnh 640/480 như procedure còn lại.</summary>
        public double NoiseAlignMm { get; set; } = 0.3;

        /// <summary>Số lần đã trigger từng Flow — để --selftest kiểm chứng những thay đổi kiểu
        /// "bớt chụp lại" (vd. S05_ScanAssy) thật sự bớt trigger chứ không chỉ vẫn ra đúng kết quả
        /// theo cách cũ (nhiều trigger hơn) mà tình cờ vẫn đạt.</summary>
        public int AlignBottomCount { get; private set; }
        public int LocateTopCount { get; private set; }

        // Mô phỏng không có camera thật để chụp — luôn null, trang Main tự hiện chỗ trống thay
        // vì hình khi chạy --selftest/dev không có máy.
        public System.Drawing.Bitmap LastTopDownImage => null;
        public System.Drawing.Bitmap LastBottomUpImage => null;

        public bool Connect() { IsConnected = true; return true; }

        public void Disconnect() { IsConnected = false; IsSolutionLoaded = false; }

        public async Task<bool> LoadSolutionAsync(string solutionPath)
        {
            await Task.Delay(200).ConfigureAwait(false);
            IsSolutionLoaded = IsConnected;
            return IsSolutionLoaded;
        }

        public async Task<VisionPose> TriggerAsync(EVisionProcedure procedure, CancellationToken ct)
        {
            if (!IsConnected) return VisionPose.NotFound("chưa kết nối");
            if (!IsSolutionLoaded) return VisionPose.NotFound("chưa nạp solution");

            bool isAlign = procedure == EVisionProcedure.AlignBottomTool1 ||
                           procedure == EVisionProcedure.AlignBottomTool2;
            bool isAlignCalib = procedure == EVisionProcedure.AlignCalibTool1 ||
                                procedure == EVisionProcedure.AlignCalibTool2;
            if (isAlign) AlignBottomCount++;
            else if (procedure == EVisionProcedure.LocateTop) LocateTopCount++;

            await Task.Delay(ProcessTimeMs, ct).ConfigureAwait(false);

            if (_rng.NextDouble() > FoundRate)
                return VisionPose.NotFound("không tìm thấy đối tượng");

            // AlignBottomTool1/2 và AlignCalibTool1/2 đã tự hiệu chuẩn + Teach bên trong
            // VisionMaster (PLAN.md §6.4) — PixelX/PixelY mô phỏng phải là ĐỘ LỆCH mm quanh 0,
            // không phải pixel quanh tâm ảnh 640/480 như procedure còn lại.
            if (isAlign || isAlignCalib)
            {
                return new VisionPose
                {
                    Found = true,
                    PixelX = (_rng.NextDouble() - 0.5) * 2 * NoiseAlignMm,
                    PixelY = (_rng.NextDouble() - 0.5) * 2 * NoiseAlignMm,
                    Angle = (_rng.NextDouble() - 0.5) * 2 * NoiseAngle,
                    Score = 85 + _rng.NextDouble() * 14
                };
            }

            return new VisionPose
            {
                Found = true,
                PixelX = 640 + (_rng.NextDouble() - 0.5) * 2 * NoisePixel,
                PixelY = 480 + (_rng.NextDouble() - 0.5) * 2 * NoisePixel,
                Angle = (_rng.NextDouble() - 0.5) * 2 * NoiseAngle,
                Score = 85 + _rng.NextDouble() * 14
            };
        }

        /// <summary>Scale mô phỏng: khớp <c>CameraCalib.CreateSimulation</c> (30 mm / 1280 px).</summary>
        public double SimScaleMmPerPixel { get; set; } = 30.0 / 1280.0;

        public async Task<CalibBoardResult> TriggerCalibBoardAsync(CancellationToken ct)
        {
            if (!IsConnected) return CalibBoardResult.NotFound("chưa kết nối");
            if (!IsSolutionLoaded) return CalibBoardResult.NotFound("chưa nạp solution");

            await Task.Delay(ProcessTimeMs, ct).ConfigureAwait(false);

            if (_rng.NextDouble() > FoundRate)
                return CalibBoardResult.NotFound("không thấy đủ góc trên bản chuẩn");

            // Nhiễu nhỏ quanh scale mô phỏng, độ không vuông góc gần 0 — đúng tính chất một
            // bản chuẩn chrome-on-glass thật (PLAN.md §6.3 điều kiện 2, 3).
            double noise = 1.0 + (_rng.NextDouble() - 0.5) * 0.01;
            return new CalibBoardResult
            {
                Found = true,
                ScaleU = SimScaleMmPerPixel * noise,
                ScaleV = SimScaleMmPerPixel * (2.0 - noise),
                SkewDeg = (_rng.NextDouble() - 0.5) * 0.2,
                CornerCount = 841,
                // Không mô phỏng vật lý ống kính di chuyển theo trục X thật, nên giá trị này gần
                // như đứng yên qua các lần gọi — đủ để kiểm chứng CÔNG THỨC đối chiếu chéo B3 báo
                // đúng "không khớp" khi không có dữ liệu chuyển động thật đi kèm.
                OriginPixelU = 640 + (_rng.NextDouble() - 0.5) * 2 * NoisePixel,
                OriginPixelV = 480 + (_rng.NextDouble() - 0.5) * 2 * NoisePixel
            };
        }
    }
}

