using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using ShieldCanAssy.Core.Communication;
using ShieldCanAssy.Core.Data;
using ShieldCanAssy.Core.Data.Model;
using ShieldCanAssy.Core.Infor;
using ShieldCanAssy.Utility.Log;

namespace ShieldCanAssy.Core.Controller
{
    /// <summary>Kết quả phép kiểm tra hiệu chuẩn CAM top-down (§6.2b).</summary>
    public class TopDownVerifyResult
    {
        public bool Ok { get; set; }
        public string Reason { get; set; }

        /// <summary>Quãng đường đã chạy thử, mm.</summary>
        public double StepMm { get; set; }

        /// <summary>Sai lệch thang đo: (lượng Flow báo) − (lượng trục đã chạy), mm. 0 là hoàn hảo.</summary>
        public double ErrorX { get; set; }
        public double ErrorY { get; set; }

        /// <summary>Lẫn trục: chạy X mà Flow báo dịch theo Y (và ngược lại), mm.</summary>
        public double CrossX { get; set; }
        public double CrossY { get; set; }

        /// <summary>Dấu của từng trục có đúng không — sai dấu là đặt lệch gấp đôi, không phải lệch ít.</summary>
        public bool SignXOk { get; set; }
        public bool SignYOk { get; set; }
    }

    /// <summary>Kết quả phép thử vòng xoay của một tay hút (§6.4b).</summary>
    public class AlignVerifyResult
    {
        public bool Ok { get; set; }
        public string Reason { get; set; }

        /// <summary>Dấu quy đổi góc VisionMaster → trục A: +1, −1, hoặc 0 nếu không kết luận được.</summary>
        public int Sign { get; set; }

        /// <summary>Góc đã xoay thử, độ.</summary>
        public double TestAngleDeg { get; set; }

        /// <summary>Góc Flow PlaceAlign trả về cho phép thử, độ.</summary>
        public double MeasuredDeltaThetaDeg { get; set; }

        /// <summary>Sai số dư: lượng dịch còn lại sau khi quay về, mm. Khác 0 nghĩa là tâm xoay
        /// hoặc chiều hệ toạ độ (handedness) trong file hiệu chuẩn bottom-up chưa đúng.</summary>
        public double ResidualMm { get; set; }

        /// <summary>Độ lệch tâm của sản phẩm lúc thử, mm — quá nhỏ thì phép thử không kết luận
        /// được về tâm xoay.</summary>
        public double EccentricityMm { get; set; }

        /// <summary>Vị trí trục X lúc thử — phải trùng vị trí soi lúc chạy Auto.</summary>
        public double PosX { get; set; }
    }

    /// <summary>Kết quả chuỗi nạp điểm hiệu chuẩn Align (§6.4).</summary>
    public class AlignCalibSequenceResult
    {
        public bool Ok { get; set; }
        public string Reason { get; set; }
        public int PointsCaptured { get; set; }
    }

    public class HandEyeMeasurement
    {
        public bool Ok { get; set; }
        public string Reason { get; set; }

        /// <summary>Vị trí trục (X, Y2) nơi tâm ảnh CAM top-down trùng dấu chuẩn.</summary>
        public double CamX { get; set; }
        public double CamY { get; set; }
    }

    /// <summary>
    /// Hiệu chuẩn vision — PLAN.md §6.
    ///
    /// <para><b>App không còn tự fit ma trận nào</b> (Tuấn chốt 2026-09-12). Phép hiệu chuẩn làm
    /// trong VisionMaster (N-point cho CAM top-down, hiệu chuẩn có xoay cho CAM bottom-up), App
    /// chỉ còn ba việc mà VisionMaster không tự làm được vì nó không điều khiển trục:</para>
    /// <list type="number">
    /// <item><b>Nạp điểm</b>: chạy trục tới từng vị trí/góc rồi kích Flow hiệu chuẩn — mỗi lần
    /// chạy Flow là module hiệu chuẩn nạp thêm một điểm (chế độ Trigger Acquisition).</item>
    /// <item><b>Kiểm tra lại</b> kết quả hiệu chuẩn bằng chuyển động trục thật: sai thang đo, sai
    /// dấu, lẫn trục, sai tâm xoay đều lộ ra ở đây chứ không lộ trong VisionMaster — VisionMaster
    /// chỉ biết ảnh, không biết trục đã đi bao xa.</item>
    /// <item><b>Đo hand-eye</b> (§6.5) — hiệu toạ độ trục, VisionMaster không đọc được encoder.</item>
    /// </list>
    ///
    /// <para>Lớp này không giữ trạng thái <c>VisionCalib</c> nào: mọi hàm nhận tham số và trả kết
    /// quả để trang Vision Edit cho operator XEM rồi mới quyết định ghi vào model — "không đạt →
    /// không cho lưu" (§6.1) là quyết định của người, không phải của routine.</para>
    /// </summary>
    public class Routine_Calib
    {
        private readonly MotionConnect _motion;
        private readonly McFunction _func;
        private readonly Func<SystemData> _sys;
        private readonly Func<IVisionDevice> _vision;

        public Routine_Calib(MotionConnect motion, McFunction func, Func<SystemData> sys, Func<IVisionDevice> vision)
        {
            _motion = motion;
            _func = func;
            _sys = sys;
            _vision = vision;
        }

        // ───────────────────────── §6.2 CAM top-down: lưới 9 điểm ─────────────────────────

        /// <summary>
        /// Thứ tự chạy 9 điểm của "Auto Calib", theo số trên bàn phím numpad.
        ///
        /// <para>Hình chữ S, KHÔNG phải quét dòng: module N-point của VisionMaster tự sinh toạ độ
        /// vật lý cho các điểm theo quỹ đạo chữ S (Help "Physical Coordinate Parameters", tham số
        /// Movement First + Commutation Number). Chạy theo thứ tự dòng 1→9 thì điểm thứ 4 và thứ 6
        /// của App rơi vào đúng chỗ ngược với điểm thứ 4 và thứ 6 mà VisionMaster giả định — ma
        /// trận vẫn fit ra được, chỉ méo, và không có thông báo lỗi nào cả.</para>
        /// </summary>
        public static readonly int[] TopDownGridSOrder = { 1, 2, 3, 6, 5, 4, 7, 8, 9 };

        /// <summary>Di chuyển tới (x, y2) rồi kích hoạt Flow TopDownCalib — mỗi lần gọi là nạp một
        /// điểm vào module N-point. Trả về false nếu di chuyển thất bại hoặc Flow báo không tìm thấy.</summary>
        public async Task<bool> MoveAndTriggerTopDownCalibAsync(double x, double y2, CancellationToken ct)
        {
            if (!await _func.MoveToCellAsync(AxisId.Y2, y2, x, ct).ConfigureAwait(false))
                return false;

            var pose = await _vision().TriggerAsync(EVisionProcedure.TopDownCalib, ct).ConfigureAwait(false);
            return pose.Found;
        }

        /// <summary>Kích hoạt Flow TopDownCalib tại vị trí hiện tại, không di chuyển — chụp lại một
        /// điểm lẻ. <b>Cũng nạp thêm một điểm</b> vào module N-point, không phải nút "test vô hại".</summary>
        public async Task<bool> TriggerTopDownCalibFlowAsync(CancellationToken ct)
        {
            var pose = await _vision().TriggerAsync(EVisionProcedure.TopDownCalib, ct).ConfigureAwait(false);
            return pose.Found;
        }

        // ───────────────────────── §6.2b Kiểm tra hiệu chuẩn CAM top-down ─────────────────────────

        /// <summary>
        /// Soi dấu chuẩn, chạy trục X đúng <paramref name="stepMm"/>, soi lại; rồi làm y hệt với
        /// trục Y2. Flow LocateMark phải báo lượng dịch ĐÚNG BẰNG quãng đường trục đã chạy và
        /// NGƯỢC DẤU (trục chạy tới thì vật lùi lại trong hệ của camera).
        ///
        /// <para>Đây là phép kiểm tra duy nhất bắt được ba lỗi mà bản thân VisionMaster không thể
        /// tự phát hiện: sai thang đo (nhập sai bước lưới lúc hiệu chuẩn), <b>sai dấu</b> (khai
        /// nhầm Camera Mode giữa "Dynamic Camera" và "Camera Stationary", hoặc nhập toạ độ vật lý
        /// ngược chiều trục), và lẫn trục X ↔ Y.</para>
        /// </summary>
        public async Task<TopDownVerifyResult> VerifyTopDownAsync(double stepMm, CancellationToken ct)
        {
            var result = new TopDownVerifyResult { StepMm = stepMm };
            try
            {
                if (Math.Abs(stepMm) < 0.5)
                {
                    result.Reason = "quãng đường thử quá nhỏ — nhiễu đo sẽ lớn hơn thứ cần đo";
                    return result;
                }

                var sys = _sys();
                int shots = sys.CalibShotsPerPoint;
                double x0 = _motion[AxisId.X]?.CurrentPos ?? 0;
                double y0 = _motion[AxisId.Y2]?.CurrentPos ?? 0;

                var p0 = await CaptureAveragedAsync(EVisionProcedure.LocateMark, shots, ct).ConfigureAwait(false);
                if (!p0.Found) { result.Reason = p0.Error ?? "không thấy dấu chuẩn ở vị trí xuất phát"; return result; }

                // ── trục X ──
                if (!await MoveAsync(AxisId.X, x0 + stepMm, ct).ConfigureAwait(false))
                { result.Reason = "không chạy được trục X"; return result; }

                var px = await CaptureAveragedAsync(EVisionProcedure.LocateMark, shots, ct).ConfigureAwait(false);
                await MoveAsync(AxisId.X, x0, ct).ConfigureAwait(false);
                if (!px.Found) { result.Reason = px.Error ?? "không thấy dấu chuẩn sau khi chạy X — dấu ra khỏi khung hình?"; return result; }

                // ── trục Y2 ──
                if (!await MoveAsync(AxisId.Y2, y0 + stepMm, ct).ConfigureAwait(false))
                { result.Reason = "không chạy được trục Y2"; return result; }

                var py = await CaptureAveragedAsync(EVisionProcedure.LocateMark, shots, ct).ConfigureAwait(false);
                await MoveAsync(AxisId.Y2, y0, ct).ConfigureAwait(false);
                if (!py.Found) { result.Reason = py.Error ?? "không thấy dấu chuẩn sau khi chạy Y2 — dấu ra khỏi khung hình?"; return result; }

                // Kỳ vọng: (lượng Flow báo) = −(quãng đường trục đã chạy).
                double dxOnX = px.X - p0.X;
                double dyOnX = px.Y - p0.Y;
                double dyOnY = py.Y - p0.Y;
                double dxOnY = py.X - p0.X;

                result.ErrorX = dxOnX + stepMm;
                result.CrossX = dyOnX;
                result.ErrorY = dyOnY + stepMm;
                result.CrossY = dxOnY;
                result.SignXOk = dxOnX < 0;
                result.SignYOk = dyOnY < 0;

                double tol = sys.CalibMaxResidualThresholdMm;
                if (!result.SignXOk || !result.SignYOk)
                {
                    result.Reason = string.Format(
                        "SAI DẤU: chạy +{0:0.0} mm mà Flow báo X {1:+0.000;-0.000}, Y {2:+0.000;-0.000} mm " +
                        "(phải cùng âm) — kiểm tra Camera Mode của module N-point (top-down là Dynamic Camera) " +
                        "và chiều toạ độ vật lý đã nhập",
                        stepMm, dxOnX, dyOnY);
                    return result;
                }

                result.Ok = Math.Abs(result.ErrorX) <= tol && Math.Abs(result.ErrorY) <= tol &&
                            Math.Abs(result.CrossX) <= tol && Math.Abs(result.CrossY) <= tol;
                if (!result.Ok)
                    result.Reason = string.Format(
                        "lệch thang đo X {0:0.000} mm, Y {1:0.000} mm; lẫn trục {2:0.000}/{3:0.000} mm — vượt ngưỡng {4:0.000} mm",
                        result.ErrorX, result.ErrorY, result.CrossX, result.CrossY, tol);

                LogWorker.Instance.RecordLog(
                    string.Format("Kiểm tra CAM top-down (chạy {0:0.0} mm): lệch X {1:0.000}, Y {2:0.000}, lẫn trục {3:0.000}/{4:0.000} mm — {5}",
                        stepMm, result.ErrorX, result.ErrorY, result.CrossX, result.CrossY, result.Ok ? "ĐẠT" : "KHÔNG ĐẠT"),
                    result.Ok ? Utility.Log.LogLevel.Info : Utility.Log.LogLevel.Warning, "Calib");

                return result;
            }
            catch (OperationCanceledException)
            {
                result.Reason = "bị huỷ";
                return result;
            }
            catch (Exception ex)
            {
                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
                result.Reason = "lỗi bất thường: " + ex.Message;
                return result;
            }
        }

        // ───────────────────────── §6.4 CAM bottom-up: nạp điểm hiệu chuẩn ─────────────────────────

        /// <summary>
        /// Chạy hết chuỗi nạp điểm cho module hiệu chuẩn bottom-up của tay
        /// <paramref name="nozzle"/>: trước hết các vị trí X lệch so với vị trí soi (phần tịnh
        /// tiến), sau đó các góc của trục A tại đúng vị trí soi (phần xoay), mỗi bước kích Flow
        /// AlignCalib_ToolN một lần.
        ///
        /// <para><b>Kết thúc bằng việc đưa trục A về 0°</b>: bước tiếp theo của quy trình là chụp
        /// ảnh mẫu chuẩn (Create Reference trong Flow runtime), mà mẫu chuẩn phải ở đúng tư thế
        /// chuẩn — bỏ trục A đứng ở góc cuối của dãy (300°) rồi teach là mốc lệch nguyên một góc,
        /// và Auto sẽ loại mọi sản phẩm vì |Δθ| vượt ngưỡng.</para>
        /// </summary>
        public async Task<AlignCalibSequenceResult> RunAlignCalibSequenceAsync(
            int nozzle, double alignPosX, IList<double> xOffsets, IList<double> anglesDeg,
            Action<string> progress, CancellationToken ct)
        {
            var result = new AlignCalibSequenceResult();
            try
            {
                string axisName = nozzle == 1 ? AxisId.A1 : AxisId.A2;
                var proc = nozzle == 1 ? EVisionProcedure.AlignCalibTool1 : EVisionProcedure.AlignCalibTool2;

                if (anglesDeg == null || anglesDeg.Count < 3)
                {
                    result.Reason = "cần tối thiểu 3 góc xoay (VisionMaster đòi các bước xoay bằng nhau)";
                    return result;
                }

                // Phần tịnh tiến chụp ở MỘT góc cố định — góc đầu của dãy. Vừa xoay vừa tịnh tiến
                // thì module hiệu chuẩn không tách được hai thành phần.
                double firstAngle = anglesDeg[0];
                if (!await MoveAsync(axisName, firstAngle, ct).ConfigureAwait(false))
                { result.Reason = "không xoay được trục " + axisName + " về góc đầu"; return result; }

                if (xOffsets != null)
                {
                    for (int i = 0; i < xOffsets.Count; i++)
                    {
                        double x = alignPosX + xOffsets[i];
                        if (progress != null) progress(string.Format("Tịnh tiến {0}/{1}: X = {2:0.000}", i + 1, xOffsets.Count, x));

                        if (!await MoveAsync(AxisId.X, x, ct).ConfigureAwait(false))
                        { result.Reason = string.Format("không chạy được X tới {0:0.000}", x); return result; }

                        var pose = await _vision().TriggerAsync(proc, ct).ConfigureAwait(false);
                        if (!pose.Found)
                        { result.Reason = string.Format("điểm tịnh tiến X = {0:0.000} không tìm thấy sản phẩm", x); return result; }
                        result.PointsCaptured++;
                    }
                }

                // Phần xoay: luôn tại ĐÚNG vị trí soi của tay này — chạy thật cũng dừng ở đó
                // (PDF Hikrobot tr.45: vị trí chụp lúc chạy phải trùng vị trí chụp lúc hiệu chuẩn).
                if (!await MoveAsync(AxisId.X, alignPosX, ct).ConfigureAwait(false))
                { result.Reason = "không chạy được X về vị trí soi"; return result; }

                for (int i = 0; i < anglesDeg.Count; i++)
                {
                    double angle = anglesDeg[i];
                    if (progress != null) progress(string.Format("Góc {0}/{1}: {2:0.0}°", i + 1, anglesDeg.Count, angle));

                    if (!await MoveAsync(axisName, angle, ct).ConfigureAwait(false))
                    { result.Reason = string.Format("không xoay được tới {0:0.0}°", angle); return result; }

                    var pose = await _vision().TriggerAsync(proc, ct).ConfigureAwait(false);
                    if (!pose.Found)
                    { result.Reason = string.Format("góc {0:0.0}° không tìm thấy sản phẩm — mở rộng Angle Range của High Precision Match?", angle); return result; }
                    result.PointsCaptured++;
                }

                if (!await MoveAsync(axisName, 0, ct).ConfigureAwait(false))
                { result.Reason = "đã nạp đủ điểm nhưng không đưa được trục " + axisName + " về 0°"; return result; }

                result.Ok = true;
                LogWorker.Instance.RecordLog(
                    string.Format("Hiệu chuẩn Align tay #{0}: đã nạp {1} điểm, trục A về 0°", nozzle, result.PointsCaptured),
                    Utility.Log.LogLevel.Info, "Calib");
                return result;
            }
            catch (OperationCanceledException)
            {
                result.Reason = "bị huỷ";
                return result;
            }
            catch (Exception ex)
            {
                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
                result.Reason = "lỗi bất thường: " + ex.Message;
                return result;
            }
        }

        /// <summary>Xoay trục A của tay <paramref name="nozzle"/> tới <paramref name="angleDeg"/>
        /// rồi kích hoạt Flow AlignCalib của đúng tay đó — nạp một điểm lẻ.</summary>
        public async Task<bool> MoveAndTriggerAlignCalibAsync(int nozzle, double angleDeg, CancellationToken ct)
        {
            string axisName = nozzle == 1 ? AxisId.A1 : AxisId.A2;
            if (_motion[axisName] == null) return false;

            if (!await MoveAsync(axisName, angleDeg, ct).ConfigureAwait(false))
                return false;

            var proc = nozzle == 1 ? EVisionProcedure.AlignCalibTool1 : EVisionProcedure.AlignCalibTool2;
            var pose = await _vision().TriggerAsync(proc, ct).ConfigureAwait(false);
            return pose.Found;
        }

        /// <summary>Kích hoạt Flow AlignCalib của tay <paramref name="nozzle"/> tại góc hiện tại,
        /// không xoay — nạp thêm một điểm tại chỗ.</summary>
        public async Task<bool> TriggerAlignCalibFlowAsync(int nozzle, CancellationToken ct)
        {
            var proc = nozzle == 1 ? EVisionProcedure.AlignCalibTool1 : EVisionProcedure.AlignCalibTool2;
            var pose = await _vision().TriggerAsync(proc, ct).ConfigureAwait(false);
            return pose.Found;
        }

        /// <summary>Đưa trục A của tay <paramref name="nozzle"/> về 0° — tư thế chuẩn để chụp ảnh
        /// mẫu (Create Reference) và để chạy Auto.</summary>
        public async Task<bool> MoveAlignAxisToZeroAsync(int nozzle, CancellationToken ct)
        {
            string axisName = nozzle == 1 ? AxisId.A1 : AxisId.A2;
            if (_motion[axisName] == null) return false;
            return await MoveAsync(axisName, 0, ct).ConfigureAwait(false);
        }

        // ───────────────────────── §6.4b Phép thử vòng xoay ─────────────────────────

        /// <summary>
        /// Hút sẵn một sản phẩm, đứng tại vị trí soi: đo tư thế, xoay trục A thêm
        /// <paramref name="testAngleDeg"/>, đo lại, rồi hỏi chính Flow PlaceAlign "muốn đưa sản
        /// phẩm về tư thế ban đầu thì phải làm gì".
        ///
        /// <para>Câu trả lời đúng là "xoay ngược lại đúng bấy nhiêu độ và KHÔNG cần dịch gì cả".
        /// Phép thử này vì vậy cho ra hai thứ cùng lúc:</para>
        /// <list type="bullet">
        /// <item><b>Dấu góc</b> — VisionMaster tính theo chiều kim đồng hồ dương, trục A của máy
        /// quy ước ngược lại (§11 #6); dấu đo được ghi vào model thay vì suy đoán.</item>
        /// <item><b>Sai số dư</b> — lượng dịch còn lại phải bằng 0. Khác 0 nghĩa là gốc toạ độ của
        /// file hiệu chuẩn bottom-up không nằm đúng tâm xoay, hoặc chiều hệ toạ độ bị lật (camera
        /// nhìn từ dưới lên là ảnh gương). Đây là cách duy nhất bắt được hai lỗi đó trước khi máy
        /// đặt lệch hàng loạt.</item>
        /// </list>
        /// </summary>
        public async Task<AlignVerifyResult> VerifyAlignRotationAsync(int nozzle, double testAngleDeg, CancellationToken ct)
        {
            var result = new AlignVerifyResult { TestAngleDeg = testAngleDeg };
            try
            {
                var sys = _sys();
                string axisName = nozzle == 1 ? AxisId.A1 : AxisId.A2;
                var proc = nozzle == 1 ? EVisionProcedure.AlignBottomTool1 : EVisionProcedure.AlignBottomTool2;

                if (Math.Abs(testAngleDeg) < 1.0)
                { result.Reason = "góc thử quá nhỏ — nhiễu đo sẽ lớn hơn thứ cần đo"; return result; }
                if (_motion[axisName] == null)
                { result.Reason = "không có trục " + axisName; return result; }

                result.PosX = _motion[AxisId.X]?.CurrentPos ?? 0;
                double a0 = _motion[axisName].CurrentPos;
                int shots = sys.CalibShotsPerPoint;

                var p0 = await CaptureAveragedAsync(proc, shots, ct).ConfigureAwait(false);
                if (!p0.Found) { result.Reason = p0.Error ?? "không thấy sản phẩm ở góc xuất phát"; return result; }

                if (!await MoveAsync(axisName, a0 + testAngleDeg, ct).ConfigureAwait(false))
                { result.Reason = "không xoay được trục " + axisName; return result; }

                var p1 = await CaptureAveragedAsync(proc, shots, ct).ConfigureAwait(false);
                await MoveAsync(axisName, a0, ct).ConfigureAwait(false);
                if (!p1.Found) { result.Reason = p1.Error ?? "không thấy sản phẩm sau khi xoay — mở rộng Angle Range của High Precision Match?"; return result; }

                // Hỏi VisionMaster: đưa tư thế SAU khi xoay về lại tư thế TRƯỚC khi xoay.
                var align = await _vision().TriggerPlaceAlignAsync(new PlaceAlignInput
                {
                    TargetX = p0.X, TargetY = p0.Y, TargetAngle = p0.Angle,
                    ObjectX = p1.X, ObjectY = p1.Y, ObjectAngle = p1.Angle
                }, ct).ConfigureAwait(false);

                if (align == null || !align.Ok)
                { result.Reason = "Flow PlaceAlign không tính được" + (align == null ? "" : ": " + align.Error); return result; }

                result.MeasuredDeltaThetaDeg = align.DeltaThetaDeg;
                result.ResidualMm = Math.Sqrt(align.DeltaX * align.DeltaX + align.DeltaY * align.DeltaY);
                result.EccentricityMm = Math.Sqrt(p0.X * p0.X + p0.Y * p0.Y);

                double measured = Math.Abs(align.DeltaThetaDeg);
                double tolDeg = sys.AlignVerifyAngleTolDeg;
                if (Math.Abs(measured - Math.Abs(testAngleDeg)) > tolDeg)
                {
                    result.Reason = string.Format(
                        "xoay thử {0:0.0}° nhưng Flow báo {1:0.0}° — lệch quá {2:0.0}°: sai đơn vị góc, sai mẫu khớp, hoặc trục A chưa đúng tỉ lệ xung/độ",
                        testAngleDeg, align.DeltaThetaDeg, tolDeg);
                    return result;
                }

                // Xoay +α thì muốn quay lại phải xoay −α. VisionMaster trả Δθ theo chiều của nó;
                // dấu cần tìm là dấu biến Δθ đó thành lệnh cho trục A.
                result.Sign = align.DeltaThetaDeg > 0 ? -1 : +1;

                double tolMm = sys.CalibMaxResidualThresholdMm;
                if (result.ResidualMm > tolMm)
                {
                    result.Reason = string.Format(
                        "sai số dư {0:0.000} mm > ngưỡng {1:0.000} mm — gốc toạ độ của file hiệu chuẩn bottom-up " +
                        "không nằm đúng tâm xoay, hoặc chiều hệ toạ độ bị lật (camera nhìn từ dưới lên là ảnh gương)",
                        result.ResidualMm, tolMm);
                    return result;
                }

                if (result.EccentricityMm < 0.5)
                {
                    result.Reason = string.Format(
                        "sản phẩm gần trùng tâm xoay ({0:0.000} mm) — dấu góc đo được vẫn dùng được, nhưng phép thử " +
                        "KHÔNG kết luận được về tâm xoay/chiều hệ toạ độ. Hút lệch sản phẩm ra rồi thử lại để kiểm cả hai.",
                        result.EccentricityMm);
                }

                result.Ok = true;
                LogWorker.Instance.RecordLog(
                    string.Format("Phép thử vòng xoay tay #{0}: xoay {1:0.0}°, Flow báo {2:0.0}° → dấu {3}, sai số dư {4:0.000} mm (lệch tâm {5:0.000} mm)",
                        nozzle, testAngleDeg, align.DeltaThetaDeg, result.Sign > 0 ? "+1" : "−1", result.ResidualMm, result.EccentricityMm),
                    Utility.Log.LogLevel.Info, "Calib");

                return result;
            }
            catch (OperationCanceledException)
            {
                result.Reason = "bị huỷ";
                return result;
            }
            catch (Exception ex)
            {
                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
                result.Reason = "lỗi bất thường: " + ex.Message;
                return result;
            }
        }

        // ───────────────────────── §6.5 Hand-eye ─────────────────────────

        /// <summary>
        /// Nửa đầu của phép đo hand-eye (PLAN.md §6.5): soi dấu chuẩn bằng CAM top-down (Flow
        /// LocateMark), trả về vị trí trục (X, Y2) nơi tâm ảnh trùng dấu chuẩn đó. Nửa sau — đưa
        /// đầu hút chạm đúng dấu chuẩn rồi đọc vị trí trục — là thao tác tay, trang Vision Edit đọc
        /// thẳng <c>CurrentPos</c> giống các nút Teach khác.
        ///
        /// <para>Dùng <b>LocateMark</b> chứ không phải LocateTop: mẫu của LocateTop là chi tiết
        /// thật trong ô tray, soi dấu chuẩn bằng nó thì không khớp. Cũng không dùng TopDownCalib vì
        /// mỗi lần chạy Flow đó là nạp thêm một điểm hiệu chuẩn.</para>
        /// </summary>
        public async Task<HandEyeMeasurement> MeasureHandEyeCameraPosAsync(CancellationToken ct)
        {
            try
            {
                var pose = await CaptureAveragedAsync(EVisionProcedure.LocateMark, _sys().CalibShotsPerPoint, ct).ConfigureAwait(false);
                if (!pose.Found)
                    return new HandEyeMeasurement { Ok = false, Reason = pose.Error ?? "không thấy dấu chuẩn" };

                // Flow trả về lượng phải dịch trục để tâm ảnh trùng dấu chuẩn, nên vị trí camera
                // "nhìn thẳng" dấu chuẩn chính là vị trí trục hiện tại cộng lượng đó.
                return new HandEyeMeasurement
                {
                    Ok = true,
                    CamX = (_motion[AxisId.X]?.CurrentPos ?? 0) + pose.X,
                    CamY = (_motion[AxisId.Y2]?.CurrentPos ?? 0) + pose.Y
                };
            }
            catch (OperationCanceledException)
            {
                return new HandEyeMeasurement { Ok = false, Reason = "bị huỷ" };
            }
            catch (Exception ex)
            {
                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
                return new HandEyeMeasurement { Ok = false, Reason = "lỗi bất thường: " + ex.Message };
            }
        }

        // ───────────────────────── tiện ích ─────────────────────────

        private async Task<bool> MoveAsync(string axisName, double pos, CancellationToken ct)
        {
            var cfg = _sys().GetAxis(axisName);
            return await _func.MoveAsync(axisName, pos, cfg.MoveSpeed, ct).ConfigureAwait(false);
        }

        private async Task<VisionPose> CaptureAveragedAsync(EVisionProcedure proc, int shots, CancellationToken ct)
        {
            var vision = _vision();
            double sumX = 0, sumY = 0, sumA = 0;
            int ok = 0;

            for (int i = 0; i < shots; i++)
            {
                if (ct.IsCancellationRequested) return VisionPose.NotFound("bị huỷ");

                var p = await vision.TriggerAsync(proc, ct).ConfigureAwait(false);
                if (!p.Found) return VisionPose.NotFound(p.Error ?? "không tìm thấy đối tượng");

                sumX += p.X;
                sumY += p.Y;
                sumA += p.Angle;
                ok++;
            }

            if (ok == 0) return VisionPose.NotFound("không chụp được lần nào");

            // PLAN §6.1 quy tắc 4: mỗi điểm chụp N ảnh, lấy trung bình để khử nhiễu đo.
            return new VisionPose { Found = true, X = sumX / ok, Y = sumY / ok, Angle = sumA / ok, Score = 1.0 };
        }
    }
}

