/// (đèn CAM2). Dùng try/finally để chắc chắn tắt đèn kể cả khi trigger lỗi/timeout — không
/// để đèn sáng treo lại.
///
/// <para>Sửa lỗi tồn tại từ trước (2026-09-10, phát hiện lúc bỏ Flow AlignBottom chung):
/// điều kiện cũ so <c>procedure == EVisionProcedure.AlignBottom</c> — Flow chung đó đã
/// orphan, S2x_Align (hàm DUY NHẤT gọi TriggerAsync này trong Auto) chỉ truyền
/// AlignBottomTool1/Tool2, nên đèn CAM1 trước đây KHÔNG BAO GIỜ bật lúc Align, luôn rơi
/// vào nhánh CAM2.</para>
/// </summary>
private async Task<VisionPose> TriggerAsync(EVisionProcedure procedure, CancellationToken ct)
{
    var vision = _vision();
    if (vision == null || !vision.IsConnected)
    {
        AlarmManager.Raise(AlarmCode.VisionDisconnected, "Vision");
        return null;
    }

    bool isBottomUp = procedure == EVisionProcedure.AlignBottomTool1 || procedure == EVisionProcedure.AlignBottomTool2;
    int lampBit = isBottomUp ? IoMap.DoLampCam1 : IoMap.DoLampCam2;
    _func.Io?.SetDo(lampBit, true);
    try
    {
        using (var timeout = CancellationTokenSource.CreateLinkedTokenSource(ct))
        {
            timeout.CancelAfter(_sys().VisionTriggerTimeoutMs);
            try
            {
                var pose = await vision.TriggerAsync(procedure, timeout.Token).ConfigureAwait(false);
                AlarmManager.ClearCondition(AlarmCode.VisionTriggerTimeout);

