/// Chạy Flow tính toán PlaceAlign (§6.6). Không có camera nên không bật đèn, không cần cửa
/// sổ timeout riêng — <c>VisionConnect</c> đã tự canh giờ cho mọi lần Run.
/// </summary>
private async Task<PlaceAlignResult> PlaceAlignAsync(PlaceAlignInput input, CancellationToken ct)
{
    var vision = _vision();
    if (vision == null || !vision.IsConnected)
    {
        AlarmManager.Raise(AlarmCode.VisionDisconnected, "Vision");
        return PlaceAlignResult.NotOk("chưa kết nối vision");
    }

    return await vision.TriggerPlaceAlignAsync(input, ct).ConfigureAwait(false);
}

