        // ───────────────────────── lưới 9 điểm CAM top-down (numpad) ─────────────────────────

        /// <summary>"Calibration Center Point" — toạ độ (X, Y2) ứng với điểm 5 (giữa khung hình).</summary>
        public double CalibrationCenterX
        {
            get => Sys.TopDownCalibCenterX;
            set { Sys.TopDownCalibCenterX = value; OnPropertyChanged(); }
        }

        public double CalibrationCenterY
        {
            get => Sys.TopDownCalibCenterY;
            set { Sys.TopDownCalibCenterY = value; OnPropertyChanged(); }
        }

        /// <summary>Phân biệt "chưa từng Save" với "đã Save đúng tại (0,0)" — 2 giá trị double mặc
        /// định 0 không tự nói lên được điều đó.</summary>
        public bool CalibrationCenterSet
        {
            get => Sys.TopDownCalibCenterSet;
            set { Sys.TopDownCalibCenterSet = value; OnPropertyChanged(); OnPropertyChanged(nameof(CalibrationCenterStatusText)); }
        }

        public string CalibrationCenterStatusText => CalibrationCenterSet ? "(đã lưu)" : "(chưa lưu)";

        /// <summary>
        /// Đọc vị trí trục (X, Y2) HIỆN TẠI rồi lưu làm Calibration Center Point — và ghi thẳng
        /// xuống <c>system.json</c>.
        ///
        /// <para>Ghi đĩa ngay tại đây chứ không chờ nút Lưu của trang Setting: tâm lưới và bước
        /// lưới nằm trong SystemData, mà trang này không có nút Lưu nào của riêng nó — trước đây
        /// tắt app là mất, và người dùng không có cách nào biết điều đó.</para>
        /// </summary>
        private void SaveCalibrationCenter()
        {
            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — toạ độ đọc lúc này không có ý nghĩa."); return; }

            CalibrationCenterX = McControl.Motion[AxisId.X].CurrentPos;
            CalibrationCenterY = McControl.Motion[AxisId.Y2].CurrentPos;
            CalibrationCenterSet = true;

            bool saved = McDataManager.SaveSystemData();
            _dialog.Info(string.Format("Đã lưu Calibration Center Point: ({0:0.000}, {1:0.000}){2}",
                CalibrationCenterX, CalibrationCenterY,
                saved ? " và ghi xuống system.json (kèm bước lưới X/Y)." : " nhưng GHI ĐĨA THẤT BẠI — xem alarm."));
        }

        /// <summary>Số numpad 1-9 → (hệ số hàng, hệ số cột) quanh tâm, khớp hình minh hoạ người
        /// dùng gửi (1,2,3 hàng dưới; 4,5,6 hàng giữa; 7,8,9 hàng trên).</summary>
        private static void TopDownGridOffset(int number, out int rowMul, out int colMul)
        {
            int idx = number - 1;
            rowMul = idx / 3 - 1;
            colMul = idx % 3 - 1;
        }

        private async Task<bool> MoveAndTriggerGridPointAsync(int number)
        {
            int rowMul, colMul;
            TopDownGridOffset(number, out rowMul, out colMul);
            double x = CalibrationCenterX + colMul * TopDownCalibStepXMm;
            double y = CalibrationCenterY + rowMul * TopDownCalibStepYMm;
            return await McControl.Calib.MoveAndTriggerTopDownCalibAsync(x, y, McControl.Safety.AbortToken).ConfigureAwait(true);
        }

        private bool CheckReadyForGrid()
        {
            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước khi hiệu chuẩn."); return false; }
            if (!CalibrationCenterSet) { _dialog.Warn("Chưa lưu Calibration Center Point — jog tới giữa khung hình rồi bấm Save trước."); return false; }
            return true;
        }

        private async Task RunTopDownGridPointAsync(int number)
        {
            if (Busy || !CheckReadyForGrid()) return;

            Busy = true;
            try
            {
                bool ok = await MoveAndTriggerGridPointAsync(number).ConfigureAwait(true);
                if (!ok) _dialog.Warn($"Điểm {number}: di chuyển hoặc Flow TopDownCalib thất bại — kiểm tra lại.");
            }
            finally { Busy = false; }
        }

        /// <summary>
        /// Auto Calib — chạy hết 9 điểm theo thứ tự hình S của VisionMaster
        /// (<see cref="Routine_Calib.TopDownGridSOrder"/>), dừng ngay khi một điểm thất bại thay vì
        /// âm thầm bỏ qua rồi báo "xong" sai sự thật.
        /// </summary>
        private async Task RunAutoCalibAsync()
        {
            if (Busy || !CheckReadyForGrid()) return;

            // Mỗi lần chạy Flow TopDownCalib là module N-point nạp thêm một điểm. Chạy đè lên danh
            // sách cũ thì ra một ma trận trộn hai lần hiệu chuẩn mà không có cảnh báo nào.
            if (!_dialog.Confirm("Trước khi chạy: đã bấm \"Clear Point\" trong module N-point Calibration " +
                                 "(cột trái) để xoá danh sách điểm cũ chưa?\n\n" +
                                 "Mỗi lần kích Flow TopDownCalib là nạp thêm MỘT điểm — chạy chồng lên " +
                                 "danh sách cũ sẽ ra ma trận trộn hai lần hiệu chuẩn."))
                return;

            Busy = true;
            try
            {
                var order = Routine_Calib.TopDownGridSOrder;
                for (int i = 0; i < order.Length; i++)
                {
                    int number = order[i];
                    SequenceStatusText = $"Điểm {i + 1}/{order.Length} (numpad {number})…";

                    bool ok = await MoveAndTriggerGridPointAsync(number).ConfigureAwait(true);
                    if (!ok)
                    {
                        SequenceStatusText = $"Dừng tại điểm {i + 1} (numpad {number}).";
                        _dialog.Warn($"Auto Calib dừng tại điểm thứ {i + 1} (numpad {number}): di chuyển hoặc Flow TopDownCalib thất bại.");
                        return;
                    }
                }

                SequenceStatusText = "Đã nạp đủ 9 điểm.";
                _dialog.Info("Auto Calib hoàn tất — đã nạp đủ 9 điểm theo thứ tự hình S.\n\n" +
                             "Giờ sang module N-point Calibration (cột trái) bấm Calibrate rồi " +
                             "\"Create Calibration File\", sau đó quay lại đây chạy \"Kiểm tra top-down\".");
            }
            finally { Busy = false; }
        }

        /// <summary>Kích hoạt Flow TopDownCalib tại vị trí hiện tại — chụp lại một điểm lẻ.</summary>
        private async Task TriggerTopDownFlowAsync()
        {
            if (Busy) return;

            Busy = true;
            try
            {
                bool ok = await McControl.Calib.TriggerTopDownCalibFlowAsync(McControl.Safety.AbortToken).ConfigureAwait(true);
                _dialog.Info(ok
                    ? "Đã kích hoạt Flow TopDownCalib — báo tìm thấy. Lưu ý: điểm này ĐÃ được nạp vào danh sách hiệu chuẩn."
                    : "Đã kích hoạt Flow TopDownCalib — KHÔNG báo tìm thấy, kiểm tra dấu chuẩn/khung hình.");
            }
            finally { Busy = false; }
        }

        /// <summary>Kiểm tra hiệu chuẩn top-down bằng chuyển động trục thật (§6.2b).</summary>
        private async Task VerifyTopDownAsync()
        {
            if (Busy) return;
            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước."); return; }

            Busy = true;
            try
            {
                SequenceStatusText = "Đang kiểm tra top-down…";
                var r = await McControl.Calib
                    .VerifyTopDownAsync(TopDownVerifyStepMm, McControl.Safety.AbortToken)
                    .ConfigureAwait(true);

                SequenceStatusText = "";
                VerifyResultText = r.Ok
                    ? string.Format("Top-down ĐẠT (chạy {0:0.0} mm): lệch X {1:0.000}, Y {2:0.000} mm; lẫn trục {3:0.000}/{4:0.000} mm.",
                        r.StepMm, r.ErrorX, r.ErrorY, r.CrossX, r.CrossY)
                    : "Top-down KHÔNG ĐẠT: " + r.Reason;

                if (r.Ok) _dialog.Info(VerifyResultText);
                else _dialog.Warn(VerifyResultText);
            }
            finally { Busy = false; }
        }

        // ───────────────────────── hiệu chuẩn Align trong VisionMaster (§6.4) ─────────────────────────

        private double AlignPosXOfSelectedTool => McDataManager.Model.AlignPosX(SelectedTool);

        /// <summary>Chạy hết chuỗi nạp điểm: các vị trí X rồi các góc, cuối cùng đưa trục A về 0°.</summary>
        private async Task RunAlignCalibSequenceAsync()
        {
            if (Busy) return;
            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước khi hiệu chuẩn."); return; }

            double alignX = AlignPosXOfSelectedTool;
            if (Math.Abs(alignX) < 1e-9)
            {
                _dialog.Warn($"Chưa teach vị trí soi CAM bottom-up của tay #{SelectedTool} " +
                             "(trang Teaching, nút \"Teach tay #" + SelectedTool + "\") — chuỗi hiệu chuẩn sẽ chạy X về 0.");
                return;
            }

            var xOffsets = Sys.AlignCalibXOffsets();
            var angles = Sys.AlignCalibAngles();
            if (angles.Count < 3) { _dialog.Warn("Cần tối thiểu 3 góc xoay — sửa danh sách góc bên trên."); return; }

            if (!_dialog.Confirm($"Hút sẵn một sản phẩm mẫu lên tay #{SelectedTool} chưa, và đã bấm " +
                                 "\"Clear Point\" trong module hiệu chuẩn (cột trái) chưa?\n\n" +
                                 $"Chuỗi sẽ nạp {xOffsets.Count} điểm tịnh tiến + {angles.Count} điểm xoay, " +
                                 "rồi đưa trục A về 0° để chụp ảnh mẫu chuẩn."))
                return;

            Busy = true;
            try
            {
                var r = await McControl.Calib.RunAlignCalibSequenceAsync(
                    SelectedTool, alignX, xOffsets, angles,
                    msg => SequenceStatusText = msg,
                    McControl.Safety.AbortToken).ConfigureAwait(true);

                SequenceStatusText = r.Ok ? $"Đã nạp {r.PointsCaptured} điểm, trục A về 0°." : "Dừng giữa chừng.";

                if (r.Ok)
                    _dialog.Info($"Đã nạp đủ {r.PointsCaptured} điểm cho tay #{SelectedTool}, trục A đang ở 0°.\n\n" +
                                 "Tiếp theo trong VisionMaster (cột trái): Calibrate → Create Calibration File, " +
                                 "rồi chạy Flow AlignBottom_Tool" + SelectedTool + " một lần và bấm Create Reference " +
                                 "để dạy tư thế mẫu. Sau đó quay lại đây chạy \"Phép thử vòng xoay\".");
                else
                    _dialog.Warn($"Chuỗi hiệu chuẩn tay #{SelectedTool} dừng: {r.Reason} (đã nạp {r.PointsCaptured} điểm).");
            }
            finally { Busy = false; }
        }

        private async Task TriggerAlignCalibFlowAsync()
        {
            if (Busy) return;

            Busy = true;
            try
            {
                bool ok = await McControl.Calib.TriggerAlignCalibFlowAsync(SelectedTool, McControl.Safety.AbortToken).ConfigureAwait(true);
                _dialog.Info(ok
                    ? $"Đã kích hoạt Flow AlignCalib Tool{SelectedTool} — báo tìm thấy. Lưu ý: điểm này ĐÃ được nạp vào danh sách hiệu chuẩn."
                    : $"Đã kích hoạt Flow AlignCalib Tool{SelectedTool} — KHÔNG báo tìm thấy, kiểm tra sản phẩm/khung hình.");
            }
            finally { Busy = false; }
        }

        private async Task MoveAlignAxisToZeroAsync()
        {
            if (Busy) return;
            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước."); return; }

            Busy = true;
            try
            {
                bool ok = await McControl.Calib.MoveAlignAxisToZeroAsync(SelectedTool, McControl.Safety.AbortToken).ConfigureAwait(true);
                if (!ok) _dialog.Warn($"Không đưa được trục A của tay #{SelectedTool} về 0°.");
            }
            finally { Busy = false; }
        }

        /// <summary>
        /// Phép thử vòng xoay (§6.4b): đo dấu góc và kiểm tâm xoay/chiều hệ toạ độ của file hiệu
        /// chuẩn bottom-up. ĐẠT thì ghi dấu vào model, KHÔNG ĐẠT thì không ghi gì.
        /// </summary>
        private async Task VerifyAlignRotationAsync()
        {
            if (Busy) return;
            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước."); return; }

            double alignX = AlignPosXOfSelectedTool;
            double currentX = McControl.Motion[AxisId.X].CurrentPos;
            if (Math.Abs(currentX - alignX) > 0.05)
            {
                // Vị trí chụp lúc thử phải trùng vị trí chụp lúc chạy Auto, nếu không thì dấu đo
                // được đúng nhưng tâm xoay lại đo ở một chỗ khác (PDF Hikrobot tr.45).
                if (!_dialog.Confirm($"Trục X đang ở {currentX:0.000} nhưng vị trí soi của tay #{SelectedTool} " +
                                     $"là {alignX:0.000}. Chạy X tới vị trí soi rồi thử?"))
                    return;

                Busy = true;
                try
                {
                    if (!await McControl.Func.MoveAsync(AxisId.X, alignX, Sys.GetAxis(AxisId.X).MoveSpeed,
                            McControl.Safety.AbortToken).ConfigureAwait(true))
                    {
                        _dialog.Warn("Không chạy được X tới vị trí soi.");
                        return;
                    }
                }
                finally { Busy = false; }
            }

            Busy = true;
            try
            {
                SequenceStatusText = "Đang chạy phép thử vòng xoay…";
                var r = await McControl.Calib
                    .VerifyAlignRotationAsync(SelectedTool, AlignVerifyAngleDeg, McControl.Safety.AbortToken)
                    .ConfigureAwait(true);
                SequenceStatusText = "";

                if (!r.Ok)
                {
                    VerifyResultText = $"Vòng xoay tay #{SelectedTool} KHÔNG ĐẠT: {r.Reason}";
                    _dialog.Warn(VerifyResultText + "\n\nChưa ghi gì vào model.");
                    return;
                }

                Calib.SetAlignVerified(SelectedTool, r.Sign, r.PosX, r.ResidualMm, DateTime.Now);
                RefreshCalibText();

                VerifyResultText = string.Format(
                    "Vòng xoay tay #{0} ĐẠT: xoay {1:0.0}° → Flow báo {2:0.0}°, dấu {3}, sai số dư {4:0.000} mm (lệch tâm {5:0.000} mm).",
                    SelectedTool, r.TestAngleDeg, r.MeasuredDeltaThetaDeg, r.Sign > 0 ? "+1" : "−1",
                    r.ResidualMm, r.EccentricityMm);

                _dialog.Info(VerifyResultText +
                    (string.IsNullOrEmpty(r.Reason) ? "" : "\n\nLưu ý: " + r.Reason) +
                    "\n\nĐã ghi vào model — nhớ bấm Lưu model ở trang Teaching.");
            }
            finally { Busy = false; }
        }

        // ───────────────────────── hand-eye (§6.5) ─────────────────────────

        private double _handEyeCamX, _handEyeCamY;
        private int _handEyeMeasuredNozzle;

        private async Task MeasureHandEyeCameraAsync(int nozzle)
        {
            if (Busy) return;
            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước."); return; }

            Busy = true;
            try
            {
                var result = await McControl.Calib
                    .MeasureHandEyeCameraPosAsync(McControl.Safety.AbortToken)
                    .ConfigureAwait(true);

                if (!result.Ok)
                {
                    _dialog.Error("Không thấy dấu chuẩn: " + result.Reason);
                    return;
                }

                _handEyeCamX = result.CamX;
                _handEyeCamY = result.CamY;
                _handEyeMeasuredNozzle = nozzle;

                _dialog.Info(string.Format(
                    "Đã đo vị trí camera: ({0:0.000}, {1:0.000}). Giờ sang trang Manual, jog đầu hút #{2} " +
                    "chạm ĐÚNG dấu chuẩn đó, rồi quay lại đây bấm \"Ghi offset\".",
                    result.CamX, result.CamY, nozzle));
            }
            finally { Busy = false; }
        }

        private void CommitHandEye(int nozzle)
        {
            if (_handEyeMeasuredNozzle != nozzle)
            {
                _dialog.Warn($"Chưa đo vị trí camera cho tay #{nozzle} — bấm \"Đo vị trí camera\" trước.");
                return;
            }
            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc."); return; }

            double nozzleX = McControl.Motion[AxisId.X].CurrentPos;
            double nozzleY = McControl.Motion[AxisId.Y2].CurrentPos;
            double dx = nozzleX - _handEyeCamX;
            double dy = nozzleY - _handEyeCamY;

            Calib.SetHandEye(nozzle, dx, dy, DateTime.Now);

            _handEyeMeasuredNozzle = 0;
            RefreshCalibText();
            _dialog.Info($"Đã ghi hand-eye tay #{nozzle}: dx={dx:0.000}, dy={dy:0.000} mm — nhớ bấm Lưu model.");
        }

        // ───────────────────────── commands ─────────────────────────

        public ICommand TopDownPoint1Command { get; }
        public ICommand TopDownPoint2Command { get; }
        public ICommand TopDownPoint3Command { get; }
        public ICommand TopDownPoint4Command { get; }
        public ICommand TopDownPoint5Command { get; }
        public ICommand TopDownPoint6Command { get; }
        public ICommand TopDownPoint7Command { get; }
        public ICommand TopDownPoint8Command { get; }
        public ICommand TopDownPoint9Command { get; }
        public ICommand SaveCalibrationCenterCommand { get; }
        public ICommand AutoCalibCommand { get; }
        public ICommand TriggerTopDownFlowCommand { get; }
        public ICommand VerifyTopDownCommand { get; }

        public ICommand RunAlignCalibSequenceCommand { get; }
        public ICommand TriggerAlignCalibFlowCommand { get; }
        public ICommand AlignAxisToZeroCommand { get; }
        public ICommand VerifyAlignRotationCommand { get; }

        public ICommand MeasureHandEyeCommand { get; }
        public ICommand CommitHandEyeCommand { get; }
    }
}

