Log("===== TỰ KIỂM TRA — Shield CAN Assy MC =====");
Log("Thư mục dữ liệu: " + AppPaths.Root);
Log("");

// CHẨN ĐOÁN TẠM: ghi file ngay sau mỗi bài test (không đợi hết toàn bộ) — để nếu một
// bài bị treo thì vẫn xem được đã dừng ở bài nào, không phải đoán mò qua Task Manager.
var tests = new Action[]
{
    TestStartupState, TestZSafeInterlock, TestOriginSequence, TestEventAlarmsAlwaysResettable,
    TestEmergencyStop, TestLightCurtain, TestVacuumHoldsThroughEmg,
    TestHardwareAssumptions, TestResetRules, TestTrayGridMath, TestPlacementMath,
    TestVisionCalibMath, TestModelManagement, TestAxisScale, TestMoveIncrement,
    TestPlanarHomeRequiresZHomed, TestRoutineCalib,
    TestAutoCycle, TestAssyPreScan, TestResumeIntegrity, TestTrayChangeover,
    TestTwoHandGate, TestBrakeInterlock, TestEmergencyBrakeRelease
};

foreach (var t in tests)
{
    Log("[BẮT ĐẦU] " + t.Method.Name);
    FlushReport();
    t();
    FlushReport();
}

Log("");
Log($"===== KẾT QUẢ: {_pass} đạt, {_fail} không đạt =====");
FlushReport();

return _fail == 0 ? 0 : 1;

