562	        private static void TestVisionCalibMath()
563	        {
564	            Section("Toán hiệu chuẩn vision (fit affine, fit vòng tròn) — PLAN.md §6.1, §6.4");
565	
566	            // Bản đồ affine biết trước đáp số đúng: X = 2u + 0v + 5, Y = 0u + 3v − 1. Không
567	            // nhiễu, nên fit phải trả lại ĐÚNG các hệ số này và residual ≈ 0 — khoá lại đúng
568	            // công thức, không phải "chạy không lỗi".
569	            var pts = new List<Core.Controller.CalibPoint>
570	            {
571	                new Core.Controller.CalibPoint(0, 0, 5, -1),
572	                new Core.Controller.CalibPoint(10, 0, 25, -1),
573	                new Core.Controller.CalibPoint(0, 10, 5, 29),
574	                new Core.Controller.CalibPoint(10, 10, 25, 29),
575	                new Core.Controller.CalibPoint(5, 5, 15, 14),
576	                new Core.Controller.CalibPoint(-5, 8, -5, 23),
577	                new Core.Controller.CalibPoint(7, -3, 19, -10),
578	                new Core.Controller.CalibPoint(3, 12, 11, 35),
579	                new Core.Controller.CalibPoint(-8, -8, -11, -25),
580	            };
581	            var fit = Core.Controller.VisionCalibMath.FitAffine(pts);
582	            Check("FitAffine với dữ liệu sạch: Ok", fit.Ok, fit.Reason);
583	            Check("FitAffine ra đúng B11..B23",
584	                fit.Ok && Near(fit.Calib.B11, 2) && Near(fit.Calib.B12, 0) && Near(fit.Calib.B13, 5) &&
585	                Near(fit.Calib.B21, 0) && Near(fit.Calib.B22, 3) && Near(fit.Calib.B23, -1),
586	                fit.Ok ? $"B=({fit.Calib.B11:0.###},{fit.Calib.B12:0.###},{fit.Calib.B13:0.###}," +
587	                         $"{fit.Calib.B21:0.###},{fit.Calib.B22:0.###},{fit.Calib.B23:0.###})" : fit.Reason);
588	            Check("FitAffine dữ liệu sạch: RMS và max residual ≈ 0",
589	                fit.Ok && fit.RmsResidual < 1e-9 && fit.MaxResidual < 1e-9,
590	                fit.Ok ? $"RMS={fit.RmsResidual:E2}, max={fit.MaxResidual:E2}" : fit.Reason);
591	
592	            // Làm hỏng đúng MỘT điểm — residual của riêng điểm đó phải nổi hẳn lên, các điểm còn
593	            // lại vẫn gần 0. Đây là cơ chế "chỉ ra đúng điểm đo hỏng" mà PLAN §6.1 mô tả.
594	            var ptsBad = new List<Core.Controller.CalibPoint>(pts);
595	            ptsBad[4] = new Core.Controller.CalibPoint(5, 5, 15 + 5, 14);   // lệch 5 mm ở điểm thứ 5 (index 4)
596	            var fitBad = Core.Controller.VisionCalibMath.FitAffine(ptsBad);
597	            Check("FitAffine vẫn Ok khi có 1 điểm lệch (đủ điểm thừa để fit)", fitBad.Ok, fitBad.Reason);
598	            Check("Residual của đúng điểm hỏng nổi bật hẳn so với các điểm còn lại",
599	                fitBad.Ok && fitBad.PointResiduals[4] > 1.0 &&
600	                fitBad.PointResiduals.Where((r, i) => i != 4).All(r => r < fitBad.PointResiduals[4] / 2),
601	                fitBad.Ok ? string.Join(",", fitBad.PointResiduals.Select(r => r.ToString("0.00"))) : fitBad.Reason);
602	
603	            // Ba điểm thẳng hàng — ma trận suy biến, phải báo lỗi rõ ràng chứ không âm thầm ra
604	            // một ma trận vô nghĩa.
605	            var collinear = new List<Core.Controller.CalibPoint>
606	            {
607	                new Core.Controller.CalibPoint(0, 0, 0, 0),
608	                new Core.Controller.CalibPoint(1, 1, 1, 1),
609	                new Core.Controller.CalibPoint(2, 2, 2, 2),
610	            };
611	            Check("3 điểm thẳng hàng → suy biến, FitAffine từ chối",
612	                !Core.Controller.VisionCalibMath.FitAffine(collinear).Ok);
613	            Check("Dưới 3 điểm → FitAffine từ chối ngay",
614	                !Core.Controller.VisionCalibMath.FitAffine(pts.Take(2).ToList()).Ok);
615	
616	            // Vòng tròn biết trước đáp số đúng: tâm (3, −2), bán kính 5, lấy 6 góc như §6.4.
617	            var xs = new List<double>();
618	            var ys = new List<double>();
619	            foreach (double deg in new[] { 0.0, 60.0, 120.0, 180.0, 240.0, 300.0 })
620	            {
621	                double rad = deg * Math.PI / 180.0;
622	                xs.Add(3 + 5 * Math.Cos(rad));
623	                ys.Add(-2 + 5 * Math.Sin(rad));
