    var offset = new Core.Communication.VisionPose { Found = true, PixelX = 1.0, PixelY = 0, Angle = 0 };
    var target90 = new Core.Communication.VisionPose { Found = true, PixelX = 640, PixelY = 480, Angle = 90 };

    var sol90 = Core.Controller.PlacementSolver.Solve(calib, 1, offset, target90, 0, 0, 95, 3);
    Check("Xoay 90° thì độ lệch tâm 1 mm theo X quay thành 1 mm theo Y",
        sol90.Ok && Near(sol90.ErrX, 0) && Near(sol90.ErrY, 1.0),
        $"e = ({sol90.ErrX:0.###}, {sol90.ErrY:0.###})");
    Check("Lệnh X/Y2 trừ đi đúng lượng lệch tâm",
        Near(sol90.CommandX, 0 + calib.HandEye1Dx - sol90.ErrX) &&
        Near(sol90.CommandY, 0 + calib.HandEye1Dy - sol90.ErrY));

    // Vượt ngưỡng = vision đo nhầm vật, phải từ chối chứ không lao trục đi bù.
    var solLimit = Core.Controller.PlacementSolver.Solve(calib, 1, bottomCentered, target90, 0, 0, 15, 3);
    Check("Góc bù vượt ngưỡng thì từ chối", !solLimit.Ok, solLimit.Reason);

    var far = new Core.Communication.VisionPose { Found = true, PixelX = 10.0, PixelY = 0, Angle = 0 };
    var solFar = Core.Controller.PlacementSolver.Solve(calib, 1, far, topCentered, 0, 0, 15, 3);
    Check("Lượng bù vượt ngưỡng thì từ chối", !solFar.Ok, solFar.Reason);

    Check("Vision không tìm thấy thì từ chối, không tính bừa",
        !Core.Controller.PlacementSolver.Solve(calib, 1,
            Core.Communication.VisionPose.NotFound("thử"), topCentered, 0, 0, 15, 3).Ok);

    Check("Chuẩn hoá góc: 350° = −10°", Near(Core.Controller.PlacementSolver.NormalizeDeg(350), -10));
    Check("Chuẩn hoá góc: −350° = 10°", Near(Core.Controller.PlacementSolver.NormalizeDeg(-350), 10));

    // Đầu hút #2 phải dùng hand-eye riêng của nó, không dùng chung với #1.
    var sol2 = Core.Controller.PlacementSolver.Solve(calib, 2, bottomCentered, topCentered, 100, 200, 15, 3);
    Check("Tay #2 dùng hand-eye riêng",
        Near(sol2.CommandX, 100 + calib.HandEye2Dx) && !Near(calib.HandEye1Dx, calib.HandEye2Dx));

