private static void TestVisionCalibMath()
{
    Section("Toán hiệu chuẩn vision (fit affine, fit vòng tròn) — PLAN.md §6.1, §6.4");

    // Bản đồ affine biết trước đáp số đúng: X = 2u + 0v + 5, Y = 0u + 3v − 1. Không
    // nhiễu, nên fit phải trả lại ĐÚNG các hệ số này và residual ≈ 0 — khoá lại đúng
    // công thức, không phải "chạy không lỗi".
    var pts = new List<Core.Controller.CalibPoint>
    {
        new Core.Controller.CalibPoint(0, 0, 5, -1),
        new Core.Controller.CalibPoint(10, 0, 25, -1),
        new Core.Controller.CalibPoint(0, 10, 5, 29),
        new Core.Controller.CalibPoint(10, 10, 25, 29),
        new Core.Controller.CalibPoint(5, 5, 15, 14),
        new Core.Controller.CalibPoint(-5, 8, -5, 23),
        new Core.Controller.CalibPoint(7, -3, 19, -10),
        new Core.Controller.CalibPoint(3, 12, 11, 35),
        new Core.Controller.CalibPoint(-8, -8, -11, -25),
    };
    var fit = Core.Controller.VisionCalibMath.FitAffine(pts);
    Check("FitAffine với dữ liệu sạch: Ok", fit.Ok, fit.Reason);
    Check("FitAffine ra đúng B11..B23",
        fit.Ok && Near(fit.Calib.B11, 2) && Near(fit.Calib.B12, 0) && Near(fit.Calib.B13, 5) &&
        Near(fit.Calib.B21, 0) && Near(fit.Calib.B22, 3) && Near(fit.Calib.B23, -1),
        fit.Ok ? $"B=({fit.Calib.B11:0.###},{fit.Calib.B12:0.###},{fit.Calib.B13:0.###}," +
                 $"{fit.Calib.B21:0.###},{fit.Calib.B22:0.###},{fit.Calib.B23:0.###})" : fit.Reason);
    Check("FitAffine dữ liệu sạch: RMS và max residual ≈ 0",
        fit.Ok && fit.RmsResidual < 1e-9 && fit.MaxResidual < 1e-9,
        fit.Ok ? $"RMS={fit.RmsResidual:E2}, max={fit.MaxResidual:E2}" : fit.Reason);

    // Làm hỏng đúng MỘT điểm — residual của riêng điểm đó phải nổi hẳn lên, các điểm còn
    // lại vẫn gần 0. Đây là cơ chế "chỉ ra đúng điểm đo hỏng" mà PLAN §6.1 mô tả.
    var ptsBad = new List<Core.Controller.CalibPoint>(pts);
    ptsBad[4] = new Core.Controller.CalibPoint(5, 5, 15 + 5, 14);   // lệch 5 mm ở điểm thứ 5 (index 4)
    var fitBad = Core.Controller.VisionCalibMath.FitAffine(ptsBad);
    Check("FitAffine vẫn Ok khi có 1 điểm lệch (đủ điểm thừa để fit)", fitBad.Ok, fitBad.Reason);
    Check("Residual của đúng điểm hỏng nổi bật hẳn so với các điểm còn lại",
        fitBad.Ok && fitBad.PointResiduals[4] > 1.0 &&
        fitBad.PointResiduals.Where((r, i) => i != 4).All(r => r < fitBad.PointResiduals[4] / 2),
        fitBad.Ok ? string.Join(",", fitBad.PointResiduals.Select(r => r.ToString("0.00"))) : fitBad.Reason);

    // Ba điểm thẳng hàng — ma trận suy biến, phải báo lỗi rõ ràng chứ không âm thầm ra
    // một ma trận vô nghĩa.
    var collinear = new List<Core.Controller.CalibPoint>
    {
        new Core.Controller.CalibPoint(0, 0, 0, 0),
        new Core.Controller.CalibPoint(1, 1, 1, 1),
        new Core.Controller.CalibPoint(2, 2, 2, 2),
    };
    Check("3 điểm thẳng hàng → suy biến, FitAffine từ chối",
