    // Ma trận fit ra phải dùng lại được đúng qua CameraCalib.ToMm — đây là cầu nối sang
    // PlacementSolver, sai khớp nối này thì fit đúng cũng vô nghĩa.
    double checkX, checkY;
    fit.Calib.ToMm(5, 5, out checkX, out checkY);
