    // ── §6.2 CAM top-down: lưới 9 điểm bằng trục máy ──
    //
    // FakeVision KHÔNG mô phỏng quang học thật: pixel trả về là nhiễu ngẫu nhiên quanh
    // tâm ảnh, KHÔNG đổi theo vị trí trục thật sự đi tới. Vì vậy phép hồi quy ở đây chắc
    // chắn ra residual rất lớn — đây là hành vi ĐÚNG cần khoá lại (từ chối lưu một hiệu
    // chuẩn không nhất quán), không phải nhánh "đạt" của thuật toán. Nhánh "đạt" đã được
    // khoá riêng bằng dữ liệu tổng hợp sạch ở TestVisionCalibMath — bài này chỉ kiểm tra
    // ĐƯỜNG DÂY: trục di chuyển đúng, đủ số điểm, không crash, không treo, và ngưỡng chặn
    // hoạt động đúng khi dữ liệu tệ.
    double centerX = McControl.Motion[AxisId.X].CurrentPos;
    double centerY = McControl.Motion[AxisId.Y2].CurrentPos;

    var topDown = McControl.Calib.CalibrateTopDownAsync(centerX, centerY, CancellationToken.None)
        .GetAwaiter().GetResult();
    Check("CalibrateTopDownAsync chạy xong, không treo/crash", topDown != null);
    Check("Có kết quả fit affine (đủ 9 điểm đo được, ma trận không suy biến)",
        topDown.Fit != null && topDown.Fit.Ok, topDown.Fit?.Reason);
    Check("Fit đủ 9 sai số dư, một cho mỗi điểm lưới",
        topDown.Fit != null && topDown.Fit.Ok && topDown.Fit.PointResiduals.Length == 9);
    Check("Dữ liệu vision mô phỏng không khớp trục thật → RMS vượt ngưỡng → KHÔNG cho lưu",
        !topDown.Ok, "RMS=" + topDown.Fit?.RmsResidual);

    // ── §6.3 CAM bottom-up: checkerboard + đối chiếu chéo B3 ──
    //
    // Cùng lý do trên: OriginPixelU mô phỏng không đổi theo trục X thật, nên đối chiếu
    // chéo B3 phải PHÁT HIỆN ra sự không nhất quán và từ chối — đây là phép thử quan
    // trọng nhất của §6.3 (bắt sai cao độ đồ gá), nên hành vi "từ chối khi lệch" phải
    // đúng cả trên dữ liệu giả lẫn dữ liệu thật.
    double x0 = McControl.Motion[AxisId.X].CurrentPos;
    var bottomUp = McControl.Calib.CalibrateBottomUpAsync(x0, x0 + 20, CancellationToken.None)
        .GetAwaiter().GetResult();
    Check("CalibrateBottomUpAsync chạy xong, không treo/crash", bottomUp != null);
    Check("Đọc được scale từ bản chuẩn (công cụ VisionMaster mô phỏng)",
        bottomUp.Calib != null && bottomUp.ScaleFromBoard > 0);
    Check("Đối chiếu chéo B3 phát hiện lệch (vì pixel mô phỏng không gắn với trục thật) → từ chối",
        !bottomUp.CrossCheckOk, bottomUp.Reason);

    // ── §6.4 mới: hiệu chuẩn Align trực tiếp trong VisionMaster — App chỉ lo xoay trục A
    // + trigger Flow AlignCalibTool{N}, đúng khuôn nút numpad CAM top-down (§6.2) ──
    var a1 = McControl.Motion[AxisId.A1];
    bool alignCalibOk = McControl.Calib
        .MoveAndTriggerAlignCalibAsync(1, 60, CancellationToken.None)
        .GetAwaiter().GetResult();
    Check("MoveAndTriggerAlignCalibAsync xoay A1 tới đúng góc rồi trigger Flow AlignCalibTool1",
        alignCalibOk && Near(a1.CurrentPos, 60), $"A1={a1.CurrentPos:0.###}");

    bool alignCalibFlowOk = McControl.Calib
        .TriggerAlignCalibFlowAsync(1, CancellationToken.None)
        .GetAwaiter().GetResult();
    Check("TriggerAlignCalibFlowAsync trigger được Flow AlignCalibTool1 tại góc hiện tại, không xoay",
        alignCalibFlowOk && Near(a1.CurrentPos, 60), $"A1={a1.CurrentPos:0.###}");

    // ── §6.5 Hand-eye ──
    var heNoCalib = McControl.Calib
        .MeasureHandEyeCameraPosAsync(null, CancellationToken.None)
        .GetAwaiter().GetResult();
    Check("Chưa hiệu chuẩn CAM top-down thì MeasureHandEyeCameraPosAsync từ chối ngay",
        !heNoCalib.Ok && heNoCalib.Reason != null && heNoCalib.Reason.Contains("top-down"),
        heNoCalib.Reason);

    // Calib GIẢ (CameraCalib.CreateSimulation, giống ModelData.CreateSimulation dùng cho
    // toàn bộ chuỗi Auto mô phỏng) — chỉ cần "đã hiệu chuẩn" để MeasureHandEyeCameraPosAsync
    // không từ chối ngay ở bước kiểm tra IsCalibrated, không kỳ vọng số liệu khớp trục thật.
    var simCalib = Core.Data.Model.CameraCalib.CreateSimulation(30.0 / 1280.0, 640, 480);

    double beforeX = McControl.Motion[AxisId.X].CurrentPos;
    double beforeY = McControl.Motion[AxisId.Y2].CurrentPos;
    var he = McControl.Calib.MeasureHandEyeCameraPosAsync(simCalib, CancellationToken.None)
        .GetAwaiter().GetResult();
    Check("MeasureHandEyeCameraPosAsync (đã hiệu chuẩn top-down giả) tìm thấy dấu chuẩn",
        he.Ok, he.Reason);
    Check("Vị trí camera đo được gần vị trí trục hiện tại (tâm ảnh mô phỏng ≈ tâm khung hình)",
        he.Ok && Math.Abs(he.CamX - beforeX) < 2.0 && Math.Abs(he.CamY - beforeY) < 2.0,
        $"cam=({he.CamX:0.###},{he.CamY:0.###}) trục=({beforeX:0.###},{beforeY:0.###})");
}

input.new_string:
    // ── §6.2b Kiểm tra hiệu chuẩn CAM top-down bằng chuyển động trục thật ──
    //
    // FakeVision KHÔNG mô phỏng quang học: kết quả trả về là nhiễu ngẫu nhiên quanh 0,
    // KHÔNG đổi theo vị trí trục thật sự đi tới. Vì vậy phép kiểm tra ở đây chắc chắn
    // KHÔNG ĐẠT — và đó đúng là hành vi cần khoá lại: phép kiểm tra phải bắt được "số
    // Flow trả về không ăn khớp với quãng đường trục đã chạy". Công thức đúng của nhánh
    // "đạt" được khoá riêng bằng dữ liệu sạch ở TestSinglePointAlignMath.
    double x0 = McControl.Motion[AxisId.X].CurrentPos;
    double y0 = McControl.Motion[AxisId.Y2].CurrentPos;

    var td = McControl.Calib.VerifyTopDownAsync(5.0, CancellationToken.None).GetAwaiter().GetResult();
    Check("VerifyTopDownAsync chạy xong, không treo/crash", td != null);
    Check("Dữ liệu vision mô phỏng không gắn với trục thật → phép kiểm tra top-down TỪ CHỐI",
        td != null && !td.Ok, td?.Reason);
    Check("Kiểm tra xong thì trả trục X và Y2 về đúng vị trí ban đầu",
        Near(McControl.Motion[AxisId.X].CurrentPos, x0) && Near(McControl.Motion[AxisId.Y2].CurrentPos, y0),
        $"X={McControl.Motion[AxisId.X].CurrentPos:0.###} (đầu {x0:0.###}), Y2={McControl.Motion[AxisId.Y2].CurrentPos:0.###} (đầu {y0:0.###})");

    var tdSmall = McControl.Calib.VerifyTopDownAsync(0.1, CancellationToken.None).GetAwaiter().GetResult();
    Check("Quãng chạy thử quá nhỏ thì từ chối ngay, không chạy trục vô ích", !tdSmall.Ok, tdSmall.Reason);

    // ── §6.4 Chuỗi nạp điểm hiệu chuẩn Align: tịnh tiến X rồi xoay A, kết thúc ở 0° ──
    var a1 = McControl.Motion[AxisId.A1];
    double alignPosX = Core.Data.McDataManager.Model.AlignPosX(1);
    var seq = McControl.Calib.RunAlignCalibSequenceAsync(
        1, alignPosX, new List<double> { -1, 0, 1 }, new List<double> { 0, 60, 120 },
        null, CancellationToken.None).GetAwaiter().GetResult();

    Check("RunAlignCalibSequenceAsync chạy hết chuỗi trên FakeVision", seq.Ok, seq.Reason);
    Check("Nạp đúng số điểm đã yêu cầu (3 tịnh tiến + 3 góc)", seq.PointsCaptured == 6, seq.PointsCaptured.ToString());
    Check("Chuỗi kết thúc với trục A ở 0° — tư thế chuẩn để chụp ảnh mẫu, không đứng ở góc cuối",
        Near(a1.CurrentPos, 0), $"A1={a1.CurrentPos:0.###}");
    Check("Chuỗi kết thúc tại đúng vị trí soi của tay hút (PDF Hikrobot tr.45)",
        Near(McControl.Motion[AxisId.X].CurrentPos, alignPosX),
        $"X={McControl.Motion[AxisId.X].CurrentPos:0.###}, vị trí soi {alignPosX:0.###}");

    var seqFewAngles = McControl.Calib.RunAlignCalibSequenceAsync(
        1, alignPosX, new List<double> { 0 }, new List<double> { 0, 90 },
        null, CancellationToken.None).GetAwaiter().GetResult();
    Check("Dưới 3 góc xoay thì từ chối (VisionMaster cần tối thiểu 3 lần xoay)", !seqFewAngles.Ok, seqFewAngles.Reason);

    bool alignCalibOk = McControl.Calib
        .MoveAndTriggerAlignCalibAsync(1, 60, CancellationToken.None)
        .GetAwaiter().GetResult();
    Check("MoveAndTriggerAlignCalibAsync xoay A1 tới đúng góc rồi trigger Flow AlignCalibTool1",
        alignCalibOk && Near(a1.CurrentPos, 60), $"A1={a1.CurrentPos:0.###}");

    bool alignCalibFlowOk = McControl.Calib
        .TriggerAlignCalibFlowAsync(1, CancellationToken.None)
        .GetAwaiter().GetResult();
    Check("TriggerAlignCalibFlowAsync trigger được Flow AlignCalibTool1 tại góc hiện tại, không xoay",
        alignCalibFlowOk && Near(a1.CurrentPos, 60), $"A1={a1.CurrentPos:0.###}");

    bool toZeroOk = McControl.Calib.MoveAlignAxisToZeroAsync(1, CancellationToken.None)
        .GetAwaiter().GetResult();
    Check("MoveAlignAxisToZeroAsync đưa trục A về 0°", toZeroOk && Near(a1.CurrentPos, 0), $"A1={a1.CurrentPos:0.###}");

    // ── §6.4b Phép thử vòng xoay ──
    //
    // Lại cùng lý do: FakeVision trả góc ngẫu nhiên, không gắn với trục A thật, nên góc
    // đo được sẽ không khớp góc đã xoay → phải TỪ CHỐI. Quan trọng hơn cả kết quả: trục
    // phải được trả về đúng góc ban đầu kể cả khi phép thử không đạt.
    double a1Before = a1.CurrentPos;
    var av = McControl.Calib.VerifyAlignRotationAsync(1, 10.0, CancellationToken.None)
        .GetAwaiter().GetResult();
    Check("VerifyAlignRotationAsync chạy xong, không treo/crash", av != null);
    Check("Góc mô phỏng không gắn với trục thật → phép thử vòng xoay TỪ CHỐI, không ghi dấu bừa",
        av != null && !av.Ok, av?.Reason);
    Check("Thử xong thì trả trục A về đúng góc ban đầu", Near(a1.CurrentPos, a1Before),
        $"A1={a1.CurrentPos:0.###} (đầu {a1Before:0.###})");

    var avSmall = McControl.Calib.VerifyAlignRotationAsync(1, 0.2, CancellationToken.None)
        .GetAwaiter().GetResult();
    Check("Góc thử quá nhỏ thì từ chối ngay, không xoay trục vô ích", !avSmall.Ok, avSmall.Reason);

    // ── §6.5 Hand-eye ──
    double beforeX = McControl.Motion[AxisId.X].CurrentPos;
    double beforeY = McControl.Motion[AxisId.Y2].CurrentPos;
    var he = McControl.Calib.MeasureHandEyeCameraPosAsync(CancellationToken.None)
        .GetAwaiter().GetResult();
    Check("MeasureHandEyeCameraPosAsync tìm thấy dấu chuẩn qua Flow LocateMark", he.Ok, he.Reason);
    Check("Vị trí camera đo được = vị trí trục + lượng dịch Flow báo (mô phỏng dao động quanh 0)",
        he.Ok && Math.Abs(he.CamX - beforeX) < 2.0 && Math.Abs(he.CamY - beforeY) < 2.0,
        $"cam=({he.CamX:0.###},{he.CamY:0.###}) trục=({beforeX:0.###},{beforeY:0.###})");
}

