/// <summary>
/// Kết quả quét trước, theo chỉ số ô của <c>Run.AssyTray</c>. Chỉ giữ trong bộ nhớ — như
/// <see cref="_bottomPose"/>, tắt app giữa chừng thì mất, quét lại từ đầu cho an toàn thay
/// vì tin vào số đo của một phiên chạy trước không rõ máy đã dịch chuyển gì chưa.
///
/// <para><b>Chụp bằng mốc tay hút #1 cho MỌI ô, bất kể sau này tay nào đặt vào đó.</b> Đúng
/// theo công thức <see cref="PlacementSolver.Solve"/>: <c>targetX = captureX + tdx +
/// handEyeDx(tay đặt)</c> — <c>captureX + tdx</c> tự nó đã là toạ độ trục để TÂM CAM trùng
/// chi tiết đích, không phụ thuộc tay nào đứng đó lúc chụp; <c>handEyeDx</c> của tay THẬT
/// SỰ đặt mới quy đổi sang toạ độ của tay đó. Không cần quét riêng cho từng tay.</para>
/// </summary>
private readonly Dictionary<int, AssyCellScan> _assyScan = new Dictionary<int, AssyCellScan>();

/// <summary>Bỏ toàn bộ kết quả quét trước — gọi khi tray lắp ráp bị nạp lại/đổi mới, để
/// không lỡ dùng số đo của tray VẬT LÝ cũ cho tray mới đang nằm ở cùng chỉ số ô.</summary>
public void InvalidateAssyScan() { _assyScan.Clear(); }

public Routine_Auto(MotionConnect motion, McFunction func, McStatus status,
                    Func<SystemData> sys, Func<IVisionDevice> vision)
{
