6	<style>
7	  :root{
8	    --ink:#1a1f27; --ink-soft:#454c56; --muted:#6b7280;
9	    --paper:#f1f2ee; --panel:#ffffff; --panel-mock:#eef0ec; --stage:#e7eae4;
10	    --line:#d9dbd3; --line-strong:#c3c6bc;
