15	    --warn:#a8560c; --warn-soft:#fbeddb;
16	    --tool1:#b23a6b; --tool1-soft:#f7e6ed;
17	    --tool2:#1791b0; --tool2-soft:#e1f1f5;
18	    --shadow:0 1px 2px rgba(20,20,10,.06), 0 6px 16px rgba(20,20,10,.05);
19	    color-scheme: light;
20	  }
21	  @media (prefers-color-scheme: dark){
22	    :root:not([data-theme="light"]){
23	      --ink:#e9ebf0; --ink-soft:#c4c8d1; --muted:#9aa0ab;
24	      --paper:#12151a; --panel:#1a1e25; --panel-mock:#20252c; --stage:#171b21;
25	      --line:#2b3038; --line-strong:#3a4049;
26	      --accent:#e2952f; --accent-ink:#1a1206;
27	      --vision:#8ba4ec; --vision-soft:#1c2438;
28	      --teach:#5fc2b0; --teach-soft:#132723;
29	      --ok:#4fc97e; --ok-soft:#122a1c;
30	      --warn:#e2952f; --warn-soft:#2e2109;
31	      --tool1:#e8779f; --tool1-soft:#3a1f29;
32	      --tool2:#5fc2dd; --tool2-soft:#16262b;
33	      --shadow:0 1px 2px rgba(0,0,0,.4), 0 8px 20px rgba(0,0,0,.35);
34	      color-scheme: dark;
35	    }
36	  }
37	  :root[data-theme="dark"]{
38	    --ink:#e9ebf0; --ink-soft:#c4c8d1; --muted:#9aa0ab;
39	    --paper:#12151a; --panel:#1a1e25; --panel-mock:#20252c; --stage:#171b21;
40	    --line:#2b3038; --line-strong:#3a4049;
41	    --accent:#e2952f; --accent-ink:#1a1206;
