51	
52	  *{box-sizing:border-box;}
53	  body{
54	    margin:0; background:var(--paper); color:var(--ink);
55	    font-family:'Be Vietnam Pro', system-ui, sans-serif; font-size:15px; line-height:1.6;
56	  }
57	  .wrap{max-width:840px; margin:0 auto; padding:40px 20px 80px;}
58	  h1,h2,h3{margin:0; text-wrap:balance;}
59	  .mono{font-family:'JetBrains Mono', ui-monospace, monospace;}
60	
61	  /* ── header ── */
