256	        {
257	            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước khi hiệu chuẩn."); return false; }
258	            if (!CalibrationCenterSet) { _dialog.Warn("Chưa lưu Calibration Center Point — jog tới giữa khung hình rồi bấm Save trước."); return false; }
