262	        private async Task RunTopDownGridPointAsync(int number)
263	        {
264	            if (Busy || !CheckReadyForGrid()) return;
265	
266	            Busy = true;
267	            try
268	            {
269	                bool ok = await MoveAndTriggerGridPointAsync(number).ConfigureAwait(true);
270	                if (!ok) _dialog.Warn($"Điểm {number}: di chuyển hoặc Flow TopDownCalib thất bại — kiểm tra lại.");
