275	        /// <summary>
276	        /// Auto Calib — chạy hết 9 điểm theo thứ tự hình S của VisionMaster
277	        /// (<see cref="Routine_Calib.TopDownGridSOrder"/>), dừng ngay khi một điểm thất bại thay vì
278	        /// âm thầm bỏ qua rồi báo "xong" sai sự thật.
279	        /// </summary>
280	        private async Task RunAutoCalibAsync()
281	        {
282	            if (Busy || !CheckReadyForGrid()) return;
283	
284	            // Mỗi lần chạy Flow TopDownCalib là module N-point nạp thêm một điểm. Chạy đè lên danh
285	            // sách cũ thì ra một ma trận trộn hai lần hiệu chuẩn mà không có cảnh báo nào.
286	            if (!_dialog.Confirm("Trước khi chạy: đã bấm \"Clear Point\" trong module N-point Calibration " +
287	                                 "(cột trái) để xoá danh sách điểm cũ chưa?\n\n" +
288	                                 "Mỗi lần kích Flow TopDownCalib là nạp thêm MỘT điểm — chạy chồng lên " +
289	                                 "danh sách cũ sẽ ra ma trận trộn hai lần hiệu chuẩn."))
290	                return;
291	
292	            Busy = true;
293	            try
294	            {
295	                var order = Routine_Calib.TopDownGridSOrder;
296	                for (int i = 0; i < order.Length; i++)
297	                {
298	                    int number = order[i];
299	                    SequenceStatusText = $"Điểm {i + 1}/{order.Length} (numpad {number})…";
