301	                    bool ok = await MoveAndTriggerGridPointAsync(number).ConfigureAwait(true);
302	                    if (!ok)
303	                    {
304	                        SequenceStatusText = $"Dừng tại điểm {i + 1} (numpad {number}).";
305	                        _dialog.Warn($"Auto Calib dừng tại điểm thứ {i + 1} (numpad {number}): di chuyển hoặc Flow TopDownCalib thất bại.");
306	                        return;
307	                    }
308	                }
309	
310	                SequenceStatusText = "Đã nạp đủ 9 điểm.";
311	                _dialog.Info("Auto Calib hoàn tất — đã nạp đủ 9 điểm theo thứ tự hình S.\n\n" +
312	                             "Giờ sang module N-point Calibration (cột trái) bấm Calibrate rồi " +
313	                             "\"Create Calibration File\", sau đó quay lại đây chạy \"Kiểm tra top-down\".");
314	            }
315	            finally { Busy = false; }
316	        }
317	
318	        /// <summary>Kích hoạt Flow TopDownCalib tại vị trí hiện tại — chụp lại một điểm lẻ.</summary>
319	        private async Task TriggerTopDownFlowAsync()
320	        {
321	            if (Busy) return;
322	
323	            Busy = true;
324	            try
325	            {
326	                bool ok = await McControl.Calib.TriggerTopDownCalibFlowAsync(McControl.Safety.AbortToken).ConfigureAwait(true);
327	                _dialog.Info(ok
328	                    ? "Đã kích hoạt Flow TopDownCalib — báo tìm thấy. Lưu ý: điểm này ĐÃ được nạp vào danh sách hiệu chuẩn."
329	                    : "Đã kích hoạt Flow TopDownCalib — KHÔNG báo tìm thấy, kiểm tra dấu chuẩn/khung hình.");
330	            }
331	            finally { Busy = false; }
332	        }
333	
334	        /// <summary>Kiểm tra hiệu chuẩn top-down bằng chuyển động trục thật (§6.2b).</summary>
335	        private async Task VerifyTopDownAsync()
336	        {
337	            if (Busy) return;
338	            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước."); return; }
339	
340	            Busy = true;
341	            try
342	            {
343	                SequenceStatusText = "Đang kiểm tra top-down…";
344	                var r = await McControl.Calib
345	                    .VerifyTopDownAsync(TopDownVerifyStepMm, McControl.Safety.AbortToken)
346	                    .ConfigureAwait(true);
347	
348	                SequenceStatusText = "";
349	                VerifyResultText = r.Ok
350	                    ? string.Format("Top-down ĐẠT (chạy {0:0.0} mm): lệch X {1:0.000}, Y {2:0.000} mm; lẫn trục {3:0.000}/{4:0.000} mm.",
351	                        r.StepMm, r.ErrorX, r.ErrorY, r.CrossX, r.CrossY)
352	                    : "Top-down KHÔNG ĐẠT: " + r.Reason;
353	
354	                if (r.Ok) _dialog.Info(VerifyResultText);
355	                else _dialog.Warn(VerifyResultText);
356	            }
357	            finally { Busy = false; }
358	        }
359	
360	        // ───────────────────────── hiệu chuẩn Align trong VisionMaster (§6.4) ─────────────────────────
361	
362	        private double AlignPosXOfSelectedTool => McDataManager.Model.AlignPosX(SelectedTool);
363	
364	        /// <summary>Chạy hết chuỗi nạp điểm: các vị trí X rồi các góc, cuối cùng đưa trục A về 0°.</summary>
365	        private async Task RunAlignCalibSequenceAsync()
366	        {
367	            if (Busy) return;
368	            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước khi hiệu chuẩn."); return; }
369	
370	            double alignX = AlignPosXOfSelectedTool;
371	            if (Math.Abs(alignX) < 1e-9)
372	            {
373	                _dialog.Warn($"Chưa teach vị trí soi CAM bottom-up của tay #{SelectedTool} " +
374	                             "(trang Teaching, nút \"Teach tay #" + SelectedTool + "\") — chuỗi hiệu chuẩn sẽ chạy X về 0.");
375	                return;
376	            }
377	
378	            var xOffsets = Sys.AlignCalibXOffsets();
379	            var angles = Sys.AlignCalibAngles();
380	            if (angles.Count < 3) { _dialog.Warn("Cần tối thiểu 3 góc xoay — sửa danh sách góc bên trên."); return; }
381	
382	            if (!_dialog.Confirm($"Hút sẵn một sản phẩm mẫu lên tay #{SelectedTool} chưa, và đã bấm " +
383	                                 "\"Clear Point\" trong module hiệu chuẩn (cột trái) chưa?\n\n" +
384	                                 $"Chuỗi sẽ nạp {xOffsets.Count} điểm tịnh tiến + {angles.Count} điểm xoay, " +
385	                                 "rồi đưa trục A về 0° để chụp ảnh mẫu chuẩn."))
386	                return;
387	
388	            Busy = true;
389	            try
390	            {
391	                var r = await McControl.Calib.RunAlignCalibSequenceAsync(
392	                    SelectedTool, alignX, xOffsets, angles,
393	                    msg => SequenceStatusText = msg,
394	                    McControl.Safety.AbortToken).ConfigureAwait(true);
395	
396	                SequenceStatusText = r.Ok ? $"Đã nạp {r.PointsCaptured} điểm, trục A về 0°." : "Dừng giữa chừng.";
397	
398	                if (r.Ok)
399	                    _dialog.Info($"Đã nạp đủ {r.PointsCaptured} điểm cho tay #{SelectedTool}, trục A đang ở 0°.\n\n" +
400	                                 "Tiếp theo trong VisionMaster (cột trái): Calibrate → Create Calibration File, " +
401	                                 "rồi chạy Flow AlignBottom_Tool" + SelectedTool + " một lần và bấm Create Reference " +
402	                                 "để dạy tư thế mẫu. Sau đó quay lại đây chạy \"Phép thử vòng xoay\".");
403	                else
404	                    _dialog.Warn($"Chuỗi hiệu chuẩn tay #{SelectedTool} dừng: {r.Reason} (đã nạp {r.PointsCaptured} điểm).");
405	            }
406	            finally { Busy = false; }
407	        }
408	
409	        private async Task TriggerAlignCalibFlowAsync()
410	        {
411	            if (Busy) return;
412	
413	            Busy = true;
414	            try
415	            {
416	                bool ok = await McControl.Calib.TriggerAlignCalibFlowAsync(SelectedTool, McControl.Safety.AbortToken).ConfigureAwait(true);
417	                _dialog.Info(ok
418	                    ? $"Đã kích hoạt Flow AlignCalib Tool{SelectedTool} — báo tìm thấy. Lưu ý: điểm này ĐÃ được nạp vào danh sách hiệu chuẩn."
419	                    : $"Đã kích hoạt Flow AlignCalib Tool{SelectedTool} — KHÔNG báo tìm thấy, kiểm tra sản phẩm/khung hình.");
420	            }
421	            finally { Busy = false; }
422	        }
423	
424	        private async Task MoveAlignAxisToZeroAsync()
425	        {
426	            if (Busy) return;
427	            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước."); return; }
428	
429	            Busy = true;
430	            try
431	            {
432	                bool ok = await McControl.Calib.MoveAlignAxisToZeroAsync(SelectedTool, McControl.Safety.AbortToken).ConfigureAwait(true);
433	                if (!ok) _dialog.Warn($"Không đưa được trục A của tay #{SelectedTool} về 0°.");
434	            }
435	            finally { Busy = false; }
436	        }
437	
438	        /// <summary>
439	        /// Phép thử vòng xoay (§6.4b): đo dấu góc và kiểm tâm xoay/chiều hệ toạ độ của file hiệu
440	        /// chuẩn bottom-up. ĐẠT thì ghi dấu vào model, KHÔNG ĐẠT thì không ghi gì.
441	        /// </summary>
442	        private async Task VerifyAlignRotationAsync()
443	        {
444	            if (Busy) return;
445	            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước."); return; }
446	
447	            double alignX = AlignPosXOfSelectedTool;
448	            double currentX = McControl.Motion[AxisId.X].CurrentPos;
449	            if (Math.Abs(currentX - alignX) > 0.05)
450	            {
451	                // Vị trí chụp lúc thử phải trùng vị trí chụp lúc chạy Auto, nếu không thì dấu đo
452	                // được đúng nhưng tâm xoay lại đo ở một chỗ khác (PDF Hikrobot tr.45).
453	                if (!_dialog.Confirm($"Trục X đang ở {currentX:0.000} nhưng vị trí soi của tay #{SelectedTool} " +
454	                                     $"là {alignX:0.000}. Chạy X tới vị trí soi rồi thử?"))
455	                    return;
456	
457	                Busy = true;
458	                try
459	                {
460	                    if (!await McControl.Func.MoveAsync(AxisId.X, alignX, Sys.GetAxis(AxisId.X).MoveSpeed,
461	                            McControl.Safety.AbortToken).ConfigureAwait(true))
462	                    {
463	                        _dialog.Warn("Không chạy được X tới vị trí soi.");
464	                        return;
465	                    }
466	                }
467	                finally { Busy = false; }
468	            }
469	
470	            Busy = true;
471	            try
472	            {
473	                SequenceStatusText = "Đang chạy phép thử vòng xoay…";
474	                var r = await McControl.Calib
475	                    .VerifyAlignRotationAsync(SelectedTool, AlignVerifyAngleDeg, McControl.Safety.AbortToken)
476	                    .ConfigureAwait(true);
477	                SequenceStatusText = "";
478	
479	                if (!r.Ok)
480	                {
481	                    VerifyResultText = $"Vòng xoay tay #{SelectedTool} KHÔNG ĐẠT: {r.Reason}";
482	                    _dialog.Warn(VerifyResultText + "\n\nChưa ghi gì vào model.");
483	                    return;
484	                }
485	
486	                Calib.SetAlignVerified(SelectedTool, r.Sign, r.PosX, r.ResidualMm, DateTime.Now);
487	                RefreshCalibText();
488	
489	                VerifyResultText = string.Format(
490	                    "Vòng xoay tay #{0} ĐẠT: xoay {1:0.0}° → Flow báo {2:0.0}°, dấu {3}, sai số dư {4:0.000} mm (lệch tâm {5:0.000} mm).",
491	                    SelectedTool, r.TestAngleDeg, r.MeasuredDeltaThetaDeg, r.Sign > 0 ? "+1" : "−1",
492	                    r.ResidualMm, r.EccentricityMm);
493	
494	                _dialog.Info(VerifyResultText +
495	                    (string.IsNullOrEmpty(r.Reason) ? "" : "\n\nLưu ý: " + r.Reason) +
496	                    "\n\nĐã ghi vào model — nhớ bấm Lưu model ở trang Teaching.");
497	            }
498	            finally { Busy = false; }
499	        }
500	
501	        // ───────────────────────── hand-eye (§6.5) ─────────────────────────
502	
503	        private double _handEyeCamX, _handEyeCamY;
504	        private int _handEyeMeasuredNozzle;
505	
506	        private async Task MeasureHandEyeCameraAsync(int nozzle)
507	        {
508	            if (Busy) return;
509	            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc — chạy Origin trước."); return; }
510	
511	            Busy = true;
512	            try
513	            {
514	                var result = await McControl.Calib
515	                    .MeasureHandEyeCameraPosAsync(McControl.Safety.AbortToken)
516	                    .ConfigureAwait(true);
517	
518	                if (!result.Ok)
519	                {
520	                    _dialog.Error("Không thấy dấu chuẩn: " + result.Reason);
521	                    return;
522	                }
523	
524	                _handEyeCamX = result.CamX;
525	                _handEyeCamY = result.CamY;
526	                _handEyeMeasuredNozzle = nozzle;
527	
528	                _dialog.Info(string.Format(
529	                    "Đã đo vị trí camera: ({0:0.000}, {1:0.000}). Giờ sang trang Manual, jog đầu hút #{2} " +
530	                    "chạm ĐÚNG dấu chuẩn đó, rồi quay lại đây bấm \"Ghi offset\".",
531	                    result.CamX, result.CamY, nozzle));
532	            }
533	            finally { Busy = false; }
534	        }
535	
536	        private void CommitHandEye(int nozzle)
537	        {
538	            if (_handEyeMeasuredNozzle != nozzle)
539	            {
540	                _dialog.Warn($"Chưa đo vị trí camera cho tay #{nozzle} — bấm \"Đo vị trí camera\" trước.");
541	                return;
542	            }
543	            if (!McControl.Status.OrgOk) { _dialog.Warn("Chưa về gốc."); return; }
544	
545	            double nozzleX = McControl.Motion[AxisId.X].CurrentPos;
546	            double nozzleY = McControl.Motion[AxisId.Y2].CurrentPos;
547	            double dx = nozzleX - _handEyeCamX;
548	            double dy = nozzleY - _handEyeCamY;
549	
550	            Calib.SetHandEye(nozzle, dx, dy, DateTime.Now);
551	
552	            _handEyeMeasuredNozzle = 0;
553	            RefreshCalibText();
554	            _dialog.Info($"Đã ghi hand-eye tay #{nozzle}: dx={dx:0.000}, dy={dy:0.000} mm — nhớ bấm Lưu model.");
555	        }
556	
