1	using System;
2	using System.Collections.Generic;
3	using System.Threading;
4	using System.Threading.Tasks;
5	using ShieldCanAssy.Core.Communication;
6	using ShieldCanAssy.Core.Data;
7	using ShieldCanAssy.Core.Data.Model;
8	using ShieldCanAssy.Core.Infor;
9	using ShieldCanAssy.Utility.Log;
10	
11	namespace ShieldCanAssy.Core.Controller
12	{
13	    /// <summary>Kết quả phép kiểm tra hiệu chuẩn CAM top-down (§6.2b).</summary>
14	    public class TopDownVerifyResult
15	    {
16	        public bool Ok { get; set; }
17	        public string Reason { get; set; }
18	
19	        /// <summary>Quãng đường đã chạy thử, mm.</summary>
20	        public double StepMm { get; set; }
21	
22	        /// <summary>Sai lệch thang đo: (lượng Flow báo) − (lượng trục đã chạy), mm. 0 là hoàn hảo.</summary>
23	        public double ErrorX { get; set; }
24	        public double ErrorY { get; set; }
25	
26	        /// <summary>Lẫn trục: chạy X mà Flow báo dịch theo Y (và ngược lại), mm.</summary>
27	        public double CrossX { get; set; }
28	        public double CrossY { get; set; }
29	
30	        /// <summary>Dấu của từng trục có đúng không — sai dấu là đặt lệch gấp đôi, không phải lệch ít.</summary>
31	        public bool SignXOk { get; set; }
32	        public bool SignYOk { get; set; }
33	    }
34	
35	    /// <summary>Kết quả phép thử vòng xoay của một tay hút (§6.4b).</summary>
36	    public class AlignVerifyResult
37	    {
38	        public bool Ok { get; set; }
39	        public string Reason { get; set; }
40	
41	        /// <summary>Dấu quy đổi góc VisionMaster → trục A: +1, −1, hoặc 0 nếu không kết luận được.</summary>
42	        public int Sign { get; set; }
43	
44	        /// <summary>Góc đã xoay thử, độ.</summary>
45	        public double TestAngleDeg { get; set; }
46	
47	        /// <summary>Góc Flow PlaceAlign trả về cho phép thử, độ.</summary>
48	        public double MeasuredDeltaThetaDeg { get; set; }
49	
50	        /// <summary>Sai số dư: lượng dịch còn lại sau khi quay về, mm. Khác 0 nghĩa là tâm xoay
51	        /// hoặc chiều hệ toạ độ (handedness) trong file hiệu chuẩn bottom-up chưa đúng.</summary>
52	        public double ResidualMm { get; set; }
53	
54	        /// <summary>Độ lệch tâm của sản phẩm lúc thử, mm — quá nhỏ thì phép thử không kết luận
55	        /// được về tâm xoay.</summary>
56	        public double EccentricityMm { get; set; }
57	
58	        /// <summary>Vị trí trục X lúc thử — phải trùng vị trí soi lúc chạy Auto.</summary>
59	        public double PosX { get; set; }
60	    }
61	
62	    /// <summary>Kết quả chuỗi nạp điểm hiệu chuẩn Align (§6.4).</summary>
63	    public class AlignCalibSequenceResult
64	    {
65	        public bool Ok { get; set; }
66	        public string Reason { get; set; }
67	        public int PointsCaptured { get; set; }
68	    }
69	
70	    public class HandEyeMeasurement
71	    {
72	        public bool Ok { get; set; }
73	        public string Reason { get; set; }
74	
75	        /// <summary>Vị trí trục (X, Y2) nơi tâm ảnh CAM top-down trùng dấu chuẩn.</summary>
76	        public double CamX { get; set; }
77	        public double CamY { get; set; }
78	    }
79	
80	    /// <summary>
81	    /// Hiệu chuẩn vision — PLAN.md §6.
82	    ///
83	    /// <para><b>App không còn tự fit ma trận nào</b> (Tuấn chốt 2026-09-12). Phép hiệu chuẩn làm
84	    /// trong VisionMaster (N-point cho CAM top-down, hiệu chuẩn có xoay cho CAM bottom-up), App
85	    /// chỉ còn ba việc mà VisionMaster không tự làm được vì nó không điều khiển trục:</para>
86	    /// <list type="number">
87	    /// <item><b>Nạp điểm</b>: chạy trục tới từng vị trí/góc rồi kích Flow hiệu chuẩn — mỗi lần
88	    /// chạy Flow là module hiệu chuẩn nạp thêm một điểm (chế độ Trigger Acquisition).</item>
89	    /// <item><b>Kiểm tra lại</b> kết quả hiệu chuẩn bằng chuyển động trục thật: sai thang đo, sai
90	    /// dấu, lẫn trục, sai tâm xoay đều lộ ra ở đây chứ không lộ trong VisionMaster — VisionMaster
91	    /// chỉ biết ảnh, không biết trục đã đi bao xa.</item>
92	    /// <item><b>Đo hand-eye</b> (§6.5) — hiệu toạ độ trục, VisionMaster không đọc được encoder.</item>
93	    /// </list>
94	    ///
95	    /// <para>Lớp này không giữ trạng thái <c>VisionCalib</c> nào: mọi hàm nhận tham số và trả kết
96	    /// quả để trang Vision Edit cho operator XEM rồi mới quyết định ghi vào model — "không đạt →
97	    /// không cho lưu" (§6.1) là quyết định của người, không phải của routine.</para>
98	    /// </summary>
99	    public class Routine_Calib
100	    {
101	        private readonly MotionConnect _motion;
102	        private readonly McFunction _func;
103	        private readonly Func<SystemData> _sys;
104	        private readonly Func<IVisionDevice> _vision;
105	
106	        public Routine_Calib(MotionConnect motion, McFunction func, Func<SystemData> sys, Func<IVisionDevice> vision)
107	        {
108	            _motion = motion;
109	            _func = func;
110	            _sys = sys;
111	            _vision = vision;
112	        }
113	
114	        // ───────────────────────── §6.2 CAM top-down: lưới 9 điểm ─────────────────────────
115	
116	        /// <summary>
117	        /// Thứ tự chạy 9 điểm của "Auto Calib", theo số trên bàn phím numpad.
118	        ///
119	        /// <para>Hình chữ S, KHÔNG phải quét dòng: module N-point của VisionMaster tự sinh toạ độ
120	        /// vật lý cho các điểm theo quỹ đạo chữ S (Help "Physical Coordinate Parameters", tham số
121	        /// Movement First + Commutation Number). Chạy theo thứ tự dòng 1→9 thì điểm thứ 4 và thứ 6
122	        /// của App rơi vào đúng chỗ ngược với điểm thứ 4 và thứ 6 mà VisionMaster giả định — ma
123	        /// trận vẫn fit ra được, chỉ méo, và không có thông báo lỗi nào cả.</para>
124	        /// </summary>
125	        public static readonly int[] TopDownGridSOrder = { 1, 2, 3, 6, 5, 4, 7, 8, 9 };
126	
127	        /// <summary>Di chuyển tới (x, y2) rồi kích hoạt Flow TopDownCalib — mỗi lần gọi là nạp một
128	        /// điểm vào module N-point. Trả về false nếu di chuyển thất bại hoặc Flow báo không tìm thấy.</summary>
129	        public async Task<bool> MoveAndTriggerTopDownCalibAsync(double x, double y2, CancellationToken ct)
130	        {
131	            if (!await _func.MoveToCellAsync(AxisId.Y2, y2, x, ct).ConfigureAwait(false))
132	                return false;
133	
134	            var pose = await _vision().TriggerAsync(EVisionProcedure.TopDownCalib, ct).ConfigureAwait(false);
135	            return pose.Found;
136	        }
137	
138	        /// <summary>Kích hoạt Flow TopDownCalib tại vị trí hiện tại, không di chuyển — chụp lại một
139	        /// điểm lẻ. <b>Cũng nạp thêm một điểm</b> vào module N-point, không phải nút "test vô hại".</summary>
140	        public async Task<bool> TriggerTopDownCalibFlowAsync(CancellationToken ct)
141	        {
142	            var pose = await _vision().TriggerAsync(EVisionProcedure.TopDownCalib, ct).ConfigureAwait(false);
143	            return pose.Found;
144	        }
145	
146	        // ───────────────────────── §6.2b Kiểm tra hiệu chuẩn CAM top-down ─────────────────────────
147	
148	        /// <summary>
149	        /// Soi dấu chuẩn, chạy trục X đúng <paramref name="stepMm"/>, soi lại; rồi làm y hệt với
150	        /// trục Y2. Flow LocateMark phải báo lượng dịch ĐÚNG BẰNG quãng đường trục đã chạy và
151	        /// NGƯỢC DẤU (trục chạy tới thì vật lùi lại trong hệ của camera).
152	        ///
153	        /// <para>Đây là phép kiểm tra duy nhất bắt được ba lỗi mà bản thân VisionMaster không thể
154	        /// tự phát hiện: sai thang đo (nhập sai bước lưới lúc hiệu chuẩn), <b>sai dấu</b> (khai
155	        /// nhầm Camera Mode giữa "Dynamic Camera" và "Camera Stationary", hoặc nhập toạ độ vật lý
156	        /// ngược chiều trục), và lẫn trục X ↔ Y.</para>
157	        /// </summary>
158	        public async Task<TopDownVerifyResult> VerifyTopDownAsync(double stepMm, CancellationToken ct)
159	        {
160	            var result = new TopDownVerifyResult { StepMm = stepMm };
161	            try
162	            {
163	                if (Math.Abs(stepMm) < 0.5)
164	                {
165	                    result.Reason = "quãng đường thử quá nhỏ — nhiễu đo sẽ lớn hơn thứ cần đo";
166	                    return result;
167	                }
168	
169	                var sys = _sys();
170	                int shots = sys.CalibShotsPerPoint;
171	                double x0 = _motion[AxisId.X]?.CurrentPos ?? 0;
172	                double y0 = _motion[AxisId.Y2]?.CurrentPos ?? 0;
173	
174	                var p0 = await CaptureAveragedAsync(EVisionProcedure.LocateMark, shots, ct).ConfigureAwait(false);
175	                if (!p0.Found) { result.Reason = p0.Error ?? "không thấy dấu chuẩn ở vị trí xuất phát"; return result; }
176	
177	                // ── trục X ──
178	                if (!await MoveAsync(AxisId.X, x0 + stepMm, ct).ConfigureAwait(false))
179	                { result.Reason = "không chạy được trục X"; return result; }
180	
181	                var px = await CaptureAveragedAsync(EVisionProcedure.LocateMark, shots, ct).ConfigureAwait(false);
182	                await MoveAsync(AxisId.X, x0, ct).ConfigureAwait(false);
183	                if (!px.Found) { result.Reason = px.Error ?? "không thấy dấu chuẩn sau khi chạy X — dấu ra khỏi khung hình?"; return result; }
184	
185	                // ── trục Y2 ──
186	                if (!await MoveAsync(AxisId.Y2, y0 + stepMm, ct).ConfigureAwait(false))
187	                { result.Reason = "không chạy được trục Y2"; return result; }
188	
189	                var py = await CaptureAveragedAsync(EVisionProcedure.LocateMark, shots, ct).ConfigureAwait(false);
190	                await MoveAsync(AxisId.Y2, y0, ct).ConfigureAwait(false);
191	                if (!py.Found) { result.Reason = py.Error ?? "không thấy dấu chuẩn sau khi chạy Y2 — dấu ra khỏi khung hình?"; return result; }
192	
193	                // Kỳ vọng: (lượng Flow báo) = −(quãng đường trục đã chạy).
194	                double dxOnX = px.X - p0.X;
195	                double dyOnX = px.Y - p0.Y;
196	                double dyOnY = py.Y - p0.Y;
197	                double dxOnY = py.X - p0.X;
198	
199	                result.ErrorX = dxOnX + stepMm;
200	                result.CrossX = dyOnX;
201	                result.ErrorY = dyOnY + stepMm;
202	                result.CrossY = dxOnY;
203	                result.SignXOk = dxOnX < 0;
204	                result.SignYOk = dyOnY < 0;
205	
206	                double tol = sys.CalibMaxResidualThresholdMm;
207	                if (!result.SignXOk || !result.SignYOk)
208	                {
209	                    result.Reason = string.Format(
210	                        "SAI DẤU: chạy +{0:0.0} mm mà Flow báo X {1:+0.000;-0.000}, Y {2:+0.000;-0.000} mm " +
211	                        "(phải cùng âm) — kiểm tra Camera Mode của module N-point (top-down là Dynamic Camera) " +
212	                        "và chiều toạ độ vật lý đã nhập",
213	                        stepMm, dxOnX, dyOnY);
214	                    return result;
215	                }
216	
217	                result.Ok = Math.Abs(result.ErrorX) <= tol && Math.Abs(result.ErrorY) <= tol &&
218	                            Math.Abs(result.CrossX) <= tol && Math.Abs(result.CrossY) <= tol;
219	                if (!result.Ok)
220	                    result.Reason = string.Format(
221	                        "lệch thang đo X {0:0.000} mm, Y {1:0.000} mm; lẫn trục {2:0.000}/{3:0.000} mm — vượt ngưỡng {4:0.000} mm",
222	                        result.ErrorX, result.ErrorY, result.CrossX, result.CrossY, tol);
223	
224	                LogWorker.Instance.RecordLog(
225	                    string.Format("Kiểm tra CAM top-down (chạy {0:0.0} mm): lệch X {1:0.000}, Y {2:0.000}, lẫn trục {3:0.000}/{4:0.000} mm — {5}",
226	                        stepMm, result.ErrorX, result.ErrorY, result.CrossX, result.CrossY, result.Ok ? "ĐẠT" : "KHÔNG ĐẠT"),
227	                    result.Ok ? Utility.Log.LogLevel.Info : Utility.Log.LogLevel.Warning, "Calib");
228	
229	                return result;
230	            }
231	            catch (OperationCanceledException)
232	            {
233	                result.Reason = "bị huỷ";
234	                return result;
235	            }
236	            catch (Exception ex)
237	            {
238	                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
239	                result.Reason = "lỗi bất thường: " + ex.Message;
240	                return result;
241	            }
242	        }
