246	        /// <summary>
247	        /// Chạy hết chuỗi nạp điểm cho module hiệu chuẩn bottom-up của tay
248	        /// <paramref name="nozzle"/>: trước hết các vị trí X lệch so với vị trí soi (phần tịnh
249	        /// tiến), sau đó các góc của trục A tại đúng vị trí soi (phần xoay), mỗi bước kích Flow
250	        /// AlignCalib_ToolN một lần.
251	        ///
252	        /// <para><b>Kết thúc bằng việc đưa trục A về 0°</b>: bước tiếp theo của quy trình là chụp
253	        /// ảnh mẫu chuẩn (Create Reference trong Flow runtime), mà mẫu chuẩn phải ở đúng tư thế
254	        /// chuẩn — bỏ trục A đứng ở góc cuối của dãy (300°) rồi teach là mốc lệch nguyên một góc,
255	        /// và Auto sẽ loại mọi sản phẩm vì |Δθ| vượt ngưỡng.</para>
256	        /// </summary>
257	        public async Task<AlignCalibSequenceResult> RunAlignCalibSequenceAsync(
258	            int nozzle, double alignPosX, IList<double> xOffsets, IList<double> anglesDeg,
259	            Action<string> progress, CancellationToken ct)
260	        {
261	            var result = new AlignCalibSequenceResult();
262	            try
263	            {
264	                string axisName = nozzle == 1 ? AxisId.A1 : AxisId.A2;
265	                var proc = nozzle == 1 ? EVisionProcedure.AlignCalibTool1 : EVisionProcedure.AlignCalibTool2;
266	
267	                if (anglesDeg == null || anglesDeg.Count < 3)
268	                {
269	                    result.Reason = "cần tối thiểu 3 góc xoay (VisionMaster đòi các bước xoay bằng nhau)";
270	                    return result;
271	                }
272	
273	                // Phần tịnh tiến chụp ở MỘT góc cố định — góc đầu của dãy. Vừa xoay vừa tịnh tiến
274	                // thì module hiệu chuẩn không tách được hai thành phần.
275	                double firstAngle = anglesDeg[0];
276	                if (!await MoveAsync(axisName, firstAngle, ct).ConfigureAwait(false))
277	                { result.Reason = "không xoay được trục " + axisName + " về góc đầu"; return result; }
278	
279	                if (xOffsets != null)
280	                {
281	                    for (int i = 0; i < xOffsets.Count; i++)
282	                    {
283	                        double x = alignPosX + xOffsets[i];
284	                        if (progress != null) progress(string.Format("Tịnh tiến {0}/{1}: X = {2:0.000}", i + 1, xOffsets.Count, x));
285	
286	                        if (!await MoveAsync(AxisId.X, x, ct).ConfigureAwait(false))
287	                        { result.Reason = string.Format("không chạy được X tới {0:0.000}", x); return result; }
288	
289	                        var pose = await _vision().TriggerAsync(proc, ct).ConfigureAwait(false);
290	                        if (!pose.Found)
291	                        { result.Reason = string.Format("điểm tịnh tiến X = {0:0.000} không tìm thấy sản phẩm", x); return result; }
292	                        result.PointsCaptured++;
293	                    }
294	                }
295	
296	                // Phần xoay: luôn tại ĐÚNG vị trí soi của tay này — chạy thật cũng dừng ở đó
297	                // (PDF Hikrobot tr.45: vị trí chụp lúc chạy phải trùng vị trí chụp lúc hiệu chuẩn).
298	                if (!await MoveAsync(AxisId.X, alignPosX, ct).ConfigureAwait(false))
299	                { result.Reason = "không chạy được X về vị trí soi"; return result; }
300	
301	                for (int i = 0; i < anglesDeg.Count; i++)
302	                {
303	                    double angle = anglesDeg[i];
304	                    if (progress != null) progress(string.Format("Góc {0}/{1}: {2:0.0}°", i + 1, anglesDeg.Count, angle));
305	
306	                    if (!await MoveAsync(axisName, angle, ct).ConfigureAwait(false))
307	                    { result.Reason = string.Format("không xoay được tới {0:0.0}°", angle); return result; }
308	
309	                    var pose = await _vision().TriggerAsync(proc, ct).ConfigureAwait(false);
310	                    if (!pose.Found)
311	                    { result.Reason = string.Format("góc {0:0.0}° không tìm thấy sản phẩm — mở rộng Angle Range của High Precision Match?", angle); return result; }
312	                    result.PointsCaptured++;
313	                }
314	
315	                if (!await MoveAsync(axisName, 0, ct).ConfigureAwait(false))
316	                { result.Reason = "đã nạp đủ điểm nhưng không đưa được trục " + axisName + " về 0°"; return result; }
317	
318	                result.Ok = true;
319	                LogWorker.Instance.RecordLog(
320	                    string.Format("Hiệu chuẩn Align tay #{0}: đã nạp {1} điểm, trục A về 0°", nozzle, result.PointsCaptured),
321	                    Utility.Log.LogLevel.Info, "Calib");
322	                return result;
323	            }
324	            catch (OperationCanceledException)
325	            {
326	                result.Reason = "bị huỷ";
327	                return result;
328	            }
329	            catch (Exception ex)
330	            {
331	                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
332	                result.Reason = "lỗi bất thường: " + ex.Message;
333	                return result;
334	            }
335	        }
