370	        // ───────────────────────── §6.4b Phép thử vòng xoay ─────────────────────────
371	
372	        /// <summary>
373	        /// Hút sẵn một sản phẩm, đứng tại vị trí soi: đo tư thế, xoay trục A thêm
374	        /// <paramref name="testAngleDeg"/>, đo lại, rồi hỏi chính Flow PlaceAlign "muốn đưa sản
375	        /// phẩm về tư thế ban đầu thì phải làm gì".
376	        ///
377	        /// <para>Câu trả lời đúng là "xoay ngược lại đúng bấy nhiêu độ và KHÔNG cần dịch gì cả".
378	        /// Phép thử này vì vậy cho ra hai thứ cùng lúc:</para>
379	        /// <list type="bullet">
380	        /// <item><b>Dấu góc</b> — VisionMaster tính theo chiều kim đồng hồ dương, trục A của máy
381	        /// quy ước ngược lại (§11 #6); dấu đo được ghi vào model thay vì suy đoán.</item>
382	        /// <item><b>Sai số dư</b> — lượng dịch còn lại phải bằng 0. Khác 0 nghĩa là gốc toạ độ của
383	        /// file hiệu chuẩn bottom-up không nằm đúng tâm xoay, hoặc chiều hệ toạ độ bị lật (camera
384	        /// nhìn từ dưới lên là ảnh gương). Đây là cách duy nhất bắt được hai lỗi đó trước khi máy
385	        /// đặt lệch hàng loạt.</item>
386	        /// </list>
387	        /// </summary>
388	        public async Task<AlignVerifyResult> VerifyAlignRotationAsync(int nozzle, double testAngleDeg, CancellationToken ct)
389	        {
390	            var result = new AlignVerifyResult { TestAngleDeg = testAngleDeg };
391	            try
392	            {
393	                var sys = _sys();
394	                string axisName = nozzle == 1 ? AxisId.A1 : AxisId.A2;
395	                var proc = nozzle == 1 ? EVisionProcedure.AlignBottomTool1 : EVisionProcedure.AlignBottomTool2;
396	
397	                if (Math.Abs(testAngleDeg) < 1.0)
398	                { result.Reason = "góc thử quá nhỏ — nhiễu đo sẽ lớn hơn thứ cần đo"; return result; }
399	                if (_motion[axisName] == null)
400	                { result.Reason = "không có trục " + axisName; return result; }
401	
402	                result.PosX = _motion[AxisId.X]?.CurrentPos ?? 0;
403	                double a0 = _motion[axisName].CurrentPos;
404	                int shots = sys.CalibShotsPerPoint;
405	
406	                var p0 = await CaptureAveragedAsync(proc, shots, ct).ConfigureAwait(false);
407	                if (!p0.Found) { result.Reason = p0.Error ?? "không thấy sản phẩm ở góc xuất phát"; return result; }
408	
409	                if (!await MoveAsync(axisName, a0 + testAngleDeg, ct).ConfigureAwait(false))
410	                { result.Reason = "không xoay được trục " + axisName; return result; }
411	
412	                var p1 = await CaptureAveragedAsync(proc, shots, ct).ConfigureAwait(false);
413	                await MoveAsync(axisName, a0, ct).ConfigureAwait(false);
414	                if (!p1.Found) { result.Reason = p1.Error ?? "không thấy sản phẩm sau khi xoay — mở rộng Angle Range của High Precision Match?"; return result; }
415	
416	                // Hỏi VisionMaster: đưa tư thế SAU khi xoay về lại tư thế TRƯỚC khi xoay.
417	                var align = await _vision().TriggerPlaceAlignAsync(new PlaceAlignInput
418	                {
419	                    TargetX = p0.X, TargetY = p0.Y, TargetAngle = p0.Angle,
420	                    ObjectX = p1.X, ObjectY = p1.Y, ObjectAngle = p1.Angle
421	                }, ct).ConfigureAwait(false);
422	
423	                if (align == null || !align.Ok)
424	                { result.Reason = "Flow PlaceAlign không tính được" + (align == null ? "" : ": " + align.Error); return result; }
425	
426	                result.MeasuredDeltaThetaDeg = align.DeltaThetaDeg;
427	                result.ResidualMm = Math.Sqrt(align.DeltaX * align.DeltaX + align.DeltaY * align.DeltaY);
428	                result.EccentricityMm = Math.Sqrt(p0.X * p0.X + p0.Y * p0.Y);
429	
430	                double measured = Math.Abs(align.DeltaThetaDeg);
431	                double tolDeg = sys.AlignVerifyAngleTolDeg;
432	                if (Math.Abs(measured - Math.Abs(testAngleDeg)) > tolDeg)
433	                {
434	                    result.Reason = string.Format(
435	                        "xoay thử {0:0.0}° nhưng Flow báo {1:0.0}° — lệch quá {2:0.0}°: sai đơn vị góc, sai mẫu khớp, hoặc trục A chưa đúng tỉ lệ xung/độ",
436	                        testAngleDeg, align.DeltaThetaDeg, tolDeg);
437	                    return result;
438	                }
439	
440	                // Xoay +α thì muốn quay lại phải xoay −α. VisionMaster trả Δθ theo chiều của nó;
441	                // dấu cần tìm là dấu biến Δθ đó thành lệnh cho trục A.
442	                result.Sign = align.DeltaThetaDeg > 0 ? -1 : +1;
443	
444	                double tolMm = sys.CalibMaxResidualThresholdMm;
445	                if (result.ResidualMm > tolMm)
446	                {
447	                    result.Reason = string.Format(
448	                        "sai số dư {0:0.000} mm > ngưỡng {1:0.000} mm — gốc toạ độ của file hiệu chuẩn bottom-up " +
449	                        "không nằm đúng tâm xoay, hoặc chiều hệ toạ độ bị lật (camera nhìn từ dưới lên là ảnh gương)",
450	                        result.ResidualMm, tolMm);
451	                    return result;
452	                }
453	
454	                if (result.EccentricityMm < 0.5)
455	                {
456	                    result.Reason = string.Format(
457	                        "sản phẩm gần trùng tâm xoay ({0:0.000} mm) — dấu góc đo được vẫn dùng được, nhưng phép thử " +
458	                        "KHÔNG kết luận được về tâm xoay/chiều hệ toạ độ. Hút lệch sản phẩm ra rồi thử lại để kiểm cả hai.",
459	                        result.EccentricityMm);
460	                }
461	
462	                result.Ok = true;
463	                LogWorker.Instance.RecordLog(
464	                    string.Format("Phép thử vòng xoay tay #{0}: xoay {1:0.0}°, Flow báo {2:0.0}° → dấu {3}, sai số dư {4:0.000} mm (lệch tâm {5:0.000} mm)",
465	                        nozzle, testAngleDeg, align.DeltaThetaDeg, result.Sign > 0 ? "+1" : "−1", result.ResidualMm, result.EccentricityMm),
466	                    Utility.Log.LogLevel.Info, "Calib");
467	
468	                return result;
469	            }
470	            catch (OperationCanceledException)
471	            {
472	                result.Reason = "bị huỷ";
473	                return result;
474	            }
475	            catch (Exception ex)
476	            {
477	                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
478	                result.Reason = "lỗi bất thường: " + ex.Message;
479	                return result;
480	            }
481	        }
