485	        /// <summary>
486	        /// Nửa đầu của phép đo hand-eye (PLAN.md §6.5): soi dấu chuẩn bằng CAM top-down (Flow
487	        /// LocateMark), trả về vị trí trục (X, Y2) nơi tâm ảnh trùng dấu chuẩn đó. Nửa sau — đưa
488	        /// đầu hút chạm đúng dấu chuẩn rồi đọc vị trí trục — là thao tác tay, trang Vision Edit đọc
489	        /// thẳng <c>CurrentPos</c> giống các nút Teach khác.
490	        ///
491	        /// <para>Dùng <b>LocateMark</b> chứ không phải LocateTop: mẫu của LocateTop là chi tiết
492	        /// thật trong ô tray, soi dấu chuẩn bằng nó thì không khớp. Cũng không dùng TopDownCalib vì
493	        /// mỗi lần chạy Flow đó là nạp thêm một điểm hiệu chuẩn.</para>
494	        /// </summary>
495	        public async Task<HandEyeMeasurement> MeasureHandEyeCameraPosAsync(CancellationToken ct)
496	        {
497	            try
498	            {
499	                var pose = await CaptureAveragedAsync(EVisionProcedure.LocateMark, _sys().CalibShotsPerPoint, ct).ConfigureAwait(false);
500	                if (!pose.Found)
501	                    return new HandEyeMeasurement { Ok = false, Reason = pose.Error ?? "không thấy dấu chuẩn" };
502	
503	                // Flow trả về lượng phải dịch trục để tâm ảnh trùng dấu chuẩn, nên vị trí camera
504	                // "nhìn thẳng" dấu chuẩn chính là vị trí trục hiện tại cộng lượng đó.
505	                return new HandEyeMeasurement
506	                {
507	                    Ok = true,
508	                    CamX = (_motion[AxisId.X]?.CurrentPos ?? 0) + pose.X,
509	                    CamY = (_motion[AxisId.Y2]?.CurrentPos ?? 0) + pose.Y
510	                };
511	            }
512	            catch (OperationCanceledException)
513	            {
514	                return new HandEyeMeasurement { Ok = false, Reason = "bị huỷ" };
515	            }
516	            catch (Exception ex)
517	            {
518	                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
519	                return new HandEyeMeasurement { Ok = false, Reason = "lỗi bất thường: " + ex.Message };
520	            }
521	        }
