531	        private async Task<VisionPose> CaptureAveragedAsync(EVisionProcedure proc, int shots, CancellationToken ct)
532	        {
533	            var vision = _vision();
534	            double sumX = 0, sumY = 0, sumA = 0;
535	            int ok = 0;
536	
537	            for (int i = 0; i < shots; i++)
538	            {
539	                if (ct.IsCancellationRequested) return VisionPose.NotFound("bị huỷ");
540	
541	                var p = await vision.TriggerAsync(proc, ct).ConfigureAwait(false);
542	                if (!p.Found) return VisionPose.NotFound(p.Error ?? "không tìm thấy đối tượng");
543	
544	                sumX += p.X;
545	                sumY += p.Y;
546	                sumA += p.Angle;
547	                ok++;
548	            }
549	
550	            if (ok == 0) return VisionPose.NotFound("không chụp được lần nào");
551	
552	            // PLAN §6.1 quy tắc 4: mỗi điểm chụp N ảnh, lấy trung bình để khử nhiễu đo.
553	            return new VisionPose { Found = true, X = sumX / ok, Y = sumY / ok, Angle = sumA / ok, Score = 1.0 };
554	        }
555	    }
556	}
