85	            if (!IsSolutionLoaded) return VisionPose.NotFound("chưa nạp solution");
86	
87	            var names = _sys.VisionOutputs;
88	            string flow;
89	            switch (procedure)
90	            {
91	                case EVisionProcedure.TopDownCalib: flow = names.FlowTopDownCalib; break;
92	                case EVisionProcedure.LocateMark: flow = names.FlowLocateMark; break;
93	                case EVisionProcedure.AlignBottomTool1: flow = names.FlowAlignBottomTool1; break;
