  /* ── figure ── */
  .figure{margin:18px 0 0; background:var(--stage); border-top:1px solid var(--line); border-bottom:1px solid var(--line); padding:14px 18px 12px;}
  .fig-cap-top{
    font-family:'JetBrains Mono',monospace; font-size:10.5px; font-weight:700;
    letter-spacing:.08em; text-transform:uppercase; color:var(--muted); margin-bottom:6px;
  }
  .fig-svg{display:block; width:100%; height:auto; max-width:520px; margin:0 auto;}
  .fig-cap{font-size:12.5px; color:var(--muted); margin:8px auto 0; max-width:56ch; text-align:center;}

  /* SVG dùng chung */
  .fig-svg .body{fill:var(--panel); stroke:var(--line-strong); stroke-width:1.4;}
  .fig-svg .solid{fill:var(--ink-soft);}
  .fig-svg .lens{fill:var(--vision-soft); stroke:var(--vision); stroke-width:1.6;}
