  .fig-svg .mid{text-anchor:middle;}
  .fig-svg .ground{fill:var(--line);}

  /* ── steps ── */
  .proc-body{padding:18px 22px 22px;}
  ol.steps{margin:0; padding:0 0 0 0; list-style:none; counter-reset:s;}
  ol.steps > li{
    counter-increment:s; position:relative; padding:0 0 14px 40px; font-size:14.5px; color:var(--ink-soft);
  }
  ol.steps > li::before{
    content:counter(s); position:absolute; left:0; top:1px;
    width:25px; height:25px; border-radius:50%;
    background:var(--panel-mock); border:1px solid var(--line-strong); color:var(--ink);
    font-family:'JetBrains Mono',monospace; font-weight:700; font-size:12px;
