        <g class="f1-plate">
          <rect x="96" y="44" width="128" height="18" rx="2" class="body"/>
          <rect x="96" y="44" width="16" height="18" class="solid"/>
          <rect x="128" y="44" width="16" height="18" class="solid"/>
