1	using System;
2	using ShieldCanAssy.Core.Communication;
3	using ShieldCanAssy.Core.Data.Model;
4	
5	namespace ShieldCanAssy.Core.Controller
6	{
7	    /// <summary>Toạ độ đích của một lần đặt — đã quy về hệ toạ độ LỆNH TRỤC của máy.</summary>
8	    public struct PlaceTarget
9	    {
10	        /// <summary>Toạ độ lệnh trục X để tâm xoay của tay hút trùng tâm chi tiết đích.</summary>
11	        public double X;
12	
13	        /// <summary>Toạ độ lệnh trục Y2 (tray lắp ráp), cùng ý nghĩa.</summary>
14	        public double Y;
15	
16	        /// <summary>Góc chi tiết đích, độ, trong hệ vật lý của file hiệu chuẩn top-down.</summary>
17	        public double AngleDeg;
18	    }
19	
20	    /// <summary>Kết quả tính điểm đặt cho một sản phẩm.</summary>
21	    public class PlaceSolution
22	    {
23	        public bool Ok { get; set; }
24	        public string Reason { get; set; }
25	
26	        /// <summary>Góc phải xoay thêm cho trục A của tay hút này, độ, ĐÃ đổi sang chiều dương
27	        /// của trục A (VisionMaster trả theo chiều kim đồng hồ dương).</summary>
28	        public double DeltaThetaDeg { get; set; }
29	
30	        /// <summary>Toạ độ lệnh cho trục X và trục Y của tray lắp ráp (Y2).</summary>
31	        public double CommandX { get; set; }
32	        public double CommandY { get; set; }
33	
34	        /// <summary>Độ lệch tâm sản phẩm so với trục xoay SAU KHI xoay — phần VisionMaster đã trừ
35	        /// sẵn khỏi lệnh. Giữ lại để hiện lên UI và để chặn ngưỡng, không dùng để tính lệnh.</summary>
36	        public double ErrX { get; set; }
37	        public double ErrY { get; set; }
38	        public double ErrDistance { get { return Math.Sqrt(ErrX * ErrX + ErrY * ErrY); } }
39	
40	        public static PlaceSolution Fail(string why)
41	        {
42	            return new PlaceSolution { Ok = false, Reason = why };
43	        }
44	    }
45	
46	    /// <summary>
47	    /// Ghép kết quả hai camera thành lệnh đặt — PLAN.md §6.6.
48	    ///
49	    /// <para><b>Phép tính bù nay nằm trong VisionMaster</b> (Tuấn chốt 2026-09-12): Flow
50	    /// <c>PlaceAlign</c> dùng module <i>Single Point Alignment</i> để tính Δθ và lệnh X/Y2, kể cả
51	    /// phần "tâm sản phẩm dịch đi do xoay". App KHÔNG còn tự nhân <c>R(Δθ)·p</c> nữa — làm cả hai
52	    /// nơi là bù hai lần (PDF Hikrobot tr.35, tr.60). Phần còn lại của lớp này chỉ là ba việc mà
53	    /// VisionMaster không biết:</para>
54	    /// <list type="number">
55	    /// <item><b>Dựng toạ độ đích</b> từ vị trí trục lúc chụp + kết quả LocateTop + hand-eye —
56	    /// VisionMaster không đọc được encoder nên không tự cộng được (<see cref="BuildTarget"/>).</item>
57	    /// <item><b>Đổi dấu góc</b> từ quy ước VisionMaster (chiều kim đồng hồ dương) sang chiều dương
58	    /// của trục A (ngược chiều kim đồng hồ, §11 #6). Dấu này ĐO bằng phép thử vòng xoay
59	    /// (<c>Routine_Calib.VerifyAlignRotationAsync</c>) rồi ghi vào model, không suy đoán.</item>
60	    /// <item><b>Chặn ngưỡng</b> trước khi phát lệnh: vượt ngưỡng nghĩa là vision đo nhầm vật.</item>
61	    /// </list>
