142	        public VisionRunResult RunAndGetFloatsWithImage(string flowName, string imageOutputName, params string[] outputNames)
143	        {
144	            var pro = GetProcedure(flowName);
145	
146	            bool wantImage = !string.IsNullOrEmpty(imageOutputName);
147	            if (wantImage) pro.EnableResultCallback();
148	
149	            pro.Run();
150	
151	            var moduResult = pro.ModuResult;
152	            float[] results = ReadFloats(pro, flowName, outputNames);
153	
154	            Bitmap image = null;
155	            if (wantImage)
156	            {
157	                try
158	                {
159	                    var imgData = moduResult.GetOutputImageV2(imageOutputName);
160	                    if (imgData != null) image = imgData.ToBitmap();
