                                         params string[] outputNames)
{
    return RunWithInputsAndGetFloatsWithImage(flowName, inputs, null, outputNames).Floats;
}

/// <summary>
/// Gán input của Flow rồi chạy, đọc cả output float lẫn ảnh của đúng lần chạy đó.
///
/// <para>Đây là đường dùng cho <b>Flow hiệu chuẩn</b> (<c>TopDownCalib</c>,
/// <c>AlignCalib_ToolN</c>): module hiệu chuẩn của VisionMaster ở chế độ <i>Trigger
/// Acquisition</i> + <i>Calibration Points Input = By Coordinate</i> nhận toạ độ vật lý của
/// từng điểm qua <i>Physical Coordinate X/Y</i> và <i>World Rotate Angle</i> — ba thứ này
/// subscribe vào input của Flow, và App gán chúng ngay trước mỗi lần Run.</para>
///
/// <para>Không làm vậy thì VisionMaster phải tự sinh toạ độ vật lý từ bước lưới khai sẵn,
/// tức là tin rằng trục đã đi ĐÚNG BẰNG lượng lệnh — trái với PLAN.md §6.1 quy tắc 3 (ghi
/// <c>ActualPosition</c> đọc từ encoder). Tài liệu Hikrobot "Calibration and Locating
/// Theory" tr.18 cũng nói rõ: nạp điểm theo giao thức truyền thông thì <b>mọi quỹ đạo của
/// máy đều dùng được</b>, không bắt buộc hình S và không bắt buộc lưới 2 chiều — đúng thứ
/// máy này cần vì CAM bottom-up chỉ có chuyển động theo X.</para>
/// </summary>
public VisionRunResult RunWithInputsAndGetFloatsWithImage(string flowName,
                                                          IDictionary<string, float> inputs,
                                                          string imageOutputName,
                                                          params string[] outputNames)
{
    var pro = GetProcedure(flowName);
    ApplyInputs(pro, inputs);

    bool wantImage = !string.IsNullOrEmpty(imageOutputName);
    if (wantImage) pro.EnableResultCallback();

    pro.Run();

    float[] results = ReadFloats(pro, flowName, outputNames);
    return new VisionRunResult { Floats = results, Image = wantImage ? TryReadImage(pro, imageOutputName) : null };
}

/// <summary>
/// Gán input float của Flow — giá trị <b>chỉ có hiệu lực cho lần chạy này</b>
/// (<c>CModuleParamBase.SetInputFloat</c>), không để lại trạng thái trong solution.
///
/// <para><b>Sai tên input thì SDK không báo lỗi</b> (<c>SetInputFloat</c> trả void) — Flow
/// vẫn chạy, chỉ là dùng giá trị cũ. Vì vậy tên nào không có trong danh sách input thật của
/// Flow sẽ bị ném lỗi ngay tại đây thay vì âm thầm nạp một điểm hiệu chuẩn sai.</para>
/// </summary>
private static void ApplyInputs(VmProcedure pro, IDictionary<string, float> inputs)
{
    if (inputs == null || inputs.Count == 0) return;

    var declared = GetInputNames(pro);
    foreach (var kv in inputs)
    {
        if (string.IsNullOrEmpty(kv.Key)) continue;

        if (declared != null && declared.Count > 0 && !declared.Contains(kv.Key))
            throw new VmException(-1, "Flow \"" + pro.Name + "\" không có input \"" + kv.Key +
                "\" — tab Input Params của Flow đang khai: " + string.Join(", ", declared.ToArray()));

        pro.ModuParams.SetInputFloat(kv.Key, new[] { kv.Value });
    }
}

/// <summary>Tên các input đã khai ở tab "Input Params" của Flow. Trả về danh sách rỗng nếu
/// SDK không đọc được — khi đó <see cref="ApplyInputs"/> bỏ qua bước đối chiếu tên thay vì
/// chặn cả phép hiệu chuẩn.</summary>
public List<string> GetFlowInputNames(string flowName)
{
    return GetInputNames(GetProcedure(flowName));
}

private static List<string> GetInputNames(VmProcedure pro)
{
    var names = new List<string>();
    try
    {
        var infos = pro.ModuParams.GetAllInputNameInfo();
        if (infos == null) return names;
        foreach (var info in infos)
        {
            if (info == null) continue;
            string s = info.ToString();
            if (!string.IsNullOrEmpty(s)) names.Add(s);
        }
    }
    catch
    {
        // Không đọc được danh sách input thì thôi — đối chiếu tên chỉ là lớp bảo vệ thêm.
        names.Clear();
    }
    return names;
}

