/// <summary>
/// Đọc tên input của Flow qua <c>ProcedureParam.GetAllInputNameInfo()</c>.
///
/// <para>Kiểu phần tử (<c>VmDynamicIODefine.IoNameInfo</c>) <b>không được tài liệu SDK mô
/// tả</b> — không có trang nào cho nó trong guide.chm — nên không thể gọi thẳng thuộc tính
/// tên. Ở đây dò bằng reflection một thành viên kiểu chuỗi; không tìm thấy thì trả danh
/// sách RỖNG để phép đối chiếu tên tự tắt. Thà không kiểm còn hơn chặn nhầm một phép hiệu
/// chuẩn đúng vì đọc sai kiểu dữ liệu.</para>
/// </summary>
private static List<string> GetInputNames(VmProcedure pro)
{
    var names = new List<string>();
    try
    {
        var infos = pro.ModuParams.GetAllInputNameInfo();
        if (infos == null) return names;

        foreach (var info in infos)
        {
            if (info == null) continue;
            string s = ExtractName(info);
            if (!string.IsNullOrEmpty(s)) names.Add(s);
        }
    }
    catch
    {
        names.Clear();
    }
    return names;
}

private static readonly string[] NameMemberCandidates = { "strName", "Name", "strIoName", "IoName", "strInputName" };

private static string ExtractName(object info)
{
    var type = info.GetType();
    foreach (string candidate in NameMemberCandidates)
    {
        var prop = type.GetProperty(candidate);
        if (prop != null && prop.PropertyType == typeof(string))
            return prop.GetValue(info, null) as string;

        var field = type.GetField(candidate);
        if (field != null && field.FieldType == typeof(string))
            return field.GetValue(info) as string;
    }
    return null;
}

