using System.ComponentModel;
using System.Threading;
using System.Threading.Tasks;

namespace ShieldCanAssy.Core.Communication
{
    /// <summary>
    /// Kết quả một lần chụp: tư thế đối tượng, ĐÃ QUY ĐỔI RA mm/độ trong hệ vật lý của file hiệu
    /// chuẩn VisionMaster.
    ///
    /// <para><b>Không Flow nào còn trả pixel thô</b> (Tuấn chốt 2026-09-12): mọi Flow "đo tư thế"
    /// đều kết thúc bằng module <i>Calibration Transformation</i> của VisionMaster, nên App không
    /// giữ ma trận hiệu chuẩn camera nào nữa (khác hẳn bản trước có <c>CameraCalib.ToMm</c>). Ý
    /// nghĩa cụ thể của <see cref="X"/>/<see cref="Y"/> khác nhau theo từng Flow — xem
    /// <see cref="EVisionProcedure"/>.</para>
    /// </summary>
    public class VisionPose
    {
        public bool Found { get; set; }

        /// <summary>Toạ độ/độ lệch theo trục X, mm. Ý nghĩa theo Flow, xem <see cref="EVisionProcedure"/>.</summary>
        public double X { get; set; }

        /// <summary>Toạ độ/độ lệch theo trục Y, mm.</summary>
        public double Y { get; set; }

        /// <summary>Góc đo được, độ, trong hệ vật lý của file hiệu chuẩn (TransPointA).</summary>
        public double Angle { get; set; }

        /// <summary>
        /// Điểm khớp mẫu. VisionMaster trả <c>MatchScore</c> trong khoảng <b>0..1</b> (không phải
        /// 0..100), và App KHÔNG dùng nó làm ngưỡng loại hàng — chỉ ghi log/hiển thị. Ngưỡng khớp
        /// đặt bên trong module High Precision Match của solution.
        /// </summary>
        public double Score { get; set; }

        public string Error { get; set; }

        public static VisionPose NotFound(string why = null)
            => new VisionPose { Found = false, Error = why };
    }

    /// <summary>Các procedure (Flow) của solution VisionMaster — PLAN.md §6.8.</summary>
    public enum EVisionProcedure
    {
        /// <summary>
        /// CAM top-down, chạy Auto: đo chi tiết đích có sẵn trong ô tray lắp ráp.
        /// <para><c>X</c>/<c>Y</c> = lượng phải dịch trục <b>X</b> và <b>Y2</b> (mm, toạ độ lệnh)
        /// để điểm tham chiếu của khung hình trùng tâm chi tiết vừa thấy — tức toạ độ đích =
        /// (vị trí lúc chụp) + (X, Y). <c>Angle</c> = góc chi tiết trong hệ vật lý.</para>
        /// </summary>
        LocateTop,

        /// <summary>
        /// CAM top-down, soi DẤU CHUẨN: cùng ý nghĩa output với <see cref="LocateTop"/> nhưng mẫu
        /// khớp là dấu chuẩn dán trên đồ gá tray, không phải chi tiết thật. Dùng cho hand-eye
        /// (§6.5) và phép kiểm tra dấu/thang đo của hiệu chuẩn top-down — KHÔNG dùng
        /// <see cref="TopDownCalib"/> cho việc này vì mỗi lần chạy Flow đó là nạp thêm một điểm
        /// vào module N-point.
        /// </summary>
        LocateMark,

        /// <summary>
        /// CAM top-down, CHỈ dùng lúc hiệu chuẩn lưới 9 điểm: mỗi lần chạy nạp thêm một điểm vào
        /// module N-point Calibration (chế độ Trigger Acquisition). Không đọc output tư thế.
        /// </summary>
        TopDownCalib,

        /// <summary>
        /// CAM bottom-up, chạy Auto, tay hút #1.
        /// <para><c>X</c>/<c>Y</c> = vị trí tâm sản phẩm trong hệ vật lý của file hiệu chuẩn
        /// bottom-up tay #1, <b>gốc đặt tại tâm xoay</b> của chính tay đó (mm, CHƯA xoay gì).
        /// <c>Angle</c> = góc sản phẩm. Đây là "đối tượng" (run point) đưa vào Flow
        /// PlaceAlign — xem <see cref="PlaceAlignInput"/>.</para>
        /// </summary>
        AlignBottomTool1,

        /// <summary>Như <see cref="AlignBottomTool1"/>, tay hút #2 (tâm xoay vật lý khác).</summary>
        AlignBottomTool2,

        /// <summary>
        /// CAM bottom-up, CHỈ dùng lúc hiệu chuẩn tâm xoay tay #1: mỗi lần chạy nạp thêm một điểm
        /// vào module hiệu chuẩn của VisionMaster, đúng khuôn <see cref="TopDownCalib"/>.
        /// </summary>
        AlignCalibTool1,

        /// <summary>Như <see cref="AlignCalibTool1"/>, tay hút #2.</summary>
        AlignCalibTool2
    }

    /// <summary>
    /// Đầu vào của Flow <c>PlaceAlign</c> — App set vào input của Flow rồi mới Run
    /// (<c>VmProcedure.ModuParams.SetInputFloat</c>, "chỉ có hiệu lực cho lần chạy này").
    ///
    /// <para>Cả hai điểm phải nằm trong CÙNG một hệ vật lý: hệ toạ độ lệnh trục (X, Y2) của máy.
    /// "Đối tượng" là tâm sản phẩm so với tâm xoay (Flow AlignBottom_ToolN), "đích" là toạ độ
    /// lệnh trục để đưa tâm xoay của tay hút tới đúng chi tiết đích (App cộng vị trí lúc chụp +
    /// kết quả LocateTop + hand-eye, xem <see cref="ShieldCanAssy.Core.Controller.PlacementSolver"/>).</para>
    /// </summary>
    public class PlaceAlignInput
    {
        public double TargetX { get; set; }
        public double TargetY { get; set; }
        public double TargetAngle { get; set; }

        public double ObjectX { get; set; }
        public double ObjectY { get; set; }
        public double ObjectAngle { get; set; }
    }

    /// <summary>
    /// Kết quả Flow <c>PlaceAlign</c> — module <i>Single Point Alignment</i> của VisionMaster tự
    /// tính: Δθ = θ_đích − θ_đối_tượng, rồi (Δx, Δy) = đích − R(Δθ)·đối_tượng. Lượng dịch do xoay
    /// đã nằm sẵn trong Δx/Δy, App KHÔNG được bù thêm lần nữa (PLAN.md §6.6).
    /// </summary>
    public class PlaceAlignResult
    {
        public bool Ok { get; set; }
        public string Error { get; set; }

        /// <summary>Toạ độ lệnh trục X (mm) — module đã trừ sẵn phần dịch do xoay.</summary>
        public double DeltaX { get; set; }

        /// <summary>Toạ độ lệnh trục Y2 (mm).</summary>
        public double DeltaY { get; set; }

        /// <summary>
        /// Góc phải xoay, độ, theo quy ước của VisionMaster (<b>chiều kim đồng hồ là dương</b>).
        /// Trục A của máy quy ước NGƯỢC chiều kim đồng hồ là dương, nên App phải nhân dấu
        /// <c>VisionCalib.AlignAngleSign</c> — dấu này đo bằng phép thử vòng xoay, không suy đoán.
        /// </summary>
        public double DeltaThetaDeg { get; set; }

        public static PlaceAlignResult NotOk(string why)
            => new PlaceAlignResult { Ok = false, Error = why };
    }

    /// <summary>
    /// Vị trí thật (đọc encoder) của các trục liên quan tới vision, gửi sang VisionMaster qua
    /// <b>biến toàn cục</b> ngay trước mỗi lần kích Flow hiệu chuẩn (Tuấn chốt 2026-09-12).
    ///
    /// <para>Module hiệu chuẩn trong solution đặt <i>Calibration Points Input = By Coordinate</i>
    /// rồi subscribe <i>Physical Coordinate X/Y</i> và <i>World Rotate Angle</i> vào đúng những
    /// biến này. Gửi cả năm trục chứ không chỉ trục đang chạy: một chỗ duy nhất giữ trạng thái máy,
    /// Flow nào cần trục nào thì tự subscribe trục đó — đổi cách hiệu chuẩn sau này không phải sửa
    /// code App.</para>
    ///
    /// <para>Đây là thứ khiến hiệu chuẩn CAM bottom-up khả thi: theo tài liệu Hikrobot "Calibration
    /// and Locating Theory" tr.18, nạp điểm kèm toạ độ thật thì <b>mọi quỹ đạo đều hợp lệ</b> —
    /// không bắt buộc hình S, không bắt buộc lưới hai chiều, mà CAM bottom-up chỉ có X và xoay A.</para>
    /// </summary>
    public class AxisSnapshot
    {
        public double X { get; set; }
        public double Y1 { get; set; }
        public double Y2 { get; set; }
        public double A1 { get; set; }
        public double A2 { get; set; }
    }

    public interface IVisionDevice : INotifyPropertyChanged
    {
        bool IsConnected { get; }
        bool IsSolutionLoaded { get; }

        bool Connect();
        void Disconnect();

        Task<bool> LoadSolutionAsync(string solutionPath);

        /// <summary>Kích chụp và chờ kết quả. Timeout sinh alarm 4003 ở lớp gọi.</summary>
        Task<VisionPose> TriggerAsync(EVisionProcedure procedure, CancellationToken ct);

        /// <summary>
        /// Chạy Flow <c>PlaceAlign</c>: truyền tư thế đích + tư thế sản phẩm vào input của Flow,
        /// VisionMaster trả về lệnh X/Y2 và góc xoay đã tính sẵn (§6.6). Không chụp ảnh — Flow này
        /// thuần tính toán nên gọi được bao nhiêu lần tuỳ ý, không đụng camera.
        /// </summary>
        Task<PlaceAlignResult> TriggerPlaceAlignAsync(PlaceAlignInput input, CancellationToken ct);

        /// <summary>Ảnh chụp được của lần trigger CAM top-down gần nhất — trang Main hiển thị để
        /// operator nhìn được CAM đang thấy gì, không bắt buộc phải có (null nếu solution chưa khai
        /// output ảnh, hoặc đang chạy mô phỏng).</summary>
        System.Drawing.Bitmap LastTopDownImage { get; }

        /// <summary>Ảnh chụp được của lần trigger CAM bottom-up gần nhất — cùng ý nghĩa với
        /// <see cref="LastTopDownImage"/>, khác camera.</summary>
        System.Drawing.Bitmap LastBottomUpImage { get; }
    }
}

