public Task<VisionPose> TriggerAsync(EVisionProcedure procedure, CancellationToken ct)
{
    return TriggerCoreAsync(procedure, null, ct);
}

/// <summary>
/// Kích Flow hiệu chuẩn kèm vị trí trục thật (§6.2, §6.4). Ghi biến toàn cục rồi Run trong
/// cùng một lần gọi — xem <see cref="IVisionDevice.TriggerCalibAsync"/>.
/// </summary>
public Task<VisionPose> TriggerCalibAsync(EVisionProcedure procedure, AxisSnapshot axes, CancellationToken ct)
{
    if (axes == null) return Task.FromResult(VisionPose.NotFound("thiếu vị trí trục để nạp điểm hiệu chuẩn"));
    return TriggerCoreAsync(procedure, axes, ct);
}

private string FlowNameOf(EVisionProcedure procedure)
{
    var names = _sys.VisionOutputs;
    switch (procedure)
    {
        case EVisionProcedure.TopDownCalib: return names.FlowTopDownCalib;
        case EVisionProcedure.LocateMark: return names.FlowLocateMark;
        case EVisionProcedure.AlignBottomTool1: return names.FlowAlignBottomTool1;
        case EVisionProcedure.AlignBottomTool2: return names.FlowAlignBottomTool2;
        case EVisionProcedure.AlignCalibTool1: return names.FlowAlignCalibTool1;
        case EVisionProcedure.AlignCalibTool2: return names.FlowAlignCalibTool2;
        default: return names.FlowLocateTop;
    }
}

/// <summary>Vị trí trục → tên biến toàn cục khai ở trang Setting. Tên để trống thì bỏ qua
/// trục đó — solution không nhất thiết cần cả năm trục.</summary>
private Dictionary<string, double> AxisVars(AxisSnapshot axes)
{
    var names = _sys.VisionOutputs;
    var vars = new Dictionary<string, double>();
    if (!string.IsNullOrEmpty(names.GvAxisX)) vars[names.GvAxisX] = axes.X;
    if (!string.IsNullOrEmpty(names.GvAxisY1)) vars[names.GvAxisY1] = axes.Y1;
    if (!string.IsNullOrEmpty(names.GvAxisY2)) vars[names.GvAxisY2] = axes.Y2;
    if (!string.IsNullOrEmpty(names.GvAxisA1)) vars[names.GvAxisA1] = axes.A1;
    if (!string.IsNullOrEmpty(names.GvAxisA2)) vars[names.GvAxisA2] = axes.A2;
    return vars;
}

private async Task<VisionPose> TriggerCoreAsync(EVisionProcedure procedure, AxisSnapshot axes, CancellationToken ct)
{
    if (!IsConnected) return VisionPose.NotFound("chưa kết nối");
    if (!IsSolutionLoaded) return VisionPose.NotFound("chưa nạp solution");

    var names = _sys.VisionOutputs;
    string flow = FlowNameOf(procedure);

    try
    {
        var result = await RunWithTimeoutAsync(() =>
            {
                // Ghi trước, chạy sau, trong cùng một lượt giữ khoá lệnh của thiết bị.
                if (axes != null) _device.SetGlobalFloats(AxisVars(axes), names.GlobalVarModule);
                return _device.RunAndGetFloatsWithImage(flow, names.OutImage,
                    names.OutFound, names.OutPoseX, names.OutPoseY, names.OutAngle, names.OutScore);
            },
            ct).ConfigureAwait(false);

