}

private async Task<VisionPose> TriggerCoreAsync(EVisionProcedure procedure, AxisSnapshot axes, CancellationToken ct)
{
    if (!IsConnected) return VisionPose.NotFound("chưa kết nối");
    if (!IsSolutionLoaded) return VisionPose.NotFound("chưa nạp solution");

    var names = _sys.VisionOutputs;
    string flow = FlowNameOf(procedure);

    try
    {
        var result = await RunWithTimeoutAsync(() =>
            {
                // Ghi trước, chạy sau, trong cùng một lượt giữ khoá lệnh của thiết bị.
                if (axes != null) _device.SetGlobalFloats(AxisVars(axes), names.GlobalVarModule);
                return _device.RunAndGetFloatsWithImage(flow, names.OutImage,
                    names.OutFound, names.OutPoseX, names.OutPoseY, names.OutAngle, names.OutScore);
            },
            ct).ConfigureAwait(false);

        if (result == null)
        {
            AlarmManager.Raise(AlarmCode.VisionTriggerTimeout, "Vision", flow);
            return VisionPose.NotFound("quá thời gian chờ");
        }

        // Sửa lỗi tồn tại từ trước (2026-09-10, phát hiện lúc bỏ Flow AlignBottom chung):
        // điều kiện cũ so procedure == AlignBottom (Flow chung, đã orphan) — nhưng Auto
        // thật CHỈ trigger AlignBottomTool1/Tool2 (không bao giờ AlignBottom nữa), nên ảnh
        // CAM bottom-up trước đây KHÔNG BAO GIỜ được gán vào LastBottomUpImage, luôn rơi
        // nhầm vào nhánh LastTopDownImage bên dưới. AlignBottomTool1/2 VÀ AlignCalibTool1/2
        // đều là CAM bottom-up (khác CAM top-down của LocateTop/TopDownCalib).
        bool isBottomUp = procedure == EVisionProcedure.AlignBottomTool1
            || procedure == EVisionProcedure.AlignBottomTool2
            || procedure == EVisionProcedure.AlignCalibTool1
            || procedure == EVisionProcedure.AlignCalibTool2;
        if (isBottomUp) LastBottomUpImage = result.Image;
        else LastTopDownImage = result.Image;

        float[] r = result.Floats;
        bool found = r[0] > 0.5f;
        if (!found) return VisionPose.NotFound("solution báo không tìm thấy");

        return new VisionPose { Found = true, X = r[1], Y = r[2], Angle = r[3], Score = r[4] };
    }
    catch (VmException ex)
    {
        LogWorker.Instance.RecordLog("Vision: " + flow + " lỗi — " + ex.errorMessage,
            Utility.Log.LogLevel.Error, "Vision");
        return VisionPose.NotFound(ex.errorMessage);
    }
    catch (Exception ex)
    {
        LogWorker.Instance.RecordLog("Vision: " + flow + " lỗi — " + ex.Message,
            Utility.Log.LogLevel.Error, "Vision");
        return VisionPose.NotFound(ex.Message);
    }
}

