/// <summary>
/// Mô phỏng nạp một điểm hiệu chuẩn: ghi lại vị trí trục "gửi sang VisionMaster" rồi chạy
/// Flow như thường. Solution thật nhận toạ độ này qua biến toàn cục; ở đây chỉ giữ lại để
/// <c>--selftest</c> đối chiếu.
/// </summary>
public Task<VisionPose> TriggerCalibAsync(EVisionProcedure procedure, AxisSnapshot axes, CancellationToken ct)
{
    if (axes == null) return Task.FromResult(VisionPose.NotFound("thiếu vị trí trục để nạp điểm hiệu chuẩn"));

    LastCalibAxes = axes;
    CalibPointCount++;
    return TriggerAsync(procedure, ct);
}

