1	using System;
2	using System.Collections.Generic;
3	using System.Threading;
4	using System.Threading.Tasks;
5	using ShieldCanAssy.Core.Communication;
6	using ShieldCanAssy.Core.Data;
7	using ShieldCanAssy.Core.Data.Model;
8	using ShieldCanAssy.Core.Infor;
9	using ShieldCanAssy.Utility.Log;
10	
11	namespace ShieldCanAssy.Core.Controller
12	{
13	    public class TopDownCalibResult
14	    {
15	        public bool Ok { get; set; }
16	        public string Reason { get; set; }
17	        public AffineFitResult Fit { get; set; }
18	        public double VerifyErrorMm { get; set; }
19	        public bool VerifyOk { get; set; }
20	    }
21	
22	    public class BottomUpCalibResult
23	    {
24	        public bool Ok { get; set; }
25	        public string Reason { get; set; }
26	        public CameraCalib Calib { get; set; }
27	        public int CornerCount { get; set; }
28	        public double SkewDeg { get; set; }
29	        public double ScaleFromBoard { get; set; }
30	        public double ScaleFromAxis { get; set; }
31	        public double ScaleCrossCheckDiffRatio { get; set; }
32	        public bool CrossCheckOk { get; set; }
33	    }
34	
35	    public class HandEyeMeasurement
36	    {
37	        public bool Ok { get; set; }
38	        public string Reason { get; set; }
39	
40	        /// <summary>Vị trí trục (X, Y2) nơi tâm ảnh CAM top-down trùng dấu chuẩn.</summary>
41	        public double CamX { get; set; }
42	        public double CamY { get; set; }
43	    }
44	
45	    /// <summary>
46	    /// Hiệu chuẩn vision — PLAN.md §6. Bốn wizard độc lập, mỗi cái trả về một kết quả để trang
47	    /// Teaching cho operator XEM residual rồi mới quyết định lưu, chứ không tự ghi đè
48	    /// <c>ModelData.Calib</c> — "Không đạt → không cho lưu" (§6.1) là quyết định của người, không
49	    /// phải của routine.
50	    ///
51	    /// <para>Cũng vì vậy lớp này không giữ trạng thái <c>VisionCalib</c> nào cả: mọi hàm nhận
52	    /// calib cần thiết qua tham số (giống <see cref="PlacementSolver"/>) và trả về kết quả mới,
53	    /// không đọc/ghi <c>McDataManager.Model</c> trực tiếp.</para>
54	    /// </summary>
55	    public class Routine_Calib
56	    {
57	        private readonly MotionConnect _motion;
58	        private readonly McFunction _func;
59	        private readonly Func<SystemData> _sys;
60	        private readonly Func<IVisionDevice> _vision;
61	
62	        public Routine_Calib(MotionConnect motion, McFunction func, Func<SystemData> sys, Func<IVisionDevice> vision)
63	        {
64	            _motion = motion;
65	            _func = func;
66	            _sys = sys;
67	            _vision = vision;
68	        }
69	
70	        // ───────────────────────── §6.2 CAM top-down: lưới 9 điểm bằng trục máy ─────────────────────────
71	
72	        /// <summary>
73	        /// Chạy lưới 3×3 quanh (<paramref name="centerX"/>, <paramref name="centerY"/>) — bước
74	        /// lấy từ <c>SystemData.TopDownCalibStepXMm/YMm</c> — rồi hồi quy affine pixel → (X, Y2).
75	        /// Sau đó chạy thêm một điểm kiểm chứng nằm ngoài lưới (PLAN.md §6.1 quy tắc 5).
76	        ///
77	        /// <para><paramref name="centerX"/>/<paramref name="centerY"/> là toạ độ trục X/Y2 operator
78	        /// đã jog tới trước khi bấm nút — trang Teaching đọc từ <c>CurrentPos</c>, giống hệt cách
79	        /// Teach điểm P00/P0C/PR0 đọc vị trí thật thay vì cho gõ tay (§8.2).</para>
80	        /// </summary>
81	        public async Task<TopDownCalibResult> CalibrateTopDownAsync(double centerX, double centerY, CancellationToken ct)
82	        {
83	            try
84	            {
85	                var sys = _sys();
86	                double stepX = sys.TopDownCalibStepXMm;
87	                double stepY = sys.TopDownCalibStepYMm;
88	                int shots = sys.CalibShotsPerPoint;
89	
90	                var pts = new List<CalibPoint>();
91	
92	                // PLAN §6.1 quy tắc 2: cùng một chiều tiếp cận. Quét kiểu "rắn bò" (serpentine)
93	                // để giảm số lần đảo chiều X xuống còn đúng một lần mỗi hàng, thay vì mọi điểm.
94	                // Chưa có số đo backlash thật nên chưa làm overshoot-rồi-lùi lại từng điểm — ghi
95	                // rõ ở đây để không ai tưởng nhầm đây đã là lời giải đầy đủ cho quy tắc 2.
96	                for (int r = -1; r <= 1; r++)
97	                {
98	                    bool reverse = (r == 0);
99	                    for (int ci = 0; ci <= 2; ci++)
100	                    {
101	                        int c = reverse ? (1 - ci) : (ci - 1);
102	                        var p = await CaptureGridPointAsync(centerX + c * stepX, centerY + r * stepY, shots, ct)
103	                            .ConfigureAwait(false);
104	                        if (p == null)
105	                            return new TopDownCalibResult { Ok = false, Reason = $"điểm lưới (hàng {r}, cột {c}) đo thất bại — dừng hiệu chuẩn" };
106	                        pts.Add(p.Value);
107	                    }
108	                }
109	
110	                var fit = VisionCalibMath.FitAffine(pts);
111	                if (!fit.Ok)
112	                    return new TopDownCalibResult { Ok = false, Reason = fit.Reason, Fit = fit };
113	
114	                bool accepted = fit.RmsResidual <= sys.CalibRmsThresholdMm && fit.MaxResidual <= sys.CalibMaxResidualThresholdMm;
115	                var result = new TopDownCalibResult { Ok = accepted, Fit = fit };
116	                if (!accepted)
117	                    result.Reason = string.Format(
118	                        "RMS {0:0.000} mm / max {1:0.000} mm vượt ngưỡng {2:0.000} / {3:0.000} mm — không lưu",
119	                        fit.RmsResidual, fit.MaxResidual, sys.CalibRmsThresholdMm, sys.CalibMaxResidualThresholdMm);
120	
121	                // Điểm kiểm chứng thứ 10, cố ý nằm ngoài lưới 3×3 (PLAN §6.1 quy tắc 5): residual
122	                // của 9 điểm gốc luôn lạc quan hơn thực tế vì chính chúng tham gia fit ra ma trận.
123	                double vx = centerX + 1.5 * stepX;
124	                double vy = centerY + 1.5 * stepY;
125	                var verify = await CaptureGridPointAsync(vx, vy, shots, ct).ConfigureAwait(false);
126	                if (verify == null)
127	                {
128	                    result.Reason = (result.Reason == null ? "" : result.Reason + "; ") + "điểm kiểm chứng đo thất bại";
129	                }
130	                else
131	                {
132	                    double predX, predY;
133	                    fit.Calib.ToMm(verify.Value.U, verify.Value.V, out predX, out predY);
134	                    double ex = predX - verify.Value.X;
135	                    double ey = predY - verify.Value.Y;
136	                    result.VerifyErrorMm = Math.Sqrt(ex * ex + ey * ey);
137	                    result.VerifyOk = result.VerifyErrorMm <= sys.CalibMaxResidualThresholdMm;
138	                    result.Ok = result.Ok && result.VerifyOk;
139	                    if (!result.VerifyOk)
140	                        result.Reason = (result.Reason == null ? "" : result.Reason + "; ") +
141	                            string.Format("điểm kiểm chứng lệch {0:0.000} mm > ngưỡng {1:0.000} mm", result.VerifyErrorMm, sys.CalibMaxResidualThresholdMm);
142	                }
143	
144	                LogWorker.Instance.RecordLog(
145	                    string.Format("Hiệu chuẩn CAM top-down: RMS {0:0.000} mm, max {1:0.000} mm, verify {2:0.000} mm — {3}",
146	                        fit.RmsResidual, fit.MaxResidual, result.VerifyErrorMm, result.Ok ? "ĐẠT" : "KHÔNG ĐẠT: " + result.Reason),
147	                    result.Ok ? Utility.Log.LogLevel.Info : Utility.Log.LogLevel.Warning, "Calib");
148	
149	                return result;
150	            }
151	            catch (OperationCanceledException)
152	            {
153	                return new TopDownCalibResult { Ok = false, Reason = "bị huỷ" };
154	            }
155	            catch (Exception ex)
156	            {
157	                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
158	                return new TopDownCalibResult { Ok = false, Reason = "lỗi bất thường: " + ex.Message };
159	            }
160	        }
161	
162	        private async Task<CalibPoint?> CaptureGridPointAsync(double x, double y2, int shots, CancellationToken ct)
163	        {
164	            if (!await _func.MoveToCellAsync(AxisId.Y2, y2, x, ct).ConfigureAwait(false))
165	                return null;
166	
167	            var pose = await CaptureAveragedAsync(EVisionProcedure.LocateTop, shots, ct).ConfigureAwait(false);
168	            if (!pose.Found) return null;
169	
170	            // PLAN §6.1 quy tắc 3: ghi ActualPosition đọc từ encoder SAU khi lệnh move đã xác
171	            // nhận tới đích, không phải giá trị lệnh (x, y2) đưa vào.
172	            double actualX = _motion[AxisId.X]?.CurrentPos ?? x;
173	            double actualY = _motion[AxisId.Y2]?.CurrentPos ?? y2;
174	            return new CalibPoint(pose.PixelX, pose.PixelY, actualX, actualY);
175	        }
176	
177	        // ───────────────────────── §6.2b lưới 9 điểm thủ công (trang Vision Edit) ─────────────────────────
178	        //
179	        // Khác CalibrateTopDownAsync ở trên (quét 9 điểm tự động, tự fit affine, tự đề xuất lưu):
180	        // đây là 2 lệnh RỜI — di chuyển-và-chụp từng điểm một, KHÔNG tính affine, KHÔNG ghi
181	        // ModelData.Calib. Phép hiệu chuẩn thực hiện thủ công bên trong VMEditControl (VisionMaster)
182	        // bằng chính các điểm đã chụp qua Flow TopDownCalib; hai lệnh này chỉ lo phần di chuyển +
183	        // kích hoạt Flow, đúng việc duy nhất phần mềm này còn cần làm cho quy trình đó.
184	
185	        /// <summary>Di chuyển tới (x, y2) rồi kích hoạt Flow TopDownCalib — dùng cho từng nút trong
186	        /// lưới 9 điểm thủ công. Trả về false nếu di chuyển thất bại hoặc Flow báo không tìm thấy.</summary>
187	        public async Task<bool> MoveAndTriggerTopDownCalibAsync(double x, double y2, CancellationToken ct)
188	        {
189	            if (!await _func.MoveToCellAsync(AxisId.Y2, y2, x, ct).ConfigureAwait(false))
190	                return false;
191	
192	            var pose = await _vision().TriggerAsync(EVisionProcedure.TopDownCalib, ct).ConfigureAwait(false);
193	            return pose.Found;
194	        }
195	
196	        /// <summary>Kích hoạt Flow TopDownCalib tại vị trí hiện tại, không di chuyển — dùng để test
197	        /// Flow riêng hoặc chụp điểm giữa (điểm 5, tâm khung hình, không cần offset).</summary>
198	        public async Task<bool> TriggerTopDownCalibFlowAsync(CancellationToken ct)
199	        {
200	            var pose = await _vision().TriggerAsync(EVisionProcedure.TopDownCalib, ct).ConfigureAwait(false);
201	            return pose.Found;
202	        }
203	
204	        // ───────────────────────── §6.3 CAM bottom-up: checkerboard ─────────────────────────
205	
206	        /// <summary>
207	        /// B2 + B3 + B4 (PLAN.md §6.3). <paramref name="xProbe1"/>/<paramref name="xProbe2"/> là
208	        /// hai vị trí X đã biết, khác nhau đủ xa (vài mm trở lên) và vẫn giữ được bản chuẩn trong
209	        /// khung hình — operator chọn khi jog thử trước lúc bấm nút.
210	        /// </summary>
211	        public async Task<BottomUpCalibResult> CalibrateBottomUpAsync(double xProbe1, double xProbe2, CancellationToken ct)
212	        {
213	            try
214	            {
215	                var sys = _sys();
216	                var vision = _vision();
217	
218	                // B2: công cụ hiệu chuẩn bản chuẩn của VisionMaster tính scale/độ không vuông góc
219	                // từ hàng trăm góc trong một ảnh.
220	                var board = await vision.TriggerCalibBoardAsync(ct).ConfigureAwait(false);
221	                if (!board.Found)
222	                    return new BottomUpCalibResult { Ok = false, Reason = board.Error ?? "không đọc được bản chuẩn — kiểm tra tấm checkerboard trong khung hình" };
223	
224	                // B4: ghép thành ma trận affine. Gốc đặt tại pixel (0,0) — PlacementSolver chỉ dùng
225	                // toạ độ TƯƠNG ĐỐI (p − C_i) nên hằng số gốc không ảnh hưởng kết quả cuối, miễn
226	                // nhất quán trong toàn bộ VisionCalib này.
227	                // BottomUpYSign KHÔNG ghép ở đây — PlacementSolver tự nhân dấu đó riêng (§6.3 cuối).
228	                double skewRad = board.SkewDeg * Math.PI / 180.0;
229	                var calib = new CameraCalib
230	                {
231	                    B11 = board.ScaleU,
232	                    B12 = board.ScaleU * Math.Sin(skewRad),
233	                    B13 = 0,
234	                    B21 = 0,
235	                    B22 = board.ScaleV,
236	                    B23 = 0,
237	                    Method = "checkerboard 1×1 mm (bottom-up)",
238	                    PointCount = board.CornerCount
239	                };
240	
241	                var result = new BottomUpCalibResult
242	                {
243	                    Calib = calib,
244	                    CornerCount = board.CornerCount,
245	                    SkewDeg = board.SkewDeg,
246	                    ScaleFromBoard = board.ScaleU
247	                };
248	
249	                // B3: chạy X tới 2 vị trí đã biết, đối chiếu chéo scale đo bằng trục máy với scale
250	                // đo bằng bản chuẩn — phép thử duy nhất bắt được lỗi cao độ đồ gá.
251	                if (!await _func.MoveAsync(AxisId.X, xProbe1, sys.GetAxis(AxisId.X).MoveSpeed, ct).ConfigureAwait(false))
252	                    return new BottomUpCalibResult { Ok = false, Reason = "không di chuyển được tới điểm đối chiếu 1" };
253	                var board1 = await vision.TriggerCalibBoardAsync(ct).ConfigureAwait(false);
254	                double axisPos1 = _motion[AxisId.X]?.CurrentPos ?? xProbe1;
255	
256	                if (!await _func.MoveAsync(AxisId.X, xProbe2, sys.GetAxis(AxisId.X).MoveSpeed, ct).ConfigureAwait(false))
257	                    return new BottomUpCalibResult { Ok = false, Reason = "không di chuyển được tới điểm đối chiếu 2" };
258	                var board2 = await vision.TriggerCalibBoardAsync(ct).ConfigureAwait(false);
259	                double axisPos2 = _motion[AxisId.X]?.CurrentPos ?? xProbe2;
260	
261	                if (!board1.Found || !board2.Found)
262	                {
263	                    result.Reason = "không thấy bản chuẩn tại điểm đối chiếu — kiểm tra khung hình";
264	                    return result;
265	                }
266	
267	                double axisDeltaMm = Math.Abs(axisPos2 - axisPos1);
268	                double pixelDeltaU = Math.Abs(board2.OriginPixelU - board1.OriginPixelU);
269	                if (axisDeltaMm < 1e-6 || pixelDeltaU < 1e-6)
270	                {
271	                    result.Reason = "hai điểm đối chiếu trùng nhau hoặc góc mốc không dịch chuyển — chọn lại vị trí";
272	                    return result;
273	                }
274	
275	                double scaleFromAxis = axisDeltaMm / pixelDeltaU;
276	                double diffRatio = Math.Abs(scaleFromAxis - board.ScaleU) / board.ScaleU;
277	
278	                result.ScaleFromAxis = scaleFromAxis;
279	                result.ScaleCrossCheckDiffRatio = diffRatio;
280	                result.CrossCheckOk = diffRatio <= sys.BottomUpScaleCrossCheckTolerance;
281	                result.Ok = result.CrossCheckOk;
282	                if (!result.CrossCheckOk)
283	                    result.Reason = string.Format(
284	                        "scale theo trục X ({0:0.00000} mm/px) lệch bản chuẩn ({1:0.00000} mm/px) {2:0.00}% > ngưỡng {3:0.00}% " +
285	                        "— thường là sai cao độ đồ gá bản chuẩn, kiểm tra trước khi đổ cho camera (§6.3)",
286	                        scaleFromAxis, board.ScaleU, diffRatio * 100, sys.BottomUpScaleCrossCheckTolerance * 100);
287	
288	                LogWorker.Instance.RecordLog(
289	                    string.Format("Hiệu chuẩn CAM bottom-up: scale bản chuẩn {0:0.00000}, scale trục X {1:0.00000}, lệch {2:0.00}% — {3}",
290	                        board.ScaleU, scaleFromAxis, diffRatio * 100, result.Ok ? "ĐẠT" : "KHÔNG ĐẠT: " + result.Reason),
291	                    result.Ok ? Utility.Log.LogLevel.Info : Utility.Log.LogLevel.Warning, "Calib");
292	
293	                return result;
294	            }
295	            catch (OperationCanceledException)
296	            {
297	                return new BottomUpCalibResult { Ok = false, Reason = "bị huỷ" };
298	            }
299	            catch (Exception ex)
300	            {
301	                AlarmManager.Raise(AlarmCode.RoutineCrashed, "Calib", ex.Message);
302	                return new BottomUpCalibResult { Ok = false, Reason = "lỗi bất thường: " + ex.Message };
303	            }
304	        }
305	
306	        // ───────────────────────── §6.4 Tâm xoay từng tay hút (VisionMaster, hiện dùng) ─────────────────────────
307	        //
308	        // Tâm xoay + Master của CAM bottom-up nay hiệu chuẩn bằng chính module N-point CÓ XOAY +
309	        // Teaching của VisionMaster (Tuấn chốt 2026-09-08), đúng khuôn đã làm cho CAM top-down
