5	    /// <summary>
6	    /// Ma trận affine pixel → mm hệ máy của một camera, cùng số liệu chất lượng của lần
7	    /// hiệu chuẩn sinh ra nó (PLAN.md §6.1).
8	    /// </summary>
9	    public class CameraCalib
10	    {
11	        /// <summary>X = B11·u + B12·v + B13</summary>
12	        public double B11 { get; set; } = 1;
13	        public double B12 { get; set; }
14	        public double B13 { get; set; }
15	
16	        /// <summary>Y = B21·u + B22·v + B23</summary>
17	        public double B21 { get; set; }
18	        public double B22 { get; set; } = 1;
19	        public double B23 { get; set; }
20	
21	        public bool IsCalibrated { get; set; }
22	        public DateTime CalibratedAt { get; set; }
23	        public string CalibratedBy { get; set; }
24	        public double RmsResidual { get; set; }
25	        public double MaxResidual { get; set; }
26	        public int PointCount { get; set; }
27	
28	        /// <summary>Ghi chú cách hiệu chuẩn: "9 điểm bằng trục máy" hay "checkerboard 1 mm".</summary>
29	        public string Method { get; set; }
30	
31	        public void ToMm(double pixelX, double pixelY, out double mmX, out double mmY)
32	        {
33	            mmX = B11 * pixelX + B12 * pixelY + B13;
34	            mmY = B21 * pixelX + B22 * pixelY + B23;
35	        }
36	
37	        public double ScaleX => Math.Sqrt(B11 * B11 + B21 * B21);
38	        public double ScaleY => Math.Sqrt(B12 * B12 + B22 * B22);
39	        public double RotationDeg => Math.Atan2(B21, B11) * 180.0 / Math.PI;
40	        public int Handedness => Math.Sign(B11 * B22 - B12 * B21);
41	
42	        public bool IsExpired(int validDays)
43	            => IsCalibrated && (DateTime.Now - CalibratedAt).TotalDays > validDays;
44	
45	        /// <summary>
46	        /// Ma trận đơn giản hoá cho chế độ mô phỏng: chỉ có tỉ lệ mm/pixel, không xoay, không
47	        /// nghiêng, gốc đặt tại tâm ảnh. Đủ để chạy và kiểm chứng toàn bộ chuỗi Auto trước khi
48	        /// có camera thật; <see cref="Method"/> ghi rõ là số giả để không ai nhầm với hiệu chuẩn.
49	        /// </summary>
50	        public static CameraCalib CreateSimulation(double mmPerPixel, double centerX, double centerY)
51	        {
52	            return new CameraCalib
53	            {
54	                B11 = mmPerPixel, B12 = 0, B13 = -mmPerPixel * centerX,
55	                B21 = 0, B22 = mmPerPixel, B23 = -mmPerPixel * centerY,
56	                IsCalibrated = true,
57	                CalibratedAt = DateTime.Now,
58	                CalibratedBy = "(mô phỏng)",
59	                Method = "SỐ GIẢ — chế độ mô phỏng, chưa hiệu chuẩn thật",
60	                PointCount = 0
61	            };
62	        }
63	    }
