106	    /// <summary>Dữ liệu một model sản phẩm — lưu ở Model\&lt;tên&gt;.json.</summary>
107	    public class ModelData
108	    {
109	        public string Name { get; set; } = "DEFAULT";
110	        public string Description { get; set; }
111	        public DateTime ModifiedAt { get; set; } = DateTime.Now;
112	
113	        public TrayLayout InputTray { get; set; } = TrayLayout.CreateInputDefault();
114	        public TrayLayout AssyTray { get; set; } = TrayLayout.CreateAssyDefault();
115	
116	        public VisionCalib Calib { get; set; } = new VisionCalib();
117	
118	        /// <summary>Vị trí X để đưa từng tay hút vào giữa khung hình CAM bottom-up.</summary>
119	        public double AlignPosX_Nozzle1 { get; set; }
120	        public double AlignPosX_Nozzle2 { get; set; }
121	
122	        /// <summary>
123	        /// Nạp bộ số giả để chạy được chuỗi Auto ở chế độ mô phỏng: lưới tray đã teach, hiệu
124	        /// chuẩn 2 camera, tâm xoay, hand-eye. Chỉ gọi khi <c>SimulationMode</c>, và có ghi log.
125	        /// Toàn bộ số ở đây là bịa — mục đích là kiểm chứng LOGIC chu trình trước khi có máy.
126	        /// </summary>
127	        public static ModelData CreateSimulation()
128	        {
129	            var m = new ModelData
130	            {
131	                Name = "SIM",
132	                Description = "Model giả lập — số liệu bịa, chỉ dùng để chạy thử chu trình"
133	            };
134	
135	            // Mỗi Tool có lưới riêng (TrayGeometry) — Z2 cố ý lệch Z1 một lượng KHÔNG PHẢI một
136	            // shift X thuần tuý (−30 X, +0.4 Y) để mô phỏng vừa pitch cơ khí vừa sai lệch nhỏ
137	            // ngoài trục X, bắt được bài test nào lỡ giả định "Tool2 = Tool1 trừ hằng số X" thay
138	            // vì đọc đúng lưới riêng của Tool2 (Tuấn xác nhận 2026-09-05).
139	            const double pitchX = 30.0, skewY = 0.4;
140	
141	            m.InputTray.Rows = 4; m.InputTray.Cols = 5;
142	            m.InputTray.GeoZ1.P00 = new TeachPoint(150, 50);
143	            m.InputTray.GeoZ1.P0C = new TeachPoint(230, 50);      // 4 bước × 20 mm
144	            m.InputTray.GeoZ1.PR0 = new TeachPoint(150, 125);     // 3 bước × 25 mm
145	            m.InputTray.GeoZ2.P00 = new TeachPoint(150 - pitchX, 50 + skewY);
146	            m.InputTray.GeoZ2.P0C = new TeachPoint(230 - pitchX, 50 + skewY);
147	            m.InputTray.GeoZ2.PR0 = new TeachPoint(150 - pitchX, 125 + skewY);
148	            // Z dương là chiều ĐI XUỐNG, "an toàn" (Z_SAFE mặc định 50) là vị trí NHỎ (Tuấn xác
149	            // nhận 2026-09-04) — Z_Pick phải LỚN HƠN Z_SAFE để mô phỏng đúng "đã hạ xuống, chưa
150	            // an toàn", nếu không chốt chặn Z_SAFE không được bài test nào chạy qua thật sự. Z1/Z2
151	            // cố ý lệch nhau 1 mm — số giả, chỉ để bài test không vô tình phụ thuộc vào việc hai
152	            // tay hút luôn cùng cao độ (Tuấn xác nhận 2026-09-05: hai tay không nhất thiết bằng nhau).
153	            m.InputTray.Z_PickZ1 = 90;
154	            m.InputTray.Z_PickZ2 = 91;
155	
156	            m.AssyTray.Rows = 5; m.AssyTray.Cols = 6;
157	            m.AssyTray.GeoZ1.P00 = new TeachPoint(350, 60);
158	            m.AssyTray.GeoZ1.P0C = new TeachPoint(460, 60);       // 5 bước × 22 mm
159	            m.AssyTray.GeoZ1.PR0 = new TeachPoint(350, 164);      // 4 bước × 26 mm
160	            m.AssyTray.GeoZ2.P00 = new TeachPoint(350 - pitchX, 60 + skewY);
161	            m.AssyTray.GeoZ2.P0C = new TeachPoint(460 - pitchX, 60 + skewY);
162	            m.AssyTray.GeoZ2.PR0 = new TeachPoint(350 - pitchX, 164 + skewY);
163	            m.AssyTray.Z_PickZ1 = 95;
164	            m.AssyTray.Z_PickZ2 = 96;
165	
166	            // CAM bottom-up cố định ở X = 300 (toạ độ của đầu hút khi nằm giữa khung hình), teach
167	            // riêng từng Tool nên không suy ra từ pitch nữa.
168	            m.AlignPosX_Nozzle1 = 300;
169	            m.AlignPosX_Nozzle2 = 300 - pitchX;
170	
171	            // FOV 30 mm trải trên 1280 pixel — khớp ảnh giả của FakeVision (tâm 640×480).
172	            const double mmPerPixel = 30.0 / 1280.0;
173	            m.Calib.BottomUp = CameraCalib.CreateSimulation(mmPerPixel, 640, 480);
174	            m.Calib.TopDown = CameraCalib.CreateSimulation(mmPerPixel, 640, 480);
175	
176	            m.Calib.HandEye1Dx = -40; m.Calib.HandEye1Dy = 5;
177	            m.Calib.HandEye2Dx = -10; m.Calib.HandEye2Dy = 5;
178	            m.Calib.BottomUpYSign = 1;
179	            m.Calib.BottomUpYSignVerifiedAt = DateTime.Now;
180	
181	            // Mốc CAM top-down = vị trí camera khi soi Ô (1,1) của Assy Tray — giữ tương đương
182	            // công thức cũ (cellPos(0,0) trừ Hand-Eye tay #1) để hành vi mô phỏng không đổi.
183	            m.AssyTray.CamTopDownAnchorX = m.AssyTray.GeoZ1.P00.X - m.Calib.HandEye1Dx;
184	            m.AssyTray.CamTopDownAnchorY = m.AssyTray.GeoZ1.P00.Y - m.Calib.HandEye1Dy;
185	            m.AssyTray.CamTopDownAnchorTaught = true;
186	
187	            return m;
188	        }
189	    }
190	}
