203	        /// <summary>
204	        /// Giá trị mặc định để app chạy được ngay lần đầu. Phần lớn số ở đây (tốc độ, soft
205	        /// limit, vị trí chờ, gốc toạ độ/điểm 0, dấu <c>HomeDir</c> của X/Y1/Y2/A1/A2) là PHỎNG
206	        /// ĐOÁN, phải xác định lại trên máy thật ở P1 (PLAN.md §11 #6) — phụ thuộc vị trí lắp
207	        /// cảm biến gốc thật. Ba thứ đã chốt sẵn, không phải xác định lại:
208	        /// <list type="bullet">
209	        /// <item><b>Chiều dương từng trục</b> (Tuấn chốt 2026-09-07, PLAN.md §11 #6) — xem ghi
210	        /// chú tại từng case bên dưới (X, Y1/Y2, A1/A2) và Z1/Z2.</item>
211	        /// <item><c>HomeDir</c> của Z1/Z2 là -1 (về gốc đi lên, nhưng quy ước "xuống = dương" nên
212	        /// đi lên là chiều âm — xem ghi chú tại case Z1/Z2 bên dưới).</item>
213	        /// <item><c>PulsePerUnit</c> là hằng số theo thiết kế (1000 xung/mm Panasonic, 10000
214	        /// xung/360° Fastech) — cấu hình driver khớp nó, không đo nó.</item>
215	        /// </list>
216	        /// </summary>
217	        private static AxisConfig DefaultAxis(string name)
218	        {
219	            var cfg = new AxisConfig { Name = name };
220	
221	            switch (name)
222	            {
223	                case AxisId.X:
224	                    // ĐÃ CHỐT (Tuấn, 2026-09-07, PLAN.md §11 #6): nhìn từ phía người thao tác,
225	                    // chiều dương của X là TRÁI → PHẢI. HomeDir = -1 dưới đây vẫn là PHỎNG ĐOÁN —
226	                    // dấu thật phụ thuộc cảm biến gốc lắp ở đầu trái hay đầu phải, xác định ở P1.
227	                    cfg.Kind = EAxisKind.Panasonic; cfg.ComPort = "COM3"; cfg.UnitId = 1;
228	                    cfg.Unit = "mm"; cfg.SoftLimitNeg = -1; cfg.SoftLimitPos = 600;
229	                    cfg.JogSpeedSlow = 30; cfg.JogSpeedFast = 60; cfg.MoveSpeed = 300; cfg.HomeDir = -1; cfg.StandbyPos = 100;
230	                    cfg.PulsePerUnit = 1000.0;         // ĐÃ CHỐT: 1000 xung/mm, cấu hình trong driver
231	                    // ĐÃ CHỐT (Tuấn xác nhận qua PANATERM, 2026-09-09): trục X dùng động cơ tuyến
232	                    // tính Alpharobot ALR160-S1 + driver Panasonic A6L — KHÔNG có "vòng quay" vật
233	                    // lý như trục vít me. Driver quy đổi tốc độ rpm dựa trên bước cực từ (magnetic
234	                    // pole pitch), đọc trực tiếp từ Pr9.02 trên driver = 27.00mm — PHẢI dùng đúng
235	                    // số này cho UnitPerRev, không phải mặc định 10.0 (vốn là bước vít me của các
236	                    // trục Y/Z). Nếu để sai, AxisScale.ToRpm quy đổi lệch, khiến tốc độ thực trên
237	                    // trục X khác hẳn giá trị mm/s cấu hình (không ảnh hưởng độ chính xác vị trí,
238	                    // vì đó là việc của PulsePerUnit — độc lập với UnitPerRev).
239	                    cfg.UnitPerRev = 27.0;
240	                    break;
241	
242	                case AxisId.Z1:
243	                case AxisId.Z2:
244	                    cfg.Kind = EAxisKind.Panasonic;
245	                    cfg.ComPort = name == AxisId.Z1 ? "COM4" : "COM5";
246	                    cfg.UnitId = 1; cfg.Unit = "mm";
247	                    cfg.SoftLimitNeg = -1; cfg.SoftLimitPos = 120;
248	                    cfg.JogSpeedSlow = 15; cfg.JogSpeedFast = 30; cfg.MoveSpeed = 150;
249	                    // ĐÃ CHỐT (Tuấn xác nhận 2026-09-04, PLAN.md §4.3): cảm biến gốc ở phía TRÊN
250	                    // hành trình, gán toạ độ gốc = 0 — KHÔNG lệch như trục khác. Chiều dương của Z
251	                    // là chiều ĐI XUỐNG (xuống gần bàn/khay = giá trị tăng), ngược với X/Y/A —
252	                    // "an toàn" (rút lên) là vị trí NHỎ, xem MotionConnect.ZSafeOk (≤ Z_SAFE, không
253	                    // phải ≥). Về gốc đi LÊN — dưới quy ước "xuống = dương" thì đi lên là chiều
254	                    // ÂM, nên HomeDir = -1 (không phải +1 như trục khác).
255	                    cfg.HomeDir = -1;
256	                    cfg.PulsePerUnit = 1000.0;         // ĐÃ CHỐT: 1000 xung/mm, cấu hình trong driver
257	                    // StandbyPos nhỏ hơn Z_SAFE — vẫn còn rất gần gốc, an toàn.
258	                    cfg.HomeOffset = 0; cfg.StandbyPos = 10;
259	                    break;
260	
261	                case AxisId.Y1:
262	                case AxisId.Y2:
263	                    // ĐÃ CHỐT (Tuấn, 2026-09-07, PLAN.md §11 #6): chiều dương của Y là từ PHÍA
264	                    // TRONG đi RA phía người thao tác. HomeDir = -1 dưới đây vẫn là PHỎNG ĐOÁN —
265	                    // dấu thật phụ thuộc cảm biến gốc lắp ở đầu trong hay đầu ngoài, xác định ở P1.
266	                    cfg.Kind = EAxisKind.Panasonic;
267	                    cfg.ComPort = name == AxisId.Y1 ? "COM6" : "COM7";
268	                    cfg.UnitId = 1; cfg.Unit = "mm";
269	                    cfg.SoftLimitNeg = -1; cfg.SoftLimitPos = 400;
270	                    cfg.JogSpeedSlow = 30; cfg.JogSpeedFast = 60; cfg.MoveSpeed = 250; cfg.HomeDir = -1; cfg.StandbyPos = 20;
271	                    cfg.PulsePerUnit = 1000.0;         // ĐÃ CHỐT: 1000 xung/mm, cấu hình trong driver
272	                    break;
273	
274	                case AxisId.A1:
275	                case AxisId.A2:
276	                    // ĐÃ CHỐT (Tuấn, 2026-09-07, PLAN.md §11 #6): nhìn từ TRÊN XUỐNG, chiều dương
277	                    // của A1/A2 là NGƯỢC CHIỀU KIM ĐỒNG HỒ (CCW). HomeDir = +1 dưới đây vẫn là
278	                    // PHỎNG ĐOÁN — dấu thật phụ thuộc cảm biến gốc nằm ở góc nào, xác định ở P1.
279	                    cfg.Kind = EAxisKind.Fastech;
280	                    cfg.IpAddress = name == AxisId.A1 ? "192.168.0.2" : "192.168.0.3";
281	                    cfg.BoardId = name == AxisId.A1
282	                        ? Lib.Fastech.FastechBoardId.AxisA1
283	                        : Lib.Fastech.FastechBoardId.AxisA2;
284	                    cfg.AxisIndex = 0; cfg.Unit = "deg";
285	                    cfg.SoftLimitNeg = -360; cfg.SoftLimitPos = 360;
286	                    cfg.JogSpeedSlow = 45; cfg.JogSpeedFast = 90; cfg.MoveSpeed = 180;
287	                    cfg.PulsePerUnit = 10000.0 / 360.0; cfg.UnitPerRev = 360;   // ĐÃ CHỐT: 10000 xung/360°
288	                    cfg.HomeDir = +1; cfg.StandbyPos = 0;
289	                    break;
290	            }
291	
292	            return cfg;
293	        }
294	    }
