253	        /// <summary>Điều kiện cho phép chạy — PLAN.md §5.1, xét lại ở đầu mỗi vòng.</summary>
254	        private bool CanRun(out string why)
255	        {
256	            why = null;
257	
258	            if (!_status.OrgOk) { why = "chưa về gốc"; return false; }
259	            if (_status.Mode != EMcMode.Auto) { why = "chìa không ở vị trí AUTO"; return false; }
260	            if (AlarmManager.HasError) { why = "còn alarm chưa xoá"; return false; }
261	
262	            var model = Model;
263	            if (model == null) { why = "chưa nạp model"; return false; }
264	            if (!model.InputTray.IsTaught) { why = "tray đầu vào chưa teach"; return false; }
265	            if (!model.AssyTray.IsTaught) { why = "tray lắp ráp chưa teach"; return false; }
266	            // IsUsable chỉ còn đòi 2 camera (BottomUp checkerboard §6.3 + TopDown §6.2) — tâm
267	            // xoay/Master của AlignBottom nay hiệu chuẩn trong VisionMaster, App không còn tự
268	            // kiểm được nên không còn nằm trong điều kiện này (PLAN.md §6.4, Tuấn chốt 2026-09-08).
269	            if (!model.Calib.IsUsable) { why = "chưa hiệu chuẩn đủ 2 camera"; return false; }
270	
271	            int validDays = _sys().CalibValidDays;
272	            if (model.Calib.BottomUp.IsExpired(validDays) || model.Calib.TopDown.IsExpired(validDays))
273	                AlarmManager.Raise(AlarmCode.VisionCalibExpired, "Vision",
274	                    "quá " + validDays + " ngày kể từ lần hiệu chuẩn gần nhất");
275	
276	            // Kiểm tra ở đây để "chưa nạp solution" hiện ra đúng như nó là, chứ không biến thành
277	            // một chuỗi NG vision mà người vận hành sẽ đi tìm nguyên nhân ở camera và đèn.
278	            var vision = _vision();
279	            if (vision == null || !vision.IsConnected) { why = "chưa kết nối vision"; return false; }
280	            if (!vision.IsSolutionLoaded) { why = "chưa nạp solution vision"; return false; }
281	
282	            if (!_func.HasTrayIn()) { why = "không có tray đầu vào"; return false; }
283	            if (!_func.HasTrayAssy()) { why = "không có tray lắp ráp"; return false; }
284	
285	            return true;
286	        }
