288	        // ───────────────────────── S10 / S11 — hút ─────────────────────────
289	
290	        private async Task<bool> S1x_Pick(int nozzle, EAutoState next, CancellationToken ct)
291	        {
292	            var nz = Nozzle(nozzle);
293	
294	            // Đã có sản phẩm sẵn trên tay (chạy tiếp sau khi dừng) thì bỏ qua bước hút.
295	            if (nz.HasProduct) { Run.AutoState = next; return true; }
296	
297	            var tray = Run.InputTray;
298	            int index = NextLoadedCell(tray);
299	            if (index < 0)
300	            {
301	                // Hết tray đầu vào. Nếu tay #1 cũng chưa có gì thì phải đổi tray trước khi
302	                // làm gì tiếp; nếu tay #1 đã có hàng thì chạy nốt sản phẩm đó rồi mới đổi.
303	                if (nozzle == 2 && Nozzle(1).HasProduct) { Run.AutoState = EAutoState.S20_Align1; return true; }
304	                Run.AutoState = EAutoState.S50_TrayCheck;
305	                return true;
306	            }
307	
308	            tray.CurrentIndex = index;
309	            int row, col;
310	            tray.RowCol(index, out row, out col);
311	
312	            string zName = nozzle == 1 ? AxisId.Z1 : AxisId.Z2;
313	            var cell = Model.InputTray.CellPos(zName, row, col);
314	
315	            tray.Set(index, ECellState.Processing);
316	
317	            int retries = _sys().PickRetryCount;
318	            for (int attempt = 0; attempt <= retries; attempt++)
319	            {
320	                if (!await _func.MoveToCellAsync(Model.InputTray.AxisRow, cell.Y, cell.X, ct).ConfigureAwait(false))
321	                    return Halt("không tới được ô hút (" + row + "," + col + ")");
322	
323	                // Hút hụt thì hạ thêm một ít: nguyên nhân phổ biến nhất là sản phẩm nằm thấp
324	                // hơn dự kiến trong hốc tray, không phải hỏng chân không (§5.4). Z dương là
325	                // chiều ĐI XUỐNG (Tuấn xác nhận 2026-09-04) nên "hạ thêm" là CỘNG thêm, không
326	                // phải trừ.
327	                double zPick = Model.InputTray.ZPickFor(zName) + attempt * _sys().PickRetryDeltaZ;
328	
329	                if (!await _func.MoveAsync(zName, zPick, ZSpeed(zName), ct).ConfigureAwait(false))
330	                    return Halt(zName + " không hạ được xuống cao độ hút");
331	
332	                _func.SetVacuum(nozzle, true);
333	                bool gripped = await WaitVacuumAsync(nozzle, true, ct).ConfigureAwait(false);
334	
335	                if (!await _func.MoveAsync(zName, SafeZ(), ZSpeed(zName), ct).ConfigureAwait(false))
336	                    return Halt(zName + " không nâng lên được");
337	
338	                if (gripped)
339	                {
340	                    nz.HasProduct = true;
341	                    nz.SourceCellIndex = index;
342	                    nz.Aligned = false;
343	                    Run.AutoState = next;
344	                    return true;
345	                }
346	
347	                _func.SetVacuum(nozzle, false);
348	                AlarmManager.Raise(AlarmCode.PickFailed, "Auto",
349	                    string.Format("tay #{0}, ô ({1},{2}), lần thử {3}/{4}",
350	                        nozzle, row, col, attempt + 1, retries + 1));
351	            }
352	
353	            // Hết số lần thử: đánh dấu ô hỏng và đi tiếp, KHÔNG dừng máy. Một ô lỗi không phải
354	            // lý do để cả tray đứng lại (§5.4).
355	            AlarmManager.ClearCondition(AlarmCode.PickFailed);
356	            tray.Set(index, ECellState.Ng);
357	            CountNg("hút hụt ô (" + row + "," + col + ")");
358	            return CheckConsecutiveNg();
359	        }
