409	        private async Task<bool> S3x_LocateAndPlace(int nozzle, EAutoState next, CancellationToken ct)
410	        {
411	            var nz = Nozzle(nozzle);
412	            if (!nz.HasProduct) { Run.AutoState = next; return true; }
413	
414	            // Chạy lại sau khi tắt app: trạng thái bước nằm trên đĩa nhưng tư thế đo được thì
415	            // không — nó chỉ có nghĩa cho đúng lần chụp đó. Đo lại thay vì dùng số cũ hoặc coi
416	            // như hỏng hàng.
417	            if (_bottomPose[nozzle] == null)
418	            {
419	                // S20_Align1 soi tay #2 trước, S21_Align2 soi tay #1 (Tuấn xác nhận 2026-09-05) —
420	                // ánh xạ ngược lại với thứ tự nozzle số vì tên BƯỚC không đổi theo.
421	                Run.AutoState = nozzle == 1 ? EAutoState.S21_Align2 : EAutoState.S20_Align1;
422	                LogWorker.Instance.RecordLog(
423	                    "Chưa có tư thế đo của tay #" + nozzle + " — soi lại trước khi đặt",
424	                    Utility.Log.LogLevel.Info, "Auto");
425	                return true;
426	            }
427	
428	            var tray = Run.AssyTray;
429	            int index = NextFreeCell(tray);
430	            if (index < 0)
431	            {
432	                // Hết ô lắp ráp mà tay vẫn còn hàng: giữ nguyên sản phẩm, đi đổi tray. Trạng
433	                // thái tay hút đã ghi xuống đĩa nên đổi xong quay lại đặt tiếp được.
434	                Run.AutoState = EAutoState.S50_TrayCheck;
435	                return true;
436	            }
437	
438	            tray.CurrentIndex = index;
439	            int row, col;
440	            tray.RowCol(index, out row, out col);
441	            tray.Set(index, ECellState.Processing);
442	
443	            VisionPose top;
444	            double captureX, captureY;
445	
446	            AssyCellScan scan;
447	            if (_assyScan.TryGetValue(index, out scan))
448	            {
449	                // Đường thường: đã có sẵn từ S05_ScanAssy — không di chuyển CAM, không trigger
450	                // gì nữa, đúng phần rút ngắn chu kỳ mà thay đổi này nhắm tới. Dùng rồi thì bỏ
451	                // khỏi cache — ô này coi như đã tiêu thụ, tránh dùng nhầm nếu ô bị gán lại.
452	                top = scan.Top;
453	                captureX = scan.CaptureX;
454	                captureY = scan.CaptureY;
455	                _assyScan.Remove(index);
456	            }
457	            else
458	            {
459	                // Dự phòng: quét trước chưa kịp phủ ô này (vd. tray bị đổi hoặc cache bị dọn
460	                // giữa chừng) — đo trực tiếp như cách làm cũ, để việc đặt hàng KHÔNG BAO GIỜ phụ
461	                // thuộc bắt buộc vào việc đã quét trước hay chưa.
462	                var cell = Model.AssyTray.CellPos(AxisId.Z1, row, col);
463	                var cell00 = Model.AssyTray.CellPos(AxisId.Z1, 0, 0);
464	                double camX = Model.AssyTray.CamTopDownAnchorX + (cell.X - cell00.X);
465	                double camY = Model.AssyTray.CamTopDownAnchorY + (cell.Y - cell00.Y);
466	
467	                if (!await _func.MoveToCellAsync(Model.AssyTray.AxisRow, camY, camX, ct).ConfigureAwait(false))
468	                    return Halt("không tới được vị trí soi ô đích (" + row + "," + col + ")");
469	
470	                captureX = _motion[AxisId.X].CurrentPos;
471	                captureY = _motion[Model.AssyTray.AxisRow].CurrentPos;
472	                top = await TriggerAsync(EVisionProcedure.LocateTop, ct).ConfigureAwait(false);
473	            }
474	
475	            if (top == null || !top.Found)
476	            {
477	                // Không thấy chi tiết đích: bỏ qua ô đó, GIỮ sản phẩm sang ô kế tiếp. Sản phẩm
478	                // trên tay còn tốt, không có lý do gì loại nó vì ô đích trống (§5.4).
479	                AlarmManager.Raise(AlarmCode.VisionNotFound, "Vision",
480	                    "LocateTop ô (" + row + "," + col + ")" + (top == null ? "" : ": " + top.Error));
481	                tray.Set(index, ECellState.Skipped);
482	                AlarmManager.ClearCondition(AlarmCode.VisionNotFound);
483	                return true;      // ở nguyên bước này, vòng sau lấy ô kế
484	            }
485	
486	            var sys = _sys();
487	            var sol = PlacementSolver.Solve(Model.Calib, nozzle, _bottomPose[nozzle], top,
488	                captureX, captureY, sys.MaxCompensationAngleDeg, sys.MaxCompensationDistance);
489	
490	            if (!sol.Ok)
491	            {
492	                AlarmManager.Raise(AlarmCode.CompensationOutOfRange, "Auto",
493	                    "tay #" + nozzle + ": " + sol.Reason);
494	                tray.Set(index, ECellState.Empty);
495	                if (!await ReturnToSourceAsync(nozzle, ct).ConfigureAwait(false)) return false;
496	                AlarmManager.ClearCondition(AlarmCode.CompensationOutOfRange);
497	                CountNg("lượng bù vượt ngưỡng tay #" + nozzle);
498	                return CheckConsecutiveNg();
499	            }
500	
501	            _status.LastDeltaTheta = sol.DeltaThetaDeg;
502	            _status.LastPlaceError = sol.ErrDistance;
503	
504	            if (!await PlaceAsync(nozzle, sol, ct).ConfigureAwait(false)) return false;
505	
506	            tray.Set(index, ECellState.Ok);
507	            Run.CountOk++;
508	            Run.CountTotal++;
509	            Run.ConsecutiveNg = 0;
510	
511	            int src = nz.SourceCellIndex;
512	            if (src >= 0) Run.InputTray.Set(src, ECellState.Ok);
513	
514	            nz.HasProduct = false;
515	            nz.SourceCellIndex = -1;
516	            nz.Aligned = false;
517	            _bottomPose[nozzle] = null;
518	
519	            Save();
520	            Run.AutoState = next;
521	            return true;
522	        }
