8	    /// <summary>
9	    /// Vision mô phỏng. Trả về tư thế quanh tâm ảnh với nhiễu ngẫu nhiên, kèm xác suất
10	    /// không tìm thấy / điểm số thấp để chạy được nhánh NG của chuỗi Auto (PLAN.md §5.4).
11	    /// </summary>
12	    public class FakeVision : Bindable, IVisionDevice
13	    {
14	        private readonly Random _rng = new Random(20260731);
15	
16	        private bool _connected;
17	        public bool IsConnected { get => _connected; private set => SetProperty(ref _connected, value); }
18	
19	        private bool _loaded;
20	        public bool IsSolutionLoaded { get => _loaded; private set => SetProperty(ref _loaded, value); }
21	
22	        /// <summary>Thời gian chụp + xử lý giả lập, ms.</summary>
23	        public int ProcessTimeMs { get; set; } = 120;
24	
25	        /// <summary>Xác suất tìm thấy đối tượng.</summary>
26	        public double FoundRate { get; set; } = 1.0;
27	
28	        /// <summary>Độ lệch tối đa mô phỏng quanh tâm, pixel.</summary>
29	        public double NoisePixel { get; set; } = 12.0;
30	
31	        /// <summary>Độ lệch góc tối đa mô phỏng, độ.</summary>
32	        public double NoiseAngle { get; set; } = 4.0;
33	
34	        /// <summary>Độ lệch tối đa mô phỏng cho AlignBottomTool1/2 và AlignCalibTool1/2, mm —
35	        /// khác <see cref="NoisePixel"/>: hai procedure này đã tự hiệu chuẩn tâm xoay + Teach
36	        /// Master bên trong VisionMaster (PLAN.md §6.4), nên PixelX/PixelY trả về là ĐỘ LỆCH mm
37	        /// đã bù sẵn, dao động quanh 0 chứ không phải quanh tâm ảnh 640/480 như procedure còn lại.</summary>
38	        public double NoiseAlignMm { get; set; } = 0.3;
39	
40	        /// <summary>Số lần đã trigger từng Flow — để --selftest kiểm chứng những thay đổi kiểu
41	        /// "bớt chụp lại" (vd. S05_ScanAssy) thật sự bớt trigger chứ không chỉ vẫn ra đúng kết quả
42	        /// theo cách cũ (nhiều trigger hơn) mà tình cờ vẫn đạt.</summary>
43	        public int AlignBottomCount { get; private set; }
44	        public int LocateTopCount { get; private set; }
45	
46	        // Mô phỏng không có camera thật để chụp — luôn null, trang Main tự hiện chỗ trống thay
47	        // vì hình khi chạy --selftest/dev không có máy.
48	        public System.Drawing.Bitmap LastTopDownImage => null;
49	        public System.Drawing.Bitmap LastBottomUpImage => null;
