62	        public async Task<VisionPose> TriggerAsync(EVisionProcedure procedure, CancellationToken ct)
63	        {
64	            if (!IsConnected) return VisionPose.NotFound("chưa kết nối");
65	            if (!IsSolutionLoaded) return VisionPose.NotFound("chưa nạp solution");
66	
67	            bool isAlign = procedure == EVisionProcedure.AlignBottomTool1 ||
68	                           procedure == EVisionProcedure.AlignBottomTool2;
69	            bool isAlignCalib = procedure == EVisionProcedure.AlignCalibTool1 ||
70	                                procedure == EVisionProcedure.AlignCalibTool2;
71	            if (isAlign) AlignBottomCount++;
72	            else if (procedure == EVisionProcedure.LocateTop) LocateTopCount++;
73	
74	            await Task.Delay(ProcessTimeMs, ct).ConfigureAwait(false);
75	
76	            if (_rng.NextDouble() > FoundRate)
77	                return VisionPose.NotFound("không tìm thấy đối tượng");
78	
79	            // AlignBottomTool1/2 và AlignCalibTool1/2 đã tự hiệu chuẩn + Teach bên trong
80	            // VisionMaster (PLAN.md §6.4) — PixelX/PixelY mô phỏng phải là ĐỘ LỆCH mm quanh 0,
81	            // không phải pixel quanh tâm ảnh 640/480 như procedure còn lại.
82	            if (isAlign || isAlignCalib)
83	            {
84	                return new VisionPose
85	                {
86	                    Found = true,
87	                    PixelX = (_rng.NextDouble() - 0.5) * 2 * NoiseAlignMm,
88	                    PixelY = (_rng.NextDouble() - 0.5) * 2 * NoiseAlignMm,
89	                    Angle = (_rng.NextDouble() - 0.5) * 2 * NoiseAngle,
90	                    Score = 85 + _rng.NextDouble() * 14
91	                };
92	            }
93	
94	            return new VisionPose
95	            {
96	                Found = true,
97	                PixelX = 640 + (_rng.NextDouble() - 0.5) * 2 * NoisePixel,
98	                PixelY = 480 + (_rng.NextDouble() - 0.5) * 2 * NoisePixel,
99	                Angle = (_rng.NextDouble() - 0.5) * 2 * NoiseAngle,
100	                Score = 85 + _rng.NextDouble() * 14
101	            };
102	        }
103	
104	        /// <summary>Scale mô phỏng: khớp <c>CameraCalib.CreateSimulation</c> (30 mm / 1280 px).</summary>
105	        public double SimScaleMmPerPixel { get; set; } = 30.0 / 1280.0;
106	
107	        public async Task<CalibBoardResult> TriggerCalibBoardAsync(CancellationToken ct)
108	        {
109	            if (!IsConnected) return CalibBoardResult.NotFound("chưa kết nối");
110	            if (!IsSolutionLoaded) return CalibBoardResult.NotFound("chưa nạp solution");
111	
112	            await Task.Delay(ProcessTimeMs, ct).ConfigureAwait(false);
113	
114	            if (_rng.NextDouble() > FoundRate)
115	                return CalibBoardResult.NotFound("không thấy đủ góc trên bản chuẩn");
116	
117	            // Nhiễu nhỏ quanh scale mô phỏng, độ không vuông góc gần 0 — đúng tính chất một
118	            // bản chuẩn chrome-on-glass thật (PLAN.md §6.3 điều kiện 2, 3).
119	            double noise = 1.0 + (_rng.NextDouble() - 0.5) * 0.01;
120	            return new CalibBoardResult
121	            {
122	                Found = true,
123	                ScaleU = SimScaleMmPerPixel * noise,
124	                ScaleV = SimScaleMmPerPixel * (2.0 - noise),
125	                SkewDeg = (_rng.NextDouble() - 0.5) * 0.2,
126	                CornerCount = 841,
127	                // Không mô phỏng vật lý ống kính di chuyển theo trục X thật, nên giá trị này gần
128	                // như đứng yên qua các lần gọi — đủ để kiểm chứng CÔNG THỨC đối chiếu chéo B3 báo
129	                // đúng "không khớp" khi không có dữ liệu chuyển động thật đi kèm.
130	                OriginPixelU = 640 + (_rng.NextDouble() - 0.5) * 2 * NoisePixel,
131	                OriginPixelV = 480 + (_rng.NextDouble() - 0.5) * 2 * NoisePixel
132	            };
133	        }
134	    }
135	}
