14	    /// <summary>Trang Setting: tham số hệ thống và cấu hình 7 trục.</summary>
15	    public class SettingViewModel : ObservableObject
16	    {
17	        public SettingViewModel()
18	        {
19	            foreach (var cfg in McDataManager.SysData.Axes)
20	                AxisConfigs.Add(cfg);
21	
22	            SaveCommand = new RelayCommand(() =>
23	            {
24	                McDataManager.SysData.ZSafe = ZSafe;
25	                McControl.Motion.ZSafe = ZSafe;
26	                SaveResult = McDataManager.SaveSystemData()
27	                    ? "Đã lưu system.json. Đổi COM/IP/Simulation cần khởi động lại app."
28	                    : "Lưu thất bại — xem alarm.";
29	            });
30	
31	            OpenDataFolderCommand = new RelayCommand(() =>
32	            {
33	                try { Process.Start("explorer.exe", AppPaths.Root); } catch { }
34	            });
35	
36	            BrowseVisionSolutionCommand = new RelayCommand(() =>
37	            {
38	                var dlg = new OpenFileDialog
39	                {
40	                    Filter = "VisionMaster solution (*.sol)|*.sol|Tất cả file|*.*",
41	                    CheckFileExists = true
42	                };
43	                if (dlg.ShowDialog() == true) VisionSolutionPath = dlg.FileName;
44	            });
45	
46	            // Nạp lại ngay để có hiệu lực không cần khởi động lại app — khác với tên Flow/Output
47	            // (VisionConnect đọc lại mỗi lần trigger, không cần bước riêng), đường dẫn solution
48	            // chỉ được VmSolution đọc MỘT LẦN lúc Init nên phải chủ động gọi lại.
49	            ReloadVisionSolutionCommand = new RelayCommand(() =>
50	            {
51	                McDataManager.SaveSystemData();
52	                McControl.ReloadVisionSolution();
53	                VisionReloadResult = "Đã yêu cầu nạp lại — xem log/alarm Vision để biết kết quả.";
54	            });
55	
56	            ZSafe = McDataManager.SysData.ZSafe;
57	        }
