196	        /// sang thẳng S10 — sau lần quét đầu của một tray, các vòng S00 sau chỉ tốn một lượt kiểm
197	        /// tra rỗng rồi đi tiếp ngay, không quét lại (§5.2b).
198	        /// </summary>
199	        private async Task<bool> S05_ScanAssy(CancellationToken ct)
200	        {
201	            var tray = Run.AssyTray;
202	            int index = NextUnscannedCell(tray);
203	            if (index < 0)
204	            {
205	                Run.AutoState = EAutoState.S10_Pick1;
206	                return true;
207	            }
208	
209	            int row, col;
210	            tray.RowCol(index, out row, out col);
211	
212	            // Mốc tay #1 cố định cho mọi ô — xem ghi chú ở _assyScan. Vị trí camera lấy từ mốc đã
213	            // teach trực tiếp (CamTopDownAnchorX/Y, xem TrayLayout) cộng độ lệch lưới tính theo
214	            // lưới của Tool1 so với ô (1,1) — không còn qua Hand-Eye Dx/Dy nữa (Tuấn xác nhận
215	            // 2026-09-05, xem ghi chú ở CamTopDownAnchorX).
216	            var cell = Model.AssyTray.CellPos(AxisId.Z1, row, col);
217	            var cell00 = Model.AssyTray.CellPos(AxisId.Z1, 0, 0);
218	            double camX = Model.AssyTray.CamTopDownAnchorX + (cell.X - cell00.X);
219	            double camY = Model.AssyTray.CamTopDownAnchorY + (cell.Y - cell00.Y);
220	
221	            if (!await _func.MoveToCellAsync(Model.AssyTray.AxisRow, camY, camX, ct).ConfigureAwait(false))
222	                return Halt("không tới được vị trí soi ô đích lúc quét trước (" + row + "," + col + ")");
223	
224	            double captureX = _motion[AxisId.X].CurrentPos;
225	            double captureY = _motion[Model.AssyTray.AxisRow].CurrentPos;
226	
227	            var top = await TriggerAsync(EVisionProcedure.LocateTop, ct).ConfigureAwait(false);
228	            if (top == null || !top.Found)
229	            {
230	                // Không thấy chi tiết đích ngay từ vòng quét: bỏ ô này luôn, không chờ tới lúc
231	                // đặt mới phát hiện — cùng cách xử lý với nhánh not-found cũ ở S3x.
232	                AlarmManager.Raise(AlarmCode.VisionNotFound, "Vision",
233	                    "LocateTop (quét trước) ô (" + row + "," + col + ")" + (top == null ? "" : ": " + top.Error));
234	                tray.Set(index, ECellState.Skipped);
235	                AlarmManager.ClearCondition(AlarmCode.VisionNotFound);
236	                Save();
237	                return true;      // ở nguyên S05, vòng sau lấy ô kế
238	            }
239	
240	            _assyScan[index] = new AssyCellScan { Top = top, CaptureX = captureX, CaptureY = captureY };
241	            Save();
242	            return true;          // ở nguyên S05 cho tới khi NextUnscannedCell hết ô
243	        }
244	
245	        /// <summary>Ô lắp ráp còn trống và CHƯA có kết quả quét trước.</summary>
246	        private int NextUnscannedCell(TrayState tray)
247	        {

524	        /// <summary>Xoay, di chuyển tới điểm đã bù, hạ, nhả, nâng.</summary>
525	        private async Task<bool> PlaceAsync(int nozzle, PlaceSolution sol, CancellationToken ct)
526	        {
527	            string aName = nozzle == 1 ? AxisId.A1 : AxisId.A2;
528	            string zName = nozzle == 1 ? AxisId.Z1 : AxisId.Z2;
529	            string yName = Model.AssyTray.AxisRow;
530	
531	            // Trục A chạy song song với X/Y2 — xoay không tốn thêm thời gian chu kỳ.
532	            double aTarget = _motion[aName].CurrentPos + sol.DeltaThetaDeg;
533	
534	            var moves = new Task<bool>[]
535	            {
536	                _func.MoveAsync(aName, aTarget, MoveSpeed(aName), ct),
537	                _func.MoveAsync(AxisId.X, sol.CommandX, MoveSpeed(AxisId.X), ct),
538	                _func.MoveAsync(yName, sol.CommandY, MoveSpeed(yName), ct)
539	            };
540	
541	            var results = await Task.WhenAll(moves).ConfigureAwait(false);
542	            foreach (bool r in results)
543	                if (!r) return Halt("không tới được điểm đặt của tay #" + nozzle);
544	
545	            if (!await _func.MoveAsync(zName, Model.AssyTray.ZPickFor(zName), ZSpeed(zName), ct).ConfigureAwait(false))
546	                return Halt(zName + " không hạ được xuống cao độ đặt");
547	
548	            _func.SetVacuum(nozzle, false);
549	            _func.SetBlow(nozzle, true);
550	
551	            bool released = await WaitVacuumAsync(nozzle, false, ct).ConfigureAwait(false);
552	            await Task.Delay(_sys().BlowTimeMs, ct).ConfigureAwait(false);
553	            _func.SetBlow(nozzle, false);
554	
555	            if (!await _func.MoveAsync(zName, SafeZ(), ZSpeed(zName), ct).ConfigureAwait(false))
556	                return Halt(zName + " không nâng lên được sau khi đặt");
557	
558	            if (!released)
559	            {
560	                // Cảm biến vẫn báo có sản phẩm sau khi thổi: hoặc sản phẩm dính lại trên đầu
561	                // hút, hoặc cảm biến hỏng. Cả hai đều phải người xem, không được chạy tiếp.
562	                AlarmManager.Raise(AlarmCode.PlaceFailed, "Auto",
563	                    "tay #" + nozzle + " vẫn báo còn sản phẩm sau khi nhả");
564	                return Halt("nhả sản phẩm không thành công ở tay #" + nozzle);
565	            }
566	
567	            return true;
568	        }

