357	        /// <summary>
358	        /// Toạ độ X của gantry để đưa tay hút <paramref name="nozzle"/> vào giữa khung hình CAM
359	        /// bottom-up trước khi trigger AlignBottom (S20_Align1/S21_Align2, xem Routine_Auto). CAM
360	        /// cố định, mỗi tay có thể lệch cơ khí khác thiết kế nên phải teach RIÊNG từng tay —
361	        /// không suy ra được từ tay còn lại.
362	        /// </summary>
363	        private void TeachAlignPos(int nozzle)
364	        {
365	            if (!McControl.Status.OrgOk)
366	            {
367	                _dialog.Warn("Chưa về gốc — toạ độ đọc lúc này không có ý nghĩa. Chạy Origin trước khi teach.");
368	                return;
369	            }
370	
371	            double x = McControl.Motion[AxisId.X].CurrentPos;
372	            if (nozzle == 1) Model.AlignPosX_Nozzle1 = x; else Model.AlignPosX_Nozzle2 = x;
373	            OnPropertyChanged(nameof(Model));
374	        }
