162	        /// </summary>
163	        private static void InstallSimulationModel()
164	        {
165	            var m = McDataManager.Model;
166	            bool usable = m != null && m.InputTray.IsTaught && m.AssyTray.IsTaught && m.Calib.IsUsable;
167	            if (usable) return;
168	
169	            McDataManager.UseModel(Data.Model.ModelData.CreateSimulation());
