using System;
using ShieldCanAssy.Core.Communication;
using ShieldCanAssy.Core.Data.Model;

namespace ShieldCanAssy.Core.Controller
{
    /// <summary>Toạ độ đích của một lần đặt — đã quy về hệ toạ độ LỆNH TRỤC của máy.</summary>
    public struct PlaceTarget
    {
        /// <summary>Toạ độ lệnh trục X để tâm xoay của tay hút trùng tâm chi tiết đích.</summary>
        public double X;

        /// <summary>Toạ độ lệnh trục Y2 (tray lắp ráp), cùng ý nghĩa.</summary>
        public double Y;

        /// <summary>Góc chi tiết đích, độ, trong hệ vật lý của file hiệu chuẩn top-down.</summary>
        public double AngleDeg;
    }

    /// <summary>Kết quả tính điểm đặt cho một sản phẩm.</summary>
    public class PlaceSolution
    {
        public bool Ok { get; set; }
        public string Reason { get; set; }

        /// <summary>Góc phải xoay thêm cho trục A của tay hút này, độ, ĐÃ đổi sang chiều dương
        /// của trục A (VisionMaster trả theo chiều kim đồng hồ dương).</summary>
        public double DeltaThetaDeg { get; set; }

        /// <summary>Toạ độ lệnh cho trục X và trục Y của tray lắp ráp (Y2).</summary>
        public double CommandX { get; set; }
        public double CommandY { get; set; }

        /// <summary>Độ lệch tâm sản phẩm so với trục xoay SAU KHI xoay — phần VisionMaster đã trừ
        /// sẵn khỏi lệnh. Giữ lại để hiện lên UI và để chặn ngưỡng, không dùng để tính lệnh.</summary>
        public double ErrX { get; set; }
        public double ErrY { get; set; }
        public double ErrDistance { get { return Math.Sqrt(ErrX * ErrX + ErrY * ErrY); } }

        public static PlaceSolution Fail(string why)
        {
            return new PlaceSolution { Ok = false, Reason = why };
        }
    }

    /// <summary>
    /// Ghép kết quả hai camera thành lệnh đặt — PLAN.md §6.6.
    ///
    /// <para><b>Phép tính bù nay nằm trong VisionMaster</b> (Tuấn chốt 2026-09-12): Flow
    /// <c>PlaceAlign</c> dùng module <i>Single Point Alignment</i> để tính Δθ và lệnh X/Y2, kể cả
    /// phần "tâm sản phẩm dịch đi do xoay". App KHÔNG còn tự nhân <c>R(Δθ)·p</c> nữa — làm cả hai
    /// nơi là bù hai lần (PDF Hikrobot tr.35, tr.60). Phần còn lại của lớp này chỉ là ba việc mà
    /// VisionMaster không biết:</para>
    /// <list type="number">
    /// <item><b>Dựng toạ độ đích</b> từ vị trí trục lúc chụp + kết quả LocateTop + hand-eye —
    /// VisionMaster không đọc được encoder nên không tự cộng được (<see cref="BuildTarget"/>).</item>
    /// <item><b>Đổi dấu góc</b> từ quy ước VisionMaster (chiều kim đồng hồ dương) sang chiều dương
    /// của trục A (ngược chiều kim đồng hồ, §11 #6). Dấu này ĐO bằng phép thử vòng xoay
    /// (<c>Routine_Calib.VerifyAlignRotationAsync</c>) rồi ghi vào model, không suy đoán.</item>
    /// <item><b>Chặn ngưỡng</b> trước khi phát lệnh: vượt ngưỡng nghĩa là vision đo nhầm vật.</item>
    /// </list>
    ///
    /// <para>Tách thành hàm thuần để kiểm chứng bằng <c>--selftest</c> mà không cần camera hay
    /// trục nào: đây là phần dễ sai nhất của cả máy và sai của nó biểu hiện thành <b>đặt lệch</b>
    /// chứ không thành thông báo lỗi.</para>
    /// </summary>
    public static class PlacementSolver
    {
        /// <summary>
        /// Toạ độ đích trong hệ lệnh trục: vị trí trục lúc chụp + lượng dịch LocateTop trả về +
        /// hand-eye của đúng tay hút sẽ đặt.
        ///
        /// <para><c>HandEye_i</c> đo riêng từng tay (§6.5) nên đã chứa sẵn khoảng cách pitch giữa
        /// hai đầu hút — <b>không</b> được cộng pitch thêm lần nữa.</para>
        /// </summary>
        /// <param name="top">Kết quả Flow LocateTop: X/Y là lượng phải dịch trục X/Y2 (mm).</param>
        /// <param name="captureX">Toạ độ trục X lúc chụp ảnh top-down.</param>
        /// <param name="captureY">Toạ độ trục Y2 lúc chụp ảnh top-down.</param>
        public static PlaceTarget BuildTarget(VisionCalib calib, int nozzle, VisionPose top,
                                              double captureX, double captureY)
        {
            return new PlaceTarget
            {
                X = captureX + top.X + calib.HandEyeDx(nozzle),
                Y = captureY + top.Y + calib.HandEyeDy(nozzle),
                AngleDeg = top.Angle
            };
        }

        /// <summary>Đầu vào cho Flow PlaceAlign: đích vừa dựng + tư thế sản phẩm do CAM bottom-up đo.</summary>
        public static PlaceAlignInput BuildAlignInput(PlaceTarget target, VisionPose bottom)
        {
            return new PlaceAlignInput
            {
                TargetX = target.X,
                TargetY = target.Y,
                TargetAngle = target.AngleDeg,
                ObjectX = bottom.X,
                ObjectY = bottom.Y,
                ObjectAngle = bottom.Angle
            };
        }

        /// <summary>
        /// Đọc kết quả Flow PlaceAlign thành lệnh trục, đổi dấu góc và chặn ngưỡng.
        /// </summary>
        public static PlaceSolution FromAlign(VisionCalib calib, int nozzle, PlaceTarget target,
                                              PlaceAlignResult align,
                                              double maxAngleDeg, double maxDistance)
        {
            if (calib == null) return PlaceSolution.Fail("chưa có dữ liệu hiệu chuẩn");
            if (align == null || !align.Ok)
                return PlaceSolution.Fail("Flow PlaceAlign không tính được" +
                    (align == null || align.Error == null ? "" : ": " + align.Error));

            int sign = calib.AlignAngleSign(nozzle);
            if (sign == 0)
                return PlaceSolution.Fail("chưa xác minh dấu góc của tay #" + nozzle +
                    " — chạy phép thử vòng xoay ở trang Vision Edit trước (§6.4)");

            if (double.IsNaN(align.DeltaX) || double.IsNaN(align.DeltaY) || double.IsNaN(align.DeltaThetaDeg))
                return PlaceSolution.Fail("Flow PlaceAlign trả số không hợp lệ (NaN)");

            double delta = NormalizeDeg(sign * align.DeltaThetaDeg);

            var sol = new PlaceSolution
            {
                Ok = true,
                DeltaThetaDeg = delta,
                CommandX = align.DeltaX,
                CommandY = align.DeltaY,
                // Chênh giữa đích và lệnh chính là lượng VisionMaster đã trừ đi cho độ lệch tâm
                // sau khi xoay. Không tính lại — chỉ đo lại để chặn ngưỡng và hiện lên UI.
                ErrX = target.X - align.DeltaX,
                ErrY = target.Y - align.DeltaY
            };

            // Vượt ngưỡng nghĩa là vision đo nhầm vật, không phải sản phẩm lệch nhiều. Coi là
            // Align fail chứ không lao trục đi bù (§6.6).
            if (Math.Abs(delta) > maxAngleDeg)
            {
                sol.Ok = false;
                sol.Reason = string.Format("góc bù {0:0.0}° vượt ngưỡng {1:0.0}°", delta, maxAngleDeg);
            }
            else if (sol.ErrDistance > maxDistance)
            {
                sol.Ok = false;
                sol.Reason = string.Format("lượng bù {0:0.00} mm vượt ngưỡng {1:0.00} mm",
                    sol.ErrDistance, maxDistance);
            }

            return sol;
        }

        /// <summary>Đưa góc về khoảng (−180, 180] — xoay 350° và xoay −10° là một, chọn cái ngắn.</summary>
        public static double NormalizeDeg(double deg)
        {
            while (deg > 180.0) deg -= 360.0;
            while (deg <= -180.0) deg += 360.0;
            return deg;
        }
    }
}

