        public DateTime HandEye1MeasuredAt { get; set; }
        public DateTime HandEye2MeasuredAt { get; set; }

        /// <summary>Dấu quy đổi góc VisionMaster → trục A của từng tay: +1, −1, hoặc <b>0 = chưa
