        public DateTime HandEyeMeasuredAt(int nozzle) { return nozzle == 1 ? HandEye1MeasuredAt : HandEye2MeasuredAt; }

        public int AlignAngleSign(int nozzle) { return nozzle == 1 ? AlignAngleSign1 : AlignAngleSign2; }
