            else { HandEye2Dx = dx; HandEye2Dy = dy; HandEye2MeasuredAt = at; }
        }

        public void SetAlignVerified(int nozzle, int sign, double posX, double residualMm, DateTime at)
        {
            if (nozzle == 1)
