        /// Đủ dữ liệu để chạy Auto chưa. Hiệu chuẩn bên trong VisionMaster App không kiểm được,
        /// nên điều kiện ở đây là những gì App TỰ ĐO và tự biết đúng/sai: hand-eye hai tay và phép
        /// thử vòng xoay hai tay (phép thử này đồng thời bắt được tâm xoay/handedness sai của file
        /// hiệu chuẩn bottom-up, xem <c>Routine_Calib.VerifyAlignRotationAsync</c>).
        /// </summary>
        public bool IsUsable
        {
            get
            {
                return IsHandEyeMeasured(1) && IsHandEyeMeasured(2) &&
                       IsAlignVerified(1) && IsAlignVerified(2);
            }
        }

        /// <summary>Quá hạn tính từ lần xác minh Align cũ nhất (§6.1 quy tắc 7, alarm 4090).</summary>
        public bool IsExpired(int validDays)
        {
            if (!IsUsable) return false;
            var oldest = AlignVerifiedAt1 < AlignVerifiedAt2 ? AlignVerifiedAt1 : AlignVerifiedAt2;
            return (DateTime.Now - oldest).TotalDays > validDays;
        }
    }

