using System;
using System.Threading;
using System.Threading.Tasks;
using ShieldCanAssy.Core.Controller;
using ShieldCanAssy.Utility;

namespace ShieldCanAssy.Core.Communication.Sim
{
    /// <summary>
    /// Vision mô phỏng. Trả về tư thế mm/độ có nhiễu ngẫu nhiên, kèm xác suất không tìm thấy để
    /// chạy được nhánh NG của chuỗi Auto (PLAN.md §5.4).
    ///
    /// <para><b>Đơn vị là mm ở MỌI Flow</b> (Tuấn chốt 2026-09-12): solution thật kết thúc bằng
    /// module Calibration Transformation nên không Flow nào còn trả pixel, mô phỏng phải giống
    /// đúng như vậy — nếu không, <c>--selftest</c> sẽ khoá lại một hợp đồng không tồn tại.</para>
    /// </summary>
    public class FakeVision : Bindable, IVisionDevice
    {
        private readonly Random _rng = new Random(20260731);

        private bool _connected;
        public bool IsConnected { get => _connected; private set => SetProperty(ref _connected, value); }

        private bool _loaded;
        public bool IsSolutionLoaded { get => _loaded; private set => SetProperty(ref _loaded, value); }

        /// <summary>Thời gian chụp + xử lý giả lập, ms.</summary>
        public int ProcessTimeMs { get; set; } = 120;

        /// <summary>Xác suất tìm thấy đối tượng.</summary>
        public double FoundRate { get; set; } = 1.0;

        /// <summary>Độ lệch tối đa mô phỏng của CAM top-down quanh tâm khung hình, mm.</summary>
        public double NoiseTopMm { get; set; } = 0.4;

        /// <summary>Độ lệch góc tối đa mô phỏng, độ.</summary>
        public double NoiseAngle { get; set; } = 4.0;

        /// <summary>Nhiễu đo của CAM bottom-up, mm.</summary>
        public double NoiseAlignMm { get; set; } = 0.05;

        /// <summary>
        /// Độ lệch tâm mô phỏng: sản phẩm KHÔNG bao giờ nằm đúng tâm xoay, nên Flow AlignBottom
        /// phải trả về một vector khác 0. Nhờ vậy chuỗi Auto mô phỏng thật sự đi qua phần "xoay
        /// làm tâm sản phẩm dịch đi" (§6.6) thay vì luôn nhận lượng bù bằng 0 — bỏ số này về 0 là
        /// mất luôn khả năng phát hiện lỗi ở đúng chỗ dễ sai nhất.
        /// </summary>
        public double SimEccentricityMm { get; set; } = 1.5;

        /// <summary>Số lần đã trigger từng Flow — để --selftest kiểm chứng những thay đổi kiểu
        /// "bớt chụp lại" (vd. S05_ScanAssy) thật sự bớt trigger chứ không chỉ vẫn ra đúng kết quả
        /// theo cách cũ (nhiều trigger hơn) mà tình cờ vẫn đạt.</summary>
        public int AlignBottomCount { get; private set; }
        public int LocateTopCount { get; private set; }

        /// <summary>Số lần đã chạy Flow tính toán PlaceAlign (§6.6).</summary>
        public int PlaceAlignCount { get; private set; }

        // Mô phỏng không có camera thật để chụp — luôn null, trang Main tự hiện chỗ trống thay
        // vì hình khi chạy --selftest/dev không có máy.
        public System.Drawing.Bitmap LastTopDownImage => null;
        public System.Drawing.Bitmap LastBottomUpImage => null;

        public bool Connect() { IsConnected = true; return true; }

        public void Disconnect() { IsConnected = false; IsSolutionLoaded = false; }

        public async Task<bool> LoadSolutionAsync(string solutionPath)
        {
            await Task.Delay(200).ConfigureAwait(false);
            IsSolutionLoaded = IsConnected;
            return IsSolutionLoaded;
        }

        public async Task<VisionPose> TriggerAsync(EVisionProcedure procedure, CancellationToken ct)
        {
            if (!IsConnected) return VisionPose.NotFound("chưa kết nối");
            if (!IsSolutionLoaded) return VisionPose.NotFound("chưa nạp solution");

            bool isAlign = procedure == EVisionProcedure.AlignBottomTool1 ||
                           procedure == EVisionProcedure.AlignBottomTool2;
            bool isAlignCalib = procedure == EVisionProcedure.AlignCalibTool1 ||
                                procedure == EVisionProcedure.AlignCalibTool2;
            if (isAlign) AlignBottomCount++;
            else if (procedure == EVisionProcedure.LocateTop) LocateTopCount++;

            await Task.Delay(ProcessTimeMs, ct).ConfigureAwait(false);

            if (_rng.NextDouble() > FoundRate)
                return VisionPose.NotFound("không tìm thấy đối tượng");

            if (isAlign || isAlignCalib)
            {
                // Tâm sản phẩm so với TÂM XOAY của tay hút: lệch tâm cố định + nhiễu đo. Tay #2
                // lệch theo hướng khác tay #1 để bài test nào lỡ dùng chung số của hai tay sẽ lộ.
                bool tool2 = procedure == EVisionProcedure.AlignBottomTool2 ||
                             procedure == EVisionProcedure.AlignCalibTool2;
                double ex = tool2 ? -SimEccentricityMm : SimEccentricityMm;
                double ey = tool2 ? SimEccentricityMm * 0.5 : -SimEccentricityMm * 0.5;

                return new VisionPose
                {
                    Found = true,
                    X = ex + Noise(NoiseAlignMm),
                    Y = ey + Noise(NoiseAlignMm),
                    Angle = Noise(NoiseAngle),
                    Score = 0.85 + _rng.NextDouble() * 0.14
                };
            }

            // CAM top-down (LocateTop / LocateMark / TopDownCalib): lượng phải dịch trục X và Y2
            // để tâm khung hình trùng đối tượng — dao động quanh 0 vì camera đã được đưa tới đúng
            // ô trước khi chụp.
            return new VisionPose
            {
                Found = true,
                X = Noise(NoiseTopMm),
                Y = Noise(NoiseTopMm),
                Angle = Noise(NoiseAngle),
                Score = 0.85 + _rng.NextDouble() * 0.14
            };
        }

        /// <summary>
        /// Mô phỏng Flow tính toán <c>PlaceAlign</c> bằng đúng công thức module Single Point
        /// Alignment của VisionMaster (<see cref="SinglePointAlignMath"/>) — không nhiễu, vì đây là
        /// phép TÍNH chứ không phải phép ĐO: VisionMaster thật cũng cho ra cùng một số với cùng
        /// đầu vào. Nhờ vậy chuỗi Auto mô phỏng kiểm chứng được cả phần ghép hai camera.
        /// </summary>
        public async Task<PlaceAlignResult> TriggerPlaceAlignAsync(PlaceAlignInput input, CancellationToken ct)
        {
            if (input == null) return PlaceAlignResult.NotOk("thiếu dữ liệu đầu vào");
            if (!IsConnected) return PlaceAlignResult.NotOk("chưa kết nối");
            if (!IsSolutionLoaded) return PlaceAlignResult.NotOk("chưa nạp solution");

            PlaceAlignCount++;

            // Flow này không chụp ảnh nên nhanh hơn hẳn Flow có camera — mô phỏng đúng như vậy để
            // cycle time ước lượng được không bị thổi phồng.
            await Task.Delay(5, ct).ConfigureAwait(false);

            double dx, dy, dTheta;
            SinglePointAlignMath.Solve(input.TargetX, input.TargetY, input.TargetAngle,
                                       input.ObjectX, input.ObjectY, input.ObjectAngle,
                                       out dx, out dy, out dTheta);

            return new PlaceAlignResult { Ok = true, DeltaX = dx, DeltaY = dy, DeltaThetaDeg = dTheta };
        }

        private double Noise(double amplitude)
        {
            return (_rng.NextDouble() - 0.5) * 2 * amplitude;
        }
    }
}

