            if (!IsSolutionLoaded) return PlaceAlignResult.NotOk("chưa nạp solution");

            PlaceAlignCount++;

            // Flow này không chụp ảnh nên nhanh hơn hẳn Flow có camera — mô phỏng đúng như vậy để
            // cycle time ước lượng được không bị thổi phồng.
            await Task.Delay(5, ct).ConfigureAwait(false);

            double dx, dy, dTheta;
            SinglePointAlignMath.Solve(input.TargetX, input.TargetY, input.TargetAngle,
                                       input.ObjectX, input.ObjectY, input.ObjectAngle,
                                       out dx, out dy, out dTheta);

            return new PlaceAlignResult { Ok = true, DeltaX = dx, DeltaY = dy, DeltaThetaDeg = dTheta };
        }

        private double Noise(double amplitude)
        {
            return (_rng.NextDouble() - 0.5) * 2 * amplitude;
        }
    }
}

