        /// <summary>
        /// Trạng thái hiệu chuẩn Align của tay đang chọn. KHÔNG hiện "scale mm/px" hay "RMS" nữa —
        /// App không còn giữ ma trận nào để mà hiện; chất lượng phép fit đọc trong chính module
        /// hiệu chuẩn của VisionMaster ở cột trái.
        /// </summary>
        public string AlignStatusText
        {
            get
            {
                int n = SelectedTool;
                if (!Calib.IsAlignVerified(n)) return "CHƯA xác minh — chạy phép thử vòng xoay";

                string expired = Calib.IsExpired(Sys.CalibValidDays) ? "HẾT HẠN — " : "";
                return string.Format("{0}dấu góc {1}, sai số dư {2:0.000} mm, soi tại X={3:0.000} — {4:dd/MM/yyyy HH:mm}",
                    expired,
                    Calib.AlignAngleSign(n) > 0 ? "+1" : "−1",
                    n == 1 ? Calib.AlignVerifyResidual1 : Calib.AlignVerifyResidual2,
                    Calib.AlignVerifiedPosX(n),
                    Calib.AlignVerifiedAt(n));
            }
        }

        public string HandEyeStatusText
        {
            get
            {
                int n = SelectedTool;
                if (!Calib.IsHandEyeMeasured(n)) return "CHƯA đo";
                return string.Format("dx={0:0.000}, dy={1:0.000} mm — {2:dd/MM/yyyy HH:mm}",
                    Calib.HandEyeDx(n), Calib.HandEyeDy(n), Calib.HandEyeMeasuredAt(n));
            }
        }

        /// <summary>Điều kiện chạy Auto, gom về một dòng để operator biết còn thiếu bước nào —
        /// đúng những gì <c>VisionCalib.IsUsable</c> đòi (§5.1).</summary>
        public string ReadyStatusText
        {
            get
            {
                if (Calib.IsUsable) return "Đủ điều kiện chạy Auto.";
                string missing = "";
                for (int n = 1; n <= 2; n++)
                {
                    if (!Calib.IsHandEyeMeasured(n)) missing += string.Format("hand-eye tay #{0}; ", n);
                    if (!Calib.IsAlignVerified(n)) missing += string.Format("phép thử vòng xoay tay #{0}; ", n);
                }
                return "Auto còn bị chặn — thiếu: " + missing.TrimEnd(' ', ';');
            }
        }

