    { Ok = true, DeltaX = target.X - 0.4, DeltaY = target.Y + 0.2, DeltaThetaDeg = 10 };

    var sol = Core.Controller.PlacementSolver.FromAlign(calib, 1, target, align, 15, 3);
    Check("Lệnh X/Y2 lấy NGUYÊN số VisionMaster trả về, không tính bù lại",
        sol.Ok && Near(sol.CommandX, align.DeltaX) && Near(sol.CommandY, align.DeltaY),
        $"({sol.CommandX:0.###}, {sol.CommandY:0.###})");
    Check("Lượng bù = chênh giữa đích và lệnh, chỉ dùng để chặn ngưỡng",
        Near(sol.ErrX, 0.4) && Near(sol.ErrY, -0.2),
        $"e = ({sol.ErrX:0.###}, {sol.ErrY:0.###})");
    Check("Dấu góc +1: lệnh xoay giữ nguyên chiều VisionMaster", Near(sol.DeltaThetaDeg, 10));

    // Dấu −1 là trường hợp THƯỜNG GẶP trên máy thật: VisionMaster tính chiều kim đồng hồ
    // dương, trục A quy ước ngược lại (§11 #6).
    var calibNeg = Core.Data.Model.ModelData.CreateSimulation().Calib;
    calibNeg.SetAlignVerified(1, -1, 300, 0, DateTime.Now);
    var solNeg = Core.Controller.PlacementSolver.FromAlign(calibNeg, 1, target, align, 15, 3);
    Check("Dấu góc −1: lệnh xoay đảo chiều so với số VisionMaster trả về",
        solNeg.Ok && Near(solNeg.DeltaThetaDeg, -10), $"{solNeg.DeltaThetaDeg:0.##}°");

    // Chưa xác minh dấu góc thì KHÔNG được đoán +1 — đoán sai là xoay ngược, hỏng hàng.
    var calibUnverified = Core.Data.Model.ModelData.CreateSimulation().Calib;
    calibUnverified.SetAlignVerified(1, 0, 0, 0, DateTime.MinValue);
    Check("Chưa xác minh dấu góc thì từ chối tính, không đoán chiều xoay",
        !Core.Controller.PlacementSolver.FromAlign(calibUnverified, 1, target, align, 15, 3).Ok);

    // Vượt ngưỡng = vision đo nhầm vật, phải từ chối chứ không lao trục đi bù.
    var alignBigAngle = new Core.Communication.PlaceAlignResult
    { Ok = true, DeltaX = target.X, DeltaY = target.Y, DeltaThetaDeg = 90 };
    Check("Góc bù vượt ngưỡng thì từ chối",
        !Core.Controller.PlacementSolver.FromAlign(calib, 1, target, alignBigAngle, 15, 3).Ok);

    var alignFar = new Core.Communication.PlaceAlignResult
    { Ok = true, DeltaX = target.X - 10, DeltaY = target.Y, DeltaThetaDeg = 0 };
    Check("Lượng bù vượt ngưỡng thì từ chối",
        !Core.Controller.PlacementSolver.FromAlign(calib, 1, target, alignFar, 15, 3).Ok);

    Check("Flow PlaceAlign lỗi thì từ chối, không tính bừa",
        !Core.Controller.PlacementSolver.FromAlign(calib, 1, target,
            Core.Communication.PlaceAlignResult.NotOk("thử"), 15, 3).Ok);
    Check("Flow trả NaN thì từ chối",
        !Core.Controller.PlacementSolver.FromAlign(calib, 1, target,
            new Core.Communication.PlaceAlignResult { Ok = true, DeltaX = double.NaN, DeltaY = 0, DeltaThetaDeg = 0 },
            15, 3).Ok);

    Check("Chuẩn hoá góc: 350° = −10°", Near(Core.Controller.PlacementSolver.NormalizeDeg(350), -10));
    Check("Chuẩn hoá góc: −350° = 10°", Near(Core.Controller.PlacementSolver.NormalizeDeg(-350), 10));

