3	namespace ShieldCanAssy.Core.Communication
4	{
5	    /// <summary>
6	    /// Quy đổi giữa đơn vị kỹ thuật (mm hoặc độ) và đơn vị của driver (xung, rpm).
7	    ///
8	    /// <para><c>PulsePerUnit</c> là <b>hằng số cố định theo thiết kế</b>, không phải số đo được
9	    /// trên máy: 1000 xung/mm cho trục tịnh tiến Panasonic (mm 3 chữ số thập phân, 12.345 mm ↔
10	    /// 12345 xung), 10000 xung/360° cho trục xoay Fastech. Driver được cấu hình tỉ số truyền
11	    /// điện tử (electronic gear) để cho ra đúng con số này — việc của P1 là cấu hình driver
12	    /// khớp hằng số đã chốt, không phải đo rồi suy ra nó.</para>
13	    ///
14	    /// <para><c>UnitPerRev</c> thì khác — đây LÀ một đại lượng cơ khí thật (bước vít me, tỉ số
15	    /// hộp giảm tốc), chỉ dùng để đổi tốc độ mm/s sang rpm. Sai nó không tạo sai số vị trí, chỉ
16	    /// làm tốc độ hiển thị lệch tốc độ thật.</para>
17	    /// </summary>
18	    public class AxisScale
19	    {
20	        private readonly AxisConfig _cfg;
21	
22	        public AxisScale(AxisConfig cfg)
23	        {
24	            if (cfg == null) throw new ArgumentNullException("cfg");
25	            _cfg = cfg;
26	        }
27	
28	        /// <summary>Số xung trên một đơn vị, đã chặn giá trị vô nghĩa.</summary>
29	        public double PulsePerUnit
30	        {
31	            get { return _cfg.PulsePerUnit > 1e-9 ? _cfg.PulsePerUnit : 1.0; }
32	        }
33	
34	        public double UnitPerRev
35	        {
36	            get { return _cfg.UnitPerRev > 1e-9 ? _cfg.UnitPerRev : 1.0; }
37	        }
38	
39	        /// <summary>mm (hoặc độ) → xung. Làm tròn về số nguyên gần nhất, không cắt cụt.</summary>
40	        public int ToPulse(double unit)
41	        {
42	            double p = unit * PulsePerUnit;
43	
44	            // Cắt ở biên int thay vì để tràn âm: tràn biến một lệnh đi xa thành một lệnh đi
45	            // ngược hết cỡ, đúng kiểu lỗi không ai ngờ tới khi nhìn code.
46	            if (p > int.MaxValue) return int.MaxValue;
47	            if (p < int.MinValue) return int.MinValue;
48	            return (int)Math.Round(p, MidpointRounding.AwayFromZero);
49	        }
50	
51	        /// <summary>Xung → mm (hoặc độ).</summary>
52	        public double ToUnit(int pulse)
53	        {
54	            return pulse / PulsePerUnit;
55	        }
56	
57	        /// <summary>
58	        /// Tốc độ đơn vị/giây → rpm, kẹp trong [1, MaxRpm].
59	        ///
60	        /// <para>Kẹp sàn ở 1 rpm là chủ ý: làm tròn xuống 0 sẽ thành lệnh "chạy với tốc độ 0",
61	        /// mà driver hiểu là đứng yên chứ không phải chạy chậm — trục không nhúc nhích và lệnh
62	        /// treo cho tới khi timeout, rất khó đoán ra nguyên nhân.</para>
63	        /// </summary>
64	        public ushort ToRpm(double unitPerSec)
65	        {
66	            double rpm = Math.Abs(unitPerSec) / UnitPerRev * 60.0;
67	            int r = (int)Math.Round(rpm, MidpointRounding.AwayFromZero);
68	
69	            int max = _cfg.MaxRpm > 0 ? _cfg.MaxRpm : 3000;
70	            if (r > max) r = max;
71	            if (r < 1) r = 1;
72	            return (ushort)r;
73	        }
74	
75	        /// <summary>
76	        /// Tốc độ đơn vị/giây → xung/giây, dạng tốc độ mà Fastech nhận (<c>lVelocity</c>).
77	        /// Kẹp sàn ở 1 xung/s với cùng lý do như <see cref="ToRpm"/>.
78	        /// </summary>
79	        public uint ToPulsePerSec(double unitPerSec)
80	        {
81	            double pps = Math.Abs(unitPerSec) * PulsePerUnit;
82	            if (pps > uint.MaxValue) return uint.MaxValue;
83	            uint v = (uint)Math.Round(pps, MidpointRounding.AwayFromZero);
84	            return v < 1 ? 1u : v;
85	        }
86	
87	        /// <summary>rpm → đơn vị/giây, để hiển thị tốc độ đọc về từ driver.</summary>
88	        public double FromRpm(double rpm)
89	        {
90	            return rpm * UnitPerRev / 60.0;
91	        }
92	    }
93	}
