1	using System;
2	using System.Diagnostics;
3	using System.Net;
4	using System.Threading;
5	using System.Threading.Tasks;
6	using FASTECH;
7	using ShieldCanAssy.Core.Infor;
8	using ShieldCanAssy.Lib.Fastech;
9	using ShieldCanAssy.Utility;
10	using ShieldCanAssy.Utility.Log;
11	
12	namespace ShieldCanAssy.Core.Communication
13	{
14	    /// <summary>
15	    /// Một trục Fastech Ezi-SERVO Plus-E qua Ethernet (A1 hoặc A2), bọc <c>EziMOTIONPlusELib</c>.
16	    ///
17	    /// <para><b>Khác Panasonic ở hai điểm quan trọng.</b> (1) Thư viện Fastech là P/Invoke đồng
18	    /// bộ và <b>không</b> có luồng monitor riêng, nên <see cref="Refresh"/> phải tự gọi
19	    /// <c>FAS_GetAllStatus</c> — một lần gọi UDP mỗi 20 ms cho mỗi trục. (2) Tốc độ tính bằng
20	    /// <b>xung/giây</b> chứ không phải rpm.</para>
21	    ///
22	    /// <para><b>Cảnh báo về bảng bit trạng thái:</b> xem <see cref="EziAxisStatus"/>. Vị trí và
23	    /// tốc độ lấy từ trường số nguyên riêng của <c>FAS_GetAllStatus</c> nên không phụ thuộc
24	    /// bảng bit; chỉ các cờ boolean mới cần xác minh khi có máy.</para>
25	    ///
26	    /// <para><b>Số hiệu board (<c>iBdID</c>) là định danh nội bộ của thư viện, không phải IP.</b>
27	    /// Mọi module Fastech trong cùng process — 2 trục xoay và 2 card I/O — phải mang
28	    /// <c>iBdID</c> khác nhau, nếu không <c>FAS_Connect</c> của cái sau sẽ đè lên cái trước và
29	    /// triệu chứng là "trục A2 điều khiển ra card I/O". Bảng phân bổ nằm ở
30	    /// <see cref="FastechBoardId"/>.</para>
31	    /// </summary>
32	    public class FastechAxis : Bindable, IAxis
33	    {
34	        private readonly AxisConfig _cfg;
35	        private readonly AxisScale _scale;
36	        private readonly int _bdId;
37	        private readonly object _cmdLock = new object();
38	
39	        private uint _rawStatus;
40	
41	        public FastechAxis(AxisConfig cfg)
42	        {
43	            _cfg = cfg;
44	            _scale = new AxisScale(cfg);
45	            _bdId = cfg.BoardId;
46	        }
47	
48	        public string Name { get { return _cfg.Name; } }
49	        public AxisConfig Config { get { return _cfg; } }
50	
51	        /// <summary>Thanh ghi trạng thái thô — hiện trên trang Manual để xác minh bảng bit.</summary>
52	        public uint RawStatus { get { return _rawStatus; } }
53	        public string RawStatusText { get { return EziAxisStatus.Describe(_rawStatus); } }
54	
55	        private bool _connected;
56	        public bool IsConnected { get { return _connected; } private set { SetProperty(ref _connected, value); } }
57	
58	        private bool _servoOn;
59	        public bool ServoOn { get { return _servoOn; } private set { SetProperty(ref _servoOn, value); } }
60	
61	        private bool _busy;
62	        public bool Busy { get { return _busy; } private set { SetProperty(ref _busy, value); } }
63	
64	        private bool _alarm;
65	        public bool Alarm { get { return _alarm; } private set { SetProperty(ref _alarm, value); } }
66	
67	        private bool _orgOk;
68	        public bool OrgOk { get { return _orgOk; } private set { SetProperty(ref _orgOk, value); } }
69	
70	        private bool _fls;
71	        public bool FLS { get { return _fls; } private set { SetProperty(ref _fls, value); } }
72	
73	        private bool _rls;
74	        public bool RLS { get { return _rls; } private set { SetProperty(ref _rls, value); } }
75	
76	        private double _pos;
77	        public double CurrentPos { get { return _pos; } private set { SetProperty(ref _pos, value); } }
78	
79	        private int _errorCode;
80	        public int ErrorCode { get { return _errorCode; } private set { SetProperty(ref _errorCode, value); } }
81	
82	        /// <summary>Cờ về gốc của phần mềm — cùng lý do như PanasonicAxis (PLAN.md §4.1).</summary>
83	        private bool _softHomed;
84	
85	        // ───────────────────────── kết nối ─────────────────────────
86	
87	        public bool Connect()
88	        {
89	            try
90	            {
91	                IPAddress ip;
92	                if (!IPAddress.TryParse(_cfg.IpAddress, out ip))
93	                {
94	                    LogWorker.Instance.RecordLog(Name + ": IP không hợp lệ — " + _cfg.IpAddress,
95	                        Utility.Log.LogLevel.Error, Name);
96	                    IsConnected = false;
97	                    return false;
98	                }
99	
100	                EziMOTIONPlusELib.FAS_Close(_bdId);
101	
102	                if (!EziMOTIONPlusELib.FAS_Connect(ip, _bdId))
103	                {
104	                    LogWorker.Instance.RecordLog(
105	                        Name + ": không kết nối được " + _cfg.IpAddress + " (bdID " + _bdId + ")",
106	                        Utility.Log.LogLevel.Error, Name);
107	                    IsConnected = false;
108	                    return false;
109	                }
110	
111	                // FAS_Connect chỉ mở socket UDP; nó thành công cả khi đầu kia không có thiết bị
112	                // nào. FAS_IsSlaveExist mới là câu hỏi "có ai trả lời không" — nhưng hỏi ngay lúc
113	                // app vừa khởi động thì driver Ezi thường CHƯA kịp sẵn sàng trả lời (đang tự khởi
114	                // động Ethernet stack của chính nó), nên hay báo "mất kết nối" oan dù cáp/nguồn
115	                // đều ổn (Tuấn báo lỗi, 2026-09-08). Thử lại vài lần thay vì hỏi đúng một lần rồi
116	                // kết luận ngay — driver trả lời được là dừng thử ngay, không phải lúc nào cũng
117	                // chờ đủ 1.2s này.
118	                const int SlaveExistRetries = 6;
119	                const int SlaveExistRetryDelayMs = 200;
120	                bool slaveExists = false;
121	                for (int attempt = 0; attempt < SlaveExistRetries; attempt++)
122	                {
123	                    if (EziMOTIONPlusELib.FAS_IsSlaveExist(_bdId) != 0) { slaveExists = true; break; }
124	                    if (attempt < SlaveExistRetries - 1) Thread.Sleep(SlaveExistRetryDelayMs);
125	                }
126	
127	                if (!slaveExists)
128	                {
129	                    LogWorker.Instance.RecordLog(
130	                        Name + ": mở được socket nhưng không có thiết bị trả lời ở " + _cfg.IpAddress +
131	                        " (đã thử " + SlaveExistRetries + " lần)",
132	                        Utility.Log.LogLevel.Error, Name);
133	                    EziMOTIONPlusELib.FAS_Close(_bdId);
134	                    IsConnected = false;
135	                    return false;
136	                }
137	
138	                IsConnected = true;
139	                LogWorker.Instance.RecordLog(Name + ": đã kết nối " + _cfg.IpAddress + " (bdID " + _bdId + ")",
140	                    Utility.Log.LogLevel.Info, Name);
141	                return true;
142	            }
143	            catch (DllNotFoundException)
144	            {
145	                // Chạy trên máy chưa có EziMOTIONPlusE.dll: báo rõ chứ không để ngoại lệ trần
146	                // làm sập vòng khởi tạo.
147	                LogWorker.Instance.RecordLog(
148	                    Name + ": không tìm thấy EziMOTIONPlusE.dll cạnh exe",
149	                    Utility.Log.LogLevel.Error, Name);
150	                IsConnected = false;
151	                return false;
152	            }
153	            catch (Exception ex)
154	            {
155	                LogWorker.Instance.RecordLog(Name + ": lỗi kết nối — " + ex.Message,
156	                    Utility.Log.LogLevel.Error, Name);
157	                IsConnected = false;
158	                return false;
159	            }
160	        }
161	
162	        public void Disconnect()
163	        {
164	            // Qua chung _cmdLock với mọi lệnh khác — đóng board giữa lúc một lệnh khác đang gửi
165	            // P/Invoke tới CÙNG bdId dễ để lại trạng thái lỡ dở (Tuấn lo ngại lúc đóng app,
166	            // 2026-09-10). Khác PanasonicAxis: lock đồng bộ, không cần timeout vì mọi lệnh ở đây
167	            // đều là gọi P/Invoke nhanh, không có bước chờ Modbus nối tiếp kiểu servo Panasonic.
168	            lock (_cmdLock)
169	            {
170	                try { EziMOTIONPlusELib.FAS_Close(_bdId); } catch { }
171	            }
172	            IsConnected = false;
173	            _softHomed = false;
174	            OrgOk = false;
175	        }
176	
177	        // ───────────────────────── đọc trạng thái ─────────────────────────
178	
179	        public void Refresh()
180	        {
181	            if (!IsConnected) return;
182	
183	            uint inStatus = 0, outStatus = 0, axisStatus = 0;
184	            int cmdPos = 0, actPos = 0, posErr = 0, actVel = 0;
185	            ushort itemNo = 0;
186	
187	            int rc;
188	            try
189	            {
190	                rc = EziMOTIONPlusELib.FAS_GetAllStatus(_bdId, ref inStatus, ref outStatus,
191	                    ref axisStatus, ref cmdPos, ref actPos, ref posErr, ref actVel, ref itemNo);
192	            }
193	            catch { IsConnected = false; return; }
194	
195	            if (rc != 0)
196	            {
197	                IsConnected = false;
198	                return;
199	            }
200	
201	            _rawStatus = axisStatus;
202	            OnPropertyChanged(nameof(RawStatus));
203	            OnPropertyChanged(nameof(RawStatusText));
204	
205	            // Vị trí là trường số nguyên riêng — đúng kể cả khi bảng bit chưa xác minh.
206	            CurrentPos = _scale.ToUnit(actPos);
207	
208	            ServoOn = EziAxisStatus.Has(axisStatus, EziAxisStatus.ServoOn);
209	            Alarm = (axisStatus & EziAxisStatus.AnyErrorMask) != 0;
210	            Busy = (axisStatus & EziAxisStatus.BusyMask) != 0;
211	            FLS = EziAxisStatus.Has(axisStatus, EziAxisStatus.HwPosLimit);
212	            RLS = EziAxisStatus.Has(axisStatus, EziAxisStatus.HwNegLimit);
213	            ErrorCode = (int)(axisStatus & EziAxisStatus.AnyErrorMask);
214	
215	            if (!ServoOn && _softHomed)
216	            {
217	                _softHomed = false;
218	                LogWorker.Instance.RecordLog(Name + ": servo tắt ngoài ý muốn — huỷ trạng thái đã về gốc",
219	                    Utility.Log.LogLevel.Warning, Name);
220	            }
221	            if (Alarm) _softHomed = false;
222	
223	            OrgOk = _softHomed && EziAxisStatus.Has(axisStatus, EziAxisStatus.OriginReturnOk);
224	        }
225	
226	        // ───────────────────────── lệnh ─────────────────────────
227	
228	        public async Task<bool> SetServoOnAsync(bool on)
229	        {
230	            if (!IsConnected) return false;
231	            try
232	            {
233	                int rc;
234	                lock (_cmdLock) rc = EziMOTIONPlusELib.FAS_ServoEnable(_bdId, on ? 1 : 0);
235	                if (rc != 0) return false;
236	
237	                if (!on) { _softHomed = false; OrgOk = false; return true; }
238	
239	                var sw = Stopwatch.StartNew();
240	                while (sw.ElapsedMilliseconds < 5000)
241	                {
242	                    uint st = 0;
243	                    lock (_cmdLock) EziMOTIONPlusELib.FAS_GetAxisStatus(_bdId, ref st);
244	                    if (EziAxisStatus.Has(st, EziAxisStatus.ServoOn)) return true;
245	                    if ((st & EziAxisStatus.AnyErrorMask) != 0) return false;
246	                    await Task.Delay(20).ConfigureAwait(false);
247	                }
248	                return false;
249	            }
250	            catch (Exception ex)
251	            {
252	                LogWorker.Instance.RecordLog(Name + ": SetServoOn lỗi — " + ex.Message,
253	                    Utility.Log.LogLevel.Error, Name);
254	                return false;
255	            }
256	        }
257	
258	        public async Task<bool> HomeAsync(CancellationToken ct)
259	        {
260	            if (!IsConnected) return false;
261	
262	            _softHomed = false;
263	            OrgOk = false;
264	
265	            int rc;
266	            lock (_cmdLock) rc = EziMOTIONPlusELib.FAS_MoveOriginSingleAxis(_bdId);
267	            if (rc != 0)
268	            {
269	                AlarmManager.RaiseAxisEvent(Name, AxisFault.HomeTimeout, "FAS_MoveOriginSingleAxis trả về " + rc);
270	                return false;
271	            }
272	
273	            var sw = Stopwatch.StartNew();
274	            while (sw.ElapsedMilliseconds < _cfg.HomeTimeoutMs)
275	            {
276	                if (ct.IsCancellationRequested) { Stop(); return false; }
277	                await Task.Delay(20, ct).ConfigureAwait(false);
278	
279	                uint st = 0;
280	                lock (_cmdLock) EziMOTIONPlusELib.FAS_GetAxisStatus(_bdId, ref st);
281	
282	                if ((st & EziAxisStatus.AnyErrorMask) != 0)
283	                {
284	                    AlarmManager.RaiseAxisEvent(Name, AxisFault.HomeTimeout,
285	                        "driver báo lỗi khi về gốc, trạng thái " + EziAxisStatus.Describe(st));
286	                    return false;
287	                }
288	
289	                if (EziAxisStatus.Has(st, EziAxisStatus.OriginReturnOk) &&
290	                    !EziAxisStatus.Has(st, EziAxisStatus.OriginReturning))
291	                {
292	                    _softHomed = true;
293	                    OrgOk = true;
294	                    LogWorker.Instance.RecordLog(
295	                        string.Format("{0}: về gốc xong sau {1:0.0} s", Name, sw.Elapsed.TotalSeconds),
296	                        Utility.Log.LogLevel.Info, Name);
297	                    return true;
298	                }
299	            }
300	
301	            Stop();
302	            AlarmManager.RaiseAxisEvent(Name, AxisFault.HomeTimeout, "quá " + _cfg.HomeTimeoutMs + " ms");
303	            return false;
304	        }
305	
306	        public async Task<bool> MoveAbsAsync(double pos, double speed, CancellationToken ct)
307	        {
308	            if (!IsConnected) return false;
309	
310	            if (!_cfg.InSoftLimit(pos))
311	            {
312	                AlarmManager.RaiseAxisEvent(Name, AxisFault.SoftLimit,
313	                    string.Format("đích {0:0.000}{1} ngoài [{2:0.000}, {3:0.000}]",
314	                        pos, _cfg.Unit, _cfg.SoftLimitNeg, _cfg.SoftLimitPos));
315	                return false;
316	            }
317	
318	            int target = _scale.ToPulse(pos);
319	            uint vel = _scale.ToPulsePerSec(speed);
320	
321	            int rc;
322	            lock (_cmdLock) rc = EziMOTIONPlusELib.FAS_MoveSingleAxisAbsPos(_bdId, target, vel);
323	            if (rc != 0)
324	            {
325	                AlarmManager.RaiseAxisEvent(Name, AxisFault.MoveTimeout, "FAS_MoveSingleAxisAbsPos trả về " + rc);
326	                return false;
327	            }
328	
329	            return await WaitReachedAsync(pos, ct).ConfigureAwait(false);
330	        }
331	
332	        /// <summary>
333	        /// Di chuyển TƯƠNG ĐỐI (Inching) — dùng lệnh gốc FAS_MoveSingleAxisIncPos của driver
334	        /// thay vì tự cộng dồn rồi gọi lại Move Abs (khác Panasonic, chưa có lệnh gốc tương ứng).
335	        /// Soft limit vẫn kiểm theo đích TUYỆT ĐỐI quy ra từ vị trí hiện tại, và dùng chung vòng
336	        /// chờ với Move Abs (<see cref="WaitReachedAsync"/>).
337	        /// </summary>
338	        public async Task<bool> MoveIncAsync(double delta, double speed, CancellationToken ct)
339	        {
340	            if (!IsConnected) return false;
341	
342	            double pos = CurrentPos + delta;
343	            if (!_cfg.InSoftLimit(pos))
344	            {
345	                AlarmManager.RaiseAxisEvent(Name, AxisFault.SoftLimit,
346	                    string.Format("đích {0:0.000}{1} ngoài [{2:0.000}, {3:0.000}]",
347	                        pos, _cfg.Unit, _cfg.SoftLimitNeg, _cfg.SoftLimitPos));
348	                return false;
349	            }
350	
351	            int incPulse = _scale.ToPulse(delta);
352	            uint vel = _scale.ToPulsePerSec(speed);
353	
354	            int rc;
355	            lock (_cmdLock) rc = EziMOTIONPlusELib.FAS_MoveSingleAxisIncPos(_bdId, incPulse, vel);
356	            if (rc != 0)
357	            {
358	                AlarmManager.RaiseAxisEvent(Name, AxisFault.MoveTimeout, "FAS_MoveSingleAxisIncPos trả về " + rc);
359	                return false;
360	            }
361	
362	            return await WaitReachedAsync(pos, ct).ConfigureAwait(false);
363	        }
364	
365	        /// <summary>Vòng chờ chung cho Move Abs/Move Inc — cả hai chỉ khác ở lệnh KHỞI ĐỘNG chuyển
366	        /// động, còn chờ tới đích (đích tuyệt đối) thì giống hệt nhau.</summary>
367	        private async Task<bool> WaitReachedAsync(double pos, CancellationToken ct)
368	        {
369	            var sw = Stopwatch.StartNew();
370	            double tol = _scale.ToUnit(Math.Max(1, _cfg.PositionTolerancePulse));
371	
372	            while (sw.ElapsedMilliseconds < _cfg.MoveTimeoutMs)
373	            {
374	                if (ct.IsCancellationRequested) { Stop(); return false; }
375	                await Task.Delay(10, ct).ConfigureAwait(false);
376	
377	                uint st = 0;
378	                int actPos = 0;
379	                lock (_cmdLock)
380	                {
381	                    EziMOTIONPlusELib.FAS_GetAxisStatus(_bdId, ref st);
382	                    EziMOTIONPlusELib.FAS_GetActualPos(_bdId, ref actPos);
383	                }
384	
385	                if ((st & EziAxisStatus.AnyErrorMask) != 0)
386	                {
387	                    AlarmManager.RaiseAxis(Name, AxisFault.DriverAlarm, EziAxisStatus.Describe(st));
388	                    return false;
389	                }
390	                if (EziAxisStatus.Has(st, EziAxisStatus.HwPosLimit) ||
391	                    EziAxisStatus.Has(st, EziAxisStatus.HwNegLimit))
392	                {
393	                    AlarmManager.RaiseAxis(Name, AxisFault.HardLimit,
394	                        EziAxisStatus.Has(st, EziAxisStatus.HwPosLimit) ? "cữ +" : "cữ −");
395	                    return false;
396	                }
397	
398	                if (!EziAxisStatus.Has(st, EziAxisStatus.Motioning) &&
399	                    Math.Abs(_scale.ToUnit(actPos) - pos) <= Math.Max(tol, 1e-6))
400	                    return true;
401	            }
402	
403	            Stop();
404	            AlarmManager.RaiseAxisEvent(Name, AxisFault.MoveTimeout,
405	                string.Format("quá {0} ms; đích {1:0.000}{2}, hiện {3:0.000}{2}",
406	                    _cfg.MoveTimeoutMs, pos, _cfg.Unit, CurrentPos));
407	            return false;
408	        }
409	
410	        /// <summary>
411	        /// Jog/Stop bị gọi THẲNG từ sự kiện chuột trên UI thread (<c>ManualView.xaml.cs</c>
412	        /// Jog_Down/Up) — bắn nền bằng <c>Task.Run</c> thay vì gọi thẳng
413	        /// <c>EziMOTIONPlusELib.FAS_*</c> tại chỗ: card/driver treo (đúng lúc báo lỗi) sẽ khoá
414	        /// cứng UI thread nếu gọi đồng bộ ở đây, y hệt lỗi vừa sửa ở PanasonicAxis (Tuấn báo lỗi,
415	        /// 2026-09-08).
416	        /// </summary>
417	        public void Jog(int dir, double speed)
418	        {
419	            if (!IsConnected) return;
420	            uint pulsePerSec = _scale.ToPulsePerSec(speed);
421	            Task.Run(() =>
422	            {
423	                try
424	                {
425	                    lock (_cmdLock)
426	                    {
427	                        if (dir == 0) EziMOTIONPlusELib.FAS_MoveStop(_bdId);
428	                        else EziMOTIONPlusELib.FAS_MoveVelocity(_bdId, pulsePerSec, dir > 0 ? 1 : 0);
429	                    }
430	                }
431	                catch (Exception ex)
432	                {
433	                    LogWorker.Instance.RecordLog(Name + ": Jog lỗi — " + ex.Message,
434	                        Utility.Log.LogLevel.Error, Name);
435	                }
436	            });
437	        }
438	
439	        public void Stop()
440	        {
441	            if (!IsConnected) return;
442	            Task.Run(() =>
443	            {
444	                try { lock (_cmdLock) EziMOTIONPlusELib.FAS_MoveStop(_bdId); } catch { }
445	            });
446	        }
447	
448	        public async Task<bool> ResetAlarmAsync()
449	        {
450	            if (!IsConnected) return false;
451	            try
452	            {
453	                int rc;
454	                lock (_cmdLock) rc = EziMOTIONPlusELib.FAS_ServoAlarmReset(_bdId);
455	
456	                _softHomed = false;
457	                OrgOk = false;
458	
459	                await Task.Delay(200).ConfigureAwait(false);
460	                return rc == 0;
461	            }
462	            catch { return false; }
463	        }
464	    }
465	}
