5	using ShieldCanAssy.Core.Infor;
6	using ShieldCanAssy.Utility;
7	
8	namespace ShieldCanAssy.Core.Communication.Sim
9	{
10	    /// <summary>
11	    /// Trục mô phỏng — cho phép viết và kiểm thử toàn bộ chuỗi Origin, chuỗi Auto, xử lý NG và
12	    /// Pause/Resume trước khi có phần cứng (PLAN.md §10, Simulation mode).
13	    ///
14	    /// <para>Mô phỏng theo thời gian thật: vị trí tiến dần về đích với tốc độ đã lệnh, cập nhật
15	    /// trong <see cref="Refresh"/> đúng như driver thật được vòng quét đọc trạng thái. Nhờ vậy
16	    /// timeout, interlock và điều kiện chờ chạy trên FakeAxis có ý nghĩa thật, chứ không phải
17	    /// hoàn tất tức thời làm mọi thứ luôn "đúng".</para>
18	    ///
19	    /// <para>Các cờ <c>Sim*</c> để bơm lỗi từ trang Manual: chúng là cách duy nhất kiểm thử được
20	    /// nhánh xử lý alarm mà không phải rút cáp máy thật.</para>
21	    /// </summary>
22	    public class FakeAxis : Bindable, IAxis
23	    {
24	        private enum Mode { Idle, MoveAbs, Jog, Home }
25	
26	        private readonly Stopwatch _clock = Stopwatch.StartNew();
27	        private readonly Random _rng;
28	        private double _lastTickSec;
29	
30	        private Mode _mode = Mode.Idle;
31	        private double _target;
32	        private double _speed;
33	        private int _jogDir;
34	        private double _homeTarget;
35	
36	        /// <summary>
37	        /// Cữ hành trình cứng đặt cách giới hạn mềm một khoảng, đúng như bố trí thật: soft limit
38	        /// là hàng rào của phần mềm, cảm biến cứng nằm sau nó vài mm làm lớp cuối cùng.
39	        /// </summary>
40	        private const double HardLimitMargin = 5.0;
41	
42	        public FakeAxis(AxisConfig config)
43	        {
44	            Config = config;
45	            Name = config.Name;
46	            _rng = new Random(Name.GetHashCode());
47	
48	            _pos = config.StandbyPos;
49	
50	            // Máy thật lúc bật nguồn không nằm sẵn ở gốc. Nếu vị trí chờ trùng gốc thì đặt lệch
51	            // ra để chuỗi về gốc có quãng đường thật sự phải chạy — không thì bước O2 hoàn tất
52	            // tức thời và chốt chặn Z_SAFE không được kiểm thử gì cả.
53	            if (Math.Abs(_pos - config.HomeOffset) < 1e-6)
54	                _pos = Clamp(config.HomeOffset - config.HomeDir * 15.0);
55	        }
56	
57	        private double Clamp(double v)
58	            => v < Config.SoftLimitNeg ? Config.SoftLimitNeg
59	             : v > Config.SoftLimitPos ? Config.SoftLimitPos
60	             : v;
61	
62	        public string Name { get; }
63	        public AxisConfig Config { get; }
64	
65	        // ── Cờ bơm lỗi cho mô phỏng ──
66	        public bool SimDisconnected { get; set; }
67	
68	        /// <summary>
69	        /// Bật/tắt qua nút ALM ở trang Manual. Phải tự bắn PropertyChanged cho cả chính nó lẫn
70	        /// <see cref="Alarm"/> — khác <c>FastechAxis</c>/<c>PanasonicAxis</c> (nơi <c>Alarm</c> là
71	        /// field có SetProperty riêng), ở đây <c>Alarm</c> chỉ là phép chiếu qua cờ này nên không
72	        /// tự thông báo được nếu cờ gán thẳng bằng auto-property.
73	        /// </summary>
74	        private bool _simDriverAlarm;
75	        public bool SimDriverAlarm
76	        {
77	            get => _simDriverAlarm;
78	            set { if (SetProperty(ref _simDriverAlarm, value)) OnPropertyChanged(nameof(Alarm)); }
79	        }
80	        /// <summary>Chạy chậm 20 lần để kích hoạt nhánh timeout.</summary>
81	        public bool SimStall { get; set; }
82	
83	        private bool _connected;
84	        public bool IsConnected { get => _connected && !SimDisconnected; private set => SetProperty(ref _connected, value); }
85	
86	        private bool _servoOn;
87	        public bool ServoOn { get => _servoOn; private set => SetProperty(ref _servoOn, value); }
88	
89	        private bool _busy;
90	        public bool Busy { get => _busy; private set => SetProperty(ref _busy, value); }
91	
92	        public bool Alarm => SimDriverAlarm;
93	
94	        private bool _orgOk;
95	        public bool OrgOk { get => _orgOk; private set => SetProperty(ref _orgOk, value); }
96	
97	        public bool FLS => _pos >= Config.SoftLimitPos + HardLimitMargin;
98	        public bool RLS => _pos <= Config.SoftLimitNeg - HardLimitMargin;
99	
100	        private double _pos;
101	        public double CurrentPos { get => _pos; private set => SetProperty(ref _pos, value); }
102	
103	        public int ErrorCode => SimDriverAlarm ? 0x1601 : 0;
104	
105	        public bool Connect()
106	        {
107	            IsConnected = true;
108	            _lastTickSec = _clock.Elapsed.TotalSeconds;
109	            return true;
110	        }
111	
112	        public void Disconnect()
113	        {
114	            IsConnected = false;
115	            ServoOn = false;
116	            OrgOk = false;
117	        }
118	
119	        public Task<bool> SetServoOnAsync(bool on)
120	        {
121	            if (!IsConnected) return Task.FromResult(false);
122	            ServoOn = on;
123	            if (!on) OrgOk = false;   // mất servo là mất gốc — khớp quy tắc §4.1
124	            return Task.FromResult(true);
125	        }
126	
127	        public async Task<bool> HomeAsync(CancellationToken ct)
128	        {
129	            if (!IsConnected || !ServoOn || Alarm) return false;
130	
131	            OrgOk = false;
132	
133	            // Cảm biến gốc nằm ở HomeOffset, trong hành trình cho phép — trục chạy TỚI nó chứ
134	            // không chạy một quãng cố định rồi tuyên bố đã về gốc. Mô phỏng kiểu "chạy 25 mm rồi
135	            // nhảy về gốc" từng làm trục vọt qua cả cữ hành trình cứng và sinh alarm giả.
136	            _homeTarget = Clamp(Config.HomeOffset);
137	            // Về gốc luôn chạy ở tốc độ CHẬM cố định — không theo nút chọn Nhanh/Chậm của thao
138	            // tác tay, an toàn không được phép phụ thuộc việc operator đang để chế độ nào.
139	            _speed = Config.JogSpeedSlow;
140	            _mode = Mode.Home;
141	            Busy = true;
142	
143	            var sw = Stopwatch.StartNew();
144	            try
145	            {
146	                while (_mode == Mode.Home)
147	                {
148	                    if (ct.IsCancellationRequested) { Abort(); return false; }
149	
150	                    if (sw.ElapsedMilliseconds > Config.HomeTimeoutMs)
151	                    {
152	                        Abort();
153	                        AlarmManager.RaiseAxisEvent(Name, AxisFault.HomeTimeout,
154	                            $"quá {Config.HomeTimeoutMs} ms");
155	                        return false;
156	                    }
157	
158	                    if (Alarm)
159	                    {
160	                        Abort();
161	                        AlarmManager.RaiseAxis(Name, AxisFault.DriverAlarm, $"0x{ErrorCode:X4}");
162	                        return false;
163	                    }
164	
165	                    await Task.Delay(20, CancellationToken.None).ConfigureAwait(false);
166	                }
167	            }
168	            finally
169	            {
170	                Busy = false;
171	            }
172	
173	            return OrgOk;
174	        }
175	
176	        public async Task<bool> MoveAbsAsync(double pos, double speed, CancellationToken ct)
177	        {
178	            if (!IsConnected || !ServoOn || Alarm) return false;
179	
180	            if (!Config.InSoftLimit(pos))
181	            {
182	                AlarmManager.RaiseAxisEvent(Name, AxisFault.SoftLimit,
183	                    $"đích {pos:0.000}{Config.Unit} ngoài [{Config.SoftLimitNeg:0.###}, {Config.SoftLimitPos:0.###}]");
184	                return false;
185	            }
186	            if (!OrgOk)
187	            {
188	                AlarmManager.RaiseAxisEvent(Name, AxisFault.NotHomed);
189	                return false;
190	            }
191	
192	            _target = pos;
193	            _speed = Math.Max(0.1, speed);
194	            _mode = Mode.MoveAbs;
195	            Busy = true;
196	
197	            var sw = Stopwatch.StartNew();
198	            try
199	            {
200	                while (_mode == Mode.MoveAbs)
201	                {
202	                    if (ct.IsCancellationRequested) { Abort(); return false; }
203	
204	                    if (sw.ElapsedMilliseconds > Config.MoveTimeoutMs)
205	                    {
206	                        Abort();
207	                        AlarmManager.RaiseAxisEvent(Name, AxisFault.MoveTimeout,
208	                            $"còn cách đích {Math.Abs(_target - _pos):0.000}{Config.Unit}");
209	                        return false;
210	                    }
211	
212	                    if (Alarm)
213	                    {
214	                        Abort();
215	                        AlarmManager.RaiseAxis(Name, AxisFault.DriverAlarm, $"0x{ErrorCode:X4}");
216	                        return false;
217	                    }
218	
219	                    await Task.Delay(10, CancellationToken.None).ConfigureAwait(false);
220	                }
221	            }
222	            finally
223	            {
224	                Busy = false;
225	            }
226	
227	            return Math.Abs(_pos - pos) < 0.01;
228	        }
229	
230	        /// <summary>Di chuyển TƯƠNG ĐỐI (Inching) — mô phỏng theo đúng cách PanasonicAxis bù bằng
231	        /// phần mềm (chưa có block Inc riêng trong driver thật): cộng dồn rồi gọi lại Move Abs.</summary>
232	        public Task<bool> MoveIncAsync(double delta, double speed, CancellationToken ct)
233	            => MoveAbsAsync(_pos + delta, speed, ct);
234	
235	        public void Jog(int dir, double speed)
236	        {
237	            if (!IsConnected || !ServoOn || Alarm) return;
238	
239	            if (dir == 0)
240	            {
241	                if (_mode == Mode.Jog) { _mode = Mode.Idle; Busy = false; }
242	                _jogDir = 0;
243	                return;
244	            }
245	
246	            _jogDir = Math.Sign(dir);
247	            _speed = Math.Max(0.1, speed);
248	            _mode = Mode.Jog;
249	            Busy = true;
250	        }
251	
252	        public void Stop() => Abort();
253	
254	        public Task<bool> ResetAlarmAsync()
255	        {
256	            SimDriverAlarm = false;
257	            AlarmManager.ClearConditionAxis(Name, AxisFault.DriverAlarm);
258	            return Task.FromResult(true);
259	        }
260	
261	        private void Abort()
262	        {
263	            _mode = Mode.Idle;
264	            _jogDir = 0;
265	            Busy = false;
266	        }
267	
268	        /// <summary>Bước mô phỏng theo thời gian thực. MotionConnect gọi mỗi vòng quét.</summary>
269	        public void Refresh()
270	        {
271	            double now = _clock.Elapsed.TotalSeconds;
272	            double dt = now - _lastTickSec;
273	            _lastTickSec = now;
274	
275	            if (dt <= 0 || dt > 1.0) dt = 0.05;      // bỏ qua bước nhảy khi debug dừng lâu
276	            if (!IsConnected || !ServoOn) return;
277	
278	            double v = _speed * (SimStall ? 0.05 : 1.0);
279	            double step = v * dt;
280	
281	            switch (_mode)
282	            {
283	                case Mode.MoveAbs:
284	                {
285	                    double remain = _target - _pos;
286	                    if (Math.Abs(remain) <= step)
287	                    {
288	                        // Sai số lặp lại ±5 µm — để logic phía trên không vô tình phụ thuộc
289	                        // vào việc trục dừng đúng tuyệt đối, thứ không bao giờ xảy ra thật.
290	                        CurrentPos = _target + (_rng.NextDouble() - 0.5) * 0.01;
291	                        _mode = Mode.Idle;
292	                    }
293	                    else
294	                    {
295	                        CurrentPos = _pos + Math.Sign(remain) * step;
296	                    }
297	                    break;
298	                }
299	
300	                case Mode.Jog:
301	                {
302	                    double next = _pos + _jogDir * step;
303	                    if (next > Config.SoftLimitPos) { next = Config.SoftLimitPos; Abort(); }
304	                    if (next < Config.SoftLimitNeg) { next = Config.SoftLimitNeg; Abort(); }
305	                    CurrentPos = next;
306	                    break;
307	                }
308	
309	                case Mode.Home:
310	                {
311	                    double remain = _homeTarget - _pos;
312	                    if (Math.Abs(remain) <= step)
313	                    {
314	                        CurrentPos = Config.HomeOffset;
315	                        OrgOk = true;
316	                        _mode = Mode.Idle;
317	                    }
318	                    else
319	                    {
320	                        CurrentPos = _pos + Math.Sign(remain) * step;
321	                    }
322	                    break;
323	                }
324	            }
325	        }
326	    }
327	}
