697	        {
698	            Section("Quy đổi đơn vị trục (mm ⇄ xung, mm/s ⇄ rpm)");
699	
700	            // Vít me bước 10 mm, encoder 10000 xung/vòng → 1000 xung/mm.
701	            var cfg = new Core.Communication.AxisConfig
702	            {
703	                Name = "TEST", Unit = "mm",
704	                PulsePerUnit = 1000, UnitPerRev = 10, MaxRpm = 3000
705	            };
706	            var s = new Core.Communication.AxisScale(cfg);
707	
708	            Check("20 mm → 20000 xung", s.ToPulse(20) == 20000, s.ToPulse(20).ToString());
709	            Check("−20 mm → −20000 xung", s.ToPulse(-20) == -20000);
710	            Check("20000 xung → 20 mm", Near(s.ToUnit(20000), 20));
711	            Check("Đi rồi về là bằng chính nó", Near(s.ToUnit(s.ToPulse(37.123)), 37.123));
712	
713	            // Đúng ví dụ đã chốt: người vận hành gõ 12.345 mm ở ô nhập trên trang Manual, số
714	            // NGUYÊN gửi xuống Modbus (ServoService.MoveAbsolute) phải là 12345 xung. Đây là
715	            // toàn bộ điều mà PanasonicAxis.MoveAbsAsync làm trước khi gọi xuống ServoControl —
716	            // khoá lại bằng đúng ví dụ người dùng đưa ra để không ai lỡ tay sửa mất.
717	            Check("12.345 mm → 12345 xung (ví dụ đã chốt)", s.ToPulse(12.345) == 12345,
718	                s.ToPulse(12.345).ToString());
719	
720	            // Làm tròn phải ra số gần nhất, không cắt cụt: cắt cụt tích luỹ thành sai vị trí.
721	            Check("0.0006 mm làm tròn thành 1 xung, không cụt về 0", s.ToPulse(0.0006) == 1,
722	                s.ToPulse(0.0006).ToString());
723	            Check("−0.0006 mm làm tròn thành −1 xung", s.ToPulse(-0.0006) == -1);
724	
725	            // Tràn int biến lệnh đi xa thành lệnh đi ngược hết cỡ — phải cắt ở biên.
726	            Check("Giá trị quá lớn bị cắt ở biên int, không tràn thành số âm",
727	                s.ToPulse(1e12) == int.MaxValue && s.ToPulse(-1e12) == int.MinValue);
728	
729	            // 100 mm/s với bước 10 mm/vòng = 10 vòng/s = 600 rpm.
730	            Check("100 mm/s → 600 rpm", s.ToRpm(100) == 600, s.ToRpm(100).ToString());
731	            Check("Tốc độ âm lấy theo độ lớn", s.ToRpm(-100) == 600);
732	            Check("Vượt MaxRpm thì kẹp lại", s.ToRpm(10000) == 3000, s.ToRpm(10000).ToString());
733	
734	            // Kẹp sàn ở 1: rpm = 0 bị driver hiểu là đứng yên, lệnh treo tới khi timeout.
735	            Check("Tốc độ rất nhỏ vẫn ra ít nhất 1 rpm, không thành 0",
736	                s.ToRpm(0.0001) == 1, s.ToRpm(0.0001).ToString());
737	            Check("600 rpm → 100 mm/s", Near(s.FromRpm(600), 100));
